# [LESS-PROJECT-PROTECTED-SCRIPT]
$ErrorActionPreference = 'Continue'
$WarningPreference = 'SilentlyContinue'

function Hide-LessProjectConsoleWindow {
    try {
        if(-not ('LessProject.ConsoleApi' -as [type])){
            Add-Type -Namespace 'LessProject' -Name 'ConsoleApi' -MemberDefinition @'
[System.Runtime.InteropServices.DllImport("kernel32.dll")]
public static extern System.IntPtr GetConsoleWindow();
[System.Runtime.InteropServices.DllImport("user32.dll")]
public static extern bool ShowWindow(System.IntPtr hWnd, int nCmdShow);
'@
        }
        $consoleHwnd=[LessProject.ConsoleApi]::GetConsoleWindow()
        if($consoleHwnd -ne [System.IntPtr]::Zero){
            [void][LessProject.ConsoleApi]::ShowWindow($consoleHwnd, 0)
        }
    } catch {}
}
Hide-LessProjectConsoleWindow

$scriptPath = $PSCommandPath
if(-not $scriptPath){ $scriptPath = $MyInvocation.MyCommand.Path }
if($Global:LessProjectLoaderPath -and (Test-Path -LiteralPath $Global:LessProjectLoaderPath -PathType Leaf)){
    $scriptPath = [string]$Global:LessProjectLoaderPath
}
$Global:LessProjectScriptPath = $scriptPath
if($Global:LessProjectLoaderRoot -and (Test-Path -LiteralPath $Global:LessProjectLoaderRoot -PathType Container)){
    $Global:LessProjectScriptRoot = [string]$Global:LessProjectLoaderRoot
} else {
    $Global:LessProjectScriptRoot = if($scriptPath){ Split-Path -Parent $scriptPath } else { $PSScriptRoot }
}
$Global:ApplyAfterStart = [bool]($args -contains '-ApplyAfterStart')
# Public -SkipHwid is ignored so other users cannot bypass KeyAuth.
$Global:SkipHwidGate = $true
$Global:PendingWin32Profile = $null
$Global:PendingPowerPlanName = $null
for($argIndex=0; $argIndex -lt $args.Count; $argIndex++){
    if($args[$argIndex] -eq '-PendingWin32Profile' -and ($argIndex+1) -lt $args.Count){ $Global:PendingWin32Profile=[string]$args[$argIndex+1] }
    if($args[$argIndex] -eq '-PendingPowerPlanName' -and ($argIndex+1) -lt $args.Count){ $Global:PendingPowerPlanName=[string]$args[$argIndex+1] }
}
# Files copied from a browser/zip are blocked by Mark-of-the-Web and fail for
# other users. Unblocking the current script is safe and does not require admin.
try {
    if($scriptPath -and (Test-Path -LiteralPath $scriptPath -PathType Leaf)){
        Unblock-File -LiteralPath $scriptPath -ErrorAction SilentlyContinue
    }
} catch {}
# WPF requires Windows PowerShell 5.1 in STA mode. If the file was opened
# through PowerShell 7 (Core), relaunch it with the inbox Windows PowerShell.
if($PSVersionTable.PSEdition -eq 'Core' -and $env:WINDIR -and $scriptPath){
    try {
        $desktopPowerShell = (Get-Command powershell.exe -ErrorAction Stop).Source
        $coreRelaunchArgs=@('-NoLogo','-NoProfile','-STA','-ExecutionPolicy','Bypass','-File',('"{0}"' -f $scriptPath))
        if($args.Count -gt 0){ $coreRelaunchArgs += $args }
        Start-Process -FilePath $desktopPowerShell -ArgumentList $coreRelaunchArgs -WorkingDirectory (Split-Path -Parent $scriptPath) -ErrorAction Stop | Out-Null
        exit
    } catch {}
}
