    Add-Type -AssemblyName PresentationCore -ErrorAction Stop
    Add-Type -AssemblyName WindowsBase -ErrorAction Stop
} catch {
    try {
        Add-Type -AssemblyName System.Windows.Forms -ErrorAction Stop
        [System.Windows.Forms.MessageBox]::Show(
            "LESS PROJECT cannot start because WPF is unavailable. Please use Windows PowerShell 5.1.",
            "LESS PROJECT",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Error
        ) | Out-Null
    } catch {}
    exit 1
}

function Invoke-LessProjectPreflight {
    $issues = New-Object System.Collections.Generic.List[string]

    if ($env:OS -ne 'Windows_NT') {
        [void]$issues.Add('Windows is required.')
    }

    if ($PSVersionTable.PSVersion.Major -lt 5) {
        [void]$issues.Add('Windows PowerShell 5.1 or newer is required.')
    }

    try {
        if ([System.Threading.Thread]::CurrentThread.ApartmentState -ne [System.Threading.ApartmentState]::STA) {
            [void]$issues.Add('PowerShell must run in STA mode for WPF.')
        }
    } catch {
        [void]$issues.Add('Unable to check STA mode.')
    }

    if ($issues.Count -gt 0) {
        try {
            [System.Windows.MessageBox]::Show(
                (($issues | ForEach-Object { '- ' + $_ }) -join "`n"),
                'LESS PROJECT / PRECHECK FAILED',
                [System.Windows.MessageBoxButton]::OK,
                [System.Windows.MessageBoxImage]::Error
            ) | Out-Null
        } catch {}
        return $false
    }

    return $true
}

if (-not (Invoke-LessProjectPreflight)) { exit 1 }
$Global:UiErrorLogPath = Join-Path ([IO.Path]::GetTempPath()) "LessProject-ui-error.log"
try {
    [System.Windows.Threading.Dispatcher]::CurrentDispatcher.add_UnhandledException({
        param($sender,$eventArgs)
        try {
            $detail = if($eventArgs.Exception){ $eventArgs.Exception.ToString() } else { "Unknown dispatcher exception" }
            Add-Content -LiteralPath $Global:UiErrorLogPath -Value ("$(Get-Date -Format o)`r`n$detail`r`n") -Encoding UTF8
        } catch {}
        try { $eventArgs.Handled = $true } catch {}
    })
} catch {}
