function Restart-LessProjectAsAdministrator {
    param([switch]$ApplyAfterStart,[string]$PendingWin32Profile,[string]$PendingPowerPlanName)
    try {
        $self = $Global:LessProjectScriptPath
        if([string]::IsNullOrWhiteSpace($self) -or -not (Test-Path -LiteralPath $self -PathType Leaf)){ throw 'ไม่พบ path ของไฟล์สคริปต์' }
        $exe = (Get-Command powershell.exe -ErrorAction SilentlyContinue).Source
        if([string]::IsNullOrWhiteSpace($exe)){ $exe = "$env:WINDIR\System32\WindowsPowerShell\v1.0\powershell.exe" }
        $elevatedArgs=@('-NoLogo','-NoProfile','-STA','-ExecutionPolicy','Bypass','-File',('"{0}"' -f $self))
        if($ApplyAfterStart){ $elevatedArgs += '-ApplyAfterStart' }
        if(-not [string]::IsNullOrWhiteSpace($PendingWin32Profile)){ $elevatedArgs += @('-PendingWin32Profile',$PendingWin32Profile) }
        if(-not [string]::IsNullOrWhiteSpace($PendingPowerPlanName)){ $elevatedArgs += @('-PendingPowerPlanName',$PendingPowerPlanName) }
        Start-Process -FilePath $exe -ArgumentList $elevatedArgs -Verb RunAs -WorkingDirectory (Split-Path -Parent $self) -ErrorAction Stop | Out-Null
        return $true
    } catch {
        try { Add-Log ("[ELEVATION FAILED] {0}" -f $_.Exception.Message) '#D8D8D8' } catch {}
        return $false
    }
}
