# LINE and similar messengers must never be force-closed, have startup removed,
# or lose Windows toast notifications. Match whole tokens so OFFLINE/pipeline are ignored.
$Global:ProtectedMessengerNames = @(
    "LINE","LINEUpdater","LINELauncher","LINEInst","LINEApp",
    "WhatsApp","Telegram","KakaoTalk","WeChat","Weixin","Signal","Viber"
)
function Test-ProtectedMessengerText {
    param([string]$Text)
    if([string]::IsNullOrWhiteSpace($Text)){ return $false }
    foreach($name in @($Global:ProtectedMessengerNames)){
        $pattern='(?i)(?:^|[^A-Za-z0-9])' + [regex]::Escape([string]$name) + '(?:$|[^A-Za-z0-9])'
        if($Text -match $pattern){ return $true }
    }
    return $false
}
function Test-ProtectedMessengerProcess {
    param($Process)
    if(-not $Process){ return $false }
    if(Test-ProtectedMessengerText ([string]$Process.ProcessName)){ return $true }
    try {
        if($Process.Path -and (Test-ProtectedMessengerText ([string]$Process.Path))){ return $true }
        if($Process.MainModule -and $Process.MainModule.FileName -and (Test-ProtectedMessengerText ([string]$Process.MainModule.FileName))){ return $true }
    } catch {}
    return $false
}
function Get-ProtectedMessengerPackageFamilies {
    $families=New-Object System.Collections.Generic.List[string]
    try {
        foreach($pkg in @(Get-AppxPackage -EA SilentlyContinue)){
            $blob=("{0} {1} {2}" -f [string]$pkg.Name,[string]$pkg.PackageFamilyName,[string]$pkg.Publisher)
            if(-not (Test-ProtectedMessengerText $blob)){ continue }
            if($pkg.PackageFamilyName -and -not $families.Contains([string]$pkg.PackageFamilyName)){
                [void]$families.Add([string]$pkg.PackageFamilyName)
            }
        }
    } catch {}
    return @($families)
}
function Protect-MessengerBackgroundAccess {
    foreach($family in @(Get-ProtectedMessengerPackageFamilies)){
        try {
            $p="HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications\$family"
            if(-not (Test-Path -LiteralPath $p)){ New-Item -Path $p -Force -EA SilentlyContinue | Out-Null }
            Set-RegValue $p "Disabled" 0 | Out-Null
            Set-RegValue $p "DisabledByUser" 0 | Out-Null
        } catch {}
    }
}
