)
# Fast metadata indexes: category rendering and preset checks use these instead of
# repeatedly scanning the full TweakInfo array with Where-Object.
$Global:TweakInfoByKey=@{}
$Global:TweakInfoByGroup=@{}
foreach($meta in @($Global:TweakInfo)){
    if($meta -and $meta.Key){
        $Global:TweakInfoByKey[[string]$meta.Key]=$meta
        $groupKey=[string]$meta.Group
        if(-not $Global:TweakInfoByGroup.ContainsKey($groupKey)){ $Global:TweakInfoByGroup[$groupKey]=New-Object System.Collections.ArrayList }
        [void]$Global:TweakInfoByGroup[$groupKey].Add($meta)
    }
}

function Get-SystemInfo {
    # Query each provider once so the splash is not held up by duplicate WMI calls.
    $info = [ordered]@{OS="Windows"; CPU="Unknown CPU"; GPU="Unknown GPU"; RAM=0; RAMType="Unknown"; Adapter="No Adapter"; NetType="None"; RAMUsedPct=0; Board="Unknown motherboard"; BIOS="Unknown BIOS"; Storage="Unknown storage"; Display="Unknown display"; Arch=$env:PROCESSOR_ARCHITECTURE}
    $os=$null; $ram=$null
    try {
        $os=Get-CimInstance Win32_OperatingSystem -Property Caption,FreePhysicalMemory -EA Stop
        if($os){
            $cap=$os.Caption -replace "Microsoft\s*","" -replace "\s+"," "
            $cap=$cap.Trim()
            # Keep it short: e.g. "Windows 10 IoT Enterprise LTSC 2021" -> "Windows 10 IoT Enterprise"
            if($cap -match "^(Windows\s+\S+(\s+IoT)?(\s+Enterprise|\s+Pro|\s+Home)?)"){ $info.OS=$Matches[1].Trim() } else { $info.OS=$cap }
        }
    } catch {
        try {
            $reg=Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -EA Stop
            if($reg.ProductName){$info.OS=[string]$reg.ProductName}
        } catch { $info.OS="Windows" }
    }
    try { $cpu=Get-CimInstance Win32_Processor -Property Name -EA Stop|Select -First 1; if($cpu){$info.CPU=($cpu.Name -replace "\(R\)|\(TM\)|CPU|Processor","").Trim()} } catch { try { $cpu=Get-WmiObject Win32_Processor -EA Stop|Select -First 1; if($cpu){$info.CPU=($cpu.Name -replace "\(R\)|\(TM\)|CPU|Processor","").Trim()} } catch {} }
    # Prefer a real vendor GPU over Microsoft's fallback display driver.
    try {
        $gpus=@(Get-CimInstance Win32_VideoController -Property Name,PNPDeviceID,AdapterCompatibility -EA SilentlyContinue)
        $realGpu=$gpus | Where-Object { $_.Name -and $_.Name -notmatch '^Microsoft Basic Display Adapter$|^Microsoft Remote Display Adapter$' } | Select-Object -First 1
        if(-not $realGpu){ $realGpu=$gpus | Select-Object -First 1 }
        if($realGpu -and $realGpu.Name){ $info.GPU=[string]$realGpu.Name }
    } catch {}
    if($info.GPU -match '^Microsoft Basic Display Adapter$|^Microsoft Remote Display Adapter$|^Unknown GPU$') {
        try {
            $pnp=@(Get-CimInstance Win32_PnPSignedDriver -Filter "DeviceClass='DISPLAY'" -EA SilentlyContinue)
            $pnpGpu=$pnp | Where-Object { $_.FriendlyName -and $_.FriendlyName -notmatch '^Microsoft Basic Display Adapter$|^Microsoft Remote Display Adapter$' } | Select-Object -First 1
            if($pnpGpu -and $pnpGpu.FriendlyName){ $info.GPU=[string]$pnpGpu.FriendlyName }
        } catch {}
    }
    if($info.GPU -match '^Microsoft Basic Display Adapter$|^Microsoft Remote Display Adapter$|^Unknown GPU$') {
        try {
            $gpuKey='HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}'
            $gpuReg=Get-ChildItem $gpuKey -EA SilentlyContinue | ForEach-Object {
                try { Get-ItemProperty $_.PSPath -EA SilentlyContinue } catch {}
            } | Where-Object { $_.DriverDesc -and $_.DriverDesc -notmatch '^Microsoft Basic Display Adapter$|^Microsoft Remote Display Adapter$' } | Select-Object -First 1
            if($gpuReg -and $gpuReg.DriverDesc){ $info.GPU=[string]$gpuReg.DriverDesc }
        } catch {}
    }
    try { $ram=Get-CimInstance Win32_ComputerSystem -Property TotalPhysicalMemory,Manufacturer,Model -EA Stop; if($ram){$info.RAM=[math]::Round($ram.TotalPhysicalMemory/1GB); if($ram.Manufacturer -or $ram.Model){$info.Board=("{0} {1}" -f $ram.Manufacturer,$ram.Model).Trim()}} } catch { try { $ram=Get-WmiObject Win32_ComputerSystem -EA Stop; if($ram){$info.RAM=[math]::Round($ram.TotalPhysicalMemory/1GB); if($ram.Manufacturer -or $ram.Model){$info.Board=("{0} {1}" -f $ram.Manufacturer,$ram.Model).Trim()}} } catch {} }
    try { $board=Get-CimInstance Win32_BaseBoard -Property Manufacturer,Product -EA SilentlyContinue|Select -First 1; if($board -and $board.Product){$info.Board=("{0} {1}" -f $board.Manufacturer,$board.Product).Trim()} } catch { try { $board=Get-WmiObject Win32_BaseBoard -EA SilentlyContinue|Select -First 1; if($board -and $board.Product){$info.Board=("{0} {1}" -f $board.Manufacturer,$board.Product).Trim()} } catch {} }
    try { $bios=Get-CimInstance Win32_BIOS -Property Manufacturer,SMBIOSBIOSVersion -EA SilentlyContinue|Select -First 1; if($bios){$info.BIOS=("{0} {1}" -f $bios.Manufacturer,$bios.SMBIOSBIOSVersion).Trim()} } catch { try { $bios=Get-WmiObject Win32_BIOS -EA SilentlyContinue|Select -First 1; if($bios){$info.BIOS=("{0} {1}" -f $bios.Manufacturer,$bios.SMBIOSBIOSVersion).Trim()} } catch {} }
    try { $disk=Get-CimInstance Win32_LogicalDisk -Filter "DriveType=3" -EA SilentlyContinue | Measure-Object Size -Sum -ErrorAction SilentlyContinue; if($disk -and $disk.Sum){$info.Storage=("{0:N0} GB" -f ($disk.Sum/1GB))} } catch { try { $disk=Get-WmiObject Win32_LogicalDisk -Filter "DriveType=3" -EA SilentlyContinue | Measure-Object Size -Sum -ErrorAction SilentlyContinue; if($disk -and $disk.Sum){$info.Storage=("{0:N0} GB" -f ($disk.Sum/1GB))} } catch {} }
    try {
        Add-Type -AssemblyName System.Windows.Forms -EA SilentlyContinue
        $screen=[System.Windows.Forms.Screen]::PrimaryScreen
        if($screen){$info.Display=("{0} x {1}" -f $screen.Bounds.Width,$screen.Bounds.Height)}
    } catch {}
    # System.Windows.Forms gives the active desktop resolution reliably.
    # Keep WMI/registry fallbacks for environments where Forms is unavailable.
    if($info.Display -eq "Unknown display" -or [string]::IsNullOrWhiteSpace([string]$info.Display)) {
        try {
            $display=@(Get-CimInstance Win32_VideoController -Property CurrentHorizontalResolution,CurrentVerticalResolution -EA SilentlyContinue) | Where-Object { $_.CurrentHorizontalResolution -and $_.CurrentVerticalResolution } | Select-Object -First 1
            if($display){$info.Display=("{0} x {1}" -f $display.CurrentHorizontalResolution,$display.CurrentVerticalResolution)}
        } catch {}
    }
    if($info.Display -eq "Unknown display" -or [string]::IsNullOrWhiteSpace([string]$info.Display)) {
        try {
            $dm=@(Get-CimInstance Win32_DesktopMonitor -EA SilentlyContinue) | Select-Object -First 1
            if($dm -and $dm.ScreenWidth -and $dm.ScreenHeight){$info.Display=("{0} x {1}" -f $dm.ScreenWidth,$dm.ScreenHeight)}
        } catch {}
    }
    if($info.Display -eq "Unknown display" -or [string]::IsNullOrWhiteSpace([string]$info.Display)) {
        try {
            $reg=Get-ItemProperty 'HKCU:\Control Panel\Desktop' -EA SilentlyContinue
            if($reg -and $reg.LogPixels){$info.Display="Display detected"}
        } catch {}
    }
    try {
        $net=@(Get-NetAdapter -EA SilentlyContinue) | Where-Object {$_.Status -eq "Up" -and $_.HardwareInterface -ne $false -and $_.InterfaceDescription} | Sort-Object ifIndex | Select-Object -First 1
        if($net){$info.Adapter=[string]$net.InterfaceDescription; $info.NetType=if($net.InterfaceDescription -match "Wi-Fi|Wireless|802.11|WLAN"){"Wi-Fi"}else{"Ethernet"}}
    } catch {}
    if($info.NetType -eq "None" -or $info.Adapter -eq "No Adapter") {
        try {
            $net=@(Get-CimInstance Win32_NetworkAdapter -EA SilentlyContinue) | Where-Object {$_.NetConnectionStatus -eq 2 -and $_.Name} | Select-Object -First 1
            if($net){$info.Adapter=[string]$net.Name; $info.NetType=if($net.Name -match "Wi-Fi|Wireless|802.11|WLAN"){"Wi-Fi"}else{"Ethernet"}}
        } catch {}
    }
    if($info.NetType -eq "None" -or $info.Adapter -eq "No Adapter") {
        try {
            $net=@(Get-WmiObject Win32_NetworkAdapterConfiguration -EA SilentlyContinue) | Where-Object {$_.IPEnabled -eq $true -and $_.Description} | Select-Object -First 1
            if($net){$info.Adapter=[string]$net.Description; $info.NetType=if($net.Description -match "Wi-Fi|Wireless|802.11|WLAN"){"Wi-Fi"}else{"Ethernet"}}
        } catch {}
    }
    try {
        $freeRam=if($os){$os.FreePhysicalMemory}else{$null}
        $totalRam=if($ram){$ram.TotalPhysicalMemory/1KB}else{$null}
        if($freeRam -and $totalRam -and $totalRam -gt 0){$info.RAMUsedPct=[math]::Round((($totalRam-$freeRam)/$totalRam)*100)}
    } catch {}
    return $info
}
$Global:ReducedMotionEnabled=$false
# Detect the real hardware before showing the dashboard, so System Overview
# opens with actual specifications instead of "Detecting..." placeholders.
try {
    $startupInfo = Get-SystemInfo
    if($startupInfo){
        $Global:SysInfo = [pscustomobject]$startupInfo
        $Global:SystemInfoLoaded = $true
        $Global:SystemInfoRefreshAt = Get-Date
    } else {
        $Global:SysInfo = [pscustomobject]@{OS="Windows";CPU="CPU not detected";GPU="GPU not detected";RAM=0;RAMType="Unknown";Adapter="Adapter not detected";NetType="Unknown";RAMUsedPct=0;Board="Motherboard not detected";BIOS="BIOS not detected";Storage="Storage not detected";Display="Display not detected";Arch=$env:PROCESSOR_ARCHITECTURE}
        $Global:SystemInfoLoaded = $true
    }
} catch {
    $Global:SysInfo = [pscustomobject]@{OS="Windows";CPU="CPU not detected";GPU="GPU not detected";RAM=0;RAMType="Unknown";Adapter="Adapter not detected";NetType="Unknown";RAMUsedPct=0;Board="Motherboard not detected";BIOS="BIOS not detected";Storage="Storage not detected";Display="Display not detected";Arch=$env:PROCESSOR_ARCHITECTURE}
    $Global:SystemInfoLoaded = $true
}
$Global:SystemInfoJob = $null
$Global:SystemInfoJobStarted = $true
$Global:SystemInfoLoaded = $true
$Global:SystemInfoRetry = $false
$Global:SystemInfoFallbackAttempted = $false
# Realtime hardware refresh state. The refresh runs off the WPF dispatcher so
# System Overview stays responsive while CIM/network providers are queried.
$Global:SystemInfoRefreshJob = $null
$Global:SystemInfoRefreshAt = [datetime]::MinValue
$Global:SystemInfoRefreshIntervalSeconds = 3
function Start-SystemInfoRefreshJob {
    if(-not $Global:SystemInfoLoaded -or $Global:SystemInfoRefreshJob){ return }
    try {
        if(Get-Command Start-ThreadJob -ErrorAction SilentlyContinue){
            $Global:SystemInfoRefreshJob=Start-ThreadJob -ScriptBlock ${function:Get-SystemInfo} -ErrorAction Stop
        } else {
            $Global:SystemInfoRefreshJob=Start-Job -ScriptBlock ${function:Get-SystemInfo} -ErrorAction Stop
        }
        $Global:SystemInfoRefreshAt=Get-Date
    } catch {
        $Global:SystemInfoRefreshJob=$null
        $Global:SystemInfoRefreshAt=Get-Date
    }
}
function Receive-SystemInfoRefreshJob {
    if(-not $Global:SystemInfoRefreshJob){ return }
    try {
        $state=[string]$Global:SystemInfoRefreshJob.State
        if($state -in @('Completed','Failed','Stopped')){
            if($state -eq 'Completed'){
                $result=Receive-Job -Job $Global:SystemInfoRefreshJob -ErrorAction SilentlyContinue | Select-Object -Last 1
                if($result -and $result.PSObject.Properties['CPU']){
                    $current=[ordered]@{}
                    foreach($property in @('OS','CPU','GPU','RAM','RAMType','Adapter','NetType','RAMUsedPct','Board','BIOS','Storage','Display','Arch')){
                        $p=$result.PSObject.Properties[$property]
                        if($p){$current[$property]=$p.Value}
                    }
                    if($current.Count -gt 0){
                        if(-not $Global:SysInfo){$Global:SysInfo=[pscustomobject]$current}
                        else { foreach($k in $current.Keys){ $v=$current[$k]; if($null -ne $v -and [string]$v -notin @('',"Unknown CPU","Unknown GPU","Unknown display","Unknown storage","No Adapter","None")){ $Global:SysInfo | Add-Member -MemberType NoteProperty -Name $k -Value $v -Force } } }
                    }
                }
            }
            Remove-Job -Job $Global:SystemInfoRefreshJob -Force -ErrorAction SilentlyContinue
            $Global:SystemInfoRefreshJob=$null
        }
    } catch {
        try { Remove-Job -Job $Global:SystemInfoRefreshJob -Force -ErrorAction SilentlyContinue } catch {}
        $Global:SystemInfoRefreshJob=$null
        # Keep the last good snapshot and retry quickly.
        $Global:SystemInfoRefreshAt=[datetime]::MinValue
    }
}
function Show-WinFormsHardwareFallback {
    try {
        Add-Type -AssemblyName System.Windows.Forms; Add-Type -AssemblyName System.Drawing; [System.Windows.Forms.Application]::EnableVisualStyles()
        $f=New-Object System.Windows.Forms.Form; $f.Text='LESS PROJECT - SYSTEM INFO'; $f.Width=720; $f.Height=520; $f.StartPosition='CenterScreen'; $f.BackColor=[System.Drawing.Color]::FromArgb(12,16,24); $f.ForeColor=[System.Drawing.Color]::White
        $title=New-Object System.Windows.Forms.Label; $title.Text='SYSTEM OVERVIEW'; $title.Font=New-Object System.Drawing.Font('Segoe UI',18,[System.Drawing.FontStyle]::Bold); $title.AutoSize=$true; $title.Location=New-Object System.Drawing.Point(24,20); [void]$f.Controls.Add($title)
        $table=New-Object System.Windows.Forms.TableLayoutPanel; $table.Location=New-Object System.Drawing.Point(24,70); $table.Size=New-Object System.Drawing.Size(650,330); $table.ColumnCount=2; $table.RowCount=9; $table.BackColor=[System.Drawing.Color]::FromArgb(22,31,45); $table.CellBorderStyle='Single'; $table.Padding=New-Object System.Windows.Forms.Padding(10); [void]$table.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle([System.Windows.Forms.SizeType]::Percent,28))); [void]$table.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle([System.Windows.Forms.SizeType]::Percent,72)))
        $s=$Global:SysInfo; $rows=@(@('CPU',[string]$s.CPU),@('GPU',[string]$s.GPU),@('RAM',("{0} GB" -f $s.RAM)),@('WINDOWS',[string]$s.OS),@('MOTHERBOARD',[string]$s.Board),@('BIOS',[string]$s.BIOS),@('STORAGE',[string]$s.Storage),@('DISPLAY',[string]$s.Display),@('NETWORK',("{0} / {1}" -f $s.NetType,$s.Adapter)))
        foreach($row in $rows){$l=New-Object System.Windows.Forms.Label; $l.Text=$row[0]; $l.Dock='Fill'; $l.TextAlign='MiddleLeft'; $l.Font=New-Object System.Drawing.Font('Segoe UI',9,[System.Drawing.FontStyle]::Bold); $l.ForeColor=[System.Drawing.Color]::LightGray; $v=New-Object System.Windows.Forms.Label; $v.Text=$row[1]; $v.Dock='Fill'; $v.TextAlign='MiddleLeft'; $v.Font=New-Object System.Drawing.Font('Segoe UI',10); $v.ForeColor=[System.Drawing.Color]::White; [void]$table.Controls.Add($l); [void]$table.Controls.Add($v)}
        [void]$f.Controls.Add($table); $close=New-Object System.Windows.Forms.Button; $close.Text='CLOSE'; $close.Width=120; $close.Height=34; $close.Location=New-Object System.Drawing.Point(554,420); $close.Add_Click({$f.Close()}); [void]$f.Controls.Add($close); [void]$f.ShowDialog()
    } catch { try {[System.Windows.Forms.MessageBox]::Show("Unable to start the UI: $($_.Exception.Message)",'LESS PROJECT')|Out-Null} catch {} }
}
