"@

# =========================================================
# SPLASH HELPER FUNCTIONS (soft chime sounds, click FX, background aura)
# =========================================================
function New-8BitBeepPlayer {
    param([double[]]$Frequencies,[int[]]$Durations,[double]$Volume=0.15)
    $sampleRate=44100
    $pcm=New-Object System.IO.MemoryStream
    $pcmWriter=New-Object System.IO.BinaryWriter($pcm)
    for($toneIndex=0;$toneIndex -lt $Frequencies.Count;$toneIndex++){
        $freq=[double]$Frequencies[$toneIndex]
        $durationMs=[int]$Durations[$toneIndex]
        $samples=[int]($sampleRate*$durationMs/1000)
        # Gentle attack/release avoids a sharp click while keeping the tone responsive.
        $attack=[math]::Max(1,[int]($sampleRate*0.006))
        $release=[math]::Max(1,[int]($sampleRate*0.022))
        for($i=0;$i -lt $samples;$i++){
            $envelope=[math]::Min(1.0,$i/[double]$attack)
            $envelope=[math]::Min($envelope,($samples-$i)/[double]$release)
            $phase=$i/[double]$sampleRate
            # Sine with a very quiet second harmonic: softer than the former square-wave beep.
            $wave=[math]::Sin(2*[math]::PI*$freq*$phase)+0.10*[math]::Sin(2*[math]::PI*($freq*2.01)*$phase)
            $pcmWriter.Write([int16]([math]::Round($Volume*32767*$envelope*$wave)))
        }
    }
    $pcmWriter.Flush()
    $data=[byte[]]$pcm.ToArray(); $pcm.Dispose()
    $dataLen=$data.Length
    $stream=New-Object System.IO.MemoryStream
    $writer=New-Object System.IO.BinaryWriter($stream)
    $writer.Write([System.Text.Encoding]::ASCII.GetBytes("RIFF")); $writer.Write([int](36+$dataLen)); $writer.Write([System.Text.Encoding]::ASCII.GetBytes("WAVE"))
    $writer.Write([System.Text.Encoding]::ASCII.GetBytes("fmt ")); $writer.Write([int]16); $writer.Write([int16]1); $writer.Write([int16]1); $writer.Write([int]$sampleRate); $writer.Write([int]($sampleRate*2)); $writer.Write([int16]2); $writer.Write([int16]16)
    $writer.Write([System.Text.Encoding]::ASCII.GetBytes("data")); $writer.Write([int]$dataLen); $writer.Write($data)
    $writer.Flush(); $stream.Position=0
    $player=New-Object System.Media.SoundPlayer($stream); $player.Load()
    return ,@($player,$stream)
}
function Initialize-UiBeep {
    # Private soft UI tone: independent of Windows sound-scheme/error sounds.
    try {
        if($Global:UiBeepPlayer){ return }
        $pair=New-8BitBeepPlayer -Frequencies @(659,784) -Durations @(20,30) -Volume 0.035
        $Global:UiBeepPlayer=$pair[0]; $Global:UiBeepStream=$pair[1]
    } catch {}
}
function Play-UiBeep {
    # Debounce repeated clicks so fast tapping cannot stack a burst of tones.
    if($Global:SoundFxEnabled -eq $false){ return }
    try {
        $now=[Environment]::TickCount64
        if($null -ne $Global:LastUiBeepTick -and (($now-[int64]$Global:LastUiBeepTick) -lt 150)){ return }
        $Global:LastUiBeepTick=$now
        if(-not $Global:UiBeepPlayer){ Initialize-UiBeep }
        if($Global:UiBeepPlayer){ $Global:UiBeepPlayer.Play() }
    } catch {}
}

function Initialize-NavHoverSound {
    if($Global:NavHoverSoundPlayer){ return }
    try {
        $pair=New-8BitBeepPlayer -Frequencies @(988) -Durations @(16) -Volume 0.018
        $Global:NavHoverSoundPlayer=$pair[0]; $Global:NavHoverSoundStream=$pair[1]
    } catch {}
}
function Play-NavHoverSound {
    if($Global:SoundFxEnabled -eq $false){ return }
    try {
        $now=[Environment]::TickCount64
        if($null -ne $Global:LastNavHoverTick -and (($now-[int64]$Global:LastNavHoverTick) -lt 110)){ return }
        $Global:LastNavHoverTick=$now
        if(-not $Global:NavHoverSoundPlayer){ Initialize-NavHoverSound }
        if($Global:NavHoverSoundPlayer){ $Global:NavHoverSoundPlayer.Play() }
    } catch {}
}
function Initialize-OneClickToggleSounds {
    if($Global:OneClickOnSoundPlayer -and $Global:OneClickOffSoundPlayer){ return }
    try {
        $onPair=New-GamingPcmPlayer -Frequencies @(560,760,1040) -Durations @(24,30,54) -Volume 0.10
        $offPair=New-GamingPcmPlayer -Frequencies @(760,540,360) -Durations @(24,30,58) -Volume 0.085
        $Global:OneClickOnSoundPlayer=$onPair[0]; $Global:OneClickOnSoundStream=$onPair[1]
        $Global:OneClickOffSoundPlayer=$offPair[0]; $Global:OneClickOffSoundStream=$offPair[1]
    } catch {}
}
function Play-OneClickToggleSound {
    param([ValidateSet("Click","On","Off")][string]$Type="Click")
    if($Global:SoundFxEnabled -eq $false){ return }
    try {
        # Non-blocking fast-click guard. Never use PlaySync or Start-Sleep here.
        $now=[Environment]::TickCount64
        if($null -ne $Global:LastOneClickSoundTick -and (($now-[int64]$Global:LastOneClickSoundTick) -lt 70)){ return }
        $Global:LastOneClickSoundTick=$now
        if($Type -eq "Click") { Play-UiBeep; return }
        Initialize-OneClickToggleSounds
        $player=if($Type -eq "On"){$Global:OneClickOnSoundPlayer}else{$Global:OneClickOffSoundPlayer}
        if($player){ $player.Play() }
    } catch {}
}

function Initialize-ReshadeButtonSounds {
    if($Global:ReshadeInstallSoundPlayer -and $Global:ReshadeHoverSoundPlayer -and $Global:ReshadeRoadSoundPlayer -and $Global:ReshadeUninstallSoundPlayer){ return }
    try {
        # Short, low-volume ascending chime for INSTALL: soft and easy on the ears.
        $installPair=New-8BitBeepPlayer -Frequencies @(392,523,659) -Durations @(18,24,42) -Volume 0.030
        $hoverPair=New-8BitBeepPlayer -Frequencies @(784) -Durations @(24) -Volume 0.018
        $roadPair=New-8BitBeepPlayer -Frequencies @(349,523) -Durations @(20,36) -Volume 0.028
        $uninstallPair=New-8BitBeepPlayer -Frequencies @(330,277,220) -Durations @(20,24,38) -Volume 0.028
        $Global:ReshadeInstallSoundPlayer=$installPair[0]; $Global:ReshadeInstallSoundStream=$installPair[1]
        $Global:ReshadeHoverSoundPlayer=$hoverPair[0]; $Global:ReshadeHoverSoundStream=$hoverPair[1]
        $Global:ReshadeRoadSoundPlayer=$roadPair[0]; $Global:ReshadeRoadSoundStream=$roadPair[1]
        $Global:ReshadeUninstallSoundPlayer=$uninstallPair[0]; $Global:ReshadeUninstallSoundStream=$uninstallPair[1]
    } catch {}
}
function Play-ReshadeHoverTone {
    if($Global:SoundFxEnabled -eq $false){ return }
    try {
        $now=[Environment]::TickCount64
        if($null -ne $Global:LastReshadeHoverTick -and (($now-[int64]$Global:LastReshadeHoverTick) -lt 180)){ return }
        $Global:LastReshadeHoverTick=$now
        Initialize-ReshadeButtonSounds
        if($Global:ReshadeHoverSoundPlayer){ $Global:ReshadeHoverSoundPlayer.Play() }
    } catch {}
}
function Play-ReshadeButtonTone {
    param([ValidateSet("Install","Road","Uninstall")][string]$Type)
    if($Global:SoundFxEnabled -eq $false){ return }
    try {
        $now=[Environment]::TickCount64
        if($null -ne $Global:LastReshadeToneTick -and (($now-[int64]$Global:LastReshadeToneTick) -lt 110)){ return }
        $Global:LastReshadeToneTick=$now
        Initialize-ReshadeButtonSounds
        $player=$null
        switch($Type){
            "Install" {$player=$Global:ReshadeInstallSoundPlayer}
            "Road" {$player=$Global:ReshadeRoadSoundPlayer}
            "Uninstall" {$player=$Global:ReshadeUninstallSoundPlayer}
        }
        if($player){$player.Play()}
    } catch {}
}
function New-GamingPcmPlayer {
    param([double[]]$Frequencies,[int[]]$Durations,[double]$Volume=0.20)
    $sampleRate=44100
    $pcm=New-Object System.IO.MemoryStream
    $pcmWriter=New-Object System.IO.BinaryWriter($pcm)
    for($toneIndex=0;$toneIndex -lt $Frequencies.Count;$toneIndex++){
        $freq=[double]$Frequencies[$toneIndex]
        $durationMs=[int]$Durations[$toneIndex]
        $samples=[int]($sampleRate*$durationMs/1000)
        $attack=[math]::Max(1,[int]($sampleRate*0.006))
        $release=[math]::Max(1,[int]($sampleRate*0.018))
        for($i=0;$i -lt $samples;$i++){
            $envelope=[math]::Min(1.0,$i/[double]$attack)
            $envelope=[math]::Min($envelope,($samples-$i)/[double]$release)
            $phase=$i/[double]$sampleRate
            # A soft harmonic gives the short UI tone a cleaner gaming-console character.
            $wave=[math]::Sin(2*[math]::PI*$freq*$phase)+0.16*[math]::Sin(2*[math]::PI*($freq*2.01)*$phase)
            $sample=[int16]([math]::Round($Volume*32767*$envelope*$wave))
            $pcmWriter.Write($sample)
        }
    }
    $pcmWriter.Flush()
    $data=[byte[]]$pcm.ToArray()
    $pcm.Dispose()
    $dataLen=$data.Length
    $stream=New-Object System.IO.MemoryStream
    $writer=New-Object System.IO.BinaryWriter($stream)
    $writer.Write([System.Text.Encoding]::ASCII.GetBytes("RIFF")); $writer.Write([int](36+$dataLen)); $writer.Write([System.Text.Encoding]::ASCII.GetBytes("WAVE"))
    $writer.Write([System.Text.Encoding]::ASCII.GetBytes("fmt ")); $writer.Write([int]16); $writer.Write([int16]1); $writer.Write([int16]1); $writer.Write([int]$sampleRate); $writer.Write([int]($sampleRate*2)); $writer.Write([int16]2); $writer.Write([int16]16)
    $writer.Write([System.Text.Encoding]::ASCII.GetBytes("data")); $writer.Write([int]$dataLen); $writer.Write($data)
    $writer.Flush(); $stream.Position=0
    $player=New-Object System.Media.SoundPlayer($stream); $player.Load()
    return ,@($player,$stream)
}
function Initialize-GamingSoundEffects {
    if($Global:ApplySoundPlayer -and $Global:CompletionSoundPlayer){ return }
    try {
        $applyPair=New-GamingPcmPlayer -Frequencies @(680,980) -Durations @(48,78) -Volume 0.18
        $donePair=New-GamingPcmPlayer -Frequencies @(740,1040,1320) -Durations @(42,48,82) -Volume 0.16
        $issuePair=New-GamingPcmPlayer -Frequencies @(420,300) -Durations @(72,105) -Volume 0.13
        $Global:ApplySoundPlayer=$applyPair[0]; $Global:ApplySoundStream=$applyPair[1]
        $Global:CompletionSoundPlayer=$donePair[0]; $Global:CompletionSoundStream=$donePair[1]
        $Global:IssueSoundPlayer=$issuePair[0]; $Global:IssueSoundStream=$issuePair[1]
    } catch {}
}
function Play-ApplyStartSound {
    if($Global:SoundFxEnabled -eq $false){ return }
    try {
        $now=[Environment]::TickCount64
