        $Global:LastApplySoundTick=$now
        if(-not $Global:ApplySoundPlayer){ Initialize-GamingSoundEffects }
        if($Global:ApplySoundPlayer){ $Global:ApplySoundPlayer.Play() }
    } catch {}
}
function Play-CompletionChime {
    if($Global:SoundFxEnabled -eq $false){ return }
    try {
