        if($Global:CompletionSoundPlayer){ $Global:CompletionSoundPlayer.Play() }
    } catch {}
}
function Play-IssueTone {
    if($Global:SoundFxEnabled -eq $false){ return }
    try {
        if(-not $Global:IssueSoundPlayer){ Initialize-GamingSoundEffects }
        if($Global:IssueSoundPlayer){ $Global:IssueSoundPlayer.Play() }
    } catch {}
}
