if($Global:LessProjectScriptRoot){ $script:LessReShadeHelperPath = Join-Path $Global:LessProjectScriptRoot 'ReShade-FiveM.ps1' }
elseif($PSScriptRoot){ $script:LessReShadeHelperPath = Join-Path $PSScriptRoot 'ReShade-FiveM.ps1' }
if($script:LessReShadeHelperPath -and (Test-Path -LiteralPath $script:LessReShadeHelperPath -PathType Leaf)){
    . $script:LessReShadeHelperPath
