function Load-LessProjectSettings {
    try {
        if(Test-Path -LiteralPath $Global:LessProjectSettingsFile -PathType Leaf){
            $saved=Get-Content -LiteralPath $Global:LessProjectSettingsFile -Raw -ErrorAction Stop | ConvertFrom-Json
            if($saved.GameFolderPath){ $Global:GameFolderPath=[string]$saved.GameFolderPath }
            if($null -ne $saved.SoundFxEnabled){ $Global:SoundFxEnabled=[bool]$saved.SoundFxEnabled }
            if($saved.MainMotionProfile -and @("Off","Soft","Normal","Fast") -contains [string]$saved.MainMotionProfile){ $Global:MainMotionProfile=[string]$saved.MainMotionProfile }
            if($null -ne $saved.RestorePointSkipped){ $Global:RestorePointSkipped=[bool]$saved.RestorePointSkipped }
            # HwidGateCompleted is no longer trusted from disk. KeyAuth (or a
            # DPAPI license sidecar) is the only persistent login proof.
        }
    } catch {}
}
