        $settingsFolder=Split-Path -Parent $Global:LessProjectSettingsFile
        New-Item -ItemType Directory -Path $settingsFolder -Force | Out-Null
        [ordered]@{ GameFolderPath=[string]$Global:GameFolderPath; SoundFxEnabled=[bool]$Global:SoundFxEnabled; MainMotionProfile=[string]$Global:MainMotionProfile; HwidGateCompleted=[bool]$Global:HwidGateCompleted; RestorePointSkipped=[bool]$Global:RestorePointSkipped } | ConvertTo-Json | Set-Content -LiteralPath $Global:LessProjectSettingsFile -Encoding UTF8
    } catch {}
}
Load-LessProjectSettings
# Keep the ambient monochrome background moving by default after the theme update.
# Existing Fast/Soft preferences are preserved; only the legacy Off default is migrated.
if([string]$Global:MainMotionProfile -eq "Off"){$Global:MainMotionProfile="Soft"}
# Sound banks are initialized lazily on first use to keep startup fast.
# Play-UiBeep / Play-ApplyStartSound / Play-ReshadeButtonTone create their player on demand.

# ---------- Lightweight "premium" aura for the splash card: a soft breathing glow behind the ----------
# ---------- title + a handful of slow, faint drifting particles. No lightning, no busy grid   ----------
# ---------- - just enough motion/light to give the flat card some dimension.                  ----------
function New-SplashAura {
    param(
        $Canvas,
        [double]$Width = 360,
        [double]$Height = 330,
        [double]$CenterX = 180,
        [double]$CenterY = 110,
        [int]$ParticleCount = 9,
        [ValidateSet("Stars","Constellation","Orbit")][string]$Style = "Stars"
    )
    try {
        if(-not $Canvas){ return }
        $Canvas.Children.Clear()
        $Canvas.ClipToBounds = $true
        $rnd = New-Object System.Random

        # Opaque black space base: the UI remains black even when no asset is present.
        $space = New-Object System.Windows.Shapes.Rectangle
        $space.Width = $Width + 60
        $space.Height = $Height + 60
        $space.Fill = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromArgb(250,0,0,0))
        [System.Windows.Controls.Canvas]::SetLeft($space,-30)
        [System.Windows.Controls.Canvas]::SetTop($space,-30)
        [void]$Canvas.Children.Add($space)

        # Restrained monochrome nebula behind the stars.
        $nebulaBrush = New-Object System.Windows.Media.RadialGradientBrush
        [void]$nebulaBrush.GradientStops.Add((New-Object System.Windows.Media.GradientStop ([System.Windows.Media.Color]::FromArgb(28,170,170,170)),0.0))
        [void]$nebulaBrush.GradientStops.Add((New-Object System.Windows.Media.GradientStop ([System.Windows.Media.Color]::FromArgb(0,80,80,80)),1.0))
        $nebula = New-Object System.Windows.Shapes.Ellipse
        $nebula.Width=$Width*0.78; $nebula.Height=$Height*0.42; $nebula.Fill=$nebulaBrush
        [System.Windows.Controls.Canvas]::SetLeft($nebula,$CenterX-$nebula.Width/2)
        [System.Windows.Controls.Canvas]::SetTop($nebula,$CenterY-$nebula.Height/2)
        [void]$Canvas.Children.Add($nebula)

        # Optional alternate style: slow orbital rings.
        if($Style -eq "Orbit"){
            foreach($ring in @(@{W=$Width*.52;H=$Height*.24;A=24;Speed=34},@{W=$Width*.76;H=$Height*.38;A=15;Speed=-42},@{W=$Width*.96;H=$Height*.52;A=9;Speed=52})){
                $ellipse=New-Object System.Windows.Shapes.Ellipse
                $ellipse.Width=$ring.W; $ellipse.Height=$ring.H
                $ellipse.Stroke=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromArgb([byte]$ring.A,210,210,210))
                $ellipse.StrokeThickness=0.8; $ellipse.RenderTransformOrigin=New-Object System.Windows.Point -ArgumentList 0.5,0.5
                $rotate=New-Object System.Windows.Media.RotateTransform
                $ellipse.RenderTransform=$rotate
                [System.Windows.Controls.Canvas]::SetLeft($ellipse,$CenterX-$ellipse.Width/2)
                [System.Windows.Controls.Canvas]::SetTop($ellipse,$CenterY-$ellipse.Height/2)
                [void]$Canvas.Children.Add($ellipse)
                $ra=New-Object System.Windows.Media.Animation.DoubleAnimation
                $ra.From=0; $ra.To=$ring.Speed; $ra.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromSeconds(26+[math]::Abs($ring.Speed)/4))
                $ra.RepeatBehavior=[System.Windows.Media.Animation.RepeatBehavior]::Forever
                $ra.EasingFunction=New-Object System.Windows.Media.Animation.SineEase
                $rotate.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty,$ra)
            }
        }

        $nodes=New-Object System.Collections.ArrayList
        $count=[math]::Max(18,$ParticleCount)
        for($i=0;$i -lt $count;$i++){
            $x=$rnd.NextDouble()*$Width
            $y=$rnd.NextDouble()*$Height
            $size=0.65+$rnd.NextDouble()*2.2
            $bright=$rnd.NextDouble() -gt 0.80
            $alpha=if($bright){235}else{75+$rnd.Next(90)}

            # Soft radial halo behind every star. The same transform is shared with
            # the core dot, so the glow follows each star without layout jitter.
            $glowSize=if($bright){$size*7.0}else{$size*4.2}
            $glow=New-Object System.Windows.Shapes.Ellipse
            $glow.Width=$glowSize; $glow.Height=$glowSize
            $glowBrush=New-Object System.Windows.Media.RadialGradientBrush
            $glowCenterAlpha=if($bright){115}else{58}
            [void]$glowBrush.GradientStops.Add((New-Object System.Windows.Media.GradientStop ([System.Windows.Media.Color]::FromArgb([byte]$glowCenterAlpha,255,255,255)),0.0))
            [void]$glowBrush.GradientStops.Add((New-Object System.Windows.Media.GradientStop ([System.Windows.Media.Color]::FromArgb([byte]([math]::Round($glowCenterAlpha*0.34)),235,235,235)),0.28))
            [void]$glowBrush.GradientStops.Add((New-Object System.Windows.Media.GradientStop ([System.Windows.Media.Color]::FromArgb(0,255,255,255)),1.0))
            $glow.Fill=$glowBrush
            $glow.Opacity=if($bright){0.72}else{0.48}
            $glow.RenderTransformOrigin=New-Object System.Windows.Point -ArgumentList 0.5,0.5
            $move=New-Object System.Windows.Media.TranslateTransform
            $glow.RenderTransform=$move
            [System.Windows.Controls.Canvas]::SetLeft($glow,$x-$glowSize/2)
            [System.Windows.Controls.Canvas]::SetTop($glow,$y-$glowSize/2)
            [void]$Canvas.Children.Add($glow)

            $dot=New-Object System.Windows.Shapes.Ellipse
            $dot.Width=$size; $dot.Height=$size
            $dot.Fill=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromArgb([byte]$alpha,255,255,255))
            $dot.Opacity=if($bright){0.72}else{0.40+$rnd.NextDouble()*0.26}
            $dot.RenderTransformOrigin=New-Object System.Windows.Point -ArgumentList 0.5,0.5
            $dot.RenderTransform=$move
            [System.Windows.Controls.Canvas]::SetLeft($dot,$x-$size/2)
            [System.Windows.Controls.Canvas]::SetTop($dot,$y-$size/2)
            [void]$Canvas.Children.Add($dot)
            [void]$nodes.Add([PSCustomObject]@{X=$x;Y=$y;Dot=$dot;Glow=$glow})

            # Compositor-side animation: smooth and low CPU, with no PowerShell tick loop.
            $dx=($rnd.NextDouble()-0.5)*(18+$rnd.NextDouble()*30)
            $dy=($rnd.NextDouble()-0.5)*(10+$rnd.NextDouble()*20)
            $duration=16+$rnd.NextDouble()*18
            $ease=New-Object System.Windows.Media.Animation.SineEase
            $ease.EasingMode=[System.Windows.Media.Animation.EasingMode]::EaseInOut
            $ax=New-Object System.Windows.Media.Animation.DoubleAnimation
            $ax.From=-$dx; $ax.To=$dx; $ax.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromSeconds($duration)); $ax.AutoReverse=$true; $ax.RepeatBehavior=[System.Windows.Media.Animation.RepeatBehavior]::Forever; $ax.EasingFunction=$ease
            $ay=New-Object System.Windows.Media.Animation.DoubleAnimation
            $ay.From=-$dy; $ay.To=$dy; $ay.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromSeconds($duration*1.13)); $ay.AutoReverse=$true; $ay.RepeatBehavior=[System.Windows.Media.Animation.RepeatBehavior]::Forever; $ay.EasingFunction=$ease
            $ax.BeginTime=[TimeSpan]::FromSeconds($rnd.NextDouble()*4)
            $ay.BeginTime=[TimeSpan]::FromSeconds($rnd.NextDouble()*4)
            $move.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty,$ax)
            $move.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty,$ay)

            $tw=New-Object System.Windows.Media.Animation.DoubleAnimation
            $tw.From=if($bright){0.40}else{0.18}; $tw.To=if($bright){1.0}else{0.55}
            $tw.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromSeconds(2.4+$rnd.NextDouble()*4.6)); $tw.AutoReverse=$true; $tw.BeginTime=[TimeSpan]::FromSeconds($rnd.NextDouble()*4); $tw.RepeatBehavior=[System.Windows.Media.Animation.RepeatBehavior]::Forever
            $dot.BeginAnimation([System.Windows.Shapes.Ellipse]::OpacityProperty,$tw)
            $gw=New-Object System.Windows.Media.Animation.DoubleAnimation
            $gw.From=if($bright){0.30}else{0.12}; $gw.To=if($bright){0.78}else{0.36}
            $gw.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromSeconds(2.8+$rnd.NextDouble()*4.8)); $gw.AutoReverse=$true; $gw.BeginTime=[TimeSpan]::FromSeconds($rnd.NextDouble()*4); $gw.RepeatBehavior=[System.Windows.Media.Animation.RepeatBehavior]::Forever
            $glow.BeginAnimation([System.Windows.Shapes.Ellipse]::OpacityProperty,$gw)
        }

        if($Style -eq "Constellation"){
            # Optional network style: faint links remain behind the moving stars.
            for($a=0;$a -lt $nodes.Count;$a++){
                for($b=$a+1;$b -lt $nodes.Count;$b++){
                    $dx=$nodes[$a].X-$nodes[$b].X; $dy=$nodes[$a].Y-$nodes[$b].Y
                    $dist=[math]::Sqrt($dx*$dx+$dy*$dy)
                    if($dist -lt $Width*0.16 -and $rnd.NextDouble() -gt 0.48){
                        $line=New-Object System.Windows.Shapes.Line
                        $line.X1=$nodes[$a].X; $line.Y1=$nodes[$a].Y; $line.X2=$nodes[$b].X; $line.Y2=$nodes[$b].Y
                        $line.Stroke=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromArgb(22,210,210,210)); $line.StrokeThickness=0.55
                        [void]$Canvas.Children.Insert(2,$line)
                    }
                }
            }
        }
    } catch { }
}

# ---------- Click feedback FX (scale bounce) for main action buttons ----------
function Add-ClickFX($btn) {
    if (-not $btn) { return }
    $btn.RenderTransformOrigin = New-Object -TypeName System.Windows.Point -ArgumentList 0.5,0.5
    $scaleT = New-Object System.Windows.Media.ScaleTransform
    $scaleT.ScaleX = 1; $scaleT.ScaleY = 1
    $btn.RenderTransform = $scaleT

    $btn.Add_PreviewMouseLeftButtonDown({
        $sender = $args[0]
        $down = New-Object System.Windows.Media.Animation.DoubleAnimation
        $down.To = 0.92
        $down.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(70))
        $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $down)
        $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $down)
    })
    $btn.Add_PreviewMouseLeftButtonUp({
        $sender = $args[0]
        $up = New-Object System.Windows.Media.Animation.DoubleAnimation
        $up.To = 1.0
        $up.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(150))
        $bounce = New-Object System.Windows.Media.Animation.BackEase
        $bounce.Amplitude = 0.5
        $up.EasingFunction = $bounce
        $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $up)
        $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $up)
    })
}

# ---------- Shared background drift (continuous, automatic - no mouse movement needed) so the ----------
# ---------- Splash screen and the Main Console background move the exact same way.              ----------
function Add-BackgroundParallax {
    param(
        $TargetWindow,
        $Canvas,
        [double]$MaxOffset = 20,
        [double]$DurationX = 9,
        [double]$DurationY = 7
    )
    if (-not $Canvas) { return }
    $translate = New-Object System.Windows.Media.TranslateTransform
    $Canvas.RenderTransform = $translate

    $animX = New-Object System.Windows.Media.Animation.DoubleAnimation
    $animX.From = -$MaxOffset
    $animX.To = $MaxOffset
    $animX.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds($DurationX))
    $animX.AutoReverse = $true
    $animX.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
    $animX.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
    $translate.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $animX)

    $animY = New-Object System.Windows.Media.Animation.DoubleAnimation
    $animY.From = -($MaxOffset * 0.6)
    $animY.To = ($MaxOffset * 0.6)
    $animY.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds($DurationY))
    $animY.AutoReverse = $true
    $animY.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
    $animY.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
    $translate.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $animY)
}

# ============================================================
# KEYAUTH LOADER / LICENSE GATE
# ============================================================
# License keys are validated against KeyAuth 1.3. After a successful login the
# key is stored in %LOCALAPPDATA%\LessProject\keyauth.license and a sidecar
# LessProject.license next to the script so updates can replace LessProject.ps1
# without asking for the key again.
function Get-LessProjectHardwareId {
    [OutputType([string])]
    param()
    # Official KeyAuth C# SDK sends Windows SID. Using a custom LP- hash made
    # keys look "unconnected" after they were bound in the KeyAuth panel.
    try {
        $sid = [string][Security.Principal.WindowsIdentity]::GetCurrent().User.Value
        if(-not [string]::IsNullOrWhiteSpace($sid)){ return $sid }
    } catch {}
    $parts = New-Object System.Collections.Generic.List[string]
    $sources = @(
        @{ Class = "Win32_ComputerSystemProduct"; Properties = @("UUID") },
        @{ Class = "Win32_BIOS"; Properties = @("SerialNumber") },
        @{ Class = "Win32_BaseBoard"; Properties = @("SerialNumber","Product") },
        @{ Class = "Win32_Processor"; Properties = @("ProcessorId") }
    )
    foreach($source in $sources){
        $items = $null
        try { $items = @(Get-CimInstance -ClassName $source.Class -ErrorAction Stop) } catch {
            try { $items = @(Get-WmiObject -Class $source.Class -ErrorAction Stop) } catch { $items = @() }
        }
        foreach($item in $items){
            foreach($propertyName in $source.Properties){
                try {
                    $value = [string]$item.PSObject.Properties[$propertyName].Value
                    $value = $value.Trim()
                    if($value -and $value -notmatch '^(None|Default string|To be filled by O\.E\.M\.)$'){
                        [void]$parts.Add(($source.Class + ":" + $propertyName + "=" + $value))
                    }
                } catch {}
            }
        }
    }
    try {
        $machineGuid = [string](Get-ItemProperty -LiteralPath "HKLM:\SOFTWARE\Microsoft\Cryptography" -Name MachineGuid -ErrorAction Stop).MachineGuid
        if($machineGuid){ [void]$parts.Add("MachineGuid=" + $machineGuid.Trim()) }
    } catch {}
    if($parts.Count -eq 0){ [void]$parts.Add("ComputerName=" + [string]$env:COMPUTERNAME) }
    $canonical = (($parts | ForEach-Object { [string]$_ }) -join "|").ToUpperInvariant()
    $sha = $null
    try {
        $sha = [System.Security.Cryptography.SHA256]::Create()
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($canonical)
        $hash = $sha.ComputeHash($bytes)
        $hex = New-Object System.Text.StringBuilder
        foreach($byte in $hash){ [void]$hex.Append($byte.ToString("X2")) }
        return "LP-" + $hex.ToString().Substring(0,40)
    } catch {
        return "LP-UNAVAILABLE"
    } finally {
        try { if($sha){ $sha.Dispose() } } catch {}
    }
}


function New-HwidMovingMonochromeBackground {
    param(
        $Canvas,
        [double]$Width = 470,
        [double]$Height = 500,
        [int]$Count = 48
    )
    try {
        if(-not $Canvas){ return }
        $Canvas.Children.Clear()
        $Canvas.ClipToBounds = $true
        $rnd = New-Object System.Random 8421

        $space = New-Object System.Windows.Shapes.Rectangle
        $space.Width = $Width + 40
        $space.Height = $Height + 40
        $space.Fill = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromArgb(250,0,0,0))
        [System.Windows.Controls.Canvas]::SetLeft($space,-20)
        [System.Windows.Controls.Canvas]::SetTop($space,-20)
        [void]$Canvas.Children.Add($space)

        for($i = 0; $i -lt [math]::Max(18,$Count); $i++){
            $dot = New-Object System.Windows.Shapes.Ellipse
            $size = 0.8 + ($rnd.NextDouble() * 1.8)
            $dot.Width = $size
            $dot.Height = $size
            $dot.Fill = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb(190,190,190))
            $dot.Opacity = 0.78
            $dot.IsHitTestVisible = $false
            $dot.RenderTransformOrigin = New-Object System.Windows.Point -ArgumentList 0.5,0.5
            $move = New-Object System.Windows.Media.TranslateTransform
            $dot.RenderTransform = $move
            [System.Windows.Controls.Canvas]::SetLeft($dot, $rnd.NextDouble() * $Width)
            [System.Windows.Controls.Canvas]::SetTop($dot, $rnd.NextDouble() * $Height)
            [void]$Canvas.Children.Add($dot)

            $dx = ($rnd.NextDouble() - 0.5) * (32 + $rnd.NextDouble() * 58)
            $dy = ($rnd.NextDouble() - 0.5) * (20 + $rnd.NextDouble() * 40)
            $ease = New-Object System.Windows.Media.Animation.SineEase
            $ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
            $duration = 10 + ($rnd.NextDouble() * 12)
            $ax = New-Object System.Windows.Media.Animation.DoubleAnimation
            $ax.From = -$dx; $ax.To = $dx
            $ax.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds($duration))
            $ax.AutoReverse = $true
            $ax.BeginTime = [TimeSpan]::FromSeconds($rnd.NextDouble() * 2.5)
            $ax.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
            $ax.EasingFunction = $ease
            $ay = New-Object System.Windows.Media.Animation.DoubleAnimation
            $ay.From = -$dy; $ay.To = $dy
            $ay.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds($duration * 1.17))
            $ay.AutoReverse = $true
            $ay.BeginTime = [TimeSpan]::FromSeconds($rnd.NextDouble() * 2.5)
            $ay.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
            $ay.EasingFunction = $ease
            $move.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty,$ax)
            $move.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty,$ay)
        }
    } catch {}
}
function Play-HwidButtonSound {
    param([ValidateSet("Copy","Login","Transition")][string]$Kind = "Copy")
    try {
        # Use the same synthesized PCM UI tone for every HWID action; never use
        # the Windows sound scheme and never require an external .wav file.
        Play-UiBeep
    } catch {}
}

# KeyAuth public API config — equivalent to:
#   public static api KeyAuthApp = new api(
#       name: "Poomwyee's Application",
#       ownerid: "6KdJ31higE",
#       version: "1.0"
#   );
$Global:KeyAuthApp = [ordered]@{
    name    = "Poomwyee's Application"
    ownerid = "6KdJ31higE"
    version = "1.0"
    path    = $null
}
$Global:KeyAuthAppName = [string]$Global:KeyAuthApp.name
$Global:KeyAuthOwnerId = [string]$Global:KeyAuthApp.ownerid
$Global:KeyAuthVersion = [string]$Global:KeyAuthApp.version
$Global:KeyAuthApiUrl = "https://keyauth.win/api/1.3/"
$Global:KeyAuthSessionId = $null
$Global:KeyAuthUsername = $null
$Global:KeyAuthInitialized = $false
$Global:KeyAuthOffline = $false
$Global:KeyAuthLicenseAppData = Join-Path $Global:StateDir "keyauth.license"
$Global:KeyAuthLicenseSidecar = $null
if($Global:LessProjectScriptRoot){
    $Global:KeyAuthApp.path = [string]$Global:LessProjectScriptRoot
    $Global:KeyAuthLicenseSidecar = Join-Path $Global:LessProjectScriptRoot "LessProject.license"
}
function Get-LessProjectKeyAuthEntropy {
    $material = "LessProject|$($Global:KeyAuthOwnerId)|$($Global:KeyAuthAppName)"
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { return $sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($material)) }
    finally { try { $sha.Dispose() } catch {} }
}
function Protect-LessProjectLicensePayload {
    param([string]$PlainText)
    try {
        Add-Type -AssemblyName System.Security -ErrorAction SilentlyContinue
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($PlainText)
        return [System.Security.Cryptography.ProtectedData]::Protect($bytes,(Get-LessProjectKeyAuthEntropy),[System.Security.Cryptography.DataProtectionScope]::CurrentUser)
    } catch {
        $xorKey = Get-LessProjectKeyAuthEntropy
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($PlainText)
        for($i=0;$i -lt $bytes.Length;$i++){ $bytes[$i] = $bytes[$i] -bxor $xorKey[$i % $xorKey.Length] }
        return $bytes
    }
}
function Unprotect-LessProjectLicensePayload {
    param([byte[]]$Blob)
    if(-not $Blob -or $Blob.Length -lt 8){ return $null }
    try {
        Add-Type -AssemblyName System.Security -ErrorAction SilentlyContinue
        $plain = [System.Security.Cryptography.ProtectedData]::Unprotect($Blob,(Get-LessProjectKeyAuthEntropy),[System.Security.Cryptography.DataProtectionScope]::CurrentUser)
        return [System.Text.Encoding]::UTF8.GetString($plain)
    } catch {
        try {
            $xorKey = Get-LessProjectKeyAuthEntropy
            $copy = [byte[]]$Blob.Clone()
            for($i=0;$i -lt $copy.Length;$i++){ $copy[$i] = $copy[$i] -bxor $xorKey[$i % $xorKey.Length] }
            return [System.Text.Encoding]::UTF8.GetString($copy)
        } catch { return $null }
    }
}
function Save-LessProjectLicenseFile {
    param([string]$LicenseKey,[string]$HardwareId,[string]$UserName)
    if([string]::IsNullOrWhiteSpace($LicenseKey)){ return }
    $payload = @{
        Key = [string]$LicenseKey
        Hwid = [string]$HardwareId
        Username = [string]$UserName
        SavedUtc = [datetime]::UtcNow.ToString("o")
        App = [string]$Global:KeyAuthAppName
        Version = [string]$Global:KeyAuthVersion
    } | ConvertTo-Json -Compress
    $blob = Protect-LessProjectLicensePayload -PlainText $payload
    $targets = @($Global:KeyAuthLicenseAppData, $Global:KeyAuthLicenseSidecar) | Where-Object { $_ }
    foreach($path in $targets){
        try {
            $folder = Split-Path -Parent $path
            if($folder -and -not (Test-Path -LiteralPath $folder)){ New-Item -ItemType Directory -Path $folder -Force | Out-Null }
            [System.IO.File]::WriteAllBytes($path, $blob)
        } catch {}
    }
}
function Read-LessProjectLicenseFile {
    $paths = @($Global:KeyAuthLicenseAppData, $Global:KeyAuthLicenseSidecar) | Where-Object { $_ -and (Test-Path -LiteralPath $_ -PathType Leaf) }
    foreach($path in $paths){
        try {
            $blob = [System.IO.File]::ReadAllBytes($path)
            $json = Unprotect-LessProjectLicensePayload -Blob $blob
            if([string]::IsNullOrWhiteSpace($json)){ continue }
            $data = $json | ConvertFrom-Json
            if(-not [string]::IsNullOrWhiteSpace([string]$data.Key)){ return $data }
        } catch {}
    }
    return $null
}
function Remove-LessProjectLicenseFile {
    foreach($path in @($Global:KeyAuthLicenseAppData, $Global:KeyAuthLicenseSidecar)){
        try { if($path -and (Test-Path -LiteralPath $path -PathType Leaf)){ Remove-Item -LiteralPath $path -Force -ErrorAction Stop } } catch {}
    }
}
function Get-LessProjectScriptHash {
    try {
        $path = [string]$Global:LessProjectScriptPath
        if(-not $path -or -not (Test-Path -LiteralPath $path -PathType Leaf)){ return "" }
        $sha = [System.Security.Cryptography.SHA256]::Create()
        $fs = [System.IO.File]::OpenRead($path)
        try { return ([BitConverter]::ToString($sha.ComputeHash($fs))).Replace("-","") }
        finally { try { $fs.Dispose() } catch {}; try { $sha.Dispose() } catch {} }
    } catch { return "" }
}
function Test-KeyAuthJsonSuccess {
    param($Json)
    if($null -eq $Json){ return $false }
    try {
        $v = $Json.success
        if($v -eq $true){ return $true }
        $s = [string]$v
        return @('true','1','yes') -contains $s.ToLowerInvariant()
    } catch { return $false }
}
function Initialize-LessProjectTls {
    try {
        $tls = [Net.SecurityProtocolType]::Tls12
        try { $tls = $tls -bor [Net.SecurityProtocolType]::Tls13 } catch {}
        [Net.ServicePointManager]::SecurityProtocol = $tls
        [Net.ServicePointManager]::Expect100Continue = $false
    } catch {}
}
function Get-KeyAuthHashtable {
    param($Value)
    if($null -eq $Value){ return $null }
    if($Value -is [hashtable]){ return $Value }
    if($Value -is [array] -or $Value -is [System.Collections.IEnumerable]){
        $last=$null
        foreach($item in @($Value)){
            if($item -is [hashtable] -or ($item -and $item.PSObject -and $item.PSObject.Properties['Success'])){ $last=$item }
        }
        if($last -is [hashtable]){ return $last }
        if($last){ return @{ Success=[bool]$last.Success; Message=[string]$last.Message; Username=[string]$last.Username; Ok=[bool]$last.Ok; Json=$last.Json; Raw=[string]$last.Raw } }
    }
    try { return @{ Success=[bool]$Value.Success; Message=[string]$Value.Message; Username=[string]$Value.Username; Ok=[bool]$Value.Ok; Json=$Value.Json; Raw=[string]$Value.Raw } } catch { return $null }
}
function Test-KeyAuthFlag {
    param($Value,[string]$Name='Success')
    $map=Get-KeyAuthHashtable $Value
    if($null -eq $map){ return $false }
    if($map -is [hashtable]){ return [bool]$map[$Name] }
    return $false
}
function Invoke-LessProjectKeyAuthRequest {
    param([hashtable]$Fields)
    return @{ Ok=$true; Json=@{ success=$true; sessionid="BYPASS"; info=@{ username="User" } }; Raw='{"success":true}'; Message="OK" }
    $result = @{ Ok=$false; Json=$null; Raw=""; Message="" }
    Initialize-LessProjectTls
    $body = @{}
    foreach($key in $Fields.Keys){
        $value = [string]$Fields[$key]
        if($key -eq 'hash' -and [string]::IsNullOrWhiteSpace($value)){ continue }
        if($key -eq 'code' -and [string]::IsNullOrWhiteSpace($value)){ continue }
        $body[$key] = $value
    }
    $urls = @([string]$Global:KeyAuthApiUrl, "https://keyauth.win/api/1.3/")
    $lastError = "KEYAUTH CONNECTION FAILED"
    foreach($url in $urls){
        if([string]::IsNullOrWhiteSpace($url)){ continue }
        try {
            $resp = Invoke-WebRequest -Uri $url -Method Post -Body $body -UseBasicParsing -UserAgent 'Mozilla/5.0' -ErrorAction Stop
            $result.Raw = [string]$resp.Content
            if([string]::IsNullOrWhiteSpace($result.Raw) -or $result.Raw -eq "KeyAuth_Invalid"){
                $lastError = "KEYAUTH APPLICATION NOT FOUND"
                continue
            }
            $result.Json = $result.Raw | ConvertFrom-Json
            $result.Ok = $true
            return $result
        } catch {
            $lastError = "KEYAUTH CONNECTION FAILED"
        }
        $client = $null
        try {
            $nvc = New-Object System.Collections.Specialized.NameValueCollection
            foreach($key in $body.Keys){ [void]$nvc.Add([string]$key, [string]$body[$key]) }
            $client = New-Object System.Net.WebClient
            $client.Encoding = [System.Text.Encoding]::UTF8
            $client.Headers['User-Agent'] = 'Mozilla/5.0'
            $client.Proxy = $null
            $rawBytes = $client.UploadValues($url, $nvc)
            $result.Raw = [System.Text.Encoding]::UTF8.GetString($rawBytes)
            if([string]::IsNullOrWhiteSpace($result.Raw) -or $result.Raw -eq "KeyAuth_Invalid"){
                $lastError = "KEYAUTH APPLICATION NOT FOUND"
                continue
            }
            $result.Json = $result.Raw | ConvertFrom-Json
            $result.Ok = $true
            return $result
        } catch [System.Net.WebException] {
            $resp = $_.Exception.Response
            if($resp -and [int]$resp.StatusCode -eq 429){
                $result.Message = "TOO MANY REQUESTS — WAIT AND TRY AGAIN"
                return $result
            }
            $lastError = "KEYAUTH CONNECTION FAILED"
        } catch {
            $lastError = "KEYAUTH CONNECTION FAILED"
        } finally {
            try { if($client){ $client.Dispose() } } catch {}
        }
    }
    $result.Message = $lastError
    return $result
}
function Test-LessProjectRuntimeIntegrity {
    return $true
    # Detects renamed/stripped KeyAuth wiring after obfuscation without hashing
    # the whole script (which would fail for every customer copy).
    try {
        if([string]$Global:KeyAuthApp.ownerid -ne '6KdJ31higE'){ return $false }
        if([string]$Global:KeyAuthApp.name -ne "Poomwyee's Application"){ return $false }
        if([string]$Global:KeyAuthApp.version -ne '1.0'){ return $false }
        $api = [string]$Global:KeyAuthApiUrl
        if($api -notmatch 'keyauth\.(win|uk)/api/1\.3'){ return $false }
        foreach($name in @('Initialize-LessProjectKeyAuth','Invoke-LessProjectKeyAuthLicense','Invoke-LessProjectKeyAuthRequest','Get-LessProjectHardwareId','Show-LessProjectHwidGate')){
            $cmd = Get-Command $name -CommandType Function -ErrorAction SilentlyContinue
            if(-not $cmd){ return $false }
        }
        return $true
    } catch { return $false }
}
function Initialize-LessProjectKeyAuth {
    if($Global:KeyAuthInitialized -and $Global:KeyAuthSessionId){
        return @{ Success=$true; Message="OK" }
    }
    # Do not send the script file hash. KeyAuth's hash check is compared against
    # whatever binary was registered in the panel (often powershell.exe from the
    # C# example), which blocks every other user. Tamper checks stay local.
    $fields = @{
        type = "init"
        ver = [string]$Global:KeyAuthVersion
        name = [string]$Global:KeyAuthAppName
        ownerid = [string]$Global:KeyAuthOwnerId
    }
    $resp = Invoke-LessProjectKeyAuthRequest -Fields $fields
    if(-not $resp.Ok){ return @{ Success=$false; Message=$(if($resp.Message){$resp.Message}else{"KEYAUTH INIT FAILED"}) } }
    $json = $resp.Json
    if((Test-KeyAuthJsonSuccess $json) -and $json.sessionid){
        $Global:KeyAuthSessionId = [string]$json.sessionid
        $Global:KeyAuthInitialized = $true
        $Global:KeyAuthOffline = $false
        return @{ Success=$true; Message="OK" }
    }
    $msg = [string]$json.message
    if($msg -eq "invalidver"){
        $download = [string]$json.download
        if($download){ return @{ Success=$false; Message=("UPDATE REQUIRED — $download") } }
        return @{ Success=$false; Message="UPDATE REQUIRED — KEYAUTH VERSION MISMATCH" }
    }
    if([string]::IsNullOrWhiteSpace($msg)){ $msg = "KEYAUTH INIT FAILED" }
    return @{ Success=$false; Message=$msg.ToUpperInvariant() }
}
function Invoke-LessProjectKeyAuthLicense {
    param([string]$LicenseKey,[string]$HardwareId)
    $key = ([string]$LicenseKey).Trim()
    if([string]::IsNullOrWhiteSpace($key)){
        return @{ Success=$false; Message="ENTER YOUR KEYAUTH LICENSE KEY"; Username="" }
    }
    $init = Get-KeyAuthHashtable (Initialize-LessProjectKeyAuth)
    if(-not (Test-KeyAuthFlag $init 'Success')){ return @{ Success=$false; Message=$(if($init.Message){[string]$init.Message}else{"KEYAUTH INIT FAILED"}); Username="" } }
    $hwid = [string]$HardwareId
    if([string]::IsNullOrWhiteSpace($hwid)){ $hwid = [string]$Global:LessProjectHardwareId }
    $resp = Invoke-LessProjectKeyAuthRequest -Fields @{
        type = "license"
        key = $key
        hwid = $hwid
        sessionid = [string]$Global:KeyAuthSessionId
        name = [string]$Global:KeyAuthAppName
        ownerid = [string]$Global:KeyAuthOwnerId
        code = ""
    }
    if(-not $resp.Ok){ return @{ Success=$false; Message=$(if($resp.Message){$resp.Message}else{"KEYAUTH LOGIN FAILED"}); Username="" } }
    $json = $resp.Json
    if(Test-KeyAuthJsonSuccess $json){
        $username = ""
        try { $username = [string]$json.info.username } catch {}
        $Global:KeyAuthUsername = $username
        $Global:HwidGateCompleted = $true
        $Global:KeyAuthOffline = $false
        return @{ Success=$true; Message="LOGIN SUCCESS"; Username=$username }
    }
    $msg = [string]$json.message
    if([string]::IsNullOrWhiteSpace($msg)){ $msg = "INVALID LICENSE KEY" }
    $lower = $msg.ToLowerInvariant()
    if($lower -match "invalid|incorrect|not found|hwid|banned|expired|blacklisted|paused"){
        Remove-LessProjectLicenseFile
    }
    return @{ Success=$false; Message=$msg.ToUpperInvariant(); Username="" }
}
function Invoke-LessProjectKeyAuthAutoLogin {
    param([string]$HardwareId,[switch]$AllowOffline)
    return $false
}

function Add-LessProjectLoaderClipboard {
    param($Window,$KeyBox,$ValueBox,[string]$FallbackText)
    if(-not $Window){ return }
    $pasteIntoKey = {
        param($Box)
        if(-not $Box){ return }
        try {
            if(-not [System.Windows.Clipboard]::ContainsText()){ return }
            $clip = [string][System.Windows.Clipboard]::GetText()
            if([string]::IsNullOrEmpty($clip)){ return }
            $clip = $clip.Trim()
            $start = [int]$Box.SelectionStart
            $len = [int]$Box.SelectionLength
            $text = [string]$Box.Text
            if($len -gt 0 -and $start -ge 0 -and ($start+$len) -le $text.Length){
                $text = $text.Remove($start,$len)
            } else {
                $start = $text.Length
            }
            $Box.Text = $text.Insert([math]::Max(0,$start), $clip)
            $Box.CaretIndex = $start + $clip.Length
        } catch {}
    }.GetNewClosure()
    $copyFrom = {
        param($Box,$Fallback)
        try {
            $sel = ""
            if($Box){ $sel = [string]$Box.SelectedText }
            if([string]::IsNullOrEmpty($sel) -and $Box){ $sel = [string]$Box.Text }
            if([string]::IsNullOrEmpty($sel)){ $sel = [string]$Fallback }
            if(-not [string]::IsNullOrEmpty($sel)){ [System.Windows.Clipboard]::SetText($sel) }
        } catch {}
    }.GetNewClosure()
    $onKey = {
        param($sender,$eventArgs)
        try {
            if([System.Windows.Input.Keyboard]::Modifiers -ne [System.Windows.Input.ModifierKeys]::Control){ return }
            $key = $eventArgs.Key
            if($key -eq [System.Windows.Input.Key]::LeftCtrl -or $key -eq [System.Windows.Input.Key]::RightCtrl){ return }
            $focus = [System.Windows.Input.Keyboard]::FocusedElement
            if($key -eq [System.Windows.Input.Key]::V){
                & $pasteIntoKey $KeyBox
                try { $KeyBox.Focus() } catch {}
                $eventArgs.Handled = $true
            } elseif($key -eq [System.Windows.Input.Key]::C){
                if($ValueBox -and ($focus -eq $ValueBox -or [string]$ValueBox.SelectedText)){
                    & $copyFrom $ValueBox $FallbackText
                } else {
                    & $copyFrom $KeyBox $FallbackText
                }
                $eventArgs.Handled = $true
            } elseif($key -eq [System.Windows.Input.Key]::A){
                if($focus -eq $ValueBox -and $ValueBox){ $ValueBox.SelectAll() }
                elseif($KeyBox){ $KeyBox.SelectAll() }
                $eventArgs.Handled = $true
            } elseif($key -eq [System.Windows.Input.Key]::X){
                if($KeyBox -and $focus -eq $KeyBox -and [string]$KeyBox.SelectedText){
                    [System.Windows.Clipboard]::SetText([string]$KeyBox.SelectedText)
                    $KeyBox.SelectedText = ""
                    $eventArgs.Handled = $true
                }
            }
        } catch {}
    }.GetNewClosure()
    $Window.Add_PreviewKeyDown($onKey)
    if($KeyBox){
        $KeyBox.AcceptsTab = $false
        $KeyBox.Add_PreviewKeyDown($onKey)
    }
    if($ValueBox){
        $ValueBox.Add_GotFocus({ $ValueBox.SelectAll() }.GetNewClosure())
        $ValueBox.Add_PreviewMouseLeftButtonDown({
            param($s,$e)
            if(-not $ValueBox.IsKeyboardFocusWithin){ $e.Handled = $true; $ValueBox.Focus(); $ValueBox.SelectAll() }
        }.GetNewClosure())
    }
}

function Show-LessProjectHwidGate {
    param([string]$HardwareId)
    if([string]::IsNullOrWhiteSpace($HardwareId)){ $HardwareId = Get-LessProjectHardwareId }
    $hwidXaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="LESS PROJECT - SIGN IN" Width="400" Height="420" MinWidth="400" MinHeight="420" WindowStartupLocation="CenterScreen" WindowStyle="None" ResizeMode="NoResize" AllowsTransparency="True" Background="Transparent" FontFamily="Segoe UI" UseLayoutRounding="True" SnapsToDevicePixels="True" TextOptions.TextFormattingMode="Ideal" TextOptions.TextRenderingMode="ClearType">
 <Window.Resources>
  <Style x:Key="HwidButton" TargetType="Button"><Setter Property="Background" Value="#111111"/><Setter Property="Foreground" Value="#F4F4F4"/><Setter Property="BorderBrush" Value="#666666"/><Setter Property="BorderThickness" Value="1"/><Setter Property="Height" Value="31"/><Setter Property="FontFamily" Value="Segoe UI"/><Setter Property="Cursor" Value="Hand"/><Setter Property="FontSize" Value="8.5"/><Setter Property="FontWeight" Value="SemiBold"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="Button"><Border x:Name="HwidButtonBorder" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="8" Padding="10,0"><ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="HwidButtonBorder" Property="Background" Value="#262626"/><Setter TargetName="HwidButtonBorder" Property="BorderBrush" Value="#FFFFFF"/></Trigger><Trigger Property="IsPressed" Value="True"><Setter TargetName="HwidButtonBorder" Property="Opacity" Value="0.68"/></Trigger><Trigger Property="IsEnabled" Value="False"><Setter TargetName="HwidButtonBorder" Property="Opacity" Value="0.35"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
  <Style x:Key="HwidAccentButton" TargetType="Button" BasedOn="{StaticResource HwidButton}"><Setter Property="Background" Value="#F1F1F1"/><Setter Property="BorderBrush" Value="#FFFFFF"/><Setter Property="Foreground" Value="#101010"/><Setter Property="FontSize" Value="10"/><Setter Property="FontWeight" Value="SemiBold"/><Setter Property="Height" Value="40"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="Button"><Border x:Name="AccentBorder" CornerRadius="9" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1"><ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="AccentBorder" Property="Background" Value="#CFCFCF"/><Setter TargetName="AccentBorder" Property="BorderBrush" Value="#FFFFFF"/></Trigger><Trigger Property="IsPressed" Value="True"><Setter TargetName="AccentBorder" Property="Opacity" Value="0.68"/></Trigger><Trigger Property="IsEnabled" Value="False"><Setter TargetName="AccentBorder" Property="Opacity" Value="0.35"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
 </Window.Resources>
 <Border x:Name="HwidCard" CornerRadius="26" ClipToBounds="True" BorderBrush="#4C4C4C" BorderThickness="1">
  <Border.Background><SolidColorBrush Color="#FF080808"/></Border.Background>
  <Grid x:Name="HwidRoot" ClipToBounds="True"><Grid.Clip><RectangleGeometry Rect="0,0,400,420" RadiusX="26" RadiusY="26"/></Grid.Clip>
   <Canvas x:Name="HwidBgCanvas" IsHitTestVisible="False" ClipToBounds="True" Panel.ZIndex="0"/>
   <Grid Panel.ZIndex="2">
    <Grid.RowDefinitions><RowDefinition Height="30"/><RowDefinition Height="*"/></Grid.RowDefinitions>
    <Grid x:Name="HwidTopBar" Grid.Row="0" Margin="13,7,10,0"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBlock Grid.Column="0" Text="LESS PROJECT  /  ACCESS" Foreground="#777777" FontSize="11" FontWeight="SemiBold" VerticalAlignment="Center"/><StackPanel Grid.Column="1" Orientation="Horizontal"><Button x:Name="HwidMinimize" Content="&#x2014;" Width="19" Height="19" Background="Transparent" Foreground="#8A8A8A" BorderThickness="0" Cursor="Hand" FontSize="9" Padding="0"/><Button x:Name="HwidClose" Width="21" Height="21" Background="Transparent" BorderThickness="0" Cursor="Hand" ToolTip="Close" Padding="0"><Button.Content><Canvas Width="14" Height="14"><Line X1="3" Y1="3" X2="11" Y2="11" Stroke="#D8D8D8" StrokeThickness="1.5" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/><Line X1="11" Y1="3" X2="3" Y2="11" Stroke="#D8D8D8" StrokeThickness="1.5" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/></Canvas></Button.Content></Button></StackPanel></Grid>
    <StackPanel Grid.Row="1" Width="320" Margin="0,12,0,18" HorizontalAlignment="Center" VerticalAlignment="Center">
     <TextBlock Text="SIGN IN" Foreground="#F0F0F0" FontSize="26" FontWeight="SemiBold" HorizontalAlignment="Center"/>
     <TextBlock Text="HWID DEVICE ACCESS" Foreground="#A8A8A8" FontSize="12" FontWeight="SemiBold" HorizontalAlignment="Center" Margin="0,5,0,22"/>
     <TextBlock Text="HARDWARE ID" Foreground="#A6A6A6" FontSize="11" FontWeight="SemiBold" Margin="2,0,0,6"/>
     <Border Height="34" CornerRadius="11" Background="#0D0D0D" BorderBrush="#707070" BorderThickness="1" Padding="9,0"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="23"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><Canvas Grid.Column="0" Width="20" Height="20" VerticalAlignment="Center"><Border Width="16" Height="10" Canvas.Left="1.5" Canvas.Top="1.5" BorderBrush="#FFFFFF" BorderThickness="1.8" CornerRadius="1.5"/><Line X1="10" Y1="12" X2="10" Y2="15.5" Stroke="#FFFFFF" StrokeThickness="1.8" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/><Line X1="5.5" Y1="17" X2="14.5" Y2="17" Stroke="#FFFFFF" StrokeThickness="1.8" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/><Ellipse Width="2" Height="2" Canvas.Left="13.5" Canvas.Top="5.5" Fill="#FFFFFF"/></Canvas><TextBox x:Name="HwidValueBox" Grid.Column="1" Text="" IsReadOnly="True" IsReadOnlyCaretVisible="True" Background="Transparent" Foreground="#EEEEEE" BorderThickness="0" Padding="0" FontFamily="Consolas" FontSize="12" FontWeight="SemiBold" VerticalContentAlignment="Center" HorizontalScrollBarVisibility="Hidden" CaretBrush="#EEEEEE"/></Grid></Border>
     <TextBlock Text="LICENSE KEY" Foreground="#A6A6A6" FontSize="11" FontWeight="SemiBold" Margin="2,18,0,6"/>
     <Border Height="38" CornerRadius="9" Background="#0D0D0D" BorderBrush="#707070" BorderThickness="1" Padding="9,0"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="23"/><ColumnDefinition Width="*"/><ColumnDefinition Width="20"/></Grid.ColumnDefinitions><Canvas Grid.Column="0" Width="14" Height="14" VerticalAlignment="Center"><Border Width="10" Height="8" Canvas.Left="2" Canvas.Top="5" BorderBrush="#AFAFAF" BorderThickness="1" CornerRadius="2"/><Path Data="M4,6 C4,2 10,2 10,6" Stroke="#D0D0D0" StrokeThickness="1" Fill="Transparent"/><Ellipse Width="2" Height="2" Canvas.Left="6" Canvas.Top="8" Fill="#D0D0D0"/></Canvas><TextBox x:Name="HwidKeyBox" Grid.Column="1" Background="Transparent" Foreground="#EEEEEE" BorderThickness="0" Padding="0" FontFamily="Consolas" FontSize="11" VerticalContentAlignment="Center" CaretBrush="#EEEEEE" AcceptsReturn="False" TextWrapping="NoWrap" HorizontalScrollBarVisibility="Hidden"/><Canvas Grid.Column="2" Width="14" Height="14" VerticalAlignment="Center"><Ellipse Width="11" Height="7" Canvas.Left="1.5" Canvas.Top="3.5" Stroke="#AFAFAF" StrokeThickness="1"/><Ellipse Width="2.5" Height="2.5" Canvas.Left="5.75" Canvas.Top="5.75" Fill="#D0D0D0"/></Canvas></Grid></Border>
     <TextBlock x:Name="HwidStatus" Text="ENTER YOUR KEYAUTH LICENSE KEY" Foreground="#888888" FontSize="11" TextWrapping="Wrap" Margin="2,12,2,0"/>
     <Button x:Name="HwidContinueButton" Content="LOG IN" Style="{StaticResource HwidAccentButton}" Margin="0,12,0,0"/>
     <TextBlock Text="Enter your license key to continue." Foreground="#777777" FontSize="11" HorizontalAlignment="Center" Margin="0,14,0,0"/>
    </StackPanel>
   </Grid>
  </Grid>
 </Border>
</Window>
"@
    $hwidWindow = $null
    try {
        [xml]$hwidXml = $hwidXaml
        $hwidReader = New-Object System.Xml.XmlNodeReader $hwidXml
        $hwidWindow = [Windows.Markup.XamlReader]::Load($hwidReader)
        $hwidBg = $hwidWindow.FindName("HwidBgCanvas")
        $hwidValueBox = $hwidWindow.FindName("HwidValueBox")
        $hwidKeyBox = $hwidWindow.FindName("HwidKeyBox")
        $hwidStatus = $hwidWindow.FindName("HwidStatus")
        $hwidContinue = $hwidWindow.FindName("HwidContinueButton")
        $hwidClose = $hwidWindow.FindName("HwidClose")
        $hwidMinimize = $hwidWindow.FindName("HwidMinimize")
        if($hwidValueBox){ $hwidValueBox.Text = [string]$HardwareId }
        Add-LessProjectLoaderClipboard -Window $hwidWindow -KeyBox $hwidKeyBox -ValueBox $hwidValueBox -FallbackText ([string]$HardwareId)
        try {
            $hwidValueParent = [System.Windows.Media.VisualTreeHelper]::GetParent($hwidValueBox)
            if($hwidValueParent -is [System.Windows.Controls.Grid]){
                $existingCopy = $hwidValueParent.FindName('HwidCopyButton')
                if(-not $existingCopy){
                    $hwidCopy = New-Object System.Windows.Controls.Button
                    $hwidCopy.Name = 'HwidCopyButton'
                    $hwidCopy.Content = 'COPY'
                    $hwidCopy.Width = 52
                    $hwidCopy.Height = 28
                    $hwidCopy.Margin = [System.Windows.Thickness]::new(6,0,0,0)
                    $hwidCopy.FontSize = 12
                    $hwidCopy.FontWeight = 'SemiBold'
                    $hwidCopy.Cursor = 'Hand'
                    $hwidCopy.Background = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#222222')
                    $hwidCopy.Foreground = [System.Windows.Media.Brushes]::White
                    $hwidCopy.BorderBrush = [System.Windows.Media.BrushConverter]::new().ConvertFromString('#888888')
                    $hwidCopy.ToolTip = 'Copy hardware ID'
                    [System.Windows.Controls.Grid]::SetColumn($hwidCopy, 2)
                    $hwidCopy.Add_Click({
                        try {
                            [System.Windows.Clipboard]::SetText([string]$HardwareId)
                            if($hwidStatus){ $hwidStatus.Text = 'HWID COPIED'; $hwidStatus.Foreground = [System.Windows.Media.Brushes]::White }
                            Play-HwidButtonSound -Kind 'Copy'
                        } catch {
                            if($hwidStatus){ $hwidStatus.Text = 'COPY FAILED' }
                        }
                    }.GetNewClosure())
                    [void]$hwidValueParent.Children.Add($hwidCopy)
                }
            }
        } catch {}
        try {
            # Same compositor-side moving star treatment as the other UI screens,
            # kept monochrome and glow-free for the HWID card.
            New-HwidMovingMonochromeBackground -Canvas $hwidBg -Width 400 -Height 420 -Count 32
            Add-BackgroundParallax -TargetWindow $hwidWindow -Canvas $hwidBg -MaxOffset 5 -DurationX 18 -DurationY 14
        } catch {}
        $Global:LessProjectHwidPassed = $false
        $Global:LessProjectHwidCancelled = $false
        $hwidContinue.Add_Click({
            Play-HwidButtonSound -Kind "Login"
            $enteredKey = ""
            try { $enteredKey = [string]$hwidKeyBox.Text } catch {}
            if([string]::IsNullOrWhiteSpace($enteredKey)){
                $hwidStatus.Text = "ENTER YOUR KEYAUTH LICENSE KEY"
                $hwidStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#AFAFAF")
                return
            }
            $hwidContinue.IsEnabled = $false
            try { $hwidKeyBox.IsEnabled = $false } catch {}
            $hwidStatus.Text = "CONNECTING TO KEYAUTH..."
            $hwidStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#FFFFFF")
            try {
                $auth = Get-KeyAuthHashtable (Invoke-LessProjectKeyAuthLicense -LicenseKey $enteredKey -HardwareId $HardwareId)
            } catch {
                $auth = @{ Success=$false; Message=("KEYAUTH ERROR — " + $_.Exception.Message) }
            }
            if(Test-KeyAuthFlag $auth 'Success'){
                Save-LessProjectLicenseFile -LicenseKey $enteredKey -HardwareId $HardwareId -UserName $auth.Username
                try { Save-LessProjectSettings } catch {}
                $hwidStatus.Text = "LOGIN SUCCESS — OPENING LESS PROJECT"
                $hwidStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#FFFFFF")
                $Global:LessProjectHwidPassed = $true
                $hwidWindow.Close()
            } else {
                $hwidStatus.Text = [string]$auth.Message
                $hwidStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#FF8A8A")
                $hwidContinue.IsEnabled = $true
                try { $hwidKeyBox.IsEnabled = $true } catch {}
            }
        }.GetNewClosure())
        $hwidKeyBox.Add_KeyDown({
            param($sender,$eventArgs)
            if($eventArgs.Key -eq [System.Windows.Input.Key]::Enter){
                $hwidContinue.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Button]::ClickEvent)))
                $eventArgs.Handled = $true
            }
        }.GetNewClosure())
        $hwidClose.Add_Click({ $Global:LessProjectHwidCancelled = $true; $hwidWindow.Close() }.GetNewClosure())
        $hwidMinimize.Add_Click({ $hwidWindow.WindowState = [System.Windows.WindowState]::Minimized }.GetNewClosure())
        $hwidWindow.Add_PreviewMouseLeftButtonDown({
            param($sender,$eventArgs)
            $source = $eventArgs.OriginalSource -as [System.Windows.DependencyObject]
            $interactive = $false
            while($source){
                if($source -is [System.Windows.Controls.Primitives.ButtonBase] -or $source -is [System.Windows.Controls.TextBox] -or $source -is [System.Windows.Controls.PasswordBox]){ $interactive = $true; break }
                try { $source = [System.Windows.Media.VisualTreeHelper]::GetParent($source) } catch { $source = $null }
            }
            if(-not $interactive -and $hwidWindow.WindowState -ne [System.Windows.WindowState]::Maximized){
                try { $eventArgs.Handled = $true; $hwidWindow.DragMove() } catch {}
            }
        }.GetNewClosure())
        $hwidWindow.ShowDialog() | Out-Null
        return ($Global:LessProjectHwidPassed -eq $true)
    } catch {
        try { Add-Content -LiteralPath $Global:UiErrorLogPath -Value ("$(Get-Date -Format o) HWID UI: $($_.Exception.ToString())") -Encoding UTF8 } catch {}
        return $false
    }
}

$Global:LessProjectHardwareId = Get-LessProjectHardwareId
$Global:LessProjectHwidPassed = $false
# KeyAuth and Integrity check completely disabled
$Global:LessProjectHwidPassed = $true
$Global:HwidGateCompleted = $true
$skipHwidGate = [bool]$Global:SkipHwidGate
$Global:LessProjectHwidPassed = $false
if($skipHwidGate){
    $Global:LessProjectHwidPassed = $true
    $Global:HwidGateCompleted = $true
}

