Block Text="by LESS PROJECT TEAM" FontFamily="Segoe UI" FontSize="11" FontWeight="Bold" Foreground="#FFFFFF" HorizontalAlignment="Center"/><Button x:Name="BtnSplashStart" Content="START" Width="180" Height="52" FontSize="20" FontFamily="Segoe UI Black" FontWeight="Black" Foreground="#FFFFFF" BorderThickness="0" Cursor="Hand" HorizontalAlignment="Center" Margin="0,22,0,0"><Button.Template><ControlTemplate TargetType="Button"><Border x:Name="StartBorder" CornerRadius="14"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,1"><GradientStop Color="#404040" Offset="0"/><GradientStop Color="#FFFFFF" Offset="0.55"/><GradientStop Color="#FFFFFF" Offset="1"/></LinearGradientBrush></Border.Background><Border.Effect><DropShadowEffect Color="#3A3A3A" BlurRadius="24" ShadowDepth="0" Opacity="0.65"/></Border.Effect><Grid><Border CornerRadius="14,14,0,0" VerticalAlignment="Top" Height="26" Opacity="0.15"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#FFFFFF" Offset="0"/><GradientStop Color="#00FFFFFF" Offset="1"/></LinearGradientBrush></Border.Background></Border><ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/></Grid></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="StartBorder" Property="Opacity" Value="0.88"/></Trigger><Trigger Property="IsPressed" Value="True"><Setter TargetName="StartBorder" Property="Opacity" Value="0.72"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Button.Template></Button></StackPanel><StackPanel x:Name="SplashLoadingGroup" Opacity="0" IsHitTestVisible="False" HorizontalAlignment="Center" VerticalAlignment="Center"><Grid x:Name="SplashRingWrap" Width="136" Height="136" HorizontalAlignment="Center" Margin="0,0,0,16"><Ellipse x:Name="SplashRingAmbient" Width="136" Height="136" Stroke="#232323" StrokeThickness="1.4" StrokeDashArray="2,9" Opacity="0.5"><Ellipse.RenderTransform><RotateTransform x:Name="SplashRingAmbientRotate" Angle="0" CenterX="68" CenterY="68"/></Ellipse.RenderTransform></Ellipse><Ellipse Width="112" Height="112" Stroke="#0A0A0A" StrokeThickness="6"/><Ellipse x:Name="SplashRingProgress" Width="112" Height="112" Stroke="#FFFFFF" StrokeThickness="6" StrokeStartLineCap="Round" StrokeEndLineCap="Round"><Ellipse.RenderTransform><RotateTransform Angle="-90" CenterX="56" CenterY="56"/></Ellipse.RenderTransform><Ellipse.Effect><DropShadowEffect Color="#3A3A3A" BlurRadius="16" ShadowDepth="0" Opacity="0.8"/></Ellipse.Effect></Ellipse><Image x:Name="SplashLoadingLogoImage" Width="52" Height="52" HorizontalAlignment="Center" VerticalAlignment="Center" Stretch="Uniform" RenderTransformOrigin="0.5,0.5"><Image.RenderTransform><ScaleTransform x:Name="SplashLogoBreathe" ScaleX="1" ScaleY="1"/></Image.RenderTransform></Image></Grid><StackPanel x:Name="SplashLoadingWrap" HorizontalAlignment="Center"><StackPanel Orientation="Horizontal" HorizontalAlignment="Center"><TextBlock Text="LESS" FontFamily="Segoe UI Black" FontSize="32" FontWeight="Black" Foreground="#FFFFFF"/><TextBlock Text=" PROJECT" FontFamily="Segoe UI Black" FontSize="32" FontWeight="Black" Foreground="#FFFFFF"/></StackPanel><TextBlock FontFamily="Consolas" Foreground="#A2A2A2" FontSize="11" FontWeight="Bold" HorizontalAlignment="Center" Margin="0,4,0,0"><Run Text="CONNECTING TO LESS PROJECT"/><Run x:Name="SplashConnectingDots" Text="..."/></TextBlock></StackPanel><StackPanel x:Name="SplashStripeWrap" Width="300" HorizontalAlignment="Center" Margin="0,22,0,0"><Border Height="20" CornerRadius="10" BorderBrush="#191919" BorderThickness="1.2" Background="#111111" HorizontalAlignment="Stretch"><Grid Margin="2" ClipToBounds="True"><Border x:Name="SplashLoadingFill" CornerRadius="8" HorizontalAlignment="Left" Width="0"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,0"><GradientStop Color="#FFFFFF" Offset="0"/><GradientStop Color="#666666" Offset="1"/></LinearGradientBrush></Border.Background></Border></Grid></Border><TextBlock x:Name="SplashRingPercentText" Text="0%" FontFamily="Consolas" Foreground="#FFFFFF" FontSize="14" FontWeight="Bold" HorizontalAlignment="Center" Margin="0,8,0,0"/></StackPanel></StackPanel></Grid></Grid></Grid></Border></Window>

"@
# Lightweight loader redesign: no particle canvas, no continuously spinning effects.
# Keeping the animation surface this small makes the first screen smooth even on low-end PCs.
[xml]$splashXaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="LESS PROJECT" Height="500" Width="820" WindowStartupLocation="CenterScreen" Background="Transparent" FontFamily="Segoe UI" WindowStyle="None" AllowsTransparency="True" ResizeMode="NoResize" Topmost="True" UseLayoutRounding="True" SnapsToDevicePixels="True">
 <Border x:Name="SplashOuterBorder" CornerRadius="26" BorderThickness="1" BorderBrush="#2A2A2A" ClipToBounds="True">
  <Border.Background><SolidColorBrush Color="#FF000000"/></Border.Background>
  <Grid ClipToBounds="True" x:Name="SplashRoot">
