      <WrapPanel HorizontalAlignment="Center" Margin="0,15,0,0"><Border Background="#CC050505" BorderBrush="#707070" BorderThickness="1" CornerRadius="12" Padding="10,5" Margin="0,0,7,0"><TextBlock Text="CLIENT-SIDE" Foreground="#B0B0B0" FontSize="11" FontWeight="Bold"/></Border><Border Background="#CC151515" BorderBrush="#707070" BorderThickness="1" CornerRadius="12" Padding="10,5"><TextBlock Text="LOW LATENCY" Foreground="#B0B0B0" FontSize="11" FontWeight="Bold"/></Border></WrapPanel>
     </StackPanel>
     <Border Grid.Column="1" CornerRadius="20" BorderBrush="#707070" BorderThickness="1" Padding="24,22" Background="#66080808">
