        <TextBlock Text="SETTING LESS PROJECT BY SOFT STORE" Foreground="#C8C8C8" FontSize="12" FontWeight="Bold" HorizontalAlignment="Center" TextAlignment="Center" Margin="0,8,0,0"/>
        <StackPanel x:Name="SplashStartActionGroup" Margin="0,22,0,0">
        <Button x:Name="BtnSplashStart" Content="LAUNCH LESS PROJECT" Height="46" Foreground="#FFFFFF" FontSize="12" FontWeight="Black" Cursor="Hand" BorderThickness="0">
         <Button.Template><ControlTemplate TargetType="Button"><Border x:Name="LaunchBorder" CornerRadius="13"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,0"><GradientStop Color="#404040" Offset="0"/><GradientStop Color="#3A3A3A" Offset="1"/></LinearGradientBrush></Border.Background><ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="LaunchBorder" Property="Opacity" Value="0.84"/></Trigger><Trigger Property="IsPressed" Value="True"><Setter TargetName="LaunchBorder" Property="Opacity" Value="0.68"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Button.Template>
        </Button>
        <TextBlock Text="Enter to continue  •  Esc to close" Foreground="#515151" FontSize="12" HorizontalAlignment="Center" Margin="0,9,0,0"/>
