        <Grid x:Name="SplashRingWrap" Width="120" Height="120" Margin="0,0,0,20"><Ellipse x:Name="SplashRingAmbient" Stroke="#0A0A0A" StrokeThickness="6"/><Ellipse x:Name="SplashRingProgress" Stroke="#FFFFFF" StrokeThickness="6" StrokeStartLineCap="Round" StrokeEndLineCap="Round"><Ellipse.RenderTransform><RotateTransform x:Name="SplashRingAmbientRotate" Angle="-90" CenterX="60" CenterY="60"/></Ellipse.RenderTransform></Ellipse><Image x:Name="SplashLoadingLogoImage" Width="48" Height="48" HorizontalAlignment="Center" VerticalAlignment="Center" RenderTransformOrigin="0.5,0.5"><Image.RenderTransform><ScaleTransform x:Name="SplashLogoBreathe"/></Image.RenderTransform></Image><TextBlock x:Name="SplashRingPercentText" Text="0%" Foreground="#FFFFFF" FontSize="11" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Bottom" Margin="0,0,0,10"/></Grid>
        <StackPanel x:Name="SplashLoadingWrap"><TextBlock Text="INITIALIZING PROFILE ENGINE" Foreground="#FFFFFF" FontSize="14" FontWeight="Bold" HorizontalAlignment="Center"/><TextBlock Foreground="#9D9D9D" FontSize="11" HorizontalAlignment="Center" Margin="0,8,0,0"><Run Text="SYNCING MODULES"/><Run x:Name="SplashConnectingDots" Text="..."/></TextBlock></StackPanel>
        <StackPanel x:Name="SplashStripeWrap" Width="300" Margin="0,22,0,0"><Border Height="5" Background="#0A0A0A" CornerRadius="3"><Border x:Name="SplashLoadingFill" Width="0" HorizontalAlignment="Left" Background="#FFFFFF" CornerRadius="3"/></Border></StackPanel>
       </StackPanel>
