 </Border>
</Window>
"@
# =========================================================
# EMBEDDED UI GIF BACKGROUND
# The new GIF is embedded once and reused by the Loading window and the main UI.
# Both layers stay inside their own clipped WPF surface and remain non-interactive.
# =========================================================
function Set-ExternalStaticUiBackground {
    param($TargetImage)
    try {
        if(-not $TargetImage){ return }
        $bgPath = Join-Path ([string]$Global:LessProjectScriptRoot) "lessproject_bg_static.png"
        if(-not (Test-Path -LiteralPath $bgPath -PathType Leaf)){ return }
        $stream = [System.IO.File]::OpenRead($bgPath)
        $bitmap = New-Object System.Windows.Media.Imaging.BitmapImage
        $bitmap.BeginInit()
        $bitmap.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
        $bitmap.StreamSource = $stream
        $bitmap.EndInit()
        $stream.Dispose()
        $bitmap.Freeze()
        $TargetImage.Source = $bitmap
        $TargetImage.Visibility = [System.Windows.Visibility]::Visible
        $TargetImage.Opacity = 1.0
        $TargetImage.Stretch = [System.Windows.Media.Stretch]::UniformToFill
    } catch {}
}
function Get-LessProjectEmbeddedUiGifBytes {
    # Keep the GIF beside the .ps1 file so this script remains compact.
    $roots=@()
    try {
        if($Global:LessProjectScriptRoot){ $roots += [string]$Global:LessProjectScriptRoot }
        if($PSScriptRoot){ $roots += [string]$PSScriptRoot }
        if($PSCommandPath){ $roots += (Split-Path -Parent $PSCommandPath) }
        $roots += (Get-Location).Path
        $candidates=@($roots | Where-Object {$_} | Select-Object -Unique | ForEach-Object { Join-Path $_ "giphy.gif" })
        foreach($candidate in $candidates){
            if(Test-Path -LiteralPath $candidate -PathType Leaf){
                $bytes=[System.IO.File]::ReadAllBytes($candidate)
                if($bytes -and $bytes.Length -gt 16 -and $bytes[0] -eq 0x47 -and $bytes[1] -eq 0x49 -and $bytes[2] -eq 0x46){
                    $Global:GifBackgroundLastPath=$candidate
                    return $bytes
                }
            }
        }
        $Global:GifBackgroundLastError="giphy.gif was not found. Expected beside the script: $(Join-Path $Global:LessProjectScriptRoot 'giphy.gif')"
    } catch { $Global:GifBackgroundLastError="Could not locate giphy.gif: $($_.Exception.Message)" }
    return $null
}
function Start-EmbeddedGifBackground {
    param($TargetImage,[string]$ScopeName,[int]$IntervalMs=33)
    if(-not $TargetImage -or [string]::IsNullOrWhiteSpace($ScopeName)) { return }
    try {
        if(-not $Global:EmbeddedGifStates) { $Global:EmbeddedGifStates=@{} }
        if($Global:EmbeddedGifStates.ContainsKey($ScopeName)) { Stop-EmbeddedGifBackground -ScopeName $ScopeName }
        $gifBytes=Get-LessProjectEmbeddedUiGifBytes
        $gifPath=[string]$Global:GifBackgroundLastPath
        if(-not $gifBytes -or $gifBytes.Length -lt 16 -or [string]::IsNullOrWhiteSpace($gifPath) -or -not (Test-Path -LiteralPath $gifPath -PathType Leaf)) {
            throw "giphy.gif is missing beside the PS1 file."
        }
        $TargetImage.Visibility=[System.Windows.Visibility]::Visible
        $TargetImage.Opacity=1.0
        $TargetImage.Stretch=[System.Windows.Media.Stretch]::UniformToFill
        $TargetImage.SetValue([System.Windows.Controls.Panel]::ZIndexProperty,0)
        # Paint an external first-frame image immediately. This keeps Splash visible
        # even on Windows systems where GIF frame decoding is unavailable.
        $bgHosts=@()
        $bgNode=$TargetImage
        for($depth=0; $bgNode -and $depth -lt 5; $depth++) {
            if($bgNode.PSObject.Properties['Background']) { $bgHosts += $bgNode }
            try { $bgNode=$bgNode.Parent } catch { $bgNode=$null }
        }
        $bgBrushes=@()
        # Paint a visible static frame from the supplied GIF before animation.
        # Prefer the external PNG when present; otherwise extract a GIF frame with
        # the Windows GDI+ decoder, which is independent from WPF GIF playback.
        $staticBitmap=$null
        $fallbackPngPath=Join-Path (Split-Path -Parent $gifPath) "giphy_background.png"
        try {
            if(Test-Path -LiteralPath $fallbackPngPath -PathType Leaf) {
                $staticBitmap=New-Object System.Windows.Media.Imaging.BitmapImage
                $staticBitmap.BeginInit()
                $staticBitmap.CacheOption=[System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
                $staticBitmap.UriSource=[System.Uri]::new($fallbackPngPath,[System.UriKind]::Absolute)
                $staticBitmap.EndInit()
                $staticBitmap.Freeze()
            } else {
                Add-Type -AssemblyName System.Drawing
                $gdImage=[System.Drawing.Image]::FromFile($gifPath)
                $gdGuid=$gdImage.FrameDimensionsList[0]
                $gdDimension=New-Object System.Drawing.Imaging.FrameDimension($gdGuid)
                $gdCount=$gdImage.GetFrameCount($gdDimension)
                $gdImage.SelectActiveFrame($gdDimension,[math]::Min(133,$gdCount-1))|Out-Null
                $gdStream=New-Object System.IO.MemoryStream
                $gdImage.Save($gdStream,[System.Drawing.Imaging.ImageFormat]::Png)
                $gdImage.Dispose()
                $gdStream.Position=0
                $staticBitmap=New-Object System.Windows.Media.Imaging.BitmapImage
                $staticBitmap.BeginInit()
                $staticBitmap.CacheOption=[System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
                $staticBitmap.StreamSource=$gdStream
                $staticBitmap.EndInit()
                $staticBitmap.Freeze()
                $gdStream.Dispose()
            }
            $TargetImage.Source=$staticBitmap
            foreach($bgHost in $bgHosts) {
                $brush=New-Object System.Windows.Media.ImageBrush
                $brush.Stretch=[System.Windows.Media.Stretch]::UniformToFill
                $brush.ImageSource=$staticBitmap
                $bgHost.Background=$brush
                $bgBrushes += $brush
            }
        } catch {
            $Global:GifBackgroundLastError="Static GIF frame could not be painted for ${ScopeName}: $($_.Exception.Message)"
        }
        # Decode the supplied GIF. The first decoded frame is painted before
        # the timer starts, so Splash never depends on automatic GIF playback.
        $stream=[System.IO.FileStream]::new($gifPath,[System.IO.FileMode]::Open,[System.IO.FileAccess]::Read,[System.IO.FileShare]::ReadWrite)
        $decoder=[System.Windows.Media.Imaging.GifBitmapDecoder]::new($stream,[System.Windows.Media.Imaging.BitmapCreateOptions]::PreservePixelFormat,[System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad)
        $frames=@($decoder.Frames)
        if(-not $frames -or $frames.Count -lt 1) { $stream.Dispose(); throw "giphy.gif contains no decodable frames for ${ScopeName}." }
        foreach($frame in $frames){ try { if($frame.CanFreeze){$frame.Freeze()} } catch {} }
        $startFrameIndex=[math]::Min(133,$frames.Count-1)
        # Paint the GIF frame directly on the Image and on every visible parent
        # background, including the transparent Window itself.
        $bgHosts=@()
        $bgNode=$TargetImage
        for($depth=0; $bgNode -and $depth -lt 5; $depth++) {
            if($bgNode.PSObject.Properties['Background']) { $bgHosts += $bgNode }
            try { $bgNode=$bgNode.Parent } catch { $bgNode=$null }
        }
        $bgBrushes=@()
        foreach($bgHost in $bgHosts) {
            $brush=New-Object System.Windows.Media.ImageBrush
            $brush.Stretch=[System.Windows.Media.Stretch]::UniformToFill
            $brush.ImageSource=$frames[$startFrameIndex]
            $bgHost.Background=$brush
            $bgBrushes += $brush
        }
        $TargetImage.Source=$frames[$startFrameIndex]
        $state=@{ Target=$TargetImage; Frames=$frames; Index=$startFrameIndex; Stream=$stream; Timer=$null; Brushes=$bgBrushes }
        $timer=New-Object System.Windows.Threading.DispatcherTimer
        $timer.Interval=[TimeSpan]::FromMilliseconds([math]::Max(20,$IntervalMs))
        $timer.Add_Tick({
            try {
                if(-not $state.Frames -or $state.Frames.Count -lt 2) { return }
                $state.Index=($state.Index+1) % $state.Frames.Count
                $frame=$state.Frames[$state.Index]
                if($state.Target) { $state.Target.Source=$frame }
                foreach($brush in @($state.Brushes)){ if($brush){ $brush.ImageSource=$frame } }
            } catch {
                $Global:GifBackgroundLastError="GIF frame update failed for ${ScopeName}: $($_.Exception.Message)"
            }
        }.GetNewClosure())
        $state.Timer=$timer
        $Global:EmbeddedGifStates[$ScopeName]=$state
        $Global:GifBackgroundLastError=$null
        $timer.Start()
        if($ScopeName -eq "Splash"){ $Global:SplashGifAnimationRunning=$true }
    } catch {
        $Global:GifBackgroundLastError="GIF background failed for ${ScopeName}: $($_.Exception.Message)"
        try { Add-Content -LiteralPath $Global:UiErrorLogPath -Value ("$(Get-Date -Format o) GIF ${ScopeName}: $($Global:GifBackgroundLastError)") -Encoding UTF8 } catch {}
        try { $TargetImage.Visibility=[System.Windows.Visibility]::Visible; $TargetImage.Opacity=1.0 } catch {}
    }
}
function Stop-EmbeddedGifBackground {
    param([string]$ScopeName)
    try {
        if($Global:EmbeddedGifStates -and $Global:EmbeddedGifStates.ContainsKey($ScopeName)) {
            $state=$Global:EmbeddedGifStates[$ScopeName]
            if($state.Timer) { $state.Timer.Stop() }
            if($state.Stream) { $state.Stream.Dispose() }
            $Global:EmbeddedGifStates.Remove($ScopeName)
        }
    } catch {}
}

$splashReader = New-Object System.Xml.XmlNodeReader $splashXaml
$splashWindow = [Windows.Markup.XamlReader]::Load($splashReader)

$SplashOuterBorder    = $splashWindow.FindName("SplashOuterBorder")
$SplashRoot           = $splashWindow.FindName("SplashRoot")
$SplashBgCanvas       = $splashWindow.FindName("SplashBgCanvas")
$SplashGifBackground = $splashWindow.FindName("SplashGifBackground")
# Loading/Splash uses the supplied giphy.gif directly, animated frame-by-frame
# via Start-EmbeddedGifBackground so the Loading screen isn't stuck on frame 0.
try {
    # Procedural monochrome Galaxy: no external GIF required.
    $SplashGifBackground.Visibility=[System.Windows.Visibility]::Collapsed
    New-SplashAura -Canvas $SplashBgCanvas -Width 820 -Height 500 -CenterX 410 -CenterY 250 -ParticleCount 120 -Style $Global:GalaxyStyle
    Add-BackgroundParallax -TargetWindow $splashWindow -Canvas $SplashBgCanvas -MaxOffset 18 -DurationX 18 -DurationY 14
    $Global:SplashGifLoaded = $false
} catch {}
$SplashTopBar         = $splashWindow.FindName("SplashTopBar")
$BtnSplashMinimize    = $splashWindow.FindName("BtnSplashMinimize")
$BtnSplashClose       = $splashWindow.FindName("BtnSplashClose")
$BtnSplashStart       = $splashWindow.FindName("BtnSplashStart")
$SplashLogoImage      = $splashWindow.FindName("SplashLogoImage")
$SplashStartGroup     = $splashWindow.FindName("SplashStartGroup")
$SplashLoadingGroup   = $splashWindow.FindName("SplashLoadingGroup")
$SplashLoadingWrap    = $splashWindow.FindName("SplashLoadingWrap")
$SplashLoadingFill    = $splashWindow.FindName("SplashLoadingFill")
$SplashStripeWrap     = $splashWindow.FindName("SplashStripeWrap")
$SplashRingPercentText = $splashWindow.FindName("SplashRingPercentText")
$SplashRingProgress   = $splashWindow.FindName("SplashRingProgress")
$SplashLoadingLogoImage = $splashWindow.FindName("SplashLoadingLogoImage")
$SplashRingAmbientRotate = $splashWindow.FindName("SplashRingAmbientRotate")
$SplashLogoBreathe       = $splashWindow.FindName("SplashLogoBreathe")
$SplashLogoFloat         = $splashWindow.FindName("SplashLogoFloat")
$SplashConnectingDots    = $splashWindow.FindName("SplashConnectingDots")
$SplashAuthGroup         = $splashWindow.FindName("SplashAuthGroup")
$SplashKeyBox            = $splashWindow.FindName("SplashKeyBox")
$SplashAuthStatus        = $splashWindow.FindName("SplashAuthStatus")

function Set-SplashAuthUiState {
    param([bool]$Authenticated)
    if($SplashAuthGroup){
        if($Authenticated){
            $SplashAuthGroup.Visibility = [System.Windows.Visibility]::Collapsed
            if($BtnSplashStart){ $BtnSplashStart.Content = "LAUNCH LESS PROJECT"; $BtnSplashStart.IsEnabled = $true }
        } else {
            $SplashAuthGroup.Visibility = [System.Windows.Visibility]::Visible
            if($BtnSplashStart){ $BtnSplashStart.Content = "LOG IN"; $BtnSplashStart.IsEnabled = $true }
        }
    }
}

function Invoke-SplashKeyAuthLogin {
    if($Global:LessProjectHwidPassed){ return $true }
    $enteredKey = ""
    try { $enteredKey = [string]$SplashKeyBox.Text } catch {}
    if([string]::IsNullOrWhiteSpace($enteredKey)){
        if($SplashAuthStatus){
            $SplashAuthStatus.Text = "ENTER YOUR KEYAUTH LICENSE KEY"
            $SplashAuthStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#AFAFAF")
        }
        return $false
    }
    if($BtnSplashStart){ $BtnSplashStart.IsEnabled = $false }
    try { $SplashKeyBox.IsEnabled = $false } catch {}
    if($SplashAuthStatus){
        $SplashAuthStatus.Text = "CONNECTING TO KEYAUTH..."
        $SplashAuthStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#FFFFFF")
    }
    try {
        $auth = Get-KeyAuthHashtable (Invoke-LessProjectKeyAuthLicense -LicenseKey $enteredKey -HardwareId $Global:LessProjectHardwareId)
    } catch {
        $auth = @{ Success=$false; Message=("KEYAUTH ERROR — " + $_.Exception.Message) }
    }
    if(Test-KeyAuthFlag $auth 'Success'){
        Save-LessProjectLicenseFile -LicenseKey $enteredKey -HardwareId $Global:LessProjectHardwareId -UserName $auth.Username
        try { Save-LessProjectSettings } catch {}
        $Global:LessProjectHwidPassed = $true
        if($SplashAuthStatus){
            $SplashAuthStatus.Text = "LOGIN SUCCESS — READY TO LAUNCH"
            $SplashAuthStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#4CB7FF")
        }
        Set-SplashAuthUiState -Authenticated $true
        try { Play-HwidButtonSound -Kind "Login" } catch {}
        return $true
    }
    if($SplashAuthStatus){
        $SplashAuthStatus.Text = [string]$auth.Message
        $SplashAuthStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#FF8A8A")
    }
    if($BtnSplashStart){ $BtnSplashStart.IsEnabled = $true; $BtnSplashStart.Content = "LOG IN" }
    try { $SplashKeyBox.IsEnabled = $true } catch {}
    return $false
}

function Start-SplashLaunchFlow {
    $Global:LessProjectHwidPassed = $true
    try { Play-HwidButtonSound -Kind "Transition" } catch {}
    Start-SplashLoading
}

try { Add-LessProjectLoaderClipboard -Window $splashWindow -KeyBox $SplashKeyBox } catch {}

# Clip all splash content to the rounded outer border. This keeps background images
# and overlays from painting square corners through the transparent window.
try {
    $splashOuterClip = New-Object System.Windows.Media.RectangleGeometry
    $splashOuterClip.RadiusX = 26
    $splashOuterClip.RadiusY = 26
    $applySplashOuterClip = {
        if($SplashOuterBorder -and $SplashOuterBorder.ActualWidth -gt 0 -and $SplashOuterBorder.ActualHeight -gt 0){
            $splashOuterClip.Rect = [System.Windows.Rect]::new(0,0,[double]$SplashOuterBorder.ActualWidth,[double]$SplashOuterBorder.ActualHeight)
            $SplashOuterBorder.Clip = $splashOuterClip
        }
    }.GetNewClosure()
    $SplashOuterBorder.Add_SizeChanged({ & $applySplashOuterClip }.GetNewClosure())
    & $applySplashOuterClip
} catch {}

$loaderHeader=New-Object System.Windows.Controls.TextBlock; $loaderHeader.Text="LESS PROJECT  /  FIVEM OPTIMIZER"; $loaderHeader.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#7A7A7A"); $loaderHeader.FontSize=12; $loaderHeader.FontWeight=[System.Windows.FontWeights]::Bold; $loaderHeader.HorizontalAlignment="Center"; $loaderHeader.Margin=[System.Windows.Thickness]::new(0,0,0,16)
$loaderFooter=New-Object System.Windows.Controls.TextBlock; $loaderFooter.Text="SYSTEM  /  NETWORK  /  GAMING"; $loaderFooter.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#7A7A7A"); $loaderFooter.FontSize=12; $loaderFooter.HorizontalAlignment="Center"; $loaderFooter.Margin=[System.Windows.Thickness]::new(0,18,0,0)
[void]$SplashLoadingGroup.Children.Insert(0,$loaderHeader); [void]$SplashLoadingGroup.Children.Add($loaderFooter)

try {
    $splashLogoBytes = [Convert]::FromBase64String($Global:SplashLogoBase64)
    $splashLogoStream = New-Object -TypeName System.IO.MemoryStream -ArgumentList @(,$splashLogoBytes)
    $splashLogoBitmap = New-Object System.Windows.Media.Imaging.BitmapImage
    $splashLogoBitmap.BeginInit()
    $splashLogoBitmap.StreamSource = $splashLogoStream
    $splashLogoBitmap.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
    $splashLogoBitmap.EndInit()
    $SplashLogoImage.Source = $splashLogoBitmap
    $SplashLoadingLogoImage.Source = $splashLogoBitmap
} catch { }

# Gentle continuous float/bob for the logo on the START screen, so it feels alive even before loading starts.
$logoFloat = New-Object System.Windows.Media.Animation.DoubleAnimationUsingKeyFrames
$logoFloat.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
$lf0 = [System.Windows.Media.Animation.EasingDoubleKeyFrame]::new([double]0,  [System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromSeconds(0)))
$lf1 = [System.Windows.Media.Animation.EasingDoubleKeyFrame]::new([double]-5, [System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromSeconds(1.4)))
$lf2 = [System.Windows.Media.Animation.EasingDoubleKeyFrame]::new([double]0,  [System.Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromSeconds(2.8)))
foreach ($kf in @($lf0,$lf1,$lf2)) {
    $ease = New-Object System.Windows.Media.Animation.SineEase
    $ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
    $kf.EasingFunction = $ease
    $logoFloat.KeyFrames.Add($kf) | Out-Null
}
$SplashLogoFloat.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $logoFloat)

# Soft premium glow + faint drifting particles behind the title, for depth (no lightning/busy grid).
# Simple fade-in for the whole card
$SplashRoot.Opacity = 1
$fadeIn = New-Object System.Windows.Media.Animation.DoubleAnimation
$fadeIn.From = 1
$fadeIn.To = 1
$fadeIn.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds(0.72))
$fadeIn.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
$fadeIn.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
$SplashRoot.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $fadeIn)

# Very slow background drift: the soft red light moves a few pixels over time,
# adding depth without making the interface feel busy or affecting hit testing.
Add-BackgroundParallax -TargetWindow $splashWindow -Canvas $SplashBgCanvas -MaxOffset 28 -DurationX 9.5 -DurationY 7.5

# Give each ambient glow its own slow path and breathing opacity. The different
# phases make the background feel layered instead of moving like one flat image.
$glowMotion = @(
    @{ Name="SplashGlowA"; X=-22; Y=16; Seconds=10; MinOpacity=0.17; MaxOpacity=0.28 },
    @{ Name="SplashGlowB"; X=20; Y=-14; Seconds=13; MinOpacity=0.13; MaxOpacity=0.23 },
    @{ Name="SplashGlowC"; X=-15; Y=-18; Seconds=9; MinOpacity=0.09; MaxOpacity=0.16 }
)
foreach($g in $glowMotion){
    try {
        $glow = $splashWindow.FindName($g.Name)
        if(-not $glow){ continue }
        $glowTransform = New-Object System.Windows.Media.TranslateTransform
        $glow.RenderTransform = $glowTransform

        $gx = New-Object System.Windows.Media.Animation.DoubleAnimation
        $gx.From = -[double]$g.X; $gx.To = [double]$g.X
        $gx.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds([double]$g.Seconds))
        $gx.AutoReverse = $true; $gx.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
        $gx.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
        $glowTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $gx)

        $gy = $gx.Clone()
        $gy.From = -[double]$g.Y; $gy.To = [double]$g.Y
        $gy.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds(([double]$g.Seconds) * 0.82))
        $glowTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $gy)

        $go = New-Object System.Windows.Media.Animation.DoubleAnimation
        $go.From = [double]$g.MinOpacity; $go.To = [double]$g.MaxOpacity
        $go.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds(([double]$g.Seconds) * 0.68))
        $go.AutoReverse = $true; $go.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
        $go.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
        $glow.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $go)
    } catch {}
}

# Tracks whether the user closed the splash with the X button (full program exit)
# rather than pressing START (proceed into the main console).
$Global:SplashClosedByX = $false

# Animates the loading bar from 0 -> 100% and then hands off to the main console.
# Runs on a DispatcherTimer so the UI stays responsive while it fills.
# NOTE: the timer and its width constant are stored in Global scope (not local to this
# function) because the Tick event fires later, after this function has already returned -
# a local variable would fall out of scope and read back as $null.
function Start-SplashLoading {
    $BtnSplashStart.IsEnabled = $false
    $BtnSplashStart.Content = "LOADING"
    $SplashLoadingFill.Width = 0
    $SplashRingPercentText.Text = "0%"

    # Circular ring math: dash-array units in WPF are multiples of StrokeThickness,
    # so total "distance" around the ring = circumference / thickness.
    $Global:SplashRingThickness = 6.0
    $Global:SplashRingCircumference = [math]::PI * (112 - $Global:SplashRingThickness)
    $Global:SplashRingDashUnits = $Global:SplashRingCircumference / $Global:SplashRingThickness
    $initialDashArray = New-Object System.Windows.Media.DoubleCollection
    [void]$initialDashArray.Add(0)
    [void]$initialDashArray.Add([double]($Global:SplashRingDashUnits * 3))
    $SplashRingProgress.StrokeDashArray = $initialDashArray

    # Subtle ambient rotation keeps the loader feeling alive without adding visual noise.
    # The progress arc still communicates the actual loading percentage.
    $ambientRotate = New-Object System.Windows.Media.Animation.DoubleAnimation
    $ambientRotate.From = -90; $ambientRotate.To = 270
    $ambientRotate.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds(6.0))
    $ambientRotate.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
    $ambientRotate.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
    $ambientRotate.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
    if($SplashRingAmbientRotate){
        $SplashRingAmbientRotate.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $ambientRotate)
    }

    # Gentle breathing pulse on the center logo for a touch of depth/life.
    $breatheX = New-Object System.Windows.Media.Animation.DoubleAnimation
    $breatheX.From = 1.0; $breatheX.To = 1.08
    $breatheX.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds(1.6))
    $breatheX.AutoReverse = $true
    $breatheX.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
    $breatheX.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
    $breatheX.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
    $breatheY = $breatheX.Clone()
    if($SplashLogoBreathe){
        $SplashLogoBreathe.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $breatheX)
        $SplashLogoBreathe.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $breatheY)
    }

    # A barely-there pulse on the thin bar adds a polished loading cue while keeping
    # the interface calm and readable.
    $barPulse = New-Object System.Windows.Media.Animation.DoubleAnimation
    $barPulse.From = 0.72; $barPulse.To = 1.0
    $barPulse.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds(1.8))
    $barPulse.AutoReverse = $true
    $barPulse.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
    $barPulse.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
    $barPulse.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
    if($SplashLoadingFill){
        $SplashLoadingFill.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $barPulse)
    }

    # Animated "..." after CONNECTING TO SYNC SETTING - cycles "." / ".." / "..." on its own timer.
    $Global:SplashDotsFrames = @(".", "..", "...")
    $Global:SplashDotsIndex = 2
    $Global:SplashDotsTimer = New-Object System.Windows.Threading.DispatcherTimer
    $Global:SplashDotsTimer.Interval = [TimeSpan]::FromMilliseconds(360)
    $Global:SplashDotsTimer.Add_Tick({
        $Global:SplashDotsIndex = ($Global:SplashDotsIndex + 1) % $Global:SplashDotsFrames.Count
        if($SplashConnectingDots){ $SplashConnectingDots.Text = $Global:SplashDotsFrames[$Global:SplashDotsIndex] }
    })
    $Global:SplashDotsTimer.Start()

    $splashFadeOut = New-Object System.Windows.Media.Animation.DoubleAnimation
    $splashFadeOut.From = 1
    $splashFadeOut.To = 0
    $splashFadeOut.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(260))
    $splashFadeOut.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
    $splashFadeOut.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
    $SplashStartGroup.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $splashFadeOut)
    $SplashStartGroup.IsHitTestVisible = $false

    $splashFadeIn = New-Object System.Windows.Media.Animation.DoubleAnimation
    $splashFadeIn.From = 0
    $splashFadeIn.To = 1
    $splashFadeIn.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(300))
    $splashFadeIn.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
    $splashFadeIn.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
    $SplashLoadingGroup.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $splashFadeIn)

    # Inner width of the thin progress bar: 260 fixed bar width - 2/2 inner grid margin
    $Global:SplashLoadFullWidth = 300 - 4
    $Global:SplashLoadPct = 0

    $Global:SplashLoadTimer = New-Object System.Windows.Threading.DispatcherTimer
    # Keep the loading screen visible long enough to read the status and feel the
    # hand-off, without introducing a long artificial wait.
    # 2% per 45ms gives about 2.25 seconds with much smoother progress updates.
    $Global:SplashLoadTimer.Interval = [TimeSpan]::FromMilliseconds(45)
    $Global:SplashLoadTimer.Add_Tick({
        $Global:SplashLoadPct += 2
        if ($Global:SplashLoadPct -ge 100) {
            $Global:SplashLoadPct = 100
        }
        $fillWidthNow = [double]$Global:SplashLoadFullWidth * ($Global:SplashLoadPct / 100.0)
        if($SplashLoadingFill){ $SplashLoadingFill.Width = $fillWidthNow }
        if($SplashRingPercentText){ $SplashRingPercentText.Text = "$($Global:SplashLoadPct)%" }

        $ringDash = $Global:SplashRingDashUnits * ($Global:SplashLoadPct / 100.0)
        $ringGap  = $Global:SplashRingDashUnits * 3
        $ringDashArray = New-Object System.Windows.Media.DoubleCollection
        [void]$ringDashArray.Add([double]$ringDash)
        [void]$ringDashArray.Add([double]$ringGap)
        if($SplashRingProgress){ $SplashRingProgress.StrokeDashArray = $ringDashArray }

        if ($Global:SplashLoadPct -ge 100) {
            if($Global:SplashLoadTimer){ $Global:SplashLoadTimer.Stop() }
            if($Global:SplashDotsTimer){ $Global:SplashDotsTimer.Stop() }
            try {
                if($SplashRingAmbientRotate){ $SplashRingAmbientRotate.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $null) }
                if($SplashLoadingFill){ $SplashLoadingFill.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null); $SplashLoadingFill.Opacity = 1 }
            } catch {}
            if($splashWindow){
                # Fade the loader out before handing control to the main window.
                $handoffFade = New-Object System.Windows.Media.Animation.DoubleAnimation
                $handoffFade.From = 1; $handoffFade.To = 0
                $handoffFade.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(260))
                $handoffFade.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
                $handoffFade.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
                $splashWindow.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $handoffFade)
                # Close from the current UI tick. A second DispatcherTimer can lose
                # its closure in a standalone/scriptblock runner, leaving the splash
                # at 100% and preventing the main window from opening.
                try { $splashWindow.Close() } catch {}
            }
        }
    })
    $Global:SplashLoadTimer.Start()
}

Add-ClickFX $BtnSplashStart
Add-ClickFX $BtnSplashMinimize
Add-ClickFX $BtnSplashClose

# The Launch button intentionally uses only its rounded template border.
# No DropShadowEffect is applied, so there is no outer glow around the control.
try { $BtnSplashStart.Effect = $null } catch {}
$BtnSplashStart.Add_Click({ Start-SplashLaunchFlow })
$BtnSplashClose.Add_Click({ $Global:SplashClosedByX = $true; $splashWindow.Close() })
$splashWindow.Add_Closed({ try { Stop-EmbeddedGifBackground -ScopeName "Splash" } catch {} })
$BtnSplashMinimize.Add_Click({ $splashWindow.WindowState = 'Minimized' })
$splashWindow.Add_ContentRendered({
    $Global:LessProjectHwidPassed = $true
})
$splashWindow.Add_PreviewKeyDown({
    param($sender, $eventArgs)
    if($eventArgs.Key -eq [System.Windows.Input.Key]::Enter){
        if($SplashStartGroup -and $SplashStartGroup.IsHitTestVisible){
            $eventArgs.Handled = $true
            Start-SplashLaunchFlow
        }
    } elseif($eventArgs.Key -eq [System.Windows.Input.Key]::Escape){
        $Global:SplashClosedByX = $true
        $splashWindow.Close()
        $eventArgs.Handled = $true
    }
})
# Allow the splash window to be dragged from any empty surface, not only the top bar.
# Interactive controls are excluded so buttons and text inputs keep their normal behavior.
# Use a Window-level preview handler. Child controls can otherwise swallow the
# bubbling mouse event, which makes the border/background feel impossible to drag.
# Preview routing catches the gesture first, while the interactive-control guard
# keeps Minimize, Close and Start buttons fully clickable.
$splashWindow.Add_PreviewMouseLeftButtonDown({
    param($sender, $eventArgs)
    $source = $eventArgs.OriginalSource -as [System.Windows.DependencyObject]
    $isInteractive = $false
    while ($source) {
        if ($source -is [System.Windows.Controls.Primitives.ButtonBase] -or
            $source -is [System.Windows.Controls.TextBox] -or
            $source -is [System.Windows.Controls.Primitives.ScrollBar]) {
            $isInteractive = $true
            break
        }
        try { $source = [System.Windows.Media.VisualTreeHelper]::GetParent($source) } catch { $source = $null }
    }
    if (-not $isInteractive -and $splashWindow.WindowState -ne [System.Windows.WindowState]::Maximized) {
        try {
            $eventArgs.Handled = $true
            $splashWindow.DragMove()
        } catch {}
    }
})

$splashWindow.ShowDialog() | Out-Null

if ($Global:SplashClosedByX) {
    # User closed the splash screen or did not authenticate - exit before the main console ever opens.
    try { if($Global:SystemInfoJob){ Stop-Job $Global:SystemInfoJob -ErrorAction SilentlyContinue; Remove-Job $Global:SystemInfoJob -Force -ErrorAction SilentlyContinue } } catch {}
    exit
}

# Main console redesign: a compact, card-based layout with static surfaces and only
# essential transitions.  It deliberately avoids expensive background animations.
$mainXamlStr = @"







<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="LESS PROJECT" Height="760" Width="1240" MinHeight="620" MinWidth="1120" WindowStartupLocation="CenterScreen" WindowStyle="None" AllowsTransparency="True" ResizeMode="CanResize" Background="Transparent" FontFamily="Segoe UI" UseLayoutRounding="True" SnapsToDevicePixels="True" HorizontalContentAlignment="Stretch" VerticalContentAlignment="Stretch">
 <Window.Resources>
  <Style TargetType="ScrollBar"><Setter Property="Background" Value="#161616"/><Setter Property="Foreground" Value="#4CB7FF"/><Setter Property="Width" Value="12"/><Setter Property="MinWidth" Value="12"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="ScrollBar"><Grid x:Name="Root" Width="12" Background="#141418"><Border Background="#242830" CornerRadius="6" Margin="3,8,3,8"/><Track x:Name="PART_Track" IsDirectionReversed="True"><Track.DecreaseRepeatButton><RepeatButton Command="ScrollBar.PageUpCommand" Opacity="0" Focusable="False"/></Track.DecreaseRepeatButton><Track.IncreaseRepeatButton><RepeatButton Command="ScrollBar.PageDownCommand" Opacity="0" Focusable="False"/></Track.IncreaseRepeatButton><Track.Thumb><Thumb><Thumb.Template><ControlTemplate TargetType="Thumb"><Border x:Name="ThumbBd" Background="#4CB7FF" CornerRadius="5" Margin="2,2" MinHeight="36"/><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="ThumbBd" Property="Background" Value="#8AD4FF"/></Trigger><Trigger Property="IsDragging" Value="True"><Setter TargetName="ThumbBd" Property="Background" Value="#D6F3FF"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Thumb.Template></Thumb></Track.Thumb></Track></Grid></ControlTemplate></Setter.Value></Setter><Style.Triggers><Trigger Property="Orientation" Value="Horizontal"><Setter Property="Width" Value="Auto"/><Setter Property="MinWidth" Value="0"/><Setter Property="Height" Value="12"/><Setter Property="MinHeight" Value="12"/></Trigger></Style.Triggers></Style>
  <Style x:Key="QuietButton" TargetType="Button"><Setter Property="Background" Value="#141414"/><Setter Property="Foreground" Value="#FAFAFA"/><Setter Property="BorderBrush" Value="#36566B"/><Setter Property="BorderThickness" Value="1"/><Setter Property="Height" Value="36"/><Setter Property="FontSize" Value="12"/><Setter Property="Cursor" Value="Hand"/><Setter Property="FontWeight" Value="SemiBold"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="Button"><Border x:Name="buttonBorder" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="10" Padding="12,0"><ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="buttonBorder" Property="Background" Value="#2A2A2A"/><Setter TargetName="buttonBorder" Property="BorderBrush" Value="#4CB7FF"/></Trigger><Trigger Property="IsPressed" Value="True"><Setter TargetName="buttonBorder" Property="Opacity" Value="0.72"/></Trigger><Trigger Property="IsEnabled" Value="False"><Setter TargetName="buttonBorder" Property="Opacity" Value="0.35"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
  <Style x:Key="TabButton" TargetType="Button"><Setter Property="Background" Value="Transparent"/><Setter Property="Foreground" Value="#D0D0D0"/><Setter Property="BorderThickness" Value="0"/><Setter Property="Height" Value="36"/><Setter Property="Cursor" Value="Hand"/><Setter Property="FontSize" Value="12"/><Setter Property="FontWeight" Value="SemiBold"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="Button"><Border x:Name="tabBorder" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="9" Padding="14,0"><ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="tabBorder" Property="Background" Value="#333333"/><Setter Property="Foreground" Value="#FFFFFF"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
  <Style x:Key="RailButton" TargetType="Button"><Setter Property="Background" Value="Transparent"/><Setter Property="Foreground" Value="#7E7E7E"/><Setter Property="BorderThickness" Value="0"/><Setter Property="Height" Value="38"/><Setter Property="Width" Value="38"/><Setter Property="FontSize" Value="13"/><Setter Property="FontWeight" Value="SemiBold"/><Setter Property="Cursor" Value="Hand"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="Button"><Border x:Name="railBorder" Background="{TemplateBinding Background}" CornerRadius="8"><ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="railBorder" Property="Background" Value="#2E2E2E"/><Setter Property="Foreground" Value="#FFFFFF"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
  <Style x:Key="SectionTitle" TargetType="TextBlock"><Setter Property="Foreground" Value="#E6E6E6"/><Setter Property="FontSize" Value="12"/><Setter Property="FontWeight" Value="Bold"/></Style>
  <Style x:Key="MetricLabel" TargetType="TextBlock"><Setter Property="Foreground" Value="#C4C4C4"/><Setter Property="FontSize" Value="11"/><Setter Property="FontWeight" Value="Bold"/></Style>
  <Style x:Key="MetricValue" TargetType="TextBlock"><Setter Property="Foreground" Value="#FFFFFF"/><Setter Property="FontSize" Value="13"/><Setter Property="FontWeight" Value="SemiBold"/></Style>
  <Style TargetType="ComboBoxItem"><Setter Property="Background" Value="#141418"/><Setter Property="Foreground" Value="#F5F5F5"/><Setter Property="Padding" Value="8,6"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="ComboBoxItem"><Border x:Name="CbItemBd" Background="{TemplateBinding Background}" Padding="{TemplateBinding Padding}"><ContentPresenter/></Border><ControlTemplate.Triggers><Trigger Property="IsHighlighted" Value="True"><Setter TargetName="CbItemBd" Property="Background" Value="#12324A"/><Setter Property="Foreground" Value="#FFFFFF"/></Trigger><Trigger Property="IsEnabled" Value="False"><Setter Property="Foreground" Value="#6A6A6A"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
  <SolidColorBrush x:Key="{x:Static SystemColors.WindowBrushKey}" Color="#141418"/>
  <SolidColorBrush x:Key="{x:Static SystemColors.WindowTextBrushKey}" Color="#F5F5F5"/>
  <SolidColorBrush x:Key="{x:Static SystemColors.HighlightBrushKey}" Color="#12324A"/>
  <SolidColorBrush x:Key="{x:Static SystemColors.HighlightTextBrushKey}" Color="#FFFFFF"/>
  <Style x:Key="DarkComboBox" TargetType="ComboBox"><Setter Property="Background" Value="#141A22"/><Setter Property="Foreground" Value="#EAF6FF"/><Setter Property="BorderBrush" Value="#445A70"/><Setter Property="BorderThickness" Value="1"/><Setter Property="Padding" Value="10,4"/><Setter Property="MaxDropDownHeight" Value="220"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="ComboBox"><Grid SnapsToDevicePixels="True"><ToggleButton x:Name="ToggleButton" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" Focusable="False" IsChecked="{Binding IsDropDownOpen, RelativeSource={RelativeSource TemplatedParent}, Mode=TwoWay}" ClickMode="Press"><ToggleButton.Template><ControlTemplate TargetType="ToggleButton"><Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="6"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="22"/></Grid.ColumnDefinitions><ContentPresenter Margin="{TemplateBinding Padding}" HorizontalAlignment="Left" VerticalAlignment="Center" TextElement.Foreground="{TemplateBinding Foreground}"/><Path Grid.Column="1" Data="M0,0 L4,4 L8,0 Z" Fill="#95A4B8" HorizontalAlignment="Center" VerticalAlignment="Center"/></Grid></Border></ControlTemplate></ToggleButton.Template></ToggleButton><ContentPresenter x:Name="ContentSite" HorizontalAlignment="Left" Margin="{TemplateBinding Padding}" VerticalAlignment="Center" IsHitTestVisible="False" Content="{TemplateBinding SelectionBoxItem}" ContentTemplate="{TemplateBinding SelectionBoxItemTemplate}" ContentTemplateSelector="{TemplateBinding ItemTemplateSelector}" TextElement.Foreground="{TemplateBinding Foreground}"/><Popup x:Name="Popup" Placement="Bottom" IsOpen="{TemplateBinding IsDropDownOpen}" AllowsTransparency="True" Focusable="False" PopupAnimation="Slide"><Border Background="#141A22" BorderBrush="#445A70" BorderThickness="1" CornerRadius="6" MinWidth="{Binding ActualWidth, RelativeSource={RelativeSource TemplatedParent}}" MaxHeight="{TemplateBinding MaxDropDownHeight}"><ScrollViewer SnapsToDevicePixels="True"><StackPanel IsItemsHost="True" KeyboardNavigation.DirectionalNavigation="Contained"/></ScrollViewer></Border></Popup></Grid></ControlTemplate></Setter.Value></Setter></Style>
  <Style TargetType="ComboBox"><Setter Property="Background" Value="#141418"/><Setter Property="Foreground" Value="#F5F5F5"/><Setter Property="BorderBrush" Value="#36566B"/><Setter Property="BorderThickness" Value="1"/><Setter Property="Padding" Value="8,4"/><Setter Property="MaxDropDownHeight" Value="220"/></Style>
  <Style x:Key="ToggleStyle" TargetType="CheckBox"><Setter Property="Cursor" Value="Hand"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="CheckBox"><Border x:Name="toggleTrack" Width="43" Height="22" CornerRadius="11" Background="#141414" BorderBrush="#3E3E3E" BorderThickness="1"><Border x:Name="toggleThumb" Width="14" Height="14" CornerRadius="7" Background="#8C8C8C" HorizontalAlignment="Left" Margin="3,0,0,0"/></Border><ControlTemplate.Triggers><Trigger Property="IsChecked" Value="True"><Setter TargetName="toggleTrack" Property="Background" Value="#181818"/><Setter TargetName="toggleTrack" Property="BorderBrush" Value="#4CB7FF"/><Setter TargetName="toggleThumb" Property="Background" Value="#4CB7FF"/><Setter TargetName="toggleThumb" Property="HorizontalAlignment" Value="Right"/><Setter TargetName="toggleThumb" Property="Margin" Value="0,0,3,0"/></Trigger><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="toggleTrack" Property="BorderBrush" Value="#4CB7FF"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
 </Window.Resources>
 <Border x:Name="MainChromeBorder" CornerRadius="16" ClipToBounds="True" BorderBrush="#2D9CDB" BorderThickness="1" HorizontalAlignment="Stretch" VerticalAlignment="Stretch">
  <Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,1"><GradientStop Color="#FF000000" Offset="0"/><GradientStop Color="#FF050505" Offset="0.66"/><GradientStop Color="#FF000000" Offset="1"/></LinearGradientBrush></Border.Background>
  <Grid x:Name="RootGrid" HorizontalAlignment="Stretch" VerticalAlignment="Stretch">
   <Grid.Clip><RectangleGeometry x:Name="RootClipGeom" Rect="0,0,1240,760" RadiusX="16" RadiusY="16"/></Grid.Clip>
   <Image x:Name="MainGifBackground" Stretch="UniformToFill" Opacity="1.0" Visibility="Visible" IsHitTestVisible="False" Panel.ZIndex="0" RenderOptions.BitmapScalingMode="HighQuality"/>
