"@
try {
    [xml]$xaml = $mainXamlStr
    $reader = New-Object System.Xml.XmlNodeReader $xaml
    $window = [Windows.Markup.XamlReader]::Load($reader)
} catch {
    try { Add-Content -LiteralPath $Global:UiErrorLogPath -Value ("$(Get-Date -Format o) Main WPF UI: $($_.Exception.ToString())") -Encoding UTF8 } catch {}
    Show-WinFormsHardwareFallback
    exit
}
$BrandLogoImage = $window.FindName("BrandLogoImage")
if($BrandLogoImage){
    $BrandLogoImage.Visibility=[System.Windows.Visibility]::Collapsed
    try {
        if($BrandLogoImage.Parent -is [System.Windows.Controls.Border]){
            $BrandLogoImage.Parent.Visibility=[System.Windows.Visibility]::Collapsed
            $BrandLogoImage.Parent.Width=0
            $BrandLogoImage.Parent.Height=0
            $BrandLogoImage.Parent.Margin=[System.Windows.Thickness]::new(0)
        }
    } catch {}
}

$MainBgCanvas = $window.FindName("MainBgCanvas")
$RootGrid = $window.FindName("RootGrid")
$Global:DisableLessProjectGlow = {
    param($node)
    if(-not $node){ return }
    try { if($node -is [System.Windows.UIElement]){ $node.Effect=$null } } catch {}
    try {
        if($node -is [System.Windows.Media.Visual]){
            for($i=0;$i -lt [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($node);$i++){
                & $Global:DisableLessProjectGlow ([System.Windows.Media.VisualTreeHelper]::GetChild($node,$i))
            }
        }
    } catch {}
}
function Disable-LessProjectGlow {
    try {
        if($GalaxyTimer){$GalaxyTimer.Stop()}
        if($Global:GlowTreeCleared){ return }
        $Global:GlowTreeCleared=$true
        & $Global:DisableLessProjectGlow $window
    } catch {}
}
function Initialize-LessProjectStaticBackdrop {
    if(-not $MainBgCanvas){ return }
    try {
        $MainBgCanvas.Children.Clear()
        $MainBgCanvas.ClipToBounds=$true
        $MainBgCanvas.IsHitTestVisible=$false
        $orbSpecs=@(
            @{W=560;H=320;L=-140;T=210;Op=0.07;Core='#664CB7FF';Edge='#004CB7FF'},
            @{W=460;H=280;L=700;T=-70;Op=0.045;Core='#44FFFFFF';Edge='#00FFFFFF'},
            @{W=380;H=240;L=320;T=470;Op=0.04;Core='#554CB7FF';Edge='#004CB7FF'}
        )
        foreach($spec in $orbSpecs){
            $orb=New-Object System.Windows.Shapes.Ellipse
            $orb.Width=$spec.W; $orb.Height=$spec.H
            [System.Windows.Controls.Canvas]::SetLeft($orb,$spec.L)
            [System.Windows.Controls.Canvas]::SetTop($orb,$spec.T)
            $orb.Opacity=$spec.Op
            $orb.IsHitTestVisible=$false
            $fill=New-Object System.Windows.Media.RadialGradientBrush
            $fill.GradientStops.Add((New-Object System.Windows.Media.GradientStop([System.Windows.Media.ColorConverter]::ConvertFromString($spec.Core),0)))
            $fill.GradientStops.Add((New-Object System.Windows.Media.GradientStop([System.Windows.Media.ColorConverter]::ConvertFromString($spec.Edge),1)))
            $orb.Fill=$fill
            [void]$MainBgCanvas.Children.Add($orb)
        }
        $MainBgCanvas.Opacity=1.0
        $MainBgCanvas.Visibility=[System.Windows.Visibility]::Visible
    } catch {}
}
$RootClipGeom = $window.FindName("RootClipGeom")
$MainChromeBorder = $window.FindName("MainChromeBorder")
$LeftNavRail = $window.FindName("LeftNavRail")
function Update-MainWindowChrome {
    try {
        $winW=[double]$window.ActualWidth
        $winH=[double]$window.ActualHeight
        if($winW -lt 8 -or $winH -lt 8){ return }
        $radius=16.0
        if($MainChromeBorder){
            $chromeClip=New-Object System.Windows.Media.RectangleGeometry
            $chromeClip.RadiusX=$radius
            $chromeClip.RadiusY=$radius
            $chromeClip.Rect=[System.Windows.Rect]::new(0,0,$winW,$winH)
            $MainChromeBorder.Clip=$chromeClip
            $MainChromeBorder.CornerRadius=[System.Windows.CornerRadius]::new($radius)
            $MainChromeBorder.Effect=$null
        }
        if($RootGrid -and $RootClipGeom){
            $innerW=[math]::Max(8,[double]$RootGrid.ActualWidth)
            $innerH=[math]::Max(8,[double]$RootGrid.ActualHeight)
            $RootClipGeom.RadiusX=[math]::Max(0,$radius-1)
            $RootClipGeom.RadiusY=[math]::Max(0,$radius-1)
            $RootClipGeom.Rect=[System.Windows.Rect]::new(0,0,$innerW,$innerH)
        }
    } catch {}
}
$MainGifBackground = $window.FindName("MainGifBackground")
try {
    if($MainGifBackground){ $MainGifBackground.Visibility=[System.Windows.Visibility]::Collapsed }
