function New-DashboardCard {
    param([string]$Title,[int]$Row,[int]$Column)
    $border=New-Object System.Windows.Controls.Border
    $border.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#D9111824')
    $border.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#667895A8')
    $border.BorderThickness=[System.Windows.Thickness]::new(1)
    $border.CornerRadius=[System.Windows.CornerRadius]::new(12)
    $border.Effect=$null
    $border.Padding=[System.Windows.Thickness]::new(16,15,16,15)
    $border.Margin=[System.Windows.Thickness]::new(5)
    [System.Windows.Controls.Grid]::SetRow($border,$Row); [System.Windows.Controls.Grid]::SetColumn($border,$Column)
    $clipHost=New-Object System.Windows.Controls.Border
    $clipHost.ClipToBounds=$true
    $clipHost.Background=[System.Windows.Media.Brushes]::Transparent
    $grid=New-Object System.Windows.Controls.Grid
    $grid.ClipToBounds=$true
    $headerRow=New-Object System.Windows.Controls.RowDefinition; $headerRow.Height=New-Object System.Windows.GridLength(32); [void]$grid.RowDefinitions.Add($headerRow)
    $contentRow=New-Object System.Windows.Controls.RowDefinition; $contentRow.Height=New-Object System.Windows.GridLength(1,[System.Windows.GridUnitType]::Star); [void]$grid.RowDefinitions.Add($contentRow)
    $header=New-Object System.Windows.Controls.StackPanel; [System.Windows.Controls.Grid]::SetRow($header,0); $header.Orientation='Horizontal'; $header.HorizontalAlignment='Left'; $header.VerticalAlignment='Top'; $header.Height=28
    $cardIconMap=@{'SYSTEM OVERVIEW'='◈';'QUICK ACTIONS'='⚡';'START LESS PROJECT'='▶';'LIVE LOG'='▣';'PERFORMANCE BOOST'='△'}
    $headIcon=New-Object System.Windows.Controls.TextBlock; $headIcon.Text=$cardIconMap[$Title]; $headIcon.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#4CB7FF'); $headIcon.FontFamily='Segoe UI Symbol'; $headIcon.FontSize=13; $headIcon.Width=24; $headIcon.Height=22; $headIcon.TextAlignment='Center'; $headIcon.VerticalAlignment='Center'; $headIcon.Margin=[System.Windows.Thickness]::new(0,0,4,0)
    $head=New-Object System.Windows.Controls.TextBlock; $head.Text=$Title; $head.Foreground=[System.Windows.Media.Brushes]::White; $head.FontFamily='Segoe UI'; $head.FontSize=12; $head.FontWeight='Bold'; $head.VerticalAlignment='Center'; $head.TextAlignment='Left'; [System.Windows.Media.TextOptions]::SetTextFormattingMode($head,[System.Windows.Media.TextFormattingMode]::Ideal)
    [void]$header.Children.Add($headIcon); [void]$header.Children.Add($head); [void]$grid.Children.Add($header); $clipHost.Child=$grid; $border.Child=$clipHost
    return @($border,$grid)
}
