function New-DashboardPerfBar {
    param([string]$Label,[double]$Width=150)
    $wrap=New-Object System.Windows.Controls.StackPanel; $wrap.Orientation='Horizontal'; $wrap.Margin=[System.Windows.Thickness]::new(0,0,10,0); $wrap.VerticalAlignment='Center'
    $lab=New-Object System.Windows.Controls.TextBlock; $lab.Text=$Label; $lab.Width=34; $lab.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#95A4B8'); $lab.FontSize=9; $lab.FontWeight='Bold'; $lab.VerticalAlignment='Center'
    $track=New-Object System.Windows.Controls.Border; $track.Width=$Width; $track.Height=8; $track.CornerRadius=[System.Windows.CornerRadius]::new(4); $track.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#18202D'); $track.ClipToBounds=$true
    $fill=New-Object System.Windows.Controls.Border; $fill.Width=0; $fill.Height=8; $fill.CornerRadius=[System.Windows.CornerRadius]::new(4); $fill.HorizontalAlignment='Left'; $fill.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#4CB7FF')
    $track.Child=$fill
    $val=New-Object System.Windows.Controls.TextBlock; $val.Text='0%'; $val.Width=34; $val.Margin=[System.Windows.Thickness]::new(6,0,0,0); $val.Foreground=[System.Windows.Media.Brushes]::White; $val.FontSize=9; $val.FontWeight='SemiBold'; $val.VerticalAlignment='Center'
    [void]$wrap.Children.Add($lab); [void]$wrap.Children.Add($track); [void]$wrap.Children.Add($val)
    return [pscustomobject]@{Host=$wrap;Track=$track;Fill=$fill;Value=$val}
}
