 # PowerShell requires a real variable before it can be passed by reference.
 # Initialising these holders also makes dashboard construction reliable in a
 # clean session (and in the standalone/scriptblock runner).
 $OverviewCpuValue=$null; $OverviewGpuValue=$null; $OverviewRamValue=$null
 $OverviewStorageValue=$null; $OverviewBoardValue=$null; $OverviewOsValue=$null
 $OverviewBiosValue=$null; $OverviewDisplayValue=$null; $OverviewNetValue=$null
 New-OverviewMetric 'CPU' 0 0 ([ref]$OverviewCpuValue); New-OverviewMetric 'GPU' 0 1 ([ref]$OverviewGpuValue); New-OverviewMetric 'RAM' 0 2 ([ref]$OverviewRamValue); New-OverviewMetric 'STORAGE' 1 0 ([ref]$OverviewStorageValue); New-OverviewMetric 'WINDOWS' 1 1 ([ref]$OverviewOsValue); New-OverviewMetric 'DISPLAY' 1 2 ([ref]$OverviewDisplayValue); New-OverviewMetric 'NETWORK' 2 0 ([ref]$OverviewNetValue)
function Set-SystemOverviewHardwareText {
    try {
        $s=$Global:SysInfo; if(-not $s){return}
        $cpu=[string]$s.CPU; if([string]::IsNullOrWhiteSpace($cpu) -or $cpu -eq 'Detecting...'){$cpu='CPU not detected'}
        $gpu=[string]$s.GPU; if([string]::IsNullOrWhiteSpace($gpu) -or $gpu -eq 'Detecting...'){$gpu='GPU not detected'}
        $ram=if([int]$s.RAM -gt 0){"$($s.RAM) GB"}else{'RAM not detected'}
        $storage=[string]$s.Storage; if([string]::IsNullOrWhiteSpace($storage) -or $storage -match 'Detecting'){$storage='Storage not detected'}
        $board=[string]$s.Board; if([string]::IsNullOrWhiteSpace($board)){$board='Motherboard not detected'}
        $os=[string]$s.OS; if([string]::IsNullOrWhiteSpace($os) -or $os -match 'Detecting'){$os='Windows not detected'}
        $bios=[string]$s.BIOS; if([string]::IsNullOrWhiteSpace($bios)){$bios='BIOS not detected'}
        $display=[string]$s.Display; if([string]::IsNullOrWhiteSpace($display) -or $display -match 'Detecting'){$display='Display not detected'}
        $network=('{0} / {1}' -f $(if([string]::IsNullOrWhiteSpace([string]$s.NetType) -or [string]$s.NetType -eq 'None'){'Network not detected'}else{$s.NetType}),$(if([string]::IsNullOrWhiteSpace([string]$s.Adapter) -or [string]$s.Adapter -eq 'No Adapter'){'Adapter not detected'}else{$s.Adapter}))
        $OverviewCpuValue.Text=$cpu; $OverviewGpuValue.Text=$gpu; $OverviewRamValue.Text=$ram; $OverviewStorageValue.Text=$storage; $OverviewBoardValue.Text=$board; $OverviewOsValue.Text=$os; $OverviewBiosValue.Text=$bios; $OverviewDisplayValue.Text=$display; $OverviewNetValue.Text=$network
        $OverviewCpuValue.ToolTip=$cpu; $OverviewGpuValue.ToolTip=$gpu; $OverviewRamValue.ToolTip=$ram; $OverviewStorageValue.ToolTip=$storage; $OverviewBoardValue.ToolTip=$board; $OverviewOsValue.ToolTip=$os; $OverviewBiosValue.ToolTip=$bios; $OverviewDisplayValue.ToolTip=$display; $OverviewNetValue.ToolTip=$network
    } catch {}
}
