function Invoke-QuickUserOptimize {
    $safeFunctions=@('Run-MenuInstant','Run-FSOptim','Run-Notifications','Run-GameMode','Run-NoGameDVR','Run-NoStickyKeys')
    $applied=0
    foreach($fn in $safeFunctions){
        try { if(Get-Command $fn -ErrorAction SilentlyContinue){ & $fn; $applied++ } } catch { Add-Log ("User optimization skipped: {0}" -f $fn) '#A0A0A0' }
    }
    Save-TweakState
    Set-CurrentTask ("USER MODE OPTIMIZE COMPLETE / {0} safe actions" -f $applied)
    Add-Log ("Quick Optimize completed in User Mode: {0} safe per-user actions" -f $applied) '#FFFFFF'
    Show-TweakToast -Label 'OPTIMIZE SYSTEM' -Enabled $true -OverrideText 'USER MODE / COMPLETE' -DurationMs 2200
}
function Invoke-QuickUserMemoryCleanup {
    try {
        Set-CurrentTask 'USER MODE MEMORY CLEANUP'
        [GC]::Collect(); [GC]::WaitForPendingFinalizers(); [GC]::Collect()
        if(-not ('LessProject.NativeMemory' -as [type])){
            Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
namespace LessProject { public static class NativeMemory {
 [DllImport("psapi.dll", SetLastError=true)] public static extern bool EmptyWorkingSet(IntPtr hProcess);
}}
'@ -ErrorAction Stop
        }
        $currentProcess=[System.Diagnostics.Process]::GetCurrentProcess()
        $before=[math]::Round($currentProcess.WorkingSet64/1MB,1)
        [void][LessProject.NativeMemory]::EmptyWorkingSet($currentProcess.Handle)
        $currentProcess.Refresh()
        $after=[math]::Round($currentProcess.WorkingSet64/1MB,1)
        Add-Log ("Working set trim completed: {0} MB -> {1} MB. Protected system standby memory was not touched." -f $before,$after) '#FFFFFF'
        Set-CurrentTask 'USER MODE MEMORY CLEANUP COMPLETE'
        Show-TweakToast -Label 'RAMMAP CLEAN' -Enabled $true -OverrideText 'WORKING SET / COMPLETE' -DurationMs 2200
    } catch {
        Add-Log ("User Mode memory cleanup skipped: {0}" -f $_.Exception.Message) '#A0A0A0'
        Show-TweakToast -Label 'RAMMAP CLEAN' -Enabled $false -OverrideText 'USER MODE / SKIPPED' -DurationMs 2200
    }
}
