function New-SettingsCard {
    param([string]$Title)
    $card=New-Object System.Windows.Controls.Border
    $card.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#D9111824')
    $card.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#667895A8')
    $card.BorderThickness=[System.Windows.Thickness]::new(1)
    $card.CornerRadius=[System.Windows.CornerRadius]::new(12)
    $card.Padding=[System.Windows.Thickness]::new(18,16,18,16)
    $card.Margin=[System.Windows.Thickness]::new(0,0,0,12)
    $head=New-Object System.Windows.Controls.TextBlock; $head.Text=$Title; $head.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#4CB7FF'); $head.FontFamily='Segoe UI'; $head.FontSize=12; $head.FontWeight='Bold'; $head.Margin=[System.Windows.Thickness]::new(0,0,0,12)
    $body=New-Object System.Windows.Controls.StackPanel
    [void]$body.Children.Add($head)
    $card.Child=$body
    return @($card,$body)
}
