function Sync-SettingsPanelFromGlobals {
    try {
        if($SettingsMotionCombo){ $SettingsMotionCombo.SelectedItem=[string]$Global:MainMotionProfile }
        if($SettingsSoundToggle){ $SettingsSoundToggle.IsChecked=[bool]$Global:SoundFxEnabled }
        if($SettingsGamePathBox){ $SettingsGamePathBox.Text=[string]$Global:GameFolderPath }
    } catch {}
}
function Save-SettingsFromPanel {
    try {
        if($SettingsMotionCombo -and $SettingsMotionCombo.SelectedItem){ $Global:MainMotionProfile=[string]$SettingsMotionCombo.SelectedItem }
        if($SettingsSoundToggle){ $Global:SoundFxEnabled=[bool]$SettingsSoundToggle.IsChecked }
        if($SettingsGamePathBox){ $Global:GameFolderPath=[string]$SettingsGamePathBox.Text.Trim() }
        Save-LessProjectSettings
        Add-Log 'Settings saved.' '#4CB7FF'
        Update-DashboardStatusPanel
        Show-TweakToast -Label 'SETTINGS' -Enabled $true -OverrideText 'SETTINGS  /  SAVED' -DurationMs 1800
    } catch {
        Add-Log ("Settings save failed: {0}" -f $_.Exception.Message) '#D8D8D8'
    }
}
$SettingsSaveButton.Add_Click({ Save-SettingsFromPanel })
$SettingsBrowseButton.Add_Click({
    try {
        Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
        $dialog=New-Object System.Windows.Forms.FolderBrowserDialog
        $dialog.Description='Select your FiveM folder'
        if($SettingsGamePathBox -and -not [string]::IsNullOrWhiteSpace($SettingsGamePathBox.Text)){ $dialog.SelectedPath=[string]$SettingsGamePathBox.Text }
        if($dialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK){
            $SettingsGamePathBox.Text=[string]$dialog.SelectedPath
        }
    } catch {
        Add-Log ("Folder browse failed: {0}" -f $_.Exception.Message) '#D8D8D8'
    }
})
$SettingsRestorePointButton.Add_Click({ Start-CreateRestorePointAsync })
$SettingsRecoveryButton.Add_Click({ Show-RecoveryCenter })
$SettingsAutoDetectButton.Add_Click({
    try {
        $found=Resolve-FiveMGameFolderPath
        if($found){
            if($SettingsGamePathBox){ $SettingsGamePathBox.Text=$found }
            Show-TweakToast -Label 'FIVEM' -Enabled $true -OverrideText 'FIVEM  /  DETECTED' -DurationMs 1800
        } else {
            [System.Windows.MessageBox]::Show('ไม่พบโฟลเดอร์ FiveM บนเครื่องนี้ กรุณาเลือกด้วย BROWSE','LESS PROJECT / FIVEM',[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Information)|Out-Null
        }
    } catch {
        Add-Log ("FiveM auto-detect failed: {0}" -f $_.Exception.Message) '#D8D8D8'
    }
})
