function Apply-PremiumMonochromeTheme {
    try {
        $window.Background=[System.Windows.Media.Brushes]::Transparent
        if($RootGrid){$RootGrid.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#070B10')}
        if($MainChromeBorder){
            $MainChromeBorder.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#664CB7FF')
            $MainChromeBorder.BorderThickness=[System.Windows.Thickness]::new(1.2)
            $chromeBg=New-Object System.Windows.Media.LinearGradientBrush
            $chromeBg.StartPoint=New-Object System.Windows.Point(0,0)
            $chromeBg.EndPoint=New-Object System.Windows.Point(1,1)
            $chromeBg.GradientStops.Add((New-Object System.Windows.Media.GradientStop([System.Windows.Media.ColorConverter]::ConvertFromString('#FF060910'),0)))
            $chromeBg.GradientStops.Add((New-Object System.Windows.Media.GradientStop([System.Windows.Media.ColorConverter]::ConvertFromString('#FF0B121A'),0.55)))
            $chromeBg.GradientStops.Add((New-Object System.Windows.Media.GradientStop([System.Windows.Media.ColorConverter]::ConvertFromString('#FF060910'),1)))
            $MainChromeBorder.Background=$chromeBg
            $MainChromeBorder.Effect=$null
        }
        if($LeftNavRail){
            $LeftNavRail.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#CC0E1319')
            $LeftNavRail.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#554CB7FF')
            $LeftNavRail.BorderThickness=[System.Windows.Thickness]::new(1)
            $LeftNavRail.CornerRadius=[System.Windows.CornerRadius]::new(14)
        }
        if($side){
            $side.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#CC0E1319')
            $side.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#554CB7FF')
            $side.BorderThickness=[System.Windows.Thickness]::new(1)
            $side.CornerRadius=[System.Windows.CornerRadius]::new(14)
        }
        if($ToolsSubNav){
            $ToolsSubNav.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#CC121820')
            $ToolsSubNav.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#445A7080')
        }
        foreach($nav in @($BtnTabDashboard,$BtnTabTools,$BtnTabFiveM,$BtnTabReshade,$BtnTabSettings,$BtnTabWin32,$BtnTabNetTweaks,$BtnTabAppSettings)){
            if($nav){$nav.FontFamily='Segoe UI';$nav.FontSize=12;$nav.FontWeight='SemiBold';$nav.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#E8E8E8');$nav.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#141A22');$nav.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#445A7080');$nav.BorderThickness=[System.Windows.Thickness]::new(1);$nav.Height=52;$nav.MinHeight=52;$nav.HorizontalAlignment='Stretch';$nav.Margin=[System.Windows.Thickness]::new(0,0,0,6)}
        }
        foreach($card in @($ovb,$qab,$rab,$pab)){
            if($card){
                $card.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#D9111824')
                $card.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#667895A8')
                $card.BorderThickness=[System.Windows.Thickness]::new(1)
                $card.CornerRadius=[System.Windows.CornerRadius]::new(12)
                $card.Effect=$null
            }
        }
        if($DashboardPanel){ $DashboardPanel.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#070B10') }
        if($StatusText){ $StatusText.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#EAF6FF') }
        if($StatusDotEllipse){ $StatusDotEllipse.Fill=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#4CB7FF') }
        if($BtnRun){
            $BtnRun.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#1A2533')
            $BtnRun.Foreground=[System.Windows.Media.Brushes]::White
            $BtnRun.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#4CB7FF')
        }
        foreach($child in @($DashboardPanel.Children)){
            if($child -is [System.Windows.Controls.TextBlock]){$child.FontFamily='Segoe UI'}
        }
    } catch {}
}
