function Add-PressMotion{
    param($Control,[double]$PressScale=0.94,[double]$PressOffset=3)
    if(-not $Control -or ([string]$Global:MainMotionProfile -eq "Off")){ return }
    try {
        $Control.RenderTransformOrigin=[System.Windows.Point]::new(0.5,0.5)
        $pressGroup=New-Object System.Windows.Media.TransformGroup
        $pressScaleTransform=New-Object System.Windows.Media.ScaleTransform
        $pressTranslate=New-Object System.Windows.Media.TranslateTransform
        [void]$pressGroup.Children.Add($pressScaleTransform)
        [void]$pressGroup.Children.Add($pressTranslate)
        $Control.RenderTransform=$pressGroup
        $Control.Add_PreviewMouseDown({
            param($sender,$eventArgs)
            try {
                $downScale=New-Object System.Windows.Media.Animation.DoubleAnimation
                $downScale.To=$PressScale
                $downScale.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(70))
                $downScale.EasingFunction=New-Object System.Windows.Media.Animation.QuadraticEase
                $downOffset=New-Object System.Windows.Media.Animation.DoubleAnimation
                $downOffset.To=$PressOffset
                $downOffset.Duration=$downScale.Duration
                $downOffset.EasingFunction=$downScale.EasingFunction
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$downScale)
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$downScale.Clone())
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty,$downOffset)
                if($sender.Effect -and $sender.Effect.PSObject.Properties["ShadowDepth"]){$sender.Effect.ShadowDepth=1}
                if($sender.Effect -and $sender.Effect.PSObject.Properties["Opacity"]){$sender.Effect.Opacity=0.30}
            } catch {}
        }.GetNewClosure())
        $Control.Add_PreviewMouseUp({
            param($sender,$eventArgs)
            try {
                $upScale=New-Object System.Windows.Media.Animation.DoubleAnimation
                $upScale.To=1.0
                $upScale.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(115))
                $upScale.EasingFunction=New-Object System.Windows.Media.Animation.BackEase
                $upScale.EasingFunction.Amplitude=0.18
                $upOffset=New-Object System.Windows.Media.Animation.DoubleAnimation
                $upOffset.To=0.0
                $upOffset.Duration=$upScale.Duration
                $upOffset.EasingFunction=$upScale.EasingFunction
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$upScale)
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$upScale.Clone())
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty,$upOffset)
                if($sender.Effect -and $sender.Effect.PSObject.Properties["ShadowDepth"]){$sender.Effect.ShadowDepth=8}
                if($sender.Effect -and $sender.Effect.PSObject.Properties["Opacity"]){$sender.Effect.Opacity=0.66}
            } catch {}
        }.GetNewClosure())
        $Control.Add_MouseLeave({
            param($sender,$eventArgs)
            try {
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$null)
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$null)
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty,$null)
                $pressScaleTransform.ScaleX=1.0; $pressScaleTransform.ScaleY=1.0; $pressTranslate.Y=0.0
                if($sender.Effect -and $sender.Effect.PSObject.Properties["ShadowDepth"]){$sender.Effect.ShadowDepth=8}
                if($sender.Effect -and $sender.Effect.PSObject.Properties["Opacity"]){$sender.Effect.Opacity=0.66}
            } catch {}
        }.GetNewClosure())
    } catch {}
}
function Add-HoverMotion{
    param($Control,[double]$Scale=-1)
    if(-not $Control -or ([string]$Global:MainMotionProfile -eq "Off")){ return }
    if($Scale -lt 0){ $Scale=Get-HoverMotionScale }
    try {
        $Control.RenderTransformOrigin=[System.Windows.Point]::new(0.5,0.5)
        $hoverScale=New-Object System.Windows.Media.ScaleTransform
        $hoverScale.ScaleX=1.0; $hoverScale.ScaleY=1.0
        $Control.RenderTransform=$hoverScale
        $enterTarget=$Scale
        $enterMs=Get-MainMotionMs 110
        $leaveMs=Get-MainMotionMs 130
        $enter={
            param($sender,$eventArgs)
            try {
                $aX=New-Object System.Windows.Media.Animation.DoubleAnimation; $aX.To=$enterTarget; $aX.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds($enterMs)); $aX.EasingFunction=New-Object System.Windows.Media.Animation.CubicEase
                $aY=$aX.Clone()
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$aX)
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$aY)
            } catch {}
        }.GetNewClosure()
        $leave={
            param($sender,$eventArgs)
            try {
                $aX=New-Object System.Windows.Media.Animation.DoubleAnimation; $aX.To=1.0; $aX.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds($leaveMs)); $aX.EasingFunction=New-Object System.Windows.Media.Animation.CubicEase
                $aY=$aX.Clone()
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$aX)
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$aY)
            } catch {}
        }.GetNewClosure()
        $Control.Add_MouseEnter($enter); $Control.Add_MouseLeave($leave)
    } catch {}
}
function Add-PremiumButtonMotion {
    param(
        $Control,
        [ValidateSet("Install","Road","Uninstall")][string]$ToneType,
        [string]$GlowColor="#FFFFFF",
        [double]$HoverScale=1.035,
        [double]$PressScale=0.94,
        [double]$PressOffset=3,
        [double]$BaseBlur=12,
        [double]$BaseDepth=3,
        [double]$BaseOpacity=0.44,
        [double]$GlowBlur=22,
        [double]$GlowDepth=7,
        [double]$GlowOpacity=0.78
    )
    if(-not $Control){ return }
    try {
        $Control.RenderTransformOrigin=[System.Windows.Point]::new(0.5,0.5)
        $motionGroup=New-Object System.Windows.Media.TransformGroup
        $hoverScaleTransform=New-Object System.Windows.Media.ScaleTransform
        $pressScaleTransform=New-Object System.Windows.Media.ScaleTransform
        $translateTransform=New-Object System.Windows.Media.TranslateTransform
        [void]$motionGroup.Children.Add($hoverScaleTransform)
        [void]$motionGroup.Children.Add($pressScaleTransform)
        [void]$motionGroup.Children.Add($translateTransform)
        $Control.RenderTransform=$motionGroup
        $glowBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString($GlowColor)
        $glowColorValue=([System.Windows.Media.SolidColorBrush]$glowBrush).Color
        # Keep the premium motion crisp and clipped: no DropShadowEffect is used
        # on moving buttons because it can bleed outside the rounded window frame.
        $Control.Effect=$null
        $baseColor=[System.Windows.Media.Colors]::Transparent
        $enter={
            param($sender,$eventArgs)
            try {
                $a=New-Object System.Windows.Media.Animation.DoubleAnimation
                $a.To=$HoverScale; $a.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(135)); $a.EasingFunction=New-Object System.Windows.Media.Animation.CubicEase
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$a)
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$a.Clone())
                if($sender.Effect){$sender.Effect.Color=$glowColorValue; $sender.Effect.BlurRadius=$GlowBlur; $sender.Effect.ShadowDepth=$GlowDepth; $sender.Effect.Opacity=$GlowOpacity}
                if($ToneType -eq "Install"){ Play-ReshadeHoverTone }
            } catch {}
        }.GetNewClosure()
        $leave={
            param($sender,$eventArgs)
            try {
                $a=New-Object System.Windows.Media.Animation.DoubleAnimation
                $a.To=1.0; $a.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(160)); $a.EasingFunction=New-Object System.Windows.Media.Animation.CubicEase
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$a)
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$a.Clone())
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty,$null)
                if($sender.Effect){$sender.Effect.Color=$baseColor; $sender.Effect.BlurRadius=$BaseBlur; $sender.Effect.ShadowDepth=$BaseDepth; $sender.Effect.Opacity=$BaseOpacity}
            } catch {}
        }.GetNewClosure()
        $down={
            param($sender,$eventArgs)
            try {
                $a=New-Object System.Windows.Media.Animation.DoubleAnimation
                $a.To=$PressScale; $a.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(65)); $a.EasingFunction=New-Object System.Windows.Media.Animation.QuadraticEase
                $b=New-Object System.Windows.Media.Animation.DoubleAnimation
                $b.To=$PressOffset; $b.Duration=$a.Duration; $b.EasingFunction=$a.EasingFunction
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$a)
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$a.Clone())
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty,$b)
                if($sender.Effect){$sender.Effect.Color=$glowColorValue; $sender.Effect.BlurRadius=[math]::Max(8,$BaseBlur-2); $sender.Effect.ShadowDepth=1; $sender.Effect.Opacity=0.34}
                Play-ReshadeButtonTone -Type $ToneType
            } catch {}
        }.GetNewClosure()
        $up={
            param($sender,$eventArgs)
            try {
                $targetScale=if($sender.IsMouseOver){$HoverScale}else{1.0}
                $a=New-Object System.Windows.Media.Animation.DoubleAnimation
                $a.To=$targetScale; $a.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(120)); $a.EasingFunction=New-Object System.Windows.Media.Animation.BackEase; $a.EasingFunction.Amplitude=0.16
                $b=New-Object System.Windows.Media.Animation.DoubleAnimation
                $b.To=0.0; $b.Duration=$a.Duration; $b.EasingFunction=$a.EasingFunction
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$a)
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$a.Clone())
                $sender.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty,$b)
                if($sender.Effect){
                    if($sender.IsMouseOver){$sender.Effect.Color=$glowColorValue; $sender.Effect.BlurRadius=$GlowBlur; $sender.Effect.ShadowDepth=$GlowDepth; $sender.Effect.Opacity=$GlowOpacity}
                    else {$sender.Effect.Color=$baseColor; $sender.Effect.BlurRadius=$BaseBlur; $sender.Effect.ShadowDepth=$BaseDepth; $sender.Effect.Opacity=$BaseOpacity}
                }
            } catch {}
        }.GetNewClosure()
        $Control.Add_MouseEnter($enter); $Control.Add_MouseLeave($leave); $Control.Add_PreviewMouseDown($down); $Control.Add_PreviewMouseUp($up)
    } catch {}
}
