function Get-SafeDashboardPercent {
    param([object]$Value)
    try {
        $candidate=@($Value) | Select-Object -First 1
        $n=[double]$candidate
        if([double]::IsNaN($n) -or [double]::IsInfinity($n)){return 0}
        return [int][math]::Round([math]::Max(0,[math]::Min(100,$n)))
    } catch { return 0 }
}
function ConvertTo-MetricPercent {
    param([object]$Value)
    try {
        $n=[double]$Value
        if([double]::IsNaN($n) -or [double]::IsInfinity($n)){return 0}
        return [int][math]::Round([math]::Max(0,[math]::Min(100,$n)))
    } catch { return 0 }
}
function Get-RealtimeDashboardMetrics {
    param([int]$RamUsedPct=0)
    # Keep the clamp local because this function is serialized into Start-Job/ThreadJob.
    function ConvertTo-MetricPercentLocal {
        param([object]$Value)
        try {
            $n=[double]$Value
            if([double]::IsNaN($n) -or [double]::IsInfinity($n)){return 0}
            return [int][math]::Round([math]::Max(0,[math]::Min(100,$n)))
        } catch { return 0 }
    }
    $m=[ordered]@{CPU=0;GPU=0;RAM=0;DISK=0;NET=0}
    try {
        # CIM formatted counters avoid localized counter-name failures on non-English Windows.
        $cpuCim=Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor -Filter "Name='_Total'" -ErrorAction SilentlyContinue
        if($cpuCim){$m.CPU=ConvertTo-MetricPercentLocal $cpuCim.PercentProcessorTime}
        else {
            $c=Get-Counter '\Processor(_Total)\% Processor Time' -ErrorAction SilentlyContinue
            if($c){$m.CPU=ConvertTo-MetricPercentLocal $c.CounterSamples[0].CookedValue}
        }
    } catch {}
    $m.RAM=ConvertTo-MetricPercentLocal $RamUsedPct
    try {
        $gpuSamples=Get-Counter '\GPU Engine(*)\Utilization Percentage' -ErrorAction SilentlyContinue
        if($gpuSamples){$m.GPU=ConvertTo-MetricPercentLocal (($gpuSamples.CounterSamples | Measure-Object CookedValue -Maximum).Maximum)}
    } catch {}
    try {
        $diskCim=Get-CimInstance Win32_PerfFormattedData_PerfDisk_PhysicalDisk -Filter "Name='_Total'" -ErrorAction SilentlyContinue
        if($diskCim){$m.DISK=ConvertTo-MetricPercentLocal $diskCim.PercentDiskTime}
        else {
            $diskSamples=Get-Counter '\PhysicalDisk(_Total)\% Disk Time' -ErrorAction SilentlyContinue
            if($diskSamples){$m.DISK=ConvertTo-MetricPercentLocal $diskSamples.CounterSamples[0].CookedValue}
        }
    } catch {}
    try {
        # Instantaneous throughput; always clamp after conversion to prevent huge percentages.
        $netSamples=Get-Counter '\Network Interface(*)\Bytes Total/sec' -ErrorAction SilentlyContinue
        if($netSamples){
            $bytesPerSecond=($netSamples.CounterSamples | Measure-Object CookedValue -Sum).Sum
            $m.NET=ConvertTo-MetricPercentLocal (([double]$bytesPerSecond)/1048576)
        }
    } catch {}
    return [pscustomobject]@{CPU=(ConvertTo-MetricPercentLocal $m.CPU);GPU=(ConvertTo-MetricPercentLocal $m.GPU);RAM=(ConvertTo-MetricPercentLocal $m.RAM);DISK=(ConvertTo-MetricPercentLocal $m.DISK);NET=(ConvertTo-MetricPercentLocal $m.NET)}
}
$Global:DashboardDisplayCache=$null
function Get-StableDashboardMetrics {
    param([object]$RawMetrics)
    try {
        if(-not $RawMetrics){ return $null }
        if(-not $Global:DashboardDisplayCache){
            $Global:DashboardDisplayCache=[pscustomobject]@{CPU=0.0;GPU=0.0;RAM=0.0;DISK=0.0;NET=0.0}
        }
        # EMA smoothing plus a per-refresh slew limit. This keeps the dashboard
        # realtime without making one noisy counter sample redraw the whole graph.
        $alpha=0.28
        $maxStep=14.0
        foreach($name in @('CPU','GPU','RAM','DISK','NET')){
            $target=[double]$RawMetrics.$name
            $target=[math]::Max(0.0,[math]::Min(100.0,$target))
            $current=[double]$Global:DashboardDisplayCache.$name
            $delta=$target-$current
            if([math]::Abs($delta) -gt $maxStep){$delta=if($delta -gt 0){$maxStep}else{-$maxStep}}
            $next=$current+($delta*$alpha)
            $Global:DashboardDisplayCache.$name=$next
        }
        return $Global:DashboardDisplayCache
    } catch { return $RawMetrics }
}
function Update-SystemInfoUi {
    try {
        # Read the first hardware snapshot synchronously before the dashboard is
        # shown. This prevents the cards from opening with Detecting... values.
        # Later refreshes remain asynchronous so the UI stays responsive.
        if(-not $Global:SystemInfoLoaded -and -not $Global:SystemInfoJobStarted){
            $Global:SystemInfoJobStarted=$true
            try {
                if(Get-Command Start-ThreadJob -ErrorAction SilentlyContinue){
                    $Global:SystemInfoJob=Start-ThreadJob -ScriptBlock ${function:Get-SystemInfo} -ErrorAction Stop
                } else {
                    $Global:SystemInfoJob=Start-Job -ScriptBlock ${function:Get-SystemInfo} -ErrorAction Stop
                }
            } catch {
                $Global:SystemInfoFallbackAttempted=$true
                $Global:SystemInfoLoaded=$true
                $Global:SysInfo=[pscustomobject]@{OS="Windows"; CPU='CPU not detected'; GPU="GPU not detected"; RAM=0; RAMType="Unknown"; Adapter="Adapter not detected"; NetType="Unknown"; RAMUsedPct=0; Board="Motherboard not detected"; BIOS="BIOS not detected"; Storage="Storage not detected"; Display="Display not detected"; Arch=$env:PROCESSOR_ARCHITECTURE}
                $Global:SystemInfoRefreshAt=Get-Date
            }
        }
        # Pick up the latest hardware snapshot, then schedule the next one.
        Receive-SystemInfoRefreshJob
        if($Global:SystemInfoLoaded -and -not $Global:SystemInfoRefreshJob -and ((Get-Date)-$Global:SystemInfoRefreshAt).TotalSeconds -ge $Global:SystemInfoRefreshIntervalSeconds){
            Start-SystemInfoRefreshJob
        }
        if(-not $Global:DashboardMetricsCache){$Global:DashboardMetricsCache=[pscustomobject]@{CPU=0;GPU=0;RAM=0;DISK=0;NET=0};$Global:DashboardMetricsAt=[datetime]::MinValue}
        if(-not $Global:DashboardMetricsJob -and ((Get-Date)-$Global:DashboardMetricsAt).TotalSeconds -ge 1){
            try {
                $ramSnapshot=[int]$Global:SysInfo.RAMUsedPct
                if(Get-Command Start-ThreadJob -ErrorAction SilentlyContinue){$Global:DashboardMetricsJob=Start-ThreadJob -ScriptBlock ${function:Get-RealtimeDashboardMetrics} -ArgumentList $ramSnapshot -ErrorAction Stop}
                else {$Global:DashboardMetricsJob=Start-Job -ScriptBlock ${function:Get-RealtimeDashboardMetrics} -ArgumentList $ramSnapshot -ErrorAction Stop}
            } catch {$Global:DashboardMetricsJob=$null}
            $Global:DashboardMetricsAt=Get-Date
        }
        if($Global:DashboardMetricsJob -and $Global:DashboardMetricsJob.State -in @('Completed','Failed','Stopped')){
            if($Global:DashboardMetricsJob.State -eq 'Completed'){$result=Receive-Job -Job $Global:DashboardMetricsJob -ErrorAction SilentlyContinue | Select-Object -Last 1; if($result){$Global:DashboardMetricsCache=$result}}
            Remove-Job -Job $Global:DashboardMetricsJob -Force -ErrorAction SilentlyContinue; $Global:DashboardMetricsJob=$null
        }
        $metrics=Get-StableDashboardMetrics -RawMetrics $Global:DashboardMetricsCache
        if(-not $metrics){$metrics=$Global:DashboardMetricsCache}
        # Normalize every metric to one scalar integer before binding to TextBlocks;
        # this prevents array/string concatenation from producing values like 5398138139%.
        $metrics=[pscustomobject]@{CPU=(Get-SafeDashboardPercent $metrics.CPU);GPU=(Get-SafeDashboardPercent $metrics.GPU);RAM=(Get-SafeDashboardPercent $metrics.RAM);DISK=(Get-SafeDashboardPercent $metrics.DISK);NET=(Get-SafeDashboardPercent $metrics.NET)}
        if($InfoOS){$InfoOS.Text=if([string]::IsNullOrWhiteSpace([string]$Global:SysInfo.OS)){"Unknown Windows"}else{[string]$Global:SysInfo.OS}}; if($InfoCPU){$InfoCPU.Text=if([string]::IsNullOrWhiteSpace([string]$Global:SysInfo.CPU)){"Unknown CPU"}else{[string]$Global:SysInfo.CPU}}; if($InfoGPU){$InfoGPU.Text=if([string]::IsNullOrWhiteSpace([string]$Global:SysInfo.GPU)){"Unknown GPU"}else{[string]$Global:SysInfo.GPU}}
        if($InfoNET){$InfoNET.Text=[string]$Global:SysInfo.NetType}; if($InfoRAM){$InfoRAM.Text=if([int]$Global:SysInfo.RAM -gt 0){"$($Global:SysInfo.RAM) GB"}else{"RAM not detected"}}; if($InfoAdapter){$InfoAdapter.Text=[string]$Global:SysInfo.Adapter}
        if($OverviewCpuValue){Set-SystemOverviewHardwareText; $cpuName=[string]$Global:SysInfo.CPU; if([string]::IsNullOrWhiteSpace($cpuName)){$cpuName='Unknown CPU'}; $gpuName=[string]$Global:SysInfo.GPU; if([string]::IsNullOrWhiteSpace($gpuName)){$gpuName='Unknown GPU'}; $ramName=if([int]$Global:SysInfo.RAM -gt 0){"$($Global:SysInfo.RAM) GB"}else{'RAM not detected'}; $OverviewCpuValue.Text=$cpuName; $OverviewGpuValue.Text=$gpuName; $OverviewRamValue.Text=$ramName}
        if($DashboardModeText){$peak=[int][math]::Max($metrics.RAM,$metrics.CPU); if($peak -ge 90){$DashboardModeText.Text='HIGH LOAD'}elseif($peak -ge 75){$DashboardModeText.Text='SYSTEM BUSY'}else{$DashboardModeText.Text='SYSTEM NOMINAL'}}
        if($DashboardPerfValueLabels -and $DashboardPerfValueLabels.Count -ge 5){$DashboardPerfValueLabels[0].Text="$($metrics.CPU)%"; $DashboardPerfValueLabels[1].Text="$($metrics.GPU)%"; $DashboardPerfValueLabels[2].Text="$($metrics.RAM)%"; $DashboardPerfValueLabels[3].Text="$($metrics.DISK)%"; $DashboardPerfValueLabels[4].Text="$($metrics.NET)%"}
        if($Global:DashboardPerfBars){$barValues=@([int]$metrics.CPU,[int]$metrics.GPU,[int]$metrics.RAM,[int]$metrics.DISK,[int]$metrics.NET); for($barIndex=0;$barIndex -lt $barValues.Count;$barIndex++){if($Global:DashboardPerfBars.Count -gt $barIndex){$trackWidth=$Global:DashboardPerfBars[$barIndex].Track.ActualWidth; if($trackWidth -le 0){$trackWidth=220}; $Global:DashboardPerfBars[$barIndex].Fill.Width=[math]::Max(0,[math]::Min($trackWidth,($barValues[$barIndex]/100.0)*$trackWidth))}}}
        if($RamUsageFill -and $RamUsageFill.Parent){$maxW=$RamUsageFill.Parent.ActualWidth; if($maxW -le 0){$maxW=400}; $RamUsageFill.Width=[math]::Max(0,($metrics.RAM/100.0)*$maxW)}; if($RamUsageText){$RamUsageText.Text="$($metrics.RAM)%"}
        Update-DashboardStatusPanel
    } catch {}
}
function Get-ActiveTweakCount {
    try { return @($Global:TweakToggles.Keys | Where-Object { [bool]$Global:TweakToggles[$_] }).Count } catch { return 0 }
}
function Test-FiveMProcessRunning {
    try {
        foreach($proc in @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -like 'FiveM*' -or $_.ProcessName -like '*GTAProcess*' -or $_.ProcessName -eq 'CitizenFX' })){ return $true }
    } catch {}
    return $false
}
function Get-DashboardPresetSummary {
    $parts=New-Object System.Collections.ArrayList
    if([bool]$Global:LowInputLagPresetEnabled){ [void]$parts.Add('LOW INPUT LAG') }
    if([bool]$Global:FlowNetPresetEnabled){ [void]$parts.Add('FLOW NET') }
    if([bool]$Global:FullSystemPresetEnabled){ [void]$parts.Add('FULL SYSTEM') }
    if([string]$Global:ActiveNetPreset -eq 'LAN NETWORK'){ [void]$parts.Add('LAN') }
    if([string]$Global:ActiveNetPreset -eq 'WI-FI NETWORK'){ [void]$parts.Add('WIFI') }
    if($parts.Count -eq 0){ return 'No preset' }
    return ($parts -join ' + ')
}
function Get-ActivePowerPlanLabel {
    try {
        if($Global:PowerPlanSelectedLabel){ return [string]$Global:PowerPlanSelectedLabel }
        $active=Get-LessActivePowerPlan
        if($active -and -not [string]::IsNullOrWhiteSpace($active.Name) -and $active.Name -ne 'NOT DETECTED'){ return [string]$active.Name }
    } catch {}
    return 'Unknown'
}
function Update-DashboardStatusPanel {
    try {
        if(-not $DashboardStatusLine1){ return }
        $plan=Get-ActivePowerPlanLabel
        $presets=Get-DashboardPresetSummary
        $fiveM=if(Test-FiveMProcessRunning){'RUNNING'}else{'CLOSED'}
        $tweaks=Get-ActiveTweakCount
        $restore=if($Global:RestorePointCreated){'READY'}elseif($Global:RestorePointSkipped -or $Global:RestorePointSkippedThisSession){'SKIPPED'}else{'NOT CREATED'}
        $DashboardStatusLine1.Text=("POWER: {0}   |   PRESETS: {1}   |   FIVEM: {2}   |   TWEAKS ON: {3}" -f $plan,$presets,$fiveM,$tweaks)
        $DashboardStatusLine2.Text=("RESTORE POINT: {0}   |   FOLDER: {1}" -f $restore,$(if([string]::IsNullOrWhiteSpace($Global:GameFolderPath)){'Not set'}else{$Global:GameFolderPath}))
    } catch {}
}
function Resolve-FiveMGameFolderPath {
    try {
        $root=Find-FiveMAppRoot
        if($root){
            $parent=Split-Path -Parent $root
            if($parent -and (Test-Path -LiteralPath $parent -PathType Container)){
                $Global:GameFolderPath=$parent
                Save-LessProjectSettings
                if($SettingsGamePathBox){ $SettingsGamePathBox.Text=$parent }
                Add-Log ("FiveM folder auto-detected: {0}" -f $parent) '#4CB7FF'
                Update-DashboardStatusPanel
                return $parent
            }
        }
    } catch {}
    return $null
}
function Get-ApplyReviewSummary {
    $activeKeys=@($Global:TweakToggles.Keys | Where-Object { [bool]$Global:TweakToggles[$_] } | ForEach-Object { [string]$_ })
    $byGroup=@{}
    foreach($key in $activeKeys){
        $meta=$Global:TweakInfo | Where-Object { [string]$_.Key -eq $key } | Select-Object -First 1
        $group=if($meta){[string]$meta.Group}else{'OTHER'}
        if(-not $byGroup.ContainsKey($group)){ $byGroup[$group]=0 }
        $byGroup[$group]++
    }
    $runModes=@()
    if($Global:LowInputLagPresetEnabled){$runModes+='LOW INPUT LAG'}
    if($Global:FlowNetPresetEnabled){$runModes+='FLOW NET'}
    if($Global:FullSystemPresetEnabled){$runModes+='FULL SYSTEM'}
    if($Global:ActiveNetPreset -eq 'LAN NETWORK'){$runModes+='LAN'}
    if($Global:ActiveNetPreset -eq 'WI-FI NETWORK'){$runModes+='WIFI'}
    $profile=if($runModes.Count -gt 0){$runModes -join ' + '}else{'CUSTOM'}
    $lines=New-Object System.Collections.ArrayList
    [void]$lines.Add("Profile: $profile")
    [void]$lines.Add("Total tweaks ON: $($activeKeys.Count)")
    [void]$lines.Add("Requires Administrator: $(if(Test-IsAdministrator){'Yes (ready)'}else{'Yes (UAC will open)'})")
    [void]$lines.Add('')
    [void]$lines.Add('By category:')
    foreach($entry in ($byGroup.GetEnumerator() | Sort-Object Name)){
        [void]$lines.Add(("  - {0}: {1}" -f $entry.Key,$entry.Value))
    }
    if($Global:RestorePointCreated){ [void]$lines.Add(''); [void]$lines.Add('Restore point: READY') }
    else { [void]$lines.Add(''); [void]$lines.Add('Restore point: NOT CREATED') }
    return ($lines -join "`n")
}
function Confirm-RestorePointBeforeApply {
    if($Global:RestorePointCreated -or $Global:RestorePointSkipped -or $Global:RestorePointSkippedThisSession){ return $true }
    Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
    $choice=[System.Windows.MessageBox]::Show(
        "แนะนำให้สร้าง Windows Restore Point ก่อน Apply ครั้งแรก`n`nYes = สร้าง restore point ตอนนี้ (กด Apply อีกครั้งเมื่อเสร็จ)`nNo = ข้ามครั้งนี้`nCancel = ยกเลิก Apply",
        'LESS PROJECT / RESTORE POINT',
        [System.Windows.Forms.MessageBoxButtons]::YesNoCancel,
        [System.Windows.Forms.MessageBoxIcon]::Warning
    )
    if($choice -eq [System.Windows.Forms.DialogResult]::Yes){
        Start-CreateRestorePointAsync
        Add-Log 'Apply paused until restore point finishes. Press START LESS PROJECT again when ready.' '#4CB7FF'
        return $false
    }
    if($choice -eq [System.Windows.Forms.DialogResult]::No){
        $Global:RestorePointSkippedThisSession=$true
        $Global:RestorePointSkipped=$true
        Save-LessProjectSettings
        Update-DashboardStatusPanel
        return $true
    }
    return $false
}
function Confirm-ApplyReviewDialog {
    $summary=Get-ApplyReviewSummary
    Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
    $choice=[System.Windows.MessageBox]::Show(
        ($summary + "`n`nApply these settings to Windows now?"),
        'LESS PROJECT / REVIEW BEFORE APPLY',
        [System.Windows.Forms.MessageBoxButtons]::OKCancel,
        [System.Windows.Forms.MessageBoxIcon]::Information
    )
    return ($choice -eq [System.Windows.Forms.DialogResult]::OK)
}
function Confirm-LessProjectApplyPreflight {
    if(-not (Confirm-RestorePointBeforeApply)){ return $false }
    if(-not (Confirm-ApplyReviewDialog)){ return $false }
    return $true
}
function Initialize-TweakSearchBar {
    $Global:TweakSearchBarInitialized=$true
}
Update-SystemInfoUi
$Global:SystemInfoTimer = New-Object System.Windows.Threading.DispatcherTimer
$Global:SystemInfoTimer.Interval = [TimeSpan]::FromMilliseconds(500)
$Global:SystemInfoTimer.Add_Tick({
    try {
        $dashboardVisible=($DashboardPanel -and $DashboardPanel.Visibility -eq [System.Windows.Visibility]::Visible)
        if($Global:SystemInfoJob){
            $systemInfoJobState=[string]$Global:SystemInfoJob.State
        } else {
            $systemInfoJobState=''
        }
        if($Global:SystemInfoJob -and $systemInfoJobState -in @("Completed","Failed","Stopped")){
            if($systemInfoJobState -eq "Completed"){
                $result=Receive-Job -Job $Global:SystemInfoJob -ErrorAction SilentlyContinue | Select-Object -Last 1
                if($result -and $result.PSObject.Properties['CPU']){
                    $defaults=[ordered]@{OS="Windows";CPU="Unknown CPU";GPU="Unknown GPU";RAM=0;RAMType="Unknown";Adapter="No Adapter";NetType="None";RAMUsedPct=0;Board="Unknown motherboard";BIOS="Unknown BIOS";Storage="Unknown storage";Display="Unknown display";Arch=$env:PROCESSOR_ARCHITECTURE}
                    foreach($key in $defaults.Keys){$value=$result.PSObject.Properties[$key]; if($value -and $null -ne $value.Value -and [string]$value.Value -ne ''){$defaults[$key]=$value.Value}}
                    $Global:SysInfo=[pscustomobject]$defaults
                    $Global:SystemInfoLoaded=$true
                    # The initial snapshot is fresh; wait for the normal interval
                    # before launching the first periodic hardware refresh.
                    $Global:SystemInfoRefreshAt=Get-Date
                }
            }
            $jobFailed=($systemInfoJobState -ne 'Completed') -or (-not $Global:SystemInfoLoaded)
            Remove-Job -Job $Global:SystemInfoJob -Force -ErrorAction SilentlyContinue
            $Global:SystemInfoJob=$null
            if($jobFailed){
                # Do not permanently replace a good snapshot with "not detected".
                # CIM providers can be temporarily busy at startup; keep retrying
                # in the background so System Overview eventually becomes live.
                $Global:SystemInfoRetry=$true
                $Global:SystemInfoFallbackAttempted=$true
                $Global:SystemInfoLoaded=$true
                if(-not $Global:SysInfo -or [string]::IsNullOrWhiteSpace([string]$Global:SysInfo.CPU) -or [string]$Global:SysInfo.CPU -eq 'Detecting...'){
                    $Global:SysInfo=[pscustomobject]@{OS="Windows";CPU='CPU not detected';GPU="GPU not detected";RAM=0;RAMType="Unknown";Adapter="Adapter not detected";NetType="Unknown";RAMUsedPct=0;Board="Motherboard not detected";BIOS="BIOS not detected";Storage="Storage not detected";Display="Display not detected";Arch=$env:PROCESSOR_ARCHITECTURE}
                }
                # Force a retry on the next timer cycle rather than waiting for the
                # full hardware refresh interval after a failed provider call.
                $Global:SystemInfoRefreshAt=[datetime]::MinValue
            }
            Update-SystemInfoUi
        }
        if($dashboardVisible){ Update-SystemInfoUi }
    } catch { }
})
$Global:SystemInfoTimer.Start()
function Initialize-NotificationSound {
    if($Global:NotificationSoundPlayer){ return }
    try {
        $pair=New-8BitBeepPlayer -Frequencies @(1175,1568) -Durations @(18,34) -Volume 0.022
        $Global:NotificationSoundPlayer=$pair[0]; $Global:NotificationSoundStream=$pair[1]
    } catch {}
}
function Play-NotificationSound {
    if($Global:SoundFxEnabled -eq $false){ return }
    try {
        $now=[Environment]::TickCount64
        if($null -ne $Global:LastNotificationSoundTick -and (($now-[int64]$Global:LastNotificationSoundTick) -lt 900)){ return }
        $Global:LastNotificationSoundTick=$now
        if(-not $Global:NotificationSoundPlayer){ Initialize-NotificationSound }
        if($Global:NotificationSoundPlayer){ $Global:NotificationSoundPlayer.Play() }
    } catch {}
}
function Show-DashboardNotification {
    param([string]$Message)
    if(-not $DashboardNotification -or -not $DashboardNotificationText){return}
    try {
        Play-NotificationSound
        $DashboardNotificationText.Text=$Message
        $DashboardNotification.BeginAnimation([System.Windows.UIElement]::OpacityProperty,$null)
        $fade=New-Object System.Windows.Media.Animation.DoubleAnimation; $fade.From=0.0; $fade.To=0.96; $fade.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(180)); $fade.EasingFunction=New-Object System.Windows.Media.Animation.CubicEase
        $DashboardNotification.BeginAnimation([System.Windows.UIElement]::OpacityProperty,$fade)
        if($Global:DashboardNotificationTimer){$Global:DashboardNotificationTimer.Stop()}
        $Global:DashboardNotificationTimer=New-Object System.Windows.Threading.DispatcherTimer; $Global:DashboardNotificationTimer.Interval=[TimeSpan]::FromSeconds(3.5); $Global:DashboardNotificationTimer.Add_Tick({
            try {$Global:DashboardNotificationTimer.Stop(); $out=New-Object System.Windows.Media.Animation.DoubleAnimation; $out.From=0.96; $out.To=0.0; $out.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(260)); $DashboardNotification.BeginAnimation([System.Windows.UIElement]::OpacityProperty,$out)} catch {}
        }.GetNewClosure()); $Global:DashboardNotificationTimer.Start()
    } catch {}
}
function Get-RealtimeFiveMProcesses {
    return @(Get-FiveMRelatedProcesses)
}
function Get-FiveMRelatedProcesses {
    try {
        return @(Get-Process -ErrorAction SilentlyContinue | Where-Object {
            -not $_.HasExited -and (
                $_.ProcessName -eq 'FiveM' -or
                $_.ProcessName -eq 'CitizenFX' -or
                $_.ProcessName -like 'FiveM_*' -or
                $_.ProcessName -like '*GTAProcess*'
            )
        })
    } catch { return @() }
}
function Get-FiveMGameProcesses {
    try {
        $all = @(Get-FiveMRelatedProcesses)
        $game = @($all | Where-Object { $_.ProcessName -like '*GTAProcess*' })
        if($game.Count -gt 0){ return $game }
        return @($all | Where-Object { $_.ProcessName -eq 'FiveM' -or $_.ProcessName -like 'FiveM_*' })
    } catch { return @() }
}
function Get-FiveMExecutableNames {
    $names = New-Object System.Collections.Generic.List[string]
    foreach($n in @('FiveM.exe','FiveM_GTAProcess.exe')){ [void]$names.Add($n) }
    try {
        $root = Find-FiveMAppRoot
        if($root -and (Test-Path -LiteralPath $root -PathType Container)){
            foreach($file in @(Get-ChildItem -LiteralPath $root -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -like 'FiveM*.exe' -or $_.Name -like '*GTAProcess*.exe' })){
                if(-not $names.Contains($file.Name)){ [void]$names.Add($file.Name) }
            }
        }
    } catch {}
    foreach($proc in @(Get-FiveMRelatedProcesses)){
        try {
            $exeName = $null
            if($proc.MainModule -and $proc.MainModule.FileName){ $exeName = [IO.Path]::GetFileName($proc.MainModule.FileName) }
            elseif($proc.ProcessName){ $exeName = $proc.ProcessName + '.exe' }
            if($exeName -and -not $names.Contains($exeName)){ [void]$names.Add($exeName) }
        } catch {}
    }
    return @($names | Select-Object -Unique)
}
function Get-FiveMExecutablePaths {
    $paths = New-Object System.Collections.Generic.List[string]
    foreach($proc in @(Get-FiveMRelatedProcesses)){
        try {
            $p = $null
            if($proc.Path){ $p = [string]$proc.Path }
            elseif($proc.MainModule -and $proc.MainModule.FileName){ $p = [string]$proc.MainModule.FileName }
            if($p -and (Test-Path -LiteralPath $p -PathType Leaf) -and -not $paths.Contains($p)){ [void]$paths.Add($p) }
        } catch {}
    }
    try {
        $root = Find-FiveMAppRoot
        if($root){
            foreach($file in @(Get-ChildItem -LiteralPath $root -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -like 'FiveM*.exe' -or $_.Name -like '*GTAProcess*.exe' })){
                if(-not $paths.Contains($file.FullName)){ [void]$paths.Add($file.FullName) }
            }
        }
    } catch {}
    return @($paths | Select-Object -Unique)
}
function Get-RealtimeProcessCpuPercent {
    param([System.Diagnostics.Process]$Process)
    try {
        $now=[datetime]::UtcNow
        $cpuMs=[double]$Process.TotalProcessorTime.TotalMilliseconds
        $key=[string]$Process.Id
        $previous=$Global:RealtimeProcessSamples[$key]
        $Global:RealtimeProcessSamples[$key]=[pscustomobject]@{CpuMs=$cpuMs;At=$now}
        if(-not $previous){ return 0.0 }
        $wallMs=($now-[datetime]$previous.At).TotalMilliseconds
        if($wallMs -lt 50){ return 0.0 }
        $logical=[math]::Max(1,[Environment]::ProcessorCount)
        # Percent of a single logical core. Dividing by all cores made 35% unreachable on 12+ core CPUs.
        $percent=(($cpuMs-[double]$previous.CpuMs)/$wallMs)*100.0
        return [math]::Max(0.0,$percent)
    } catch { return 0.0 }
}
function Set-RealtimeFiveMPriority {
    param([object[]]$Processes,[bool]$Boost)
    foreach($proc in @($Processes)){
        try {
            if(-not $Global:RealtimeBoostOriginalPriorities.ContainsKey([string]$proc.Id)){
                $original=[string]$proc.PriorityClass
                # Never reintroduce High/Realtime from a previous optimizer run.
                if($original -in @('High','RealTime')){ $original='Normal' }
                $Global:RealtimeBoostOriginalPriorities[[string]$proc.Id]=$original
            }
            if($Boost){
                $desired=[System.Diagnostics.ProcessPriorityClass]::AboveNormal
            } else {
                $restoreName=[string]$Global:RealtimeBoostOriginalPriorities[[string]$proc.Id]
                $desired=switch($restoreName){
                    'Idle' {[System.Diagnostics.ProcessPriorityClass]::Idle;break}
                    'BelowNormal' {[System.Diagnostics.ProcessPriorityClass]::BelowNormal;break}
                    'AboveNormal' {[System.Diagnostics.ProcessPriorityClass]::AboveNormal;break}
                    'High' {[System.Diagnostics.ProcessPriorityClass]::Normal;break}
                    'RealTime' {[System.Diagnostics.ProcessPriorityClass]::Normal;break}
                    default {[System.Diagnostics.ProcessPriorityClass]::Normal}
                }
            }
            if($proc.PriorityClass -ne $desired){
                $proc.PriorityClass=$desired
                $label=if($Boost){'ABOVENORMAL'}else{'NORMAL'}
                Add-Log ("Realtime priority transition: {0} -> {1}" -f $proc.ProcessName,$label) "#FFFFFF"
            }
        } catch {
            Add-Log ("Realtime priority skipped for PID {0}: {1}" -f $proc.Id,$_.Exception.Message) "#A0A0A0"
        }
    }
}
function Update-RealtimeBoostController {
    if(-not $Global:RealtimeBoostEnabled){ return }
    try {
        $processes=@(Get-FiveMGameProcesses)
        $now=[datetime]::UtcNow
        if($processes.Count -eq 0){
            if($Global:RealtimeBoostState -ne 'Waiting'){
                $Global:RealtimeBoostState='Waiting'
                $Global:RealtimeBoostHighSince=[datetime]::MinValue
                $Global:RealtimeBoostLowSince=[datetime]::MinValue
                Add-Log 'Realtime Boost waiting for FiveM game process (FiveM_*GTAProcess).' '#A0A0A0'
            }
            return
        }
        $loads=@(foreach($proc in $processes){ Get-RealtimeProcessCpuPercent $proc })
        # Busiest game process as % of one logical core. 100 = one core fully busy.
        $gameLoad=if($loads.Count -gt 0){[double](($loads | Measure-Object -Maximum).Maximum)}else{0.0}
        $systemLoad=if($Global:DashboardMetricsCache){[double]$Global:DashboardMetricsCache.CPU}else{0.0}
        $eligible=($gameLoad -ge [double]$Global:RealtimeBoostOnThreshold -and $systemLoad -le [double]$Global:RealtimeSystemHeadroomLimit)
        $release=($gameLoad -lt [double]$Global:RealtimeBoostOffThreshold -or $systemLoad -ge [double]$Global:RealtimeSystemReleaseLimit)
        if($Global:RealtimeBoostState -eq 'Boosted'){
            if($release){
                if($Global:RealtimeBoostLowSince -eq [datetime]::MinValue){$Global:RealtimeBoostLowSince=$now}
                if(($now-$Global:RealtimeBoostLowSince).TotalSeconds -ge [double]$Global:RealtimeReleaseDelaySeconds){
                    Set-RealtimeFiveMPriority -Processes $processes -Boost:$false
                    $Global:RealtimeBoostState='Normal'
                    $Global:RealtimeBoostHighSince=[datetime]::MinValue
                    $Global:RealtimeBoostLowSince=[datetime]::MinValue
                    Add-Log ("Realtime Boost released after sustained low/headroom load (FiveM {0:N0}% / System {1:N0}%)." -f $gameLoad,$systemLoad) '#FFFFFF'
                }
            } else {
                $Global:RealtimeBoostLowSince=[datetime]::MinValue
            }
        } elseif($eligible){
            $Global:RealtimeBoostLowSince=[datetime]::MinValue
            if($Global:RealtimeBoostHighSince -eq [datetime]::MinValue){$Global:RealtimeBoostHighSince=$now}
            if(($now-$Global:RealtimeBoostHighSince).TotalSeconds -ge [double]$Global:RealtimeBoostDelaySeconds){
                Set-RealtimeFiveMPriority -Processes $processes -Boost:$true
                $Global:RealtimeBoostState='Boosted'
                $Global:RealtimeBoostLowSince=[datetime]::MinValue
                Add-Log ("Realtime Boost engaged at AboveNormal after sustained load (FiveM {0:N0}% / System {1:N0}%)." -f $gameLoad,$systemLoad) '#FFFFFF'
            }
        } else {
            # Reset the on-timer whenever the signal drops below the entry band.
            # The gap between 18% and 35% is the hysteresis band that prevents chatter.
            $Global:RealtimeBoostHighSince=[datetime]::MinValue
            $Global:RealtimeBoostLowSince=[datetime]::MinValue
            if($Global:RealtimeBoostState -ne 'Normal'){$Global:RealtimeBoostState='Normal'}
        }
    } catch { Add-Log ("Realtime Boost monitor skipped: {0}" -f $_.Exception.Message) '#A0A0A0' }
}
function Start-RealtimeBoostController {
    if($Global:RealtimeBoostTimer){ return }
    $Global:RealtimeBoostEnabled=$true
    $Global:RealtimeBoostState='Waiting'
    $Global:RealtimeBoostHighSince=[datetime]::MinValue
    $Global:RealtimeBoostLowSince=[datetime]::MinValue
    $Global:RealtimeProcessSamples=@{}
    $Global:RealtimeBoostTimer=New-Object System.Windows.Threading.DispatcherTimer
    $Global:RealtimeBoostTimer.Interval=[TimeSpan]::FromSeconds(1)
    $Global:RealtimeBoostTimer.Add_Tick({ Update-RealtimeBoostController })
    $Global:RealtimeBoostTimer.Start()
    Add-Log (("Realtime Boost monitor started: entry >= {0:N0}% for {1}s; release < {2:N0}% for {3}s; system headroom <= {4}%." -f $Global:RealtimeBoostOnThreshold,$Global:RealtimeBoostDelaySeconds,$Global:RealtimeBoostOffThreshold,$Global:RealtimeReleaseDelaySeconds,$Global:RealtimeSystemHeadroomLimit)) '#FFFFFF'
}
function Stop-RealtimeBoostController {
    param([bool]$Restore=$true)
    $Global:RealtimeBoostEnabled=$false
    if($Global:RealtimeBoostTimer){ try{$Global:RealtimeBoostTimer.Stop()}catch{} }
    $Global:RealtimeBoostTimer=$null
    if($Restore){
        try { Set-RealtimeFiveMPriority -Processes @(Get-RealtimeFiveMProcesses) -Boost:$false } catch {}
    }
    $Global:RealtimeBoostState='Idle'
    $Global:RealtimeProcessSamples=@{}
    $Global:RealtimeBoostOriginalPriorities=@{}
}
function Update-PerformanceBoostUi {
    try {
        # Reuse the smoothed dashboard snapshot; counters are sampled separately
        # and the display is updated without an additional Get-Counter call.
        if(-not $Global:DashboardDisplayCache){return}
        $cpu=Get-SafeDashboardPercent $Global:DashboardDisplayCache.CPU; $gpu=Get-SafeDashboardPercent $Global:DashboardDisplayCache.GPU; $disk=Get-SafeDashboardPercent $Global:DashboardDisplayCache.DISK; $ram=Get-SafeDashboardPercent $Global:DashboardDisplayCache.RAM; $net=Get-SafeDashboardPercent $Global:DashboardDisplayCache.NET
        if($Global:DashboardPerfBars){$barValues=@($cpu,$gpu,$ram,$disk,$net); for($barIndex=0;$barIndex -lt $barValues.Count;$barIndex++){if($Global:DashboardPerfBars.Count -gt $barIndex){$trackWidth=$Global:DashboardPerfBars[$barIndex].Track.ActualWidth; if($trackWidth -le 0){$trackWidth=220}; $Global:DashboardPerfBars[$barIndex].Fill.Width=[math]::Max(0,[math]::Min($trackWidth,($barValues[$barIndex]/100.0)*$trackWidth))}}}
        $vals=@("$cpu%","$gpu%","$ram%","$disk%","$net%")
        for($i=0;$i -lt $vals.Count;$i++){if($Global:DashboardPerfValueLabels.Count -gt $i){$Global:DashboardPerfValueLabels[$i].Text=$vals[$i]}}
    } catch {}
}
$Global:PerformanceTimer=New-Object System.Windows.Threading.DispatcherTimer; $Global:PerformanceTimer.Interval=[TimeSpan]::FromSeconds(3); $Global:PerformanceTimer.Add_Tick({Update-PerformanceBoostUi}); $Global:PerformanceTimer.Start(); Update-PerformanceBoostUi
$window.Add_Loaded({
    $window.Opacity = 1
    $maxW=$RamUsageFill.Parent.ActualWidth; if($maxW -le 0){$maxW=400}
    $pct=$Global:SysInfo.RAMUsedPct; $RamUsageFill.Width=[math]::Max(0,($pct/100.0)*$maxW); $RamUsageText.Text="$pct%"
})
function Restore-LessProjectWindowSize {
    param($CursorDip)
    if($window.Tag -ne 'Maximized'){ return }
    if($Global:NormalW -gt 0 -and $Global:NormalH -gt 0){
        $window.Width=$Global:NormalW
        $window.Height=$Global:NormalH
    }
    $window.Tag=$null
    if($CursorDip){
        $wa=[System.Windows.SystemParameters]::WorkArea
        $window.Left=[math]::Max($wa.Left,[math]::Min($wa.Right-$window.Width,$CursorDip.X-($window.Width/2)))
        $window.Top=$wa.Top
    } elseif($Global:NormalW -gt 0){
        $window.Left=$Global:NormalL
        $window.Top=$Global:NormalT
    }
}
function Test-LessProjectTopBarHit {
    param($EventArgs)
    if(-not $EventArgs -or -not $window){ return $false }
    $band=92.0
    if($TopBar -and $TopBar.ActualHeight -gt 0){ $band=[double]$TopBar.ActualHeight }
    return ($EventArgs.GetPosition($window).Y -le $band)
}
if($TopBar){
    # Alpha 1 rather than fully transparent: a layered window (AllowsTransparency)
    # treats alpha-0 pixels as click-through, which can swallow the drag gesture.
    $TopBar.Background=(New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.Color]::FromArgb(1,0,0,0)))
    $TopBar.Cursor=[System.Windows.Input.Cursors]::Arrow
}
if($MainChromeBorder){
    if(-not $MainChromeBorder.Background){
        $MainChromeBorder.Background=(New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.Color]::FromArgb(1,0,0,0)))
    }
}
# Allow the main window to be dragged from any empty surface, same as the loader.
# Interactive controls are excluded so buttons and text inputs keep their normal behavior.
# Use a Window-level preview handler. Child controls can otherwise swallow the
# bubbling mouse event, which makes the border/background feel impossible to drag.
$window.Add_PreviewMouseLeftButtonDown({
    param($sender, $eventArgs)
    if($eventArgs.ClickCount -eq 2 -and $BtnMax -and (Test-LessProjectTopBarHit $eventArgs)){
        try { $BtnMax.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Button]::ClickEvent))) } catch {}
        $eventArgs.Handled = $true
        return
    }
    $source = $eventArgs.OriginalSource -as [System.Windows.DependencyObject]
    $isInteractive = $false
    while ($source) {
        if ($source -is [System.Windows.Controls.Primitives.ButtonBase] -or
            $source -is [System.Windows.Controls.TextBox] -or
            $source -is [System.Windows.Controls.Primitives.ScrollBar]) {
            $isInteractive = $true
            break
        }
        try { $source = [System.Windows.Media.VisualTreeHelper]::GetParent($source) } catch { $source = $null }
    }
    if (-not $isInteractive -and $window.WindowState -ne [System.Windows.WindowState]::Maximized) {
        try {
            $eventArgs.Handled = $true
            $window.DragMove()
        } catch {}
    }
})
$window.Add_Loaded({
    try { Hide-LessProjectConsoleWindow } catch {}
    try { $window.WindowStartupLocation='Manual' } catch {}
})
# Window controls are explicitly wired here so the custom borderless window keeps
# native-feeling Minimize and Close behavior.
$BtnClose.Add_Click({ $window.Close() })
$StatusDetailsClose.Add_Click({ Close-StatusDetailsModal })
$StatusDetailsApplyHint.Add_Click({ Close-StatusDetailsModal })
$StatusDetailsOverlay.Add_MouseLeftButtonDown({
    param($sender,$eventArgs)
    if($eventArgs.OriginalSource -eq $StatusDetailsOverlay){ Close-StatusDetailsModal }
})
$window.Add_Closed({
    try { Stop-EmbeddedGifBackground -ScopeName "Main" } catch {}
    try { if($Global:SystemInfoTimer){$Global:SystemInfoTimer.Stop()} } catch {}
    try { if($Global:PerformanceTimer){$Global:PerformanceTimer.Stop()} } catch {}
    try { Stop-RealtimeBoostController -Restore $true } catch {}
    try { if($Global:SystemInfoJob){Stop-Job $Global:SystemInfoJob -ErrorAction SilentlyContinue;Remove-Job $Global:SystemInfoJob -Force -ErrorAction SilentlyContinue} } catch {}
    try { if($Global:SystemInfoRefreshJob){Stop-Job $Global:SystemInfoRefreshJob -ErrorAction SilentlyContinue;Remove-Job $Global:SystemInfoRefreshJob -Force -ErrorAction SilentlyContinue} } catch {}
})
$BtnMin.Add_Click({ $window.WindowState="Minimized" })
$BtnMax.Add_Click({
    if($window.Tag -eq "Maximized"){
        Restore-LessProjectWindowSize $null
    } else {
        $Global:NormalW=$window.Width; $Global:NormalH=$window.Height
        $Global:NormalL=$window.Left; $Global:NormalT=$window.Top
        $wa=[System.Windows.SystemParameters]::WorkArea
        $window.Left=$wa.Left; $window.Top=$wa.Top
        $window.Width=$wa.Width; $window.Height=$wa.Height
        $window.Tag="Maximized"
    }
})
# Keep the rounded-corner clip matched to the actual window size so resizing/maximizing
# never leaves stray hairlines at the edges or a stuck/oversized render surface.
$window.Add_SizeChanged({
    Update-MainWindowChrome
})
# The category overlay's clip geometry was hardcoded to 600x600 in XAML, but the overlay
# itself stretches to fill the whole right-hand panel (which is wider than 600px on most
# window sizes). That mismatch pushed each row's toggle switch (right-aligned "Auto" column)
# past the clipped/visible area, so the switches rendered off-screen and couldn't be clicked.
# Keep the clip synced to the overlay's actual size, the same way RootClipGeom tracks the window.
$CategoryOverlay.Add_SizeChanged({
    if($CategoryOverlay.ActualWidth -gt 2 -and $CategoryOverlay.ActualHeight -gt 2){
        $CatOverlayClipGeom.Rect=[System.Windows.Rect]::new(0,0,$CategoryOverlay.ActualWidth,$CategoryOverlay.ActualHeight)
    }
})

$Global:LogLines=[System.Collections.Generic.List[string]]::new()
$Global:LogEntries=[System.Collections.Generic.List[object]]::new()
function Get-LessProjectLogColor {
    param([string]$Color='#A0A0A0')
    if([string]::IsNullOrWhiteSpace($Color)){ return '#A0A0A0' }
    if($Color.ToUpperInvariant() -eq '#FFFFFF'){ return '#4CB7FF' }
    return $Color
}
function Sync-DashboardLiveLog {
    if(-not $Global:DashboardLiveLogBox){ return }
    try {
        if($Global:DashboardLiveLogBox -isnot [System.Windows.Controls.RichTextBox]){ return }
        $Global:DashboardLiveLogBox.Document.Blocks.Clear()
        foreach($entry in @($Global:LogEntries | Select-Object -Last 80)){
            $para=New-Object System.Windows.Documents.Paragraph
            $para.Margin=[System.Windows.Thickness]::new(0,0,0,2)
            $run=New-Object System.Windows.Documents.Run
            $run.Text=('> {0}' -f [string]$entry.Text)
            try { $run.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString([string]$entry.Color) } catch { $run.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#95A4B8') }
            [void]$para.Inlines.Add($run)
            [void]$Global:DashboardLiveLogBox.Document.Blocks.Add($para)
        }
        $Global:DashboardLiveLogBox.ScrollToEnd()
    } catch {}
}
function Add-Log {
    param([string]$msg,[string]$color="#A0A0A0")
    $color=Get-LessProjectLogColor $color
    [void]$Global:LogLines.Add($msg)
    [void]$Global:LogEntries.Add([pscustomobject]@{ Text=$msg; Color=$color })
    try {
        [void]$window.Dispatcher.BeginInvoke([Action]{
            if($LogBox -and $LogScrollV){
                $run=New-Object System.Windows.Documents.Run; $run.Text="> $msg`n"
                try{$run.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString($color)}catch{}
                [void]$LogBox.Inlines.Add($run); $LogScrollV.ScrollToEnd()
            }
            Sync-DashboardLiveLog
        })
    } catch {}
}
