    try {
        $bytes=[System.Convert]::FromBase64String(($encoded -replace '\s',''))
        $stream=New-Object System.IO.MemoryStream(,$bytes)
        $bitmap=New-Object System.Windows.Media.Imaging.BitmapImage
        $bitmap.BeginInit()
        $bitmap.CacheOption=[System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
        $bitmap.StreamSource=$stream
        $bitmap.EndInit()
        $bitmap.Freeze()
        $stream.Dispose()
        return $bitmap
    } catch { return $null }
}
function Convert-LessBase64ToBytes {
    param([AllowEmptyString()][string]$Encoded)
    if([string]::IsNullOrWhiteSpace($Encoded)){ return [byte[]]@() }
    try {
        $clean = ($Encoded -replace '\s','')
        return [System.Convert]::FromBase64String($clean)
    } catch {
        throw "Embedded resource is not valid Base64: $($_.Exception.Message)"
    }
}
