function Invoke-LessPowerCfg {
    param([Parameter(Mandatory=$true)][string[]]$Arguments)
    $savedPref=$ErrorActionPreference
    try {
        $ErrorActionPreference='SilentlyContinue'
        $candidates=@(
            (Join-Path $env:SystemRoot 'Sysnative\powercfg.exe'),
            (Join-Path $env:SystemRoot 'System32\powercfg.exe')
        )
        $powerCfgPath=$candidates | Where-Object { $_ -and (Test-Path -LiteralPath $_ -PathType Leaf) } | Select-Object -First 1
        if(-not $powerCfgPath){
            $command=Get-Command powercfg.exe -ErrorAction SilentlyContinue
            if($command){ $powerCfgPath=$command.Source }
        }
        if(-not $powerCfgPath){ throw 'ไม่พบ powercfg.exe ใน Windows System32' }
        $output=(& $powerCfgPath @Arguments | Out-String)
        return [pscustomobject]@{ ExitCode=[int]$LASTEXITCODE; Output=[string]$output }
    } catch {
        return [pscustomobject]@{ ExitCode=1; Output=$_.Exception.Message }
    } finally {
        $ErrorActionPreference=$savedPref
    }
}
function Get-LessCimPowerPlans {
    try {
        return @(Get-CimInstance -Namespace 'root\cimv2\power' -ClassName Win32_PowerPlan -ErrorAction SilentlyContinue)
    } catch {
        return @()
    }
}
function Get-LessActivePowerPlan {
    foreach($plan in @(Get-LessCimPowerPlans)){
        if(-not $plan.IsActive){ continue }
        $guid=''
        if([string]$plan.InstanceID -match '\{([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\}'){
            $guid=$Matches[1].ToLowerInvariant()
        }
        $name=[string]$plan.ElementName
        if([string]::IsNullOrWhiteSpace($name)){ $name='ACTIVE POWER PLAN' }
        if($guid){ return [pscustomobject]@{ Guid=$guid; Name=$name; ExitCode=0; Output='CIM' } }
    }
    $result=Invoke-LessPowerCfg -Arguments @('/getactivescheme')
    $match=[regex]::Match([string]$result.Output,'([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}).*?\(([^()]*)\)')
    if($match.Success){ return [pscustomobject]@{ Guid=$match.Groups[1].Value.ToLowerInvariant(); Name=$match.Groups[2].Value.Trim(); ExitCode=$result.ExitCode; Output=$result.Output } }
    $guidOnly=[regex]::Match([string]$result.Output,'([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})')
    if($guidOnly.Success){ return [pscustomobject]@{ Guid=$guidOnly.Groups[1].Value.ToLowerInvariant(); Name='ACTIVE POWER PLAN'; ExitCode=$result.ExitCode; Output=$result.Output } }
    return [pscustomobject]@{ Guid=''; Name='NOT DETECTED'; ExitCode=$result.ExitCode; Output=$result.Output }
}
function Get-LessPowerSchemes {
    $items=@()
    foreach($plan in @(Get-LessCimPowerPlans)){
        $guid=''
        if([string]$plan.InstanceID -match '\{([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\}'){
            $guid=$Matches[1].ToLowerInvariant()
        }
        if($guid){ $items += [pscustomobject]@{ Guid=$guid; Name=[string]$plan.ElementName } }
    }
    if($items.Count -gt 0){ return $items }
    $result=Invoke-LessPowerCfg -Arguments @('/list')
    $items=@()
    foreach($line in @($result.Output -split "`r?`n")){
        $match=[regex]::Match($line,'([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\s+\(([^()]*)\)')
        if($match.Success){ $items += [pscustomobject]@{ Guid=$match.Groups[1].Value.ToLowerInvariant(); Name=$match.Groups[2].Value.Trim() } }
    }
    return $items
}
function Get-LessUncPowerplanNames {
    return @('adamx','ancel','atlas','bitsum','calypto','core','exmfree','FrameSyncBoost','hybred','kaisen','khorvie','kirby','kizzimo','lawliet','nexus','powerx','sapphire','vtrl','xilly','xos')
}
function Save-LessEmbeddedPowerplanAssets {
    $folder=Join-Path ([IO.Path]::GetTempPath()) ('LessProject\PowerPlans\' + [guid]::NewGuid().ToString('N'))
    New-Item -ItemType Directory -Path $folder -Force | Out-Null
    $softFile=Join-Path $folder 'SoftPowerplan_Bysoft.pow'
    $zipFile=Join-Path $folder 'UncsPowerplans.zip'
    [IO.File]::WriteAllBytes($softFile,(Get-EmbeddedSoftPowerplanBytes))
    [IO.File]::WriteAllBytes($zipFile,(Get-EmbeddedUncPowerplansZipBytes))
    return [pscustomobject]@{ Folder=$folder; SoftFile=$softFile; ZipFile=$zipFile }
}
function Get-LessUncPowerplanFile {
    param([string]$PlanName)
    if([string]::IsNullOrWhiteSpace($PlanName)){ throw 'Please select an UNC power plan first.' }
    $safeName=[IO.Path]::GetFileName($PlanName)
    if($safeName -ne $PlanName -or $safeName -notmatch '^[a-zA-Z0-9_-]+$'){ throw 'Invalid power plan name.' }
    $assets=Save-LessEmbeddedPowerplanAssets
    $extract=Join-Path $assets.Folder 'UNC'
    New-Item -ItemType Directory -Path $extract -Force | Out-Null
    try {
        Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction Stop
        [System.IO.Compression.ZipFile]::ExtractToDirectory($assets.ZipFile,$extract)
    } catch { throw ('Could not unpack UNC power plans: ' + $_.Exception.Message) }
    $candidate=Get-ChildItem -LiteralPath $extract -Recurse -File -ErrorAction SilentlyContinue | Where-Object { $_.BaseName -eq $safeName -and $_.Extension -ieq '.pow' } | Select-Object -First 1
    if(-not $candidate){ throw ('Power plan not found in UNC archive: ' + $safeName) }
    return $candidate.FullName
}
function Import-AndActivate-LessPowerplan {
    param([string]$PowerplanFile,[string]$DisplayLabel)
    if(-not (Test-Path -LiteralPath $PowerplanFile -PathType Leaf)){ throw 'Power plan file was not found.' }

    # Capture the existing schemes so that, when powercfg does not print the new
    # GUID, we can still identify the scheme created by this import.
    $before=@(Get-LessPowerSchemes | ForEach-Object { $_.Guid })
    $requestedGuid=([guid]::NewGuid().ToString()).ToLowerInvariant()
    $import=Invoke-LessPowerCfg -Arguments @('/import',$PowerplanFile,$requestedGuid)
    if($import.ExitCode -ne 0){
        # Some Windows builds accept only the two-argument form.
        $import=Invoke-LessPowerCfg -Arguments @('/import',$PowerplanFile)
    }
    if($import.ExitCode -ne 0){ throw ('powercfg import failed: ' + $import.Output) }

    $guidMatch=[regex]::Match($import.Output,'([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})')
    $activateGuid=''
    if($guidMatch.Success){ $activateGuid=$guidMatch.Groups[1].Value.ToLowerInvariant() }
    if([string]::IsNullOrWhiteSpace($activateGuid) -and $requestedGuid -and $before -notcontains $requestedGuid){
        $schemesAfter=@(Get-LessPowerSchemes)
        $newScheme=$schemesAfter | Where-Object { $_.Guid -notin $before } | Select-Object -Last 1
        if($newScheme){ $activateGuid=$newScheme.Guid }
    }
    if([string]::IsNullOrWhiteSpace($activateGuid)){
        throw ('Power plan imported, but Windows returned no usable scheme GUID. ' + $import.Output)
    }

    $activate=Invoke-LessPowerCfg -Arguments @('/setactive',$activateGuid)
    if($activate.ExitCode -ne 0){ throw ('powercfg activation failed for GUID ' + $activateGuid + ': ' + $activate.Output) }
    $active=Get-LessActivePowerPlan
    for($attempt=0;$attempt -lt 8 -and (-not $active.Guid -or $active.Guid -ne $activateGuid);$attempt++){
        Start-Sleep -Milliseconds 250
        $active=Get-LessActivePowerPlan
        if($active.Guid -and $active.Guid -ne $activateGuid){
            $retry=Invoke-LessPowerCfg -Arguments @('/setactive',$activateGuid)
            if($retry.ExitCode -ne 0){ throw ('Power plan was imported but could not be activated: ' + $retry.Output) }
        }
    }
    if(-not $active.Guid -or $active.Guid -ne $activateGuid){
        $detected=if($active.Guid){$active.Guid}else{'NOT DETECTED'}
        throw ('Power plan activation could not be verified. Expected GUID ' + $activateGuid + ', detected ' + $detected + '. Run as Administrator and try again.')
    }
    return [pscustomobject]@{ Guid=$activateGuid; Name=$active.Name; Label=$DisplayLabel; Active=$true }
}
function Activate-SoftPowerplan {
    $assets=Save-LessEmbeddedPowerplanAssets
    return Import-AndActivate-LessPowerplan -PowerplanFile $assets.SoftFile -DisplayLabel 'SOFTPOWERPLAN'
}
function Activate-UncPowerplan {
    param([string]$PlanName)
    $file=Get-LessUncPowerplanFile -PlanName $PlanName
    return Import-AndActivate-LessPowerplan -PowerplanFile $file -DisplayLabel ('UNC / ' + $PlanName)
}

function Start-LessPowerplanActivationJob {
    param([string]$PowerplanFile,[string]$DisplayLabel,[string]$ArchiveBase64="",[string]$PlanName="")
    $script = {
        param($File,$Label,$ArchiveEncoded,$RequestedPlan)
        function Invoke-WorkerPowerCfg {
            param([string[]]$Arguments)
            try {
                $powerCfgPath=Join-Path $env:SystemRoot 'System32\powercfg.exe'
                if(-not (Test-Path -LiteralPath $powerCfgPath -PathType Leaf)){ $powerCfgPath='powercfg.exe' }
                $lines=@(& $powerCfgPath @Arguments 2>&1)
                [pscustomobject]@{ ExitCode=[int]$LASTEXITCODE; Output=($lines -join [Environment]::NewLine) }
            } catch { [pscustomobject]@{ ExitCode=1; Output=$_.Exception.Message } }
        }
        function Get-WorkerActivePowerPlan {
            $result=Invoke-WorkerPowerCfg @('/getactivescheme')
            $match=[regex]::Match($result.Output,'([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}).*?\(([^()]*)\)')
            if($match.Success){ return [pscustomobject]@{ Guid=$match.Groups[1].Value.ToLowerInvariant(); Name=$match.Groups[2].Value.Trim(); ExitCode=$result.ExitCode; Output=$result.Output } }
            $guidOnly=[regex]::Match($result.Output,'([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})')
            if($guidOnly.Success){ return [pscustomobject]@{ Guid=$guidOnly.Groups[1].Value.ToLowerInvariant(); Name='ACTIVE POWER PLAN'; ExitCode=$result.ExitCode; Output=$result.Output } }
            return [pscustomobject]@{ Guid=''; Name='NOT DETECTED'; ExitCode=$result.ExitCode; Output=$result.Output }
        }
        function Get-WorkerPowerSchemes {
            $result=Invoke-WorkerPowerCfg @('/list')
            $items=@()
            foreach($line in @($result.Output -split "`r?`n")){
                $m=[regex]::Match($line,'([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\s+\(([^()]*)\)')
                if($m.Success){ $items += [pscustomobject]@{ Guid=$m.Groups[1].Value.ToLowerInvariant(); Name=$m.Groups[2].Value.Trim() } }
            }
            return $items
        }
        try {
            if(-not [string]::IsNullOrWhiteSpace($RequestedPlan)){
                if([string]::IsNullOrWhiteSpace($ArchiveEncoded)){ throw 'UNC archive data was not prepared.' }
                $safeName=[IO.Path]::GetFileName($RequestedPlan)
                if($safeName -ne $RequestedPlan -or $safeName -notmatch '^[a-zA-Z0-9_-]+$'){ throw 'Invalid power plan name.' }
                $folder=Join-Path ([IO.Path]::GetTempPath()) ('LessProject\PowerPlans\' + [guid]::NewGuid().ToString('N'))
                $extract=Join-Path $folder 'UNC'
                New-Item -ItemType Directory -Path $extract -Force | Out-Null
                $zipFile=Join-Path $folder 'UncsPowerplans.zip'
                [IO.File]::WriteAllBytes($zipFile,[Convert]::FromBase64String($ArchiveEncoded))
                Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction Stop
                [System.IO.Compression.ZipFile]::ExtractToDirectory($zipFile,$extract)
                $candidate=Get-ChildItem -LiteralPath $extract -Recurse -File -ErrorAction SilentlyContinue | Where-Object { $_.BaseName -eq $safeName -and $_.Extension -ieq '.pow' } | Select-Object -First 1
                if(-not $candidate){ throw ('Power plan not found in UNC archive: ' + $safeName) }
                $File=$candidate.FullName
            }
            if(-not (Test-Path -LiteralPath $File -PathType Leaf)){ throw 'Power plan file was not found.' }

            # Import without a destination GUID first. Windows then reports/creates the
            # actual scheme GUID. This avoids activating a caller-generated GUID that some
            # Windows builds silently ignore when importing a .pow file.
            $before=@(Get-WorkerPowerSchemes | ForEach-Object { $_.Guid })
            $import=Invoke-WorkerPowerCfg @('/import',$File)
            if($import.ExitCode -ne 0){ throw ('powercfg import failed: ' + $import.Output) }
            $guidMatch=[regex]::Match($import.Output,'([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})')
            $activateGuid=''
            if($guidMatch.Success){ $activateGuid=$guidMatch.Groups[1].Value.ToLowerInvariant() }
            if([string]::IsNullOrWhiteSpace($activateGuid)){
                Start-Sleep -Milliseconds 120
                $after=@(Get-WorkerPowerSchemes)
                $newScheme=$after | Where-Object { $_.Guid -notin $before } | Select-Object -Last 1
                if($newScheme){ $activateGuid=$newScheme.Guid }
            }
            # Compatibility fallback for builds that accept only the optional GUID form.
            if([string]::IsNullOrWhiteSpace($activateGuid)){
                $fallbackGuid=([guid]::NewGuid().ToString()).ToLowerInvariant()
                $fallback=Invoke-WorkerPowerCfg @('/import',$File,$fallbackGuid)
                if($fallback.ExitCode -ne 0){ throw ('powercfg imported no usable GUID: ' + $fallback.Output) }
                $fallbackMatch=[regex]::Match($fallback.Output,'([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})')
                if($fallbackMatch.Success){ $activateGuid=$fallbackMatch.Groups[1].Value.ToLowerInvariant() } else { $activateGuid=$fallbackGuid }
            }
            if([string]::IsNullOrWhiteSpace($activateGuid)){ throw 'Power Plan imported but Windows returned no scheme GUID.' }

            $activate=Invoke-WorkerPowerCfg @('/setactive',$activateGuid)
            if($activate.ExitCode -ne 0){ throw ('powercfg activation failed for GUID ' + $activateGuid + ': ' + $activate.Output) }
            $active=Get-WorkerActivePowerPlan
            for($attempt=0;$attempt -lt 5 -and (-not $active.Guid -or $active.Guid -ne $activateGuid);$attempt++){
                Start-Sleep -Milliseconds 250
                $active=Get-WorkerActivePowerPlan
                if($active.Guid -and $active.Guid -ne $activateGuid){
                    $retry=Invoke-WorkerPowerCfg @('/setactive',$activateGuid)
                    if($retry.ExitCode -ne 0){ throw ('Power Plan was imported but could not be activated: ' + $retry.Output) }
                }
            }
            if(-not $active.Guid -or $active.Guid -ne $activateGuid){
                throw ('Power Plan activation could not be verified. Expected GUID ' + $activateGuid + ', detected ' + $active.Guid + '. Run as Administrator and try again.')
            }
            [pscustomobject]@{ Success=$true; Guid=$activateGuid; Name=$active.Name; Label=$Label; Active=$true; Error='' }
        } catch {
            [pscustomobject]@{ Success=$false; Guid=''; Name=''; Label=$Label; Active=$false; Error=$_.Exception.Message }
        }
    }
    if([string]::IsNullOrWhiteSpace($PowerplanFile) -and [string]::IsNullOrWhiteSpace($ArchiveBase64)){ throw 'No power plan payload was provided.' }
    Start-Job -ScriptBlock $script -ArgumentList $PowerplanFile,$DisplayLabel,$ArchiveBase64,$PlanName -ErrorAction Stop
}

function Show-StatusDetailsModal {
    param($Tweak,[bool]$Enabled)
    if(-not $Tweak -or -not $StatusDetailsOverlay){ return }
    try {
        $safety=Get-TweakSafetyProfile -Tweak $Tweak
        $tagLabel=if($Tweak.Tag -and $Global:TagMeta.ContainsKey([string]$Tweak.Tag)){$Global:TagMeta[[string]$Tweak.Tag].Label}else{"CATEGORY: $($Tweak.Category)"}
        $StatusDetailsKicker.Text="TOOL STATUS  /  $($Tweak.Group)"
        $StatusDetailsTitle.Text=[string]$Tweak.Title
        $StatusDetailsState.Text=if($Enabled){"ON / SELECTED"}else{"OFF / DISABLED"}
        $StatusDetailsSafety.Text="$($safety.Label)  /  $($safety.Note)"
        $StatusDetailsDescription.Text=[string]$Tweak.Desc
        $StatusDetailsTag.Text="TOUCHES: $tagLabel`n`nToggle changes are saved immediately. Press START LESS PROJECT to apply the selected value to Windows."
        $StatusDetailsOverlay.Visibility="Visible"
        $StatusDetailsOverlay.BringIntoView()
    } catch {}
}
function Close-StatusDetailsModal { try { if($StatusDetailsOverlay){$StatusDetailsOverlay.Visibility="Collapsed"} } catch {} }
