    $card.Width=$CardWidth; $card.Height=196; $card.CornerRadius=14; $card.BorderThickness=1
    $card.Margin="0,0,$CardGap,10"; $card.Padding="15,14,15,13"
    $card.Cursor="Hand"; $card.ToolTip="$($safety.Label): $($safety.Note). เปิดหรือปิด $($t.Title) แล้วกด START LESS PROJECT เพื่อให้ค่ามีผลกับ Windows"
    if($isOn){
        $card.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#1E1E1E")
        $card.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString([string]$safety.Border)
    } else {
        $card.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#111111")
        $card.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#3A3A3A")
    }
    $cardGrid=New-Object System.Windows.Controls.Grid
    [void]$cardGrid.RowDefinitions.Add((New-Object System.Windows.Controls.RowDefinition))
    $cardGrid.RowDefinitions[0].Height="Auto"
    [void]$cardGrid.RowDefinitions.Add((New-Object System.Windows.Controls.RowDefinition))
    $cardGrid.RowDefinitions[1].Height="*"
    [void]$cardGrid.RowDefinitions.Add((New-Object System.Windows.Controls.RowDefinition))
    $cardGrid.RowDefinitions[2].Height="Auto"
    $topGrid=New-Object System.Windows.Controls.Grid
    foreach($width in @("Auto","*","Auto")){ $col=New-Object System.Windows.Controls.ColumnDefinition; $col.Width=$width; [void]$topGrid.ColumnDefinitions.Add($col) }
    $iconBox=New-Object System.Windows.Controls.Border; $iconBox.Tag="ToolIcon"; $iconBox.Width=34; $iconBox.Height=34; $iconBox.CornerRadius=10; $iconBox.Margin="0,0,10,0"; $iconBox.Background=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromArgb(0x30,[byte]$accentColor[0],[byte]$accentColor[1],[byte]$accentColor[2])); $iconBox.BorderBrush=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromArgb(0x80,[byte]$accentColor[0],[byte]$accentColor[1],[byte]$accentColor[2])); $iconBox.BorderThickness=1; $iconBox.Child=(New-CategoryIconVisual $t.Group $accentColor $isOn); [System.Windows.Controls.Grid]::SetColumn($iconBox,0)
    $title=New-Object System.Windows.Controls.TextBlock; $title.Text=$t.Title; $title.FontSize=13; $title.FontWeight="Bold"; $title.Foreground=[System.Windows.Media.Brushes]::White; $title.TextWrapping="Wrap"; $title.VerticalAlignment="Center"; $title.Margin="0,0,6,0"; [System.Windows.Controls.Grid]::SetColumn($title,1)
    $risk=New-Object System.Windows.Controls.Border; $risk.Tag="ToolSafety"; $risk.Width=96; $risk.MinWidth=96; $risk.Height=22; $risk.CornerRadius=7; $risk.Padding="6,2"; $risk.Margin="4,0,0,0"; $risk.HorizontalAlignment="Right"; $risk.VerticalAlignment="Top"; $risk.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString([string]$safety.Background); $risk.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString($(if([string]$safety.Label -eq "RECOMMENDED"){"#4CB7FF"}else{[string]$safety.Border})); $risk.BorderThickness=1; $risk.Effect=$null; [System.Windows.Controls.Grid]::SetColumn($risk,2)
    $riskText=New-Object System.Windows.Controls.TextBlock; $riskText.Text=$safety.Label; $riskText.FontSize=10; $riskText.FontWeight="Bold"; $riskText.Foreground=$accentBrush; $riskText.TextAlignment="Center"; $riskText.HorizontalAlignment="Center"; $riskText.VerticalAlignment="Center"; $riskText.TextTrimming="CharacterEllipsis"; $risk.Child=$riskText
    [void]$topGrid.Children.Add($iconBox); [void]$topGrid.Children.Add($title); [void]$topGrid.Children.Add($risk)
    [System.Windows.Controls.Grid]::SetRow($topGrid,0); [void]$cardGrid.Children.Add($topGrid)
    $desc=New-Object System.Windows.Controls.TextBlock; $desc.Text=$t.Desc; $desc.FontSize=12; $desc.LineHeight=18; $desc.TextWrapping="Wrap"; $desc.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#A1A1A1"); $desc.Margin="0,10,0,4"; [System.Windows.Controls.Grid]::SetRow($desc,1); [void]$cardGrid.Children.Add($desc)
    $bottom=New-Object System.Windows.Controls.Grid
    $bottom.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition))
    $bottom.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition))
    $bottom.ColumnDefinitions[0].Width="*"
    $bottom.ColumnDefinitions[1].Width="58"
    $statusPill=New-Object System.Windows.Controls.Border; $statusPill.Tag="ToolState"; $statusPill.Width=118; $statusPill.MinWidth=118; $statusPill.Height=28; $statusPill.HorizontalAlignment="Left"; $statusPill.CornerRadius=8; $statusPill.Padding="8,4"; $statusPill.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#242424"); $statusPill.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#666666"); $statusPill.BorderThickness=1; [System.Windows.Controls.Grid]::SetColumn($statusPill,0)
    $status=New-Object System.Windows.Controls.TextBlock; $status.Text=if($isOn){"ON"}else{"OFF"}; $status.FontSize=12; $status.FontWeight="Bold"; $status.TextAlignment="Center"; $status.HorizontalAlignment="Stretch"; $status.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString($(if($isOn){"#4CB7FF"}else{"#A0A0A0"})); $status.VerticalAlignment="Center"; $statusPill.Child=$status
    $cb=New-Object System.Windows.Controls.CheckBox; $cb.Style=$window.Resources["ToggleStyle"]; $cb.Width=48; $cb.Height=24; $cb.IsThreeState=$false; $cb.IsChecked=$isOn; $cb.VerticalAlignment="Center"; $cb.HorizontalAlignment="Center"; $cb.Margin="8,0,0,0"; $cb.ToolTip="เปิดหรือปิดค่านี้"; [System.Windows.Controls.Grid]::SetColumn($cb,1)
    [void]$bottom.Children.Add($statusPill); [void]$bottom.Children.Add($cb); [System.Windows.Controls.Grid]::SetRow($bottom,2); [void]$cardGrid.Children.Add($bottom)
    $capturedKey=$key; $capturedTweak=$t; $capturedCard=$card; $capturedStatus=$status; $capturedTitle=[string]$t.Title; $capturedAccentColor=@($accentColor)
    $card.Add_MouseLeftButtonUp({
        param($sender,$eventArgs)
        try {
            if($eventArgs.OriginalSource -is [System.Windows.Controls.Primitives.ToggleButton]){ return }
            Show-StatusDetailsModal -Tweak $capturedTweak -Enabled ([bool]$Global:TweakToggles[$capturedKey])
            $eventArgs.Handled=$true
        } catch {}
    }.GetNewClosure())
    $applyCardState={
        param([bool]$enabled)
        $Global:TweakToggles[$capturedKey]=[bool]$enabled
        $newColor=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb([byte]$capturedAccentColor[0],[byte]$capturedAccentColor[1],[byte]$capturedAccentColor[2]))
        $capturedCard.Background=if($enabled){[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromArgb(0x2A,[byte]$capturedAccentColor[0],[byte]$capturedAccentColor[1],[byte]$capturedAccentColor[2]))}else{[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb(0x14,0x14,0x14))}
        $capturedCard.BorderBrush=if($enabled){$newColor}else{[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromArgb(0x80,[byte]$capturedAccentColor[0],[byte]$capturedAccentColor[1],[byte]$capturedAccentColor[2]))}
        $capturedStatus.Text=if($enabled){"ON"}else{"OFF"}
        $capturedStatus.Foreground=$newColor
        $Global:TweakToggleDirty=$true
        Update-EnabledBadge; Update-PresetGlowConsistency; Update-ActiveTweakCounts -GroupName $Global:ActiveCategory
        Save-TweakState
        $verb=if($enabled){"selected"}else{"deselected"}
        Add-Log ("$capturedTitle $verb. Press START LESS PROJECT to apply the saved selection.") $(if($enabled){"#4CB7FF"}else{"#A1A1A1"})
        Set-CurrentTask "$capturedTitle $verb. Press START LESS PROJECT to apply."
        Show-TweakToast -Label $capturedTitle -Enabled $enabled -OverrideText $(if($enabled){"$capturedTitle  /  SELECTED"}else{"$capturedTitle  /  DISABLED"})
    }.GetNewClosure()
    $cb.Add_Checked({param($sender,$eventArgs); Play-TweakBeep; & $applyCardState $true}.GetNewClosure())
    $cb.Add_Unchecked({param($sender,$eventArgs); Play-TweakBeep; & $applyCardState $false}.GetNewClosure())
    $Global:StageCBs[$key]=$cb
    $card.Child=$cardGrid
    [void]$CardWrap.Children.Add($card)
}
function Add-PendingTweakCardBatch {
    $token=[int]$Global:TweakCardBuildToken
    $queue=$Global:TweakCardBuildQueue
    $wrap=$Global:TweakCardWrap
    $width=[double]$Global:TweakCardWidth
    $gap=[int]$Global:TweakCardGap
    if($token -ne [int]$Global:TweakCardBuildToken -or -not $queue -or -not $wrap){
        $Global:TweakCardBuildBusy=$false
        return
    }
    $budget=10
    while($budget -gt 0 -and $queue.Count -gt 0){
        $t=$queue.Dequeue()
        Add-OneTweakToolCard -Tweak $t -CardWrap $wrap -CardWidth $width -CardGap $gap
        $budget--
    }
    if($queue.Count -gt 0 -and $token -eq [int]$Global:TweakCardBuildToken){
        [void]$window.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::Background, [Action]{ Add-PendingTweakCardBatch })
    } else {
        if($token -eq [int]$Global:TweakCardBuildToken){ $Global:TweakCardBuildBusy=$false }
    }
}
function Save-ActiveCategoryView {
    param([string]$Name)
    if([string]::IsNullOrWhiteSpace($Name) -or -not $CatOverlayItems){ return }
    if($Global:TweakCardBuildBusy){ return }
    $saved=New-Object System.Collections.ArrayList
    foreach($child in @($CatOverlayItems.Children)){ [void]$saved.Add($child) }
    if(-not $Global:CategoryViewCache){ $Global:CategoryViewCache=@{} }
    $Global:CategoryViewCache[$Name]=$saved
}
function Restore-CachedCategoryView {
    param([string]$Name)
    if(-not $Global:CategoryViewCache -or -not $Global:CategoryViewCache.ContainsKey($Name)){ return $false }
    $CatOverlayItems.Children.Clear()
    foreach($child in @($Global:CategoryViewCache[$Name])){
        if(-not $child){ continue }
        try {
            $parent=$child.Parent
            if($parent -and $parent.Children){ [void]$parent.Children.Remove($child) }
        } catch {}
        [void]$CatOverlayItems.Children.Add($child)
    }
    return $true
}
# POWERPLAN, WIN32, RESHADE and NET TWEAKS restyle the shared overlay chrome (title,
# description, actions row, overlay height) and must always run their own branch so the
# chrome is re-applied instead of served from the child cache.
$Global:CategoryCustomChromeViews=@('__SETTINGS__','__WIN32__','__RESHADE__','__NETWORK__')
function Reset-CategoryOverlayChrome {
    if($CategoryOverlay){
        $CategoryOverlay.Height=[double]::NaN
        $CategoryOverlay.MaxHeight=[double]::PositiveInfinity
        $CategoryOverlay.MinHeight=0
        $CategoryOverlay.VerticalAlignment='Stretch'
        $CategoryOverlay.HorizontalAlignment='Stretch'
        $CategoryOverlay.Margin=[System.Windows.Thickness]::new(0)
        $CategoryOverlay.Padding=[System.Windows.Thickness]::new(18)
        $CategoryOverlay.CornerRadius=[System.Windows.CornerRadius]::new(15)
    }
    if($CatOverlayTitle){
        $CatOverlayTitle.Visibility='Visible'
        $CatOverlayTitle.FontSize=17
        $CatOverlayTitle.FontWeight='Black'
        $CatOverlayTitle.Foreground=[System.Windows.Media.Brushes]::White
        $CatOverlayTitle.Margin=[System.Windows.Thickness]::new(0)
    }
    if($CatOverlayKicker){ $CatOverlayKicker.Visibility='Visible' }
    if($CatOverlayDesc){
        $CatOverlayDesc.Visibility='Visible'
        $CatOverlayDesc.FontSize=12
        $CatOverlayDesc.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#D8D8D8')
        $CatOverlayDesc.Margin=[System.Windows.Thickness]::new(0,10,0,10)
    }
    foreach($chromeItem in @($CatOverlayActionsRow,$CatOverlayCount,$CatOverlayEnableAll,$CatOverlayDisableAll)){
        if($chromeItem){ $chromeItem.Visibility='Visible' }
    }
    if($CatOverlayItemsScroll){
        $CatOverlayItemsScroll.VerticalContentAlignment='Top'
        $CatOverlayItemsScroll.MinHeight=0
    }
    if($CatOverlayItems){
        $CatOverlayItems.HorizontalAlignment='Stretch'
        $CatOverlayItems.VerticalAlignment='Top'
    }
}
function Show-CategoryDetail {
    param([string]$groupName,[string]$Filter="")
    $previousCategory=$Global:ActiveCategory
    $Global:TweakCardBuildToken = ([int]$Global:TweakCardBuildToken) + 1
    if($CategoryOverlay){ $CategoryOverlay.Visibility=[System.Windows.Visibility]::Visible; $CategoryOverlay.Opacity=1 }
    Reset-CategoryOverlayChrome
    $customChrome=($Global:CategoryCustomChromeViews -contains $groupName)
    if([string]::IsNullOrWhiteSpace($Filter) -and $previousCategory -and $previousCategory -ne $groupName){
        Save-ActiveCategoryView $previousCategory
    }
    $Global:ActiveCategory=$groupName
    if(-not $customChrome -and [string]::IsNullOrWhiteSpace($Filter) -and $Global:CategoryViewCache -and $Global:CategoryViewCache.ContainsKey($groupName) -and $CatOverlayItems){
        $CatOverlayTitle.Text=Get-ViewTitle $groupName
        $CatOverlayDesc.Text=Get-ViewDescription $groupName
        if(Restore-CachedCategoryView $groupName){
            $CategoryOverlay.Visibility=[System.Windows.Visibility]::Visible
            return
        }
    }
    # Reuse an already-built view when the user returns to the same TWEAKS page.
    # The controls remain attached to CatOverlayItems while the overlay is hidden,
    # so rebuilding hundreds of cards is unnecessary and makes navigation feel stuck.
    if(-not $customChrome -and $previousCategory -eq $groupName -and [string]::IsNullOrWhiteSpace($Filter) -and $CatOverlayItems -and $CatOverlayItems.Children.Count -gt 0){
        $CategoryOverlay.Visibility=[System.Windows.Visibility]::Visible
        return
    }
    # Rebuilding a view must not leave a detached Power Plan job or poller behind. The old
    # version stopped the poller but kept the job when the same POWERPLAN view was rebuilt,
    # leaving PowerPlanActionBusy=true forever and making every UNC button look dead.
    if($Global:PowerPlanStatusTimer){ try{$Global:PowerPlanStatusTimer.Stop()}catch{}; $Global:PowerPlanStatusTimer=$null }
    if($Global:PowerPlanActivationPoller){ try{$Global:PowerPlanActivationPoller.Stop()}catch{}; $Global:PowerPlanActivationPoller=$null }
    if($Global:PowerPlanActivationJob){ try{if($Global:PowerPlanActivationJob.State -eq 'Running'){Stop-Job $Global:PowerPlanActivationJob -ErrorAction SilentlyContinue}; Remove-Job $Global:PowerPlanActivationJob -Force -ErrorAction SilentlyContinue}catch{}; $Global:PowerPlanActivationJob=$null }
    $Global:PowerPlanActionBusy=$false
    $CatOverlayTitle.Text=Get-ViewTitle $groupName
    $CatOverlayDesc.Text=Get-ViewDescription $groupName
    $viewGroups=@(Get-ViewGroups $groupName)
    if($groupName -eq "__LOW_INPUT_LAG__" -and $Global:LowInputLagPresetKeys){
        # The preset view is intentionally filtered to its own keys. Building every
        # LAN/Wi-Fi card here caused a noticeable 1–2 second UI stall on selection.
        $presetKeySet=@($Global:LowInputLagPresetKeys)
        $itemsInGroup=@($Global:TweakInfo | Where-Object { $presetKeySet -contains [string]$_.Key })
    } elseif($groupName -eq "__ALL__"){
        $itemsInGroup=@($Global:TweakInfo)
    } else {
        $itemsBuffer=New-Object System.Collections.ArrayList
        foreach($viewGroup in $viewGroups){
            $bucket=$Global:TweakInfoByGroup[[string]$viewGroup]
            if($bucket){ foreach($item in $bucket){ [void]$itemsBuffer.Add($item) } }
        }
        $itemsInGroup=@($itemsBuffer)
    }
    if($Filter){ $itemsInGroup=@($itemsInGroup | Where-Object { $_.Title -like "*$Filter*" -or $_.Category -like "*$Filter*" -or $_.Desc -like "*$Filter*" }) }
    Update-ActiveTweakCounts -GroupName $groupName
    $CatOverlayItems.Children.Clear()
    if($CatOverlayActionsRow){$CatOverlayActionsRow.Visibility="Visible"}
    if($CatOverlayCount){$CatOverlayCount.Visibility="Visible"}
    if($CatOverlayEnableAll){$CatOverlayEnableAll.Visibility="Visible"}
    if($CatOverlayItemsScroll){$CatOverlayItemsScroll.VerticalContentAlignment="Top"}
    if($groupName -in @("__LAN__","__WIFI__")){
        if($CatOverlayItemsScroll){$CatOverlayItemsScroll.VerticalContentAlignment="Center";$CatOverlayItemsScroll.MinHeight=420}
        if($CatOverlayItems){$CatOverlayItems.HorizontalAlignment="Center";$CatOverlayItems.VerticalAlignment="Center"}
    } elseif($CatOverlayItems){$CatOverlayItems.HorizontalAlignment="Stretch";$CatOverlayItems.VerticalAlignment="Top"}

    # Net Tweaks landing view: choose the connection type before showing settings.
    if($groupName -eq "__NETWORK__"){
        if($CatOverlayCloseBtn){$CatOverlayCloseBtn.Visibility="Collapsed"}
        if($CatOverlayCloseX){$CatOverlayCloseX.Visibility="Collapsed"}
        if($CatOverlayItemsScroll){
            $CatOverlayItemsScroll.VerticalContentAlignment="Center"
            $CatOverlayItemsScroll.MinHeight=420
        }
        $CatOverlayDesc.Margin="14,0,0,8"
        if($CatOverlayActionsRow){$CatOverlayActionsRow.Visibility="Collapsed"}
        if($CatOverlayCount){$CatOverlayCount.Visibility="Collapsed"}
        if($CatOverlayEnableAll){$CatOverlayEnableAll.Visibility="Collapsed"}
        if($CatOverlayDisableAll){$CatOverlayDisableAll.Visibility="Collapsed"}

        $netPicker=New-Object System.Windows.Controls.StackPanel
        $netPicker.Orientation="Vertical"
        $netPicker.Width=640
        $netPicker.HorizontalAlignment="Center"
        $netPicker.VerticalAlignment="Center"
        $netPicker.Margin="0,0,0,0"
        $netPickerHint=New-Object System.Windows.Controls.TextBlock
        $netPickerHint.Text="SELECT CONNECTION TYPE"
        $netPickerHint.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#8C8C8C")
        $netPickerHint.FontSize=12
        $netPickerHint.FontWeight="Black"
        $netPickerHint.HorizontalAlignment="Center"
        $netPickerHint.Margin="0,0,0,6"
        [void]$netPicker.Children.Add($netPickerHint)

        $netPickerGrid=New-Object System.Windows.Controls.Grid
        $netPickerGrid.Width=640
        $netPickerGrid.HorizontalAlignment="Center"
        foreach($columnIndex in 0..2){
            $columnDefinition=New-Object System.Windows.Controls.ColumnDefinition
            if($columnIndex -eq 1){$columnDefinition.Width=[System.Windows.GridLength]::new(10)}else{$columnDefinition.Width=New-Object System.Windows.GridLength(1,[System.Windows.GridUnitType]::Star)}
            [void]$netPickerGrid.ColumnDefinitions.Add($columnDefinition)
        }

        $netButtons=@(
            [pscustomobject]@{Label="LAN"; View="__LAN__"; Hint="WIRED ETHERNET SETTINGS"},
