        $resetNetworkButton.Cursor="Hand"
        $resetNetworkButton.ToolTip="Flush DNS cache, reset Winsock and reset TCP/IP stack. Restart Windows afterward to complete."
        $resetNetworkButton.Add_Click({
            Play-UiBeep
            $confirm=[System.Windows.MessageBox]::Show("RESET NETWORK จะล้าง DNS Cache, Reset Winsock และ Reset TCP/IP Stack`n`nแนะนำให้ Restart Windows หลังทำรายการ ต้องการดำเนินการต่อหรือไม่?","RESET NETWORK",[System.Windows.MessageBoxButton]::YesNo,[System.Windows.MessageBoxImage]::Warning)
            if($confirm -eq [System.Windows.MessageBoxResult]::Yes){
                $flushOk=$false
                $winsockOk=$false
                $tcpIpOk=$false
                try { $flushOk=[bool](Run-FlushDns) } catch { Add-Log ("Flush DNS failed: " + $_.Exception.Message) "#D8D8D8" }
                try { $winsockOk=[bool](Run-ResetWinsock) } catch { Add-Log ("Reset Winsock failed: " + $_.Exception.Message) "#D8D8D8" }
                try { $tcpIpOk=[bool](Run-ResetTcpIp) } catch { Add-Log ("Reset TCP/IP failed: " + $_.Exception.Message) "#D8D8D8" }
                $successCount=@($flushOk,$winsockOk,$tcpIpOk) | Where-Object {$_} | Measure-Object | Select-Object -ExpandProperty Count
                if($successCount -eq 3){
                    Show-TweakToast -Label "RESET NETWORK" -Enabled $true -OverrideText "RESET NETWORK  /  DNS + WINSOCK + TCP/IP DONE" -DurationMs 3600
                } elseif($successCount -gt 0){
                    Show-TweakToast -Label "RESET NETWORK" -Enabled $false -OverrideText "RESET NETWORK  /  PARTIAL SUCCESS" -DurationMs 3600
                } else {
                    Show-TweakToast -Label "RESET NETWORK" -Enabled $false -OverrideText "RESET NETWORK  /  FAILED" -DurationMs 3600
                }
            }
        }.GetNewClosure())
