        $powerStatusGuid.Margin="0,3,0,0"
        [void]$statusTextStack.Children.Add($powerStatusGuid)
        [System.Windows.Controls.Grid]::SetColumn($statusTextStack,1)
        [void]$statusGrid.Children.Add($statusTextStack)
        $refreshPower=New-Object System.Windows.Controls.Button
        $refreshPower.Content="REFRESH"
        $refreshPower.Width=86
        $refreshPower.Height=32
        $refreshPower.Style=$window.Resources["QuietButton"]
        $refreshPower.Foreground=[System.Windows.Media.Brushes]::White
        $refreshPower.FontSize=11
        $refreshPower.FontWeight="Black"
        $refreshPower.Cursor="Hand"
        $refreshPower.ToolTip="Query Windows for the active power scheme now."
        [System.Windows.Controls.Grid]::SetColumn($refreshPower,2)
        [void]$statusGrid.Children.Add($refreshPower)
        $statusCard.Child=$statusGrid
        [void]$powerStack.Children.Add($statusCard)

        $uncActivationBindings=@()
        if(-not $Global:UncPowerplansArchiveBase64){
            $Global:UncPowerplansArchiveBase64=[Convert]::ToBase64String([byte[]](Get-EmbeddedUncPowerplansZipBytes))
        }
        $uncCard=New-Object System.Windows.Controls.Border
        $uncCard.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#171717")
        $uncCard.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#555555")
        $uncCard.BorderThickness=1
        $uncCard.CornerRadius=[System.Windows.CornerRadius]::new(14)
        $uncCard.Padding=[System.Windows.Thickness]::new(18,16,18,17)
        $uncCard.Margin="0,0,0,12"
        $uncInfo=New-Object System.Windows.Controls.StackPanel
        $uncTitle=New-Object System.Windows.Controls.TextBlock
        $uncTitle.Text="UNC'S POWERPLANS"
        $uncTitle.Foreground=[System.Windows.Media.Brushes]::White
        $uncTitle.FontSize=15
        $uncTitle.FontWeight="Black"
        [void]$uncInfo.Children.Add($uncTitle)
        $uncDesc=New-Object System.Windows.Controls.TextBlock
        $uncDesc.Text="Optional profiles from the embedded UNC collection. Click any profile to import and activate it."
        $uncDesc.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#9E9E9E")
        $uncDesc.FontSize=12
        $uncDesc.TextWrapping="Wrap"
        $uncDesc.Margin="0,4,0,0"
        [void]$uncInfo.Children.Add($uncDesc)
        $uncGrid=New-Object System.Windows.Controls.Grid
        $uncGrid.Margin="0,11,0,0"
        $uncGrid.HorizontalAlignment="Stretch"
        $uncGrid.VerticalAlignment="Top"
        foreach($rowIndex in 0..6){
            $rowDef=New-Object System.Windows.Controls.RowDefinition
            $rowDef.Height=[System.Windows.GridLength]::new(34)
            [void]$uncGrid.RowDefinitions.Add($rowDef)
        }
        foreach($columnIndex in 0..4){
            $columnDef=New-Object System.Windows.Controls.ColumnDefinition
            if($columnIndex -eq 1 -or $columnIndex -eq 3){$columnDef.Width=[System.Windows.GridLength]::new(8)}else{$columnDef.Width=[System.Windows.GridLength]::new(1,[System.Windows.GridUnitType]::Star)}
            [void]$uncGrid.ColumnDefinitions.Add($columnDef)
        }
        $uncPlanButtonTemplateXaml=@'
<ControlTemplate xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" TargetType="{x:Type Button}">
  <Border x:Name="PlanBorder" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="8" Padding="10,0">
    <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
  </Border>
  <ControlTemplate.Triggers>
    <Trigger Property="IsMouseOver" Value="True">
      <Setter TargetName="PlanBorder" Property="Background" Value="#3A3A3A"/>
      <Setter TargetName="PlanBorder" Property="BorderBrush" Value="#E8E8E8"/>
    </Trigger>
    <Trigger Property="IsPressed" Value="True">
      <Setter TargetName="PlanBorder" Property="Background" Value="#4A4A4A"/>
      <Setter TargetName="PlanBorder" Property="BorderBrush" Value="#FFFFFF"/>
    </Trigger>
    <Trigger Property="IsEnabled" Value="False"><Setter TargetName="PlanBorder" Property="Opacity" Value="0.42"/></Trigger>
  </ControlTemplate.Triggers>
</ControlTemplate>
'@
        $uncPlanButtonTemplate=[System.Windows.Markup.XamlReader]::Parse($uncPlanButtonTemplateXaml)
        $uncNames=@(Get-LessUncPowerplanNames)
        for($planIndex=0;$planIndex -lt $uncNames.Count;$planIndex++){
            $planName=[string]$uncNames[$planIndex]
            $planButton=New-Object System.Windows.Controls.Button
            $planButton.Content=$planName.ToUpperInvariant()
            $planButton.Height=36
            $planButton.Margin="0,2,0,2"
            $planButton.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#151515")
            $planButton.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#F2F2F2")
            $planButton.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#666666")
            $planButton.BorderThickness=1.1
            $planButton.FontSize=12
            $planButton.FontWeight="Black"
            $planButton.Template=$uncPlanButtonTemplate
            $planButton.Cursor="Hand"
            $planButton.ToolTip=('Import and activate UNC power plan: {0}' -f $planName)
            $row=[math]::Floor($planIndex / 3)
            $column=($planIndex % 3) * 2
            [System.Windows.Controls.Grid]::SetRow($planButton,[int]$row)
            [System.Windows.Controls.Grid]::SetColumn($planButton,[int]$column)
            [void]$uncGrid.Children.Add($planButton)
            $uncActivationBindings += [pscustomobject]@{ Button=$planButton; Name=$planName }
        }
        [void]$uncInfo.Children.Add($uncGrid)
        $uncCard.Child=$uncInfo
        [void]$powerStack.Children.Add($uncCard)

        if(-not $Global:SoftPowerplanLocked){
            $Global:PowerPlanSelectedLabel=''
            $Global:PowerPlanExpectedGuid=''
            $Global:PowerPlanStatusUiLock=$false
        }
        $Global:PowerPlanActionToken=''
        $updatePowerStatus = {
            try {
                $active=Get-LessActivePowerPlan
                # While a button is being applied, keep the card tied to that button. The old
                # scheme (often Sapphire) must not overwrite the selected label during the
                # short import/setactive window. Unlock the live card only after Windows
                # reports the exact GUID verified by the worker.
                if($Global:PowerPlanStatusUiLock){
                    if($Global:PowerPlanExpectedGuid -and $active.Guid -and ($active.Guid.ToLowerInvariant() -eq $Global:PowerPlanExpectedGuid.ToLowerInvariant())){
                        $Global:PowerPlanStatusUiLock=$false
                    } else {
                        if($Global:PowerPlanSelectedLabel){ $powerStatusText.Text=$Global:PowerPlanSelectedLabel }
                        $powerStatusGuid.Text='SELECTED / APPLYING TO WINDOWS'
                        $powerStatusDot.Fill=[System.Windows.Media.Brushes]::White
                        $statusIndicator.Background=[System.Windows.Media.Brushes]::White
                        return
                    }
                }
                if($active.Guid){
                    if($Global:PowerPlanSelectedLabel -and $Global:PowerPlanExpectedGuid -and ($active.Guid.ToLowerInvariant() -eq $Global:PowerPlanExpectedGuid.ToLowerInvariant())){
                        $powerStatusText.Text=$Global:PowerPlanSelectedLabel
                    } else {
                        $powerStatusText.Text=$active.Name
                    }
                    $powerStatusGuid.Text=('GUID  /  {0}' -f $active.Guid)
                    $powerStatusDot.Fill=[System.Windows.Media.Brushes]::Black
                    $statusIndicator.Background=[System.Windows.Media.Brushes]::White
                } else {
                    if(-not $Global:PowerPlanStatusUiLock){
                        $powerStatusText.Text='POWERCFG STATUS UNAVAILABLE'
                        $powerStatusGuid.Text='LIVE CHECK FAILED'
                    }
                    $powerStatusDot.Fill=[System.Windows.Media.Brushes]::White
                    $statusIndicator.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#666666")
                }
            } catch {
                if(-not $Global:PowerPlanStatusUiLock){
                    $powerStatusText.Text='POWERCFG STATUS UNAVAILABLE'
                    $powerStatusGuid.Text='LIVE CHECK FAILED'
                }
                $powerStatusDot.Fill=[System.Windows.Media.Brushes]::White
                $statusIndicator.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#666666")
            }
        }.GetNewClosure()
        & $updatePowerStatus
        $refreshPower.Add_Click({ & $updatePowerStatus }.GetNewClosure())
        $Global:PowerPlanStatusTimer=New-Object System.Windows.Threading.DispatcherTimer
        $Global:PowerPlanStatusTimer.Interval=[TimeSpan]::FromSeconds(5)
        $Global:PowerPlanStatusTimer.Add_Tick({ & $updatePowerStatus }.GetNewClosure())
        $Global:PowerPlanStatusTimer.Start()
        $allPowerButtons=@($softButton)
        foreach($binding in @($uncActivationBindings)){ $allPowerButtons += $binding.Button }
        foreach($button in @($allPowerButtons)){ try{$button.IsEnabled=$true}catch{} }
        $startPowerplanUiAction = {
            param([System.Windows.Controls.Button]$TriggerButton,[string]$PowerplanFile,[string]$DisplayLabel,[string]$DialogTitle,[string]$ArchiveBase64="",[string]$PlanName="")
            # Each click gets a new token. A newer click owns the UI state and the
            # previous activation is stopped before the selected plan is activated.
            $actionToken=[guid]::NewGuid().ToString('N')
            $Global:PowerPlanActionToken=$actionToken
            if($Global:PowerPlanActivationPoller){ try{$Global:PowerPlanActivationPoller.Stop()}catch{}; $Global:PowerPlanActivationPoller=$null }
            if($Global:PowerPlanActivationJob){
                try{
                    if($Global:PowerPlanActivationJob.State -in @('NotStarted','Running','Blocked','Disconnected')){ Stop-Job -Job $Global:PowerPlanActivationJob -ErrorAction SilentlyContinue }
                    Remove-Job -Job $Global:PowerPlanActivationJob -Force -ErrorAction SilentlyContinue
                }catch{}
                $Global:PowerPlanActivationJob=$null
            }
            if(-not (Test-IsAdministrator)){
                $pendingPlanName=if(-not [string]::IsNullOrWhiteSpace($PlanName)){$PlanName}else{'SOFTPOWERPLAN'}
                if(Restart-LessProjectAsAdministrator -PendingPowerPlanName $pendingPlanName){
                    try { $window.Close() } catch {}
                } else {
                    [System.Windows.MessageBox]::Show('Power Plan ต้องใช้สิทธิ์ Administrator และไม่สามารถขอสิทธิ์ได้ กรุณาคลิกขวาไฟล์แล้วเลือก Run as administrator','POWERPLAN',[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Warning) | Out-Null
                }
                return
            }
            $Global:PowerPlanActionBusy=$true
            # Do not disable the choices; a later click must be able to replace this one.
            foreach($button in @($allPowerButtons)){ try{$button.IsEnabled=$true}catch{} }
            $targetLabel=if(-not [string]::IsNullOrWhiteSpace($PlanName)){ $PlanName.ToUpperInvariant() }else{ 'SOFTPOWERPLAN' }
            $Global:PowerPlanSelectedLabel=$targetLabel
            $Global:PowerPlanExpectedGuid=''
            $Global:PowerPlanStatusUiLock=$true
            $powerStatusText.Text=$targetLabel
            $powerStatusGuid.Text='SELECTED / APPLYING TO WINDOWS'
            try {
                # Resolve the UNC file on the UI side, then import and activate it
                # directly in this PowerShell process. The old Start-Job path could
                # remain Running indefinitely while the UI stayed stuck at APPLYING.
                $resolvedPowerplanFile=$PowerplanFile
                if(-not [string]::IsNullOrWhiteSpace($PlanName)){
                    $resolvedPowerplanFile=Get-LessUncPowerplanFile -PlanName $PlanName
                }
                if([string]::IsNullOrWhiteSpace($resolvedPowerplanFile)){ throw 'No power plan file was provided.' }
                $r=Import-AndActivate-LessPowerplan -PowerplanFile $resolvedPowerplanFile -DisplayLabel $DisplayLabel
                if([string]$Global:PowerPlanActionToken -ne [string]$actionToken){ return }
                if(-not $r -or [string]::IsNullOrWhiteSpace([string]$r.Guid)){ throw 'Power plan activation returned no verified GUID.' }
                $Global:PowerPlanExpectedGuid=[string]$r.Guid
                $Global:SoftPowerplanLocked=($DisplayLabel -eq 'SOFTPOWERPLAN')
                $Global:PowerPlanStatusUiLock=$true
                $powerStatusText.Text=if($Global:PowerPlanSelectedLabel){$Global:PowerPlanSelectedLabel}else{[string]$r.Name}
                $powerStatusGuid.Text=('GUID  /  {0}' -f $r.Guid)
                $powerStatusDot.Fill=[System.Windows.Media.Brushes]::Black
                $statusIndicator.Background=[System.Windows.Media.Brushes]::White
                try { & $updatePowerStatus } catch {}
                Set-CurrentTask (('{0} activated.' -f $r.Label))
                Show-TweakToast -Label "POWERPLAN" -Enabled $true -OverrideText (('{0}  /  ACTIVE' -f $r.Label)) -DurationMs 2800
                Add-Log ("Activated {0}: {1}" -f $r.Label,$r.Guid) "#FFFFFF"
            } catch {
                if([string]$Global:PowerPlanActionToken -ne [string]$actionToken){ return }
                $Global:PowerPlanStatusUiLock=$false
                $Global:PowerPlanExpectedGuid=''
                $powerStatusText.Text=('ACTIVATION FAILED / {0}' -f $DisplayLabel)
                $powerStatusGuid.Text='POWERCFG ACTIVATION ERROR'
                Set-CurrentTask ("Could not activate {0}." -f $DisplayLabel)
                Show-TweakToast -Label "POWERPLAN" -Enabled $false -OverrideText (('{0}  /  FAILED' -f $DisplayLabel)) -DurationMs 3200
                [System.Windows.MessageBox]::Show($_.Exception.Message,$DialogTitle,[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Warning) | Out-Null
            } finally {
                if([string]$Global:PowerPlanActionToken -eq [string]$actionToken){
                    $Global:PowerPlanActivationJob=$null
                    $Global:PowerPlanActivationPoller=$null
                    $Global:PowerPlanActionBusy=$false
                    foreach($button in @($allPowerButtons)){ try{$button.IsEnabled=$true}catch{} }
                }
            }
        }.GetNewClosure()
        $softButton.Add_Click({
            try {
                if(-not $Global:SoftPowerplanFileCache -or -not (Test-Path -LiteralPath $Global:SoftPowerplanFileCache -PathType Leaf)){
                    $assets=Save-LessEmbeddedPowerplanAssets
                    $Global:SoftPowerplanFileCache=$assets.SoftFile
                }
                & $startPowerplanUiAction -TriggerButton $softButton -PowerplanFile $Global:SoftPowerplanFileCache -DisplayLabel 'SOFTPOWERPLAN' -DialogTitle 'SOFTPOWERPLAN'
            } catch {
                $powerStatusText.Text='SOFTPOWERPLAN / FAILED TO START'
                Set-CurrentTask 'Could not start SoftPowerplan activation.'
                Show-TweakToast -Label "POWERPLAN" -Enabled $false -OverrideText "SOFTPOWERPLAN  /  COULD NOT START" -DurationMs 3200
            }
        }.GetNewClosure())
        foreach($binding in @($uncActivationBindings)){
            $planButton=$binding.Button
            $planName=[string]$binding.Name
            $planButton.Add_Click({
                try {
                    # Choosing an UNC profile is an explicit user action, so it must be allowed
                    # even when SOFTPOWERPLAN was previously locked by ONE CLICK LESS.
                    # The lock is released only for this selection; the selected UNC plan becomes
                    # the new active plan after successful verification.
                    $Global:SoftPowerplanLocked=$false
                    # The archive is cached once on page creation. File creation, ZIP extraction and
                    # powercfg work all happen inside the background activation job.
                    $archiveBase64=$Global:UncPowerplansArchiveBase64
                    if($Global:SelectedPowerPlanButton -and $Global:SelectedPowerPlanButton -ne $planButton){
                        try{$Global:SelectedPowerPlanButton.Background="#141414";$Global:SelectedPowerPlanButton.BorderBrush="#454545"}catch{}
                    }
                    $Global:SelectedPowerPlanButton=$planButton
                    $planButton.Background="#2A2A2A"
                    $planButton.BorderBrush="#FFFFFF"
                    & $startPowerplanUiAction -TriggerButton $planButton -PowerplanFile '' -DisplayLabel ('UNC / ' + $planName) -DialogTitle "UNC'S POWERPLANS" -ArchiveBase64 $archiveBase64 -PlanName $planName
                } catch {
                    $powerStatusText.Text=('UNC / {0} / FAILED TO START' -f $planName)
                    Set-CurrentTask ('Could not start UNC activation: {0}' -f $planName)
                    Show-TweakToast -Label "POWERPLAN" -Enabled $false -OverrideText (('UNC / {0}  /  COULD NOT START' -f $planName)) -DurationMs 3200
                }
            }.GetNewClosure())
        }
        [void]$CatOverlayItems.Children.Add($powerStack)
        $CategoryOverlay.Visibility="Visible"
        return
    }
    if($groupName -eq "__WIN32__"){
        $CategoryOverlay.VerticalAlignment='Top'
        $CategoryOverlay.Height=590
        $CategoryOverlay.MaxHeight=590
        $CategoryOverlay.HorizontalAlignment='Stretch'
        $CategoryOverlay.Margin='0,0,0,0'
        $CategoryOverlay.CornerRadius=[System.Windows.CornerRadius]::new(4)
        if($CatOverlayActionsRow){$CatOverlayActionsRow.Visibility="Collapsed"}
        if($CatOverlayCount){$CatOverlayCount.Visibility="Collapsed"}
        if($CatOverlayEnableAll){$CatOverlayEnableAll.Visibility="Collapsed"}
        if($CatOverlayDisableAll){$CatOverlayDisableAll.Visibility="Collapsed"}
        if($CatOverlayCloseBtn){$CatOverlayCloseBtn.Visibility="Collapsed"}
        if($CatOverlayCloseX){$CatOverlayCloseX.Visibility="Collapsed"}
        $CatOverlayTitle.Text="WIN32 PRIORITY PROFILE"
        $CatOverlayTitle.FontSize=22
        $CatOverlayTitle.FontWeight="Black"
        $CatOverlayDesc.Text="เลือก Win32PrioritySeparation แยกจาก POWERPLAN; ค่า 0x2E คือ Recommended และ CUSTOM HEX ใช้สำหรับทดสอบทีละค่าเท่านั้น."
        $CatOverlayDesc.FontSize=12
        $CatOverlayDesc.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#B5B5B5")
        $CatOverlayTitle.Visibility='Collapsed'
        $CatOverlayDesc.Visibility='Collapsed'
        if($CatOverlayKicker){ $CatOverlayKicker.Visibility='Collapsed' }
        $win32Stack=New-Object System.Windows.Controls.StackPanel
        $win32Stack.Margin="0"

        # Live status card mirrors the Power Plan page: current value is visible before Apply.
        $win32StatusCard=New-Object System.Windows.Controls.Border
        $win32StatusCard.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#090909')
        $win32StatusCard.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#4CB7FF')
        $win32StatusCard.BorderThickness=1.2
        $win32StatusCard.CornerRadius=[System.Windows.CornerRadius]::new(4)
        $win32StatusCard.Padding=[System.Windows.Thickness]::new(16,13,16,13)
        $win32StatusCard.Margin='0,0,0,12'
        $win32StatusCard.HorizontalAlignment='Stretch'
        $win32StatusGrid=New-Object System.Windows.Controls.Grid
        $win32StatusGrid.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition))
        $win32StatusGrid.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition))
        $win32StatusGrid.ColumnDefinitions[1].Width='Auto'
        $win32StatusText=New-Object System.Windows.Controls.StackPanel
        $win32StatusKicker=New-Object System.Windows.Controls.TextBlock
        $win32StatusKicker.Text='LIVE WIN32 STATUS'
        $win32StatusKicker.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#8C8C8C')
        $win32StatusKicker.FontSize=11
        $win32StatusKicker.FontWeight='Bold'
        [void]$win32StatusText.Children.Add($win32StatusKicker)
        $Global:Win32LiveStatus=New-Object System.Windows.Controls.TextBlock
        $Global:Win32LiveStatus.Text='READING CURRENT VALUE...'
        $Global:Win32LiveStatus.Foreground=[System.Windows.Media.Brushes]::White
        $Global:Win32LiveStatus.FontSize=14
        $Global:Win32LiveStatus.FontWeight='Black'
        $Global:Win32LiveStatus.Margin='0,4,0,0'
        [void]$win32StatusText.Children.Add($Global:Win32LiveStatus)
        $win32StatusHint=New-Object System.Windows.Controls.TextBlock
        $win32StatusHint.Text='Registry: PriorityControl / Win32PrioritySeparation'
        $win32StatusHint.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#8A8A8A')
        $win32StatusHint.FontSize=11
        $win32StatusHint.Margin='0,5,0,0'
        [void]$win32StatusText.Children.Add($win32StatusHint)
        [System.Windows.Controls.Grid]::SetColumn($win32StatusText,0)
        [void]$win32StatusGrid.Children.Add($win32StatusText)
        $win32StatusCard.Child=$win32StatusGrid
        [void]$win32Stack.Children.Add($win32StatusCard)

        $win32Card=New-Object System.Windows.Controls.Border
        $win32Card.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#171717')
        $win32Card.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#555555')
        $win32Card.BorderThickness=1
        $win32Card.CornerRadius=[System.Windows.CornerRadius]::new(4)
        $win32Card.Padding=[System.Windows.Thickness]::new(18,16,18,17)
        $win32Card.Margin='0,0,0,12'
        $win32Card.HorizontalAlignment='Stretch'
        $win32Grid=New-Object System.Windows.Controls.Grid
        $win32Grid.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition))
        $win32Grid.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition))
        $win32Grid.ColumnDefinitions[0].Width='0'
        $win32Grid.ColumnDefinitions[1].Width='*'
        $win32Text=New-Object System.Windows.Controls.StackPanel
        $win32Title=New-Object System.Windows.Controls.TextBlock
        $win32Title.Text='WIN32 PRIORITY PROFILE'
        $win32Title.Foreground=[System.Windows.Media.Brushes]::White
        $win32Title.FontSize=16
        $win32Title.FontWeight='Black'
        [void]$win32Text.Children.Add($win32Title)
        $win32Desc=New-Object System.Windows.Controls.TextBlock
        $win32Desc.Text='เลือก Win32PrioritySeparation แบบ Power Plan; 0x2E คือ Recommended gaming ส่วนค่า CUSTOM HEX เป็นตัวเลือกทดลองแยก ไม่รวม One Click และควรเปลี่ยนทีละค่า.'
        $win32Desc.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#B5B5B5')
        $win32Desc.FontSize=12
        $win32Desc.TextWrapping='Wrap'
        $win32Desc.Margin='0,5,20,0'
        $win32Desc.Text=''
        $win32Desc.Visibility='Collapsed'
        [void]$win32Text.Children.Add($win32Desc)
        $Global:Win32ProfileStatus=New-Object System.Windows.Controls.TextBlock
        $Global:Win32ProfileStatus.Text='SELECT A PROFILE'
        $Global:Win32ProfileStatus.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#8A8A8A')
        $Global:Win32ProfileStatus.FontSize=11
        $Global:Win32ProfileStatus.FontWeight='Bold'
        $Global:Win32ProfileStatus.Margin='0,8,0,0'
        [void]$win32Text.Children.Add($Global:Win32ProfileStatus)
        [System.Windows.Controls.Grid]::SetColumn($win32Text,0)
        [void]$win32Grid.Children.Add($win32Text)
        $win32Text.Visibility='Collapsed'
        $win32Action=New-Object System.Windows.Controls.StackPanel
        # Width is a Double on StackPanel; the WPF "Auto" token only applies to
        # GridLength. Leave it NaN so the action column sizes naturally.
        $win32Action.Width=[double]::NaN
        $win32Action.HorizontalAlignment='Stretch'
        $win32Action.Margin='0'
        $win32Recommended=New-Object System.Windows.Controls.TextBlock
        $win32Recommended.Text='SELECT A WIN32 PROFILE'
        $win32Recommended.Foreground=[System.Windows.Media.Brushes]::White
        $win32Recommended.FontSize=11
        $win32Recommended.FontWeight='Black'
        $win32Recommended.HorizontalAlignment='Center'
        $win32Recommended.Text=''
        $win32Recommended.Visibility='Collapsed'
        $win32Recommended.Margin='0'
        [void]$win32Action.Children.Add($win32Recommended)
        $win32Profiles=@(
            'WINDOWS DEFAULT (0x26) :: BALANCED',
            'GAMING RECOMMENDED (0x2E) :: FPS + INPUT LAG  /  BEST',
            'GAMING RECOMMENDED ALT A (0x2E) :: FPS + INPUT LAG  /  SAME VALUE',
            'GAMING RECOMMENDED ALT B (0x2E) :: FPS + INPUT LAG  /  SAME VALUE',
            'SHORT FIXED / HIGH BOOST (0x2A) :: FPS  /  GOOD',
            'SHORT FIXED / MEDIUM BOOST (0x29) :: FPS  /  GOOD',
            'SHORT FIXED / NO BOOST (0x28) :: FPS  /  FAIR',
            'SHORT VARIABLE / HIGH BOOST (0x26) :: INPUT LAG  /  GOOD',
            'SHORT VARIABLE / MEDIUM BOOST (0x25) :: INPUT LAG  /  GOOD',
            'SHORT VARIABLE / NO BOOST (0x24) :: INPUT LAG  /  FAIR',
            'LONG FIXED / HIGH BOOST (0x1A) :: FPS  /  FAIR',
            'LONG FIXED / MEDIUM BOOST (0x19) :: FPS  /  FAIR',
            'LONG FIXED / NO BOOST (0x18) :: FPS  /  NOT RECOMMENDED',
            'LONG VARIABLE / HIGH BOOST (0x16) :: INPUT LAG  /  FAIR',
            'LONG VARIABLE / MEDIUM BOOST (0x15) :: INPUT LAG  /  FAIR',
            'LONG VARIABLE / NO BOOST (0x14) :: INPUT LAG  /  NOT RECOMMENDED',
            'CUSTOM LOW INPUT LAG (0xFA332A) :: INPUT LAG  /  EXPERIMENTAL',
            'CUSTOM HEX (0xE82A) :: CUSTOM  /  EXPERIMENTAL',
            'CUSTOM HEX (0xFB882828) :: CUSTOM  /  NOT RECOMMENDED',
            'CUSTOM HEX (0xFA2A2A) :: CUSTOM  /  NOT RECOMMENDED',
            'CUSTOM HEX (0xFA002A) :: CUSTOM  /  NOT RECOMMENDED',
            'CUSTOM HEX (0x0FFF987) :: CUSTOM  /  NOT RECOMMENDED',
            'CUSTOM HEX (0x0FB00000) :: CUSTOM  /  NOT RECOMMENDED',
            'CUSTOM HEX (0x02) :: CUSTOM  /  EXPERIMENTAL'
        )
        $Global:Win32ProfileSelection='GAMING RECOMMENDED (0x2E)'
        $Global:Win32ProfileButtons=@()
        $win32List=New-Object System.Windows.Controls.Grid
        # Grid.Width also uses a Double. NaN is WPF's Auto-sized value.
        $win32List.Width=[double]::NaN
        $win32List.HorizontalAlignment='Stretch'
        $win32List.VerticalAlignment='Top'
        foreach($columnIndex in 0..4){
            $columnDefinition=New-Object System.Windows.Controls.ColumnDefinition
            if($columnIndex -eq 1 -or $columnIndex -eq 3){$columnDefinition.Width=[System.Windows.GridLength]::new(8)}else{$columnDefinition.Width=New-Object System.Windows.GridLength(1,[System.Windows.GridUnitType]::Star)}
            [void]$win32List.ColumnDefinitions.Add($columnDefinition)
        }
        foreach($rowIndex in 0..7){
            $rowDefinition=New-Object System.Windows.Controls.RowDefinition
            $rowDefinition.Height=[System.Windows.GridLength]::new(52)
            [void]$win32List.RowDefinitions.Add($rowDefinition)
        }
        foreach($profileIndex in 0..($win32Profiles.Count-1)){
            $profileEntry=[string]$win32Profiles[$profileIndex]
            $profileParts=$profileEntry -split ' :: ',2
            $profileName=[string]$profileParts[0]
            $profileLabel=if($profileParts.Count -gt 1){[string]$profileParts[1]}else{$profileName}
            $isFeatured=($profileName -eq 'CUSTOM LOW INPUT LAG (0xFA332A)')
            $profileTooltip=switch -Regex ($profileLabel){
                'FPS \+ INPUT LAG' { 'FPS: HIGH / INPUT LAG: LOW`nBest all-round gaming profile.'; break }
                '^FPS' { 'FPS: FOCUSED / INPUT LAG: BALANCED`nPrioritizes frame-time performance.'; break }
                '^INPUT LAG' { 'FPS: BALANCED / INPUT LAG: FOCUSED`nPrioritizes quick input response.'; break }
                'BALANCED' { 'FPS: BALANCED / INPUT LAG: BALANCED`nSafe Windows default behavior.'; break }
                'NOT RECOMMENDED' { 'FPS: UNPREDICTABLE / INPUT LAG: UNPREDICTABLE`nUse only for testing; not recommended.'; break }
                'EXPERIMENTAL' { 'FPS: EXPERIMENTAL / INPUT LAG: EXPERIMENTAL`nTest carefully and revert if unstable.'; break }
                default { 'FPS: CUSTOM / INPUT LAG: CUSTOM`nAdvanced value; test before daily use.'; break }
            }
            $profileButton=New-Object System.Windows.Controls.Button
            $profileButton.Content=if($isFeatured){'FA332A  /  RECOMMENDED'}else{$profileName}
            $profileButton.ToolTip=('Status: ' + $profileLabel + "`n" + $profileTooltip + "`nValue: " + $profileName)
            $profileButton.Style=$window.Resources['QuietButton']
            $profileButton.Height=42
            $profileButton.Margin='0,5,0,5'
            $profileButton.Padding='9,0'
            $profileButton.HorizontalContentAlignment='Center'
            $profileButton.FontSize=12
            $isRecommended=($profileIndex -eq 1)
            $profileFontWeight=if($isFeatured){'Black'}elseif($isRecommended){'Bold'}else{'SemiBold'}
            $profileForegroundColor=if($isFeatured){'#FFFFFF'}elseif($isRecommended){'#FFFFFF'}else{'#C8C8C8'}
            $profileBackgroundColor=if($isFeatured){'#6F1D1D'}elseif($isRecommended){'#3A3A3A'}else{'#151515'}
            $profileBorderColor=if($isFeatured){'#FF4D4D'}elseif($isRecommended){'#FFFFFF'}else{'#3A3A3A'}
            $profileButton.FontWeight=$profileFontWeight
            $profileButton.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString($profileForegroundColor)
            $profileButton.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString($profileBackgroundColor)
            $profileButton.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString($profileBorderColor)
            $profileButton.BorderThickness=1.1
            $profileButton.Cursor='Hand'
            $profileButton.Effect=$null
            $profileButton.Tag=$profileName
            $capturedProfile=$profileName
            $profileButton.Add_Click({
                Play-UiBeep
                $Global:Win32ProfileSelection=$capturedProfile
                $Global:SelectedWin32Profile=$capturedProfile
                Save-TweakState
                foreach($candidate in @($Global:Win32ProfileButtons)){
                    $isSelected=([string]$candidate.Tag -eq [string]$Global:Win32ProfileSelection)
                    $isFeaturedCandidate=([string]$candidate.Tag -eq 'CUSTOM LOW INPUT LAG (0xFA332A)')
                    $selectedBackgroundColor=if($isFeaturedCandidate){'#6F1D1D'}elseif($isSelected){'#3A3A3A'}else{'#151515'}
                    $selectedBorderColor=if($isFeaturedCandidate){'#FF4D4D'}elseif($isSelected){'#FFFFFF'}else{'#3A3A3A'}
                    $selectedForegroundColor=if($isSelected -or $isFeaturedCandidate){'#FFFFFF'}else{'#C8C8C8'}
                    $candidate.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString($selectedBackgroundColor)
                    $candidate.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString($selectedBorderColor)
                    $candidate.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString($selectedForegroundColor)
                }
                if($Global:Win32ProfileStatus){$Global:Win32ProfileStatus.Text=('APPLYING REALTIME  /  ' + $Global:Win32ProfileSelection)}
                # Selection is also the action: apply immediately. If HKLM is protected,
                # Invoke-Win32PriorityProfile opens the elevated helper with this profile.
                [void](Invoke-Win32PriorityProfile $capturedProfile)
            }.GetNewClosure())
            $profileButton.Add_MouseEnter({
                param($sender,$eventArgs)
                try {
                    if([string]$Global:Win32ProfileSelection -ne [string]$capturedProfile){
                        $sender.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString($(if([string]$capturedProfile -eq 'CUSTOM LOW INPUT LAG (0xFA332A)'){'#8F2525'}else{'#242424'}))
                        $sender.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#8A8A8A')
                        $sender.Foreground=[System.Windows.Media.Brushes]::White
                    }
                } catch {}
            }.GetNewClosure())
            $profileButton.Add_MouseLeave({
                param($sender,$eventArgs)
                try {
                    if([string]$Global:Win32ProfileSelection -ne [string]$capturedProfile){
                        $isFeaturedLeave=([string]$capturedProfile -eq 'CUSTOM LOW INPUT LAG (0xFA332A)')
                        $sender.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString($(if($isFeaturedLeave){'#6F1D1D'}else{'#151515'}))
                        $sender.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString($(if($isFeaturedLeave){'#FFFFFF'}else{'#3A3A3A'}))
                        $sender.Foreground=[System.Windows.Media.Brushes]::White
                    }
                } catch {}
            }.GetNewClosure())
            $Global:Win32ProfileButtons += $profileButton
            $profileColumn=[math]::Floor($profileIndex / 8)
            $profileRow=$profileIndex % 8
            [System.Windows.Controls.Grid]::SetColumn($profileButton,[int]($profileColumn * 2))
            [System.Windows.Controls.Grid]::SetRow($profileButton,[int]$profileRow)
            [void]$win32List.Children.Add($profileButton)
            Add-PressMotion -Control $profileButton -PressScale 0.965 -PressOffset 1
        }
        [void]$win32Action.Children.Add($win32List)
        $Global:Win32ProfileSelection=if($Global:SelectedWin32Profile){[string]$Global:SelectedWin32Profile}else{'GAMING RECOMMENDED (0x2E)'}
        $Global:SelectedWin32Profile=$Global:Win32ProfileSelection
        if($Global:Win32ProfileStatus){$Global:Win32ProfileStatus.Text=('SELECTED  /  ' + $Global:Win32ProfileSelection)}
        [System.Windows.Controls.Grid]::SetColumn($win32Action,1)
        [void]$win32Grid.Children.Add($win32Action)
        $win32Card.Child=$win32Grid
        [void]$win32Stack.Children.Add($win32Card)

        [void]$CatOverlayItems.Children.Add($win32Stack)
        $CategoryOverlay.Visibility="Visible"
        return
    }

    if($groupName -eq "__RESHADE__"){
        # One-click ReShade page: strong focal point, supplied brand logo, and one clean action.
        if($CatOverlayActionsRow){$CatOverlayActionsRow.Visibility="Collapsed"}
        if($CatOverlayCount){$CatOverlayCount.Visibility="Collapsed"}
        if($CatOverlayEnableAll){$CatOverlayEnableAll.Visibility="Collapsed"}
        if($CatOverlayDisableAll){$CatOverlayDisableAll.Visibility="Collapsed"}
        if($CatOverlayCloseBtn){$CatOverlayCloseBtn.Visibility="Collapsed"}
        if($CatOverlayCloseX){$CatOverlayCloseX.Visibility="Collapsed"}

        $CatOverlayTitle.Text="RESHADE / SHADERS"
        $CatOverlayTitle.FontSize=21
        $CatOverlayTitle.FontWeight="Black"
        $CatOverlayTitle.Foreground=[System.Windows.Media.Brushes]::White
        $CatOverlayTitle.Margin="0,0,0,0"
        if($CatOverlayKicker){ $CatOverlayKicker.Text="Official DXGI from reshade.me into FiveM plugins" }
        $CatOverlayDesc.Text=""
        $CatOverlayDesc.FontSize=12
        $CatOverlayDesc.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#B5B5B5")
        $CatOverlayDesc.Margin="0,4,0,0"
        $scriptRootForInstall=$PSScriptRoot

        $reshadePage=New-Object System.Windows.Controls.StackPanel
        $reshadePage.HorizontalAlignment="Stretch"
        $reshadePage.VerticalAlignment="Top"
        $reshadePage.Margin="0,12,0,12"

        $reshadeInfo=New-Object System.Windows.Controls.Border
        $reshadeInfo.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#111111")
        $reshadeInfo.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#D8D8D8")
        $reshadeInfo.BorderThickness=[System.Windows.Thickness]::new(2,0,0,0)
        $reshadeInfo.Padding=[System.Windows.Thickness]::new(14,11,14,11)
        $reshadeInfo.Margin=[System.Windows.Thickness]::new(0,0,0,18)
        $reshadeInfo.HorizontalAlignment="Stretch"
        $reshadeInfoText=New-Object System.Windows.Controls.TextBlock
        $reshadeInfoText.Text="Downloads DXGI from reshade.me and installs every ReShade file into FiveM.app\plugins."
        $reshadeInfoText.Foreground=[System.Windows.Media.Brushes]::White
        $reshadeInfoText.FontSize=12
        $reshadeInfoText.FontWeight="SemiBold"
        $reshadeInfoText.TextWrapping="Wrap"
        $reshadeInfo.Child=$reshadeInfoText
        [void]$reshadePage.Children.Add($reshadeInfo)

        $heroPanel=New-Object System.Windows.Controls.Border
        $heroPanel.Width=690
        $heroPanel.MinHeight=520
        $heroPanel.Height=[double]::NaN
        $heroPanel.HorizontalAlignment="Center"
        $heroPanel.VerticalAlignment="Top"
        $heroPanel.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#090909")
        $heroPanel.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#707070")
        $heroPanel.BorderThickness=[System.Windows.Thickness]::new(1)
        $heroPanel.CornerRadius=[System.Windows.CornerRadius]::new(20)
        $heroPanel.Padding=[System.Windows.Thickness]::new(36,28,36,30)
        $heroShadow=New-Object System.Windows.Media.Effects.DropShadowEffect
        $heroShadow.Color=[System.Windows.Media.Color]::FromRgb(0x00,0x00,0x00)
        $heroShadow.BlurRadius=30
        $heroShadow.ShadowDepth=0
        $heroShadow.Opacity=0.72
        $heroPanel.Effect=$heroShadow

        $heroStack=New-Object System.Windows.Controls.StackPanel
        $heroStack.HorizontalAlignment="Center"
        $heroStack.VerticalAlignment="Center"

        $heroLogo=New-Object System.Windows.Controls.Image
        $heroLogo.Width=88
        $heroLogo.Height=88
        $heroLogo.Stretch="Uniform"
        $heroLogo.HorizontalAlignment="Center"
        $heroLogo.VerticalAlignment="Center"
        $heroLogo.Opacity=1.0
        $heroLogo.Margin="0,0,0,12"
        if($splashLogoBitmap){ $heroLogo.Source=$splashLogoBitmap }
        else { $heroLogo.Source=New-LessProjectEmbeddedLogoImage }
        [void]$heroStack.Children.Add($heroLogo)

        $heroTitle=New-Object System.Windows.Controls.TextBlock
        $heroTitle.Text="INSTALL RESHADE"
        $heroTitle.Foreground=[System.Windows.Media.Brushes]::White
        $heroTitle.FontSize=26
        $heroTitle.FontWeight="Black"
        $heroTitle.HorizontalAlignment="Center"
        $heroTitle.Margin="0,0,0,7"
        [void]$heroStack.Children.Add($heroTitle)

        $heroSubtitle=New-Object System.Windows.Controls.TextBlock
        $heroSubtitle.Text="OFFICIAL DXGI FROM RESHADE.ME  ·  FILES GO TO FIVEM PLUGINS"
        $heroSubtitle.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#B5B5B5")
        $heroSubtitle.FontSize=12
        $heroSubtitle.HorizontalAlignment="Center"
        $heroSubtitle.TextAlignment="Center"
        $heroSubtitle.Margin="0,0,0,16"
        [void]$heroStack.Children.Add($heroSubtitle)

        $reshadeStatus=New-Object System.Windows.Controls.TextBlock
        $reshadeStatus.Text="Detecting latest ReShade version from reshade.me ..."
        $reshadeStatus.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#D0D0D0")
        $reshadeStatus.FontSize=11
        $reshadeStatus.TextWrapping="Wrap"
        $reshadeStatus.TextAlignment="Center"
        $reshadeStatus.HorizontalAlignment="Center"
        $reshadeStatus.Margin="0,0,0,10"
        [void]$heroStack.Children.Add($reshadeStatus)

        $reshadePathText=New-Object System.Windows.Controls.TextBlock
        $reshadePathText.Text="Target: FiveM.app\plugins"
        $reshadePathText.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#8A8A8A")
        $reshadePathText.FontSize=11
        $reshadePathText.TextWrapping="Wrap"
        $reshadePathText.TextTrimming="CharacterEllipsis"
        $reshadePathText.MaxWidth=640
        $reshadePathText.TextAlignment="Center"
        $reshadePathText.HorizontalAlignment="Center"
        $reshadePathText.Margin="0,0,0,14"
        [void]$heroStack.Children.Add($reshadePathText)

        $versionRow=New-Object System.Windows.Controls.Grid
        $versionRow.Margin="0,0,0,14"
        $versionRow.HorizontalAlignment="Stretch"
        [void]$versionRow.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition))
        $versionCol2=New-Object System.Windows.Controls.ColumnDefinition
        $versionCol2.Width=[System.Windows.GridLength]::new(110)
        [void]$versionRow.ColumnDefinitions.Add($versionCol2)

        $versionBox=New-Object System.Windows.Controls.ComboBox
        $versionBox.Height=34
        $versionBox.FontSize=13
        $versionBox.Padding="8,4"
        $versionBox.MaxDropDownHeight=220
        $versionBox.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#141418")
        $versionBox.Foreground=[System.Windows.Media.Brushes]::White
        $versionBox.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#36566B")
        $darkPopup=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#141418")
        $lightPopup=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#F5F5F5")
        $versionBox.Resources[[System.Windows.SystemColors]::WindowBrushKey]=$darkPopup
        $versionBox.Resources[[System.Windows.SystemColors]::WindowTextBrushKey]=$lightPopup
        $versionBox.Resources[[System.Windows.SystemColors]::HighlightBrushKey]=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#12324A")
        $versionBox.ToolTip="ReShade version from reshade.me / GitHub tags"
        [System.Windows.Controls.Grid]::SetColumn($versionBox,0)
        [void]$versionRow.Children.Add($versionBox)

        $refreshButton=New-Object System.Windows.Controls.Button
        $refreshButton.Content="REFRESH"
        $refreshButton.Height=34
        $refreshButton.Margin="8,0,0,0"
        $refreshButton.Cursor="Hand"
        $refreshButton.Style=$window.Resources["QuietButton"]
        $refreshButton.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#1A1A1A")
        $refreshButton.Foreground=[System.Windows.Media.Brushes]::White
        $refreshButton.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#888888")
        $refreshButton.ToolTip="Detect the newest ReShade version from reshade.me"
        [System.Windows.Controls.Grid]::SetColumn($refreshButton,1)
        [void]$versionRow.Children.Add($refreshButton)
        [void]$heroStack.Children.Add($versionRow)

        $Global:ReshadeStatusText=$reshadeStatus
        $Global:ReshadePathText=$reshadePathText
        $Global:ReshadeVersionCombo=$versionBox

        $installButton=New-Object System.Windows.Controls.Button
        $installButton.Content="INSTALL RESHADE"
        $installButton.Width=520
        $installButton.Height=78
        $installButton.HorizontalAlignment="Center"
        $installButton.VerticalAlignment="Center"
        $installButton.Margin="0"
        $installButton.Padding="18,0"
        $installButton.Cursor="Hand"
        $installButton.Style=$window.Resources["QuietButton"]
        $buttonGradient=New-Object System.Windows.Media.LinearGradientBrush
        $buttonGradient.StartPoint=[System.Windows.Point]::new(0,0)
        $buttonGradient.EndPoint=[System.Windows.Point]::new(0,1)
        [void]$buttonGradient.GradientStops.Add((New-Object System.Windows.Media.GradientStop([System.Windows.Media.Color]::FromRgb(0x3A,0x3A,0x3A),0.0)))
        [void]$buttonGradient.GradientStops.Add((New-Object System.Windows.Media.GradientStop([System.Windows.Media.Color]::FromRgb(0x18,0x18,0x18),0.5)))
        [void]$buttonGradient.GradientStops.Add((New-Object System.Windows.Media.GradientStop([System.Windows.Media.Color]::FromRgb(0x0A,0x0A,0x0A),1.0)))
        $installButton.Background=$buttonGradient
        $installButton.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#C8C8C8")
        $installButton.BorderThickness=[System.Windows.Thickness]::new(1.25)
        $installButton.Foreground=[System.Windows.Media.Brushes]::White
        $installButton.FontSize=17
        $installButton.FontWeight="Bold"
        $installButton.HorizontalContentAlignment="Stretch"
        $installButton.VerticalContentAlignment="Center"
        $installButton.ToolTip="Download DXGI from reshade.me and install every ReShade file into FiveM.app\plugins"

        $installButtonContent=New-Object System.Windows.Controls.StackPanel
        $installButtonContent.Orientation="Horizontal"
        $installButtonContent.HorizontalAlignment="Center"
        $installButtonContent.VerticalAlignment="Center"
        $installButtonLabel=New-Object System.Windows.Controls.TextBlock
        $installButtonLabel.Text="INSTALL RESHADE"
        $installButtonLabel.Foreground=[System.Windows.Media.Brushes]::White
        $installButtonLabel.FontSize=17
        $installButtonLabel.FontWeight="Bold"
        $installButtonLabel.VerticalAlignment="Center"
        [void]$installButtonContent.Children.Add($installButtonLabel)
        $installButtonArrow=New-Object System.Windows.Shapes.Path
        $installButtonArrow.Data=[System.Windows.Media.Geometry]::Parse("M 0,0 L 5,5 L 0,10")
        $installButtonArrow.Stroke=[System.Windows.Media.Brushes]::White
        $installButtonArrow.StrokeThickness=1.6
        $installButtonArrow.StrokeStartLineCap=[System.Windows.Media.PenLineCap]::Round
        $installButtonArrow.StrokeEndLineCap=[System.Windows.Media.PenLineCap]::Round
        $installButtonArrow.Width=6
        $installButtonArrow.Height=12
        $installButtonArrow.Stretch="Fill"
        $installButtonArrow.VerticalAlignment="Center"
        $installButtonArrow.Margin="7,0,0,0"
        [void]$installButtonContent.Children.Add($installButtonArrow)
$installButton.Content=$installButtonContent
        [void]$heroStack.Children.Add($installButton)
        $heroPanel.Child=$heroStack
        [void]$reshadePage.Children.Add($heroPanel)

        $uninstallButton=New-Object System.Windows.Controls.Button
        $uninstallButton.Content="UNINSTALL FROM PLUGINS"
        $uninstallButton.Width=520
        $uninstallButton.Height=40
        $uninstallButton.Margin="0,10,0,0"
        $uninstallButton.Cursor="Hand"
        $uninstallButton.Style=$window.Resources["QuietButton"]
        $uninstallButton.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#141414")
        $uninstallButton.Foreground=[System.Windows.Media.Brushes]::White
        $uninstallButton.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#666666")
        $uninstallButton.FontSize=12
        $uninstallButton.FontWeight="SemiBold"
        $uninstallButton.ToolTip="Remove dxgi.dll, ReShade.ini and reshade-shaders from FiveM plugins"
        [void]$heroStack.Children.Add($uninstallButton)

        Add-PremiumButtonMotion $installButton "Install" "#FFFFFF" 1.018 0.965 2 18 2 0.40 28 2 0.66
        $loadReshadeCatalog = {
            try {
                if(-not (Get-Command Get-ReShadeVersionCatalog -ErrorAction SilentlyContinue)){ throw 'ReShade helper was not loaded. Keep ReShade-FiveM.ps1 beside LessProject.ps1.' }
                $cat=Get-ReShadeVersionCatalog
                $Global:ReshadeCatalog=$cat
                $Global:ReshadeLatestVersion=[string]$cat.Latest
                Update-ReShadeVersionCombo -Combo $Global:ReshadeVersionCombo -Catalog $cat -Preferred $Global:ReshadeLatestVersion
                $status=Get-LessReShadeInstallStatusText
                if($Global:ReshadeStatusText){ $Global:ReshadeStatusText.Text = ("Latest on reshade.me: {0}`n{1}" -f $cat.Latest,$status) }
                if($Global:ReshadePathText){
                    try { $Global:ReshadePathText.Text = ("Install path: {0}" -f (Get-LessFiveMPluginsDirectory)) } catch { $Global:ReshadePathText.Text = $_.Exception.Message }
                }
                Add-Log ("ReShade catalog ready. Latest {0} from reshade.me" -f $cat.Latest) "#FFFFFF"
            } catch {
                if($Global:ReshadeStatusText){ $Global:ReshadeStatusText.Text = ("Could not read reshade.me: {0}" -f $_.Exception.Message) }
                Add-Log ("ReShade catalog failed: {0}" -f $_.Exception.Message) "#D8D8D8"
            }
        }
        $refreshButton.Add_Click({ Play-UiBeep; & $loadReshadeCatalog }.GetNewClosure())
        $installButton.Add_Click({
            Show-InstallProgressModal -DetailText "Reading reshade.me and installing into FiveM plugins..."
            try {
                if(-not (Get-Command Install-LessProjectReShadeToFiveM -ErrorAction SilentlyContinue)){ throw 'ReShade helper was not loaded. Keep ReShade-FiveM.ps1 beside LessProject.ps1.' }
                $selectedVersion=Get-SelectedReShadeVersion -Combo $Global:ReshadeVersionCombo
                $progress={
                    param($pct,$state,$detail)
                    Update-InstallModalProgress -Percent $pct -StateText $state -DetailText $detail
                }
                $result=Install-LessProjectReShadeToFiveM -Version $selectedVersion -Progress $progress
                Complete-InstallProgressModal -Success $true -DetailText ("Installed ReShade {0} to`n{1}" -f $result.Version,$result.Plugins)
                Set-CurrentTask ("ReShade {0} installed into FiveM plugins." -f $result.Version)
                Show-TweakToast -Label "RESHADE" -Enabled $true -OverrideText ("RESHADE  /  {0} INSTALLED" -f $result.Version) -DurationMs 3200
                Add-Log ("ReShade {0} installed: dxgi={1}" -f $result.Version,$result.Dxgi) "#FFFFFF"
                if($Global:ReshadeStatusText){ $Global:ReshadeStatusText.Text = Get-LessReShadeInstallStatusText }
            } catch {
                $errorText=$_.Exception.Message
                Complete-InstallProgressModal -Success $false -DetailText $errorText
                Set-CurrentTask "ReShade install failed."
                Show-TweakToast -Label "RESHADE" -Enabled $false -OverrideText "RESHADE  /  INSTALL FAILED" -DurationMs 3200
                [System.Windows.MessageBox]::Show($errorText,"INSTALL RESHADE",[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Warning) | Out-Null
            }
        }.GetNewClosure())
        $uninstallButton.Add_Click({
            try {
                Play-ReshadeButtonTone -Type "Uninstall"
                $answer=[System.Windows.MessageBox]::Show("Remove ReShade files from FiveM.app\plugins?`n`ndxgi.dll, ReShade.ini and reshade-shaders will be deleted. Other plugins are left untouched.","UNINSTALL RESHADE",[System.Windows.MessageBoxButton]::YesNo,[System.Windows.MessageBoxImage]::Warning)
                if($answer -ne [System.Windows.MessageBoxResult]::Yes){ return }
                $result=Uninstall-LessProjectReShadeFromFiveM
                $msg=if($result.Removed.Count -gt 0){ "Removed: " + ($result.Removed -join ', ') } else { "No ReShade files were present." }
                Set-CurrentTask $msg
                Show-TweakToast -Label "RESHADE" -Enabled $false -OverrideText "RESHADE  /  UNINSTALLED" -DurationMs 2800
                Add-Log ("ReShade uninstall from {0}: {1}" -f $result.Plugins,$msg) "#FFFFFF"
                if($Global:ReshadeStatusText){ $Global:ReshadeStatusText.Text = Get-LessReShadeInstallStatusText }
            } catch {
                [System.Windows.MessageBox]::Show($_.Exception.Message,"UNINSTALL RESHADE",[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Warning) | Out-Null
            }
        }.GetNewClosure())
        & $loadReshadeCatalog

        [void]$CatOverlayItems.Children.Add($reshadePage)
        $CategoryOverlay.Visibility="Visible"
        return
    }
    if($itemsInGroup){
        $summaryWrap=New-Object System.Windows.Controls.WrapPanel
        $summaryWrap.HorizontalAlignment=if($groupName -in @("__LAN__","__WIFI__")){"Center"}else{"Left"}
        $summaryWrap.Margin="0,0,0,10"
        $tagGroups=$itemsInGroup | Group-Object Tag | Sort-Object Count -Descending
        foreach($tg in $tagGroups){
            if(-not $tg.Name -or -not $Global:TagMeta.ContainsKey($tg.Name)){continue}
            $tm=$Global:TagMeta[$tg.Name]
            $chip=New-Object System.Windows.Controls.Border; $chip.CornerRadius="7"; $chip.Padding="8,4"; $chip.Margin="0,0,5,5"
            $chip.Background=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb([byte]$tm.Bg[0],[byte]$tm.Bg[1],[byte]$tm.Bg[2]))
            $chip.BorderBrush=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb([byte]$tm.Fg[0],[byte]$tm.Fg[1],[byte]$tm.Fg[2]))
            $chip.BorderThickness=1
            $chipTxt=New-Object System.Windows.Controls.TextBlock; $chipTxt.Text="$($tg.Count) $($tm.Label)"; $chipTxt.FontSize=11; $chipTxt.FontWeight="Bold"; $chipTxt.Foreground=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb([byte]$tm.Fg[0],[byte]$tm.Fg[1],[byte]$tm.Fg[2])); $chip.Child=$chipTxt
            $summaryWrap.Children.Add($chip)|Out-Null
        }
        $CatOverlayItems.Children.Add($summaryWrap)|Out-Null
    }
    # Render individual tweaks as a balanced 3-column card grid.
    # The overlay is already the full content column; size the cards from its
    # measured width instead of using a narrow fixed max that leaves blank space.
    $cardGap=8
    if($CategoryOverlay.Visibility -ne [System.Windows.Visibility]::Visible){$CategoryOverlay.Visibility=[System.Windows.Visibility]::Visible}
    # Do not force a synchronous full layout here; it blocks the click handler
    # while hundreds of tweak controls are being measured. Use the last measured
    # width when available and let WPF arrange the view asynchronously.
    $cardAreaWidth=[double]$CategoryOverlay.ActualWidth
    if($cardAreaWidth -le 0){ $cardAreaWidth=[double]$window.ActualWidth - 320 }
    $cardAreaWidth=[math]::Max(600,$cardAreaWidth - 36)
    $cardWidth=[math]::Floor(($cardAreaWidth - (3*$cardGap))/3)
    $cardWidth=[math]::Max(190,[math]::Min(420,$cardWidth))
    $cardWrap=New-Object System.Windows.Controls.WrapPanel
    $cardWrap.Width=($cardWidth*3)+(3*$cardGap)
    $cardWrap.Orientation="Horizontal"
    $cardWrap.HorizontalAlignment="Stretch"
    $cardWrap.Margin="0,0,0,4"
    [void]$CatOverlayItems.Children.Add($cardWrap)
    $buildToken=[int]$Global:TweakCardBuildToken
    $Global:TweakCardBuildBusy=$true
    $pending=New-Object System.Collections.Generic.Queue[object]
    foreach($item in @($itemsInGroup)){ $pending.Enqueue($item) }
    $Global:TweakCardBuildQueue=$pending
    $Global:TweakCardWrap=$cardWrap
    $Global:TweakCardWidth=$cardWidth
    $Global:TweakCardGap=$cardGap
    Add-PendingTweakCardBatch
    $CategoryOverlay.Visibility="Visible"
}
function Close-CategoryDetail { $CategoryOverlay.Visibility="Collapsed" }
function Play-TweakBeep { Play-UiBeep }
function Show-TweakToast {
    param([string]$Label,[bool]$Enabled,[string]$OverrideText="",[int]$DurationMs=1500)
    try {
        if(-not $TweakToastBanner){ return }
        $TweakToastText.Text=if($OverrideText){$OverrideText}elseif($Enabled){"เปิด $Label"}else{"ปิด $Label"}
        $TweakToastIcon.Text=if($OverrideText){if($Enabled){"✓"}else{"!"}}elseif($Enabled){"✓"}else{"–"}
        $tone=if($Enabled){"#4CB7FF"}else{"#6E8291"}
        $TweakToastBanner.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString($tone)
        $TweakToastIcon.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString($tone)
        $TweakToastBanner.Visibility="Visible"; $TweakToastBanner.Opacity=0
        $TweakToastScale.ScaleX=0.88; $TweakToastScale.ScaleY=0.88; $TweakToastTranslate.Y=8
        $fade=New-Object System.Windows.Media.Animation.DoubleAnimation
        $fade.From=0; $fade.To=1; $fade.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(180))
        $growX=New-Object System.Windows.Media.Animation.DoubleAnimation
        $growX.From=0.88; $growX.To=1.0; $growX.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(220))
        $growY=New-Object System.Windows.Media.Animation.DoubleAnimation
        $growY.From=0.88; $growY.To=1.0; $growY.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(220))
        $slide=New-Object System.Windows.Media.Animation.DoubleAnimation
        $slide.From=8; $slide.To=0; $slide.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(220))
        $ease=New-Object System.Windows.Media.Animation.CubicEase; $ease.EasingMode="EaseOut"
        $growX.EasingFunction=$ease; $growY.EasingFunction=$ease; $slide.EasingFunction=$ease
        $TweakToastBanner.BeginAnimation([System.Windows.UIElement]::OpacityProperty,$fade)
        $TweakToastScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$growX)
        $TweakToastScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$growY)
        $TweakToastTranslate.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty,$slide)
        if($Global:TweakToastTimer){ try{$Global:TweakToastTimer.Stop()}catch{} }
        $Global:TweakToastTimer=New-Object System.Windows.Threading.DispatcherTimer
        $Global:TweakToastTimer.Interval=[TimeSpan]::FromMilliseconds($DurationMs)
        $Global:TweakToastTimer.Add_Tick({
            param($sender,$eventArgs)
            $sender.Stop()
            try {
                $fadeOut=New-Object System.Windows.Media.Animation.DoubleAnimation
                $fadeOut.From=1; $fadeOut.To=0; $fadeOut.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(280))
                $shrinkX=New-Object System.Windows.Media.Animation.DoubleAnimation
                $shrinkX.From=1.0; $shrinkX.To=0.92; $shrinkX.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(280))
                $shrinkY=New-Object System.Windows.Media.Animation.DoubleAnimation
                $shrinkY.From=1.0; $shrinkY.To=0.92; $shrinkY.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(280))
                $easeOut=New-Object System.Windows.Media.Animation.CubicEase; $easeOut.EasingMode="EaseIn"
                $fadeOut.EasingFunction=$easeOut; $shrinkX.EasingFunction=$easeOut; $shrinkY.EasingFunction=$easeOut
                $fadeOut.add_Completed({ try { $Global:TweakToastBanner.Visibility="Collapsed" } catch {} }.GetNewClosure())
                $Global:TweakToastBanner.BeginAnimation([System.Windows.UIElement]::OpacityProperty,$fadeOut)
                $Global:TweakToastScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$shrinkX)
                $Global:TweakToastScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$shrinkY)
            } catch { try { $Global:TweakToastBanner.Visibility="Collapsed" } catch {} }
        }.GetNewClosure())
        $Global:TweakToastTimer.Start()
    } catch {}
}
function Update-InstallModalProgress {
    param([int]$Percent,[string]$StateText="INSTALLING",[string]$DetailText="Working...")
    try {
        if(-not $InstallModalOverlay){ return }
        $pct=[math]::Max(0,[math]::Min(100,$Percent))
        $InstallModalOverlay.Visibility="Visible"
        $InstallModalState.Text=$StateText
        $InstallModalPercent.Text=($pct.ToString() + "%")
        $InstallModalDetail.Text=$DetailText
        $trackWidth=0
        if($InstallModalProgressFill.Parent){ $trackWidth=$InstallModalProgressFill.Parent.ActualWidth }
        if($trackWidth -le 0){ $trackWidth=476 }
        $InstallModalProgressFill.Width=[math]::Max(0,[math]::Min($trackWidth,$trackWidth*($pct/100.0)))
        $InstallModalSuccessBadge.Visibility="Collapsed"
        $InstallModalClose.IsEnabled=$false
        $window.Dispatcher.Invoke([Action]{},[System.Windows.Threading.DispatcherPriority]::Render)
    } catch {}
}
function Show-InstallProgressModal {
    param([string]$DetailText="Preparing the ReShade installer...")
    Update-InstallModalProgress -Percent 8 -StateText "PREPARING INSTALLATION" -DetailText $DetailText
}
function Complete-InstallProgressModal {
    param([bool]$Success,[string]$DetailText)
    try {
        if(-not $InstallModalOverlay){ return }
        if($Success){
            Update-InstallModalProgress -Percent 100 -StateText "INSTALLER READY" -DetailText $DetailText
            $InstallModalSuccessBadge.Visibility="Visible"
            $InstallModalSuccessText.Text="INSTALLER LAUNCHED SUCCESSFULLY"
            $InstallModalClose.IsEnabled=$true
        } else {
            Update-InstallModalProgress -Percent 100 -StateText "INSTALL FAILED" -DetailText $DetailText
            $InstallModalSuccessBadge.Visibility="Visible"
            $InstallModalSuccessText.Text="INSTALLER COULD NOT START"
            $InstallModalClose.IsEnabled=$true
        }
    } catch {}
}
function Close-InstallProgressModal {
    try { $InstallModalOverlay.Visibility="Collapsed"; $InstallModalClose.IsEnabled=$false } catch {}
}
$InstallModalClose.Add_Click({ Close-InstallProgressModal })
