function Set-PresetGlow {
    param($Border,[bool]$Selected,[string]$AccentColor,[string]$DefaultColor="#232323")
    if(-not $Border){ return }
    $bc = New-Object System.Windows.Media.BrushConverter
    if($Selected){
        $accent = $bc.ConvertFromString($AccentColor)
        $Border.BorderBrush = $accent
        $Border.BorderThickness = [System.Windows.Thickness]::new(1.6)
        $Border.Effect = $null
    } else {
        $Border.BorderBrush = $bc.ConvertFromString($DefaultColor)
        $Border.BorderThickness = [System.Windows.Thickness]::new(1)
        $Border.Effect = $null
    }
}
function Set-NetPresetGlow {
    param([string]$Selected)
    if(-not $NetPresetLan -or -not $NetPresetWifi){ return }
    [void]$NetPresetLan.ApplyTemplate(); [void]$NetPresetWifi.ApplyTemplate()
    $lanBd = $NetPresetLan.Template.FindName("buttonBorder",$NetPresetLan)
    $wifiBd = $NetPresetWifi.Template.FindName("buttonBorder",$NetPresetWifi)
    Set-PresetGlow -Border $lanBd  -Selected ($Selected -eq "LAN NETWORK")   -AccentColor "#4CB7FF" -DefaultColor "#36566B"
    Set-PresetGlow -Border $wifiBd -Selected ($Selected -eq "WI-FI NETWORK") -AccentColor "#4CB7FF" -DefaultColor "#36566B"
}
function Set-ButtonSelectionGlow{
    param($Button,[bool]$Selected,[string]$AccentColor,[string]$DefaultColor="#515151",[string]$SelectedBackgroundColor="#3A3A3A")
    if(-not $Button){ return }
    $bc=New-Object System.Windows.Media.BrushConverter
    if($Selected){
        $accent=$bc.ConvertFromString($AccentColor)
        $Button.Background=$bc.ConvertFromString("#12324A")
        $Button.Foreground=$bc.ConvertFromString("#FFFFFF")
        $Button.BorderBrush=$accent
        $Button.BorderThickness=[System.Windows.Thickness]::new(1.6)
        $Button.Effect=$null
    } else {
        $Button.Background=$bc.ConvertFromString("#161616")
        $Button.Foreground=$bc.ConvertFromString("#F2F2F2")
        $Button.BorderBrush=$bc.ConvertFromString($DefaultColor)
        $Button.BorderThickness=[System.Windows.Thickness]::new(1)
        $Button.Effect=$null
    }
}
