function Update-PresetGlowConsistency {
    # Re-checks whether the actual tweak toggle state still matches each preset, and dims
    # the glow on any preset button whose selection no longer reflects reality (e.g. the
    # user manually flipped a checkbox that the preset had set).
    if($Global:ActiveNetPreset){
        $type=$Global:ActiveNetPreset
        $other="WI-FI NETWORK"; if($type -eq "WI-FI NETWORK"){ $other="LAN NETWORK" }
        $match=$true
        foreach($t in $Global:TweakInfo){
            # Only invalidate if a tweak in the ACTIVE group is turned OFF.
            # We no longer invalidate just because a tweak in the OTHER group is turned ON (by FiveM Optimize).
            if($t.Group -eq $type -and -not $Global:TweakToggles[$t.Key]){ $match=$false; break }
        }
        if($match){ Set-NetPresetGlow -Selected $type } else { Set-NetPresetGlow -Selected $null }
    } else { Set-NetPresetGlow -Selected $null }
    if($Global:ActiveGpuPreset){
        $vendor=$Global:ActiveGpuPreset
        $mine="AMD GPU"; $other="NVIDIA GPU"; if($vendor -eq "NVIDIA"){ $mine="NVIDIA GPU"; $other="AMD GPU" }
        $match=$true
        foreach($t in $Global:TweakInfo){
            if($t.Group -eq $mine -and -not $Global:TweakToggles[$t.Key]){ $match=$false }
            elseif($t.Group -eq $other -and $Global:TweakToggles[$t.Key]){ $match=$false }
        }
        if($match){ Set-GpuPresetGlow -Selected $vendor } else { Set-GpuPresetGlow -Selected $null }
    } else { Set-GpuPresetGlow -Selected $null }
    # ONE CLICK LESS Glow: only evaluate the recommended keys that the button owns.
    $oneClickKeys=@(Get-OneClickLessKeys)
    $match=($oneClickKeys.Count -gt 0)
    foreach($key in $oneClickKeys){
        if(-not $Global:TweakToggles[$key]){ $match=$false; break }
    }
    Set-OneClickLessButtonState -Active $match
}
function Set-NetPreset {
    param([ValidateSet("LAN NETWORK","WI-FI NETWORK")][string]$Type,[switch]$KeepDashboard)
    $other= if($Type -eq "LAN NETWORK"){"WI-FI NETWORK"}else{"LAN NETWORK"}
    
    # Toggle Logic: If clicking the already active preset, turn it OFF.
    if($Global:ActiveNetPreset -eq $Type){
        foreach($t in $Global:TweakInfo){
            if($t.Group -eq $Type){ $Global:TweakToggles[$t.Key]=$false }
        }
        $Global:ActiveNetPreset = $null
        Add-Log "Network preset: Deselected" "#FFFFFF"
        $networkLabel=if($Type -eq "LAN NETWORK"){"LAN"}else{"WIFI"}
        Show-TweakToast -Label $networkLabel -Enabled $false -OverrideText "$networkLabel  /  OFF" -DurationMs 2600
    } else {
        $safeLan=@('LanOptimize','TcpGlobal','NetThrottle','NET_NoNagle','NET_PowerSaving','NET_TcpTimedWait','NET_PortRange','NET_QoSReserve','NET_LanInterruptModeration','NET_DnsFast','NET_DeliveryOptOff','NET_DnsCacheAggressive','NET_RssEnable','NET_FastLan','NET_LowLatencyLan','NET_LanMtu','NET_LanSpeedDuplex')
        $safeWifi=@('WifiOptimize','TcpGlobal_WiFi','NetThrottle_WiFi','NET_NoNagle_WiFi','NET_PowerSaving_WiFi','NET_TcpTimedWait_WiFi','NET_PortRange_WiFi','NET_QoSReserve_WiFi','NET_WifiPowerSaveMode','NET_WifiRoamingAggressiveness','NET_DnsFast_WiFi','NET_FastWifi','NET_LowLatencyWifi','NET_WifiMtu','NET_WifiSpeedDuplex')
        $unsafeNet=@('NET_LanJumboFrame','NET_Ipv6Disable','NET_Ipv6Disable_WiFi','NduDisable','NduDisable_WiFi','NET_NetbiosDisable')
        foreach($t in $Global:TweakInfo){
            if($t.Group -eq $Type){
                $enableThis = if($Type -eq 'LAN NETWORK'){ $safeLan -contains $t.Key } else { $safeWifi -contains $t.Key }
                $Global:TweakToggles[$t.Key]=[bool]$enableThis
            }
            elseif($t.Group -eq $other){
                $Global:TweakToggles[$t.Key]=$false
            }
        }
        foreach($unsafeKey in $unsafeNet){ if($Global:TweakToggles.ContainsKey($unsafeKey)){ $Global:TweakToggles[$unsafeKey]=$false } }
        $Global:ActiveNetPreset = $Type
        $label= if($Type -eq "LAN NETWORK"){"LAN (wired)"}else{"Wi-Fi"}
        Add-Log "Network preset: $label tweaks enabled" "#FFFFFF"
        $networkLabel=if($Type -eq "LAN NETWORK"){"LAN"}else{"WIFI"}
        Show-TweakToast -Label $networkLabel -Enabled $true -OverrideText "$networkLabel  /  SELECTED`nกด START LESS PROJECT เพื่อ Apply ค่า" -DurationMs 3600
    }
    
    Update-PresetGlowConsistency
    Update-DashboardNetworkButtons
    Update-DashboardStatusPanel
    if(-not $KeepDashboard){
        # The left-side NET TWEAKS buttons still open their detailed view. Dashboard
        # LAN/WIFI buttons use -KeepDashboard so presets can be selected in either order.
        $targetView=if($Type -eq "LAN NETWORK"){"__LAN__"}else{"__WIFI__"}
        $targetTab=if($Type -eq "LAN NETWORK"){$BtnTabLan}else{$BtnTabWifi}
        if(Get-Command Set-ToolsSubTabActive -ErrorAction SilentlyContinue){
            Set-MainMenuActive "NETTWEAKS"
            $Global:ActiveToolsView=$targetView
            Set-ToolsSubTabActive $targetTab
        }
        Show-CategoryDetail $targetView
    }
    Save-TweakState
}
function Set-GpuPreset {
    param([ValidateSet("AMD","NVIDIA")][string]$Vendor)
    # Preset buttons are manual UI choices. Do not block AMD/NVIDIA when WMI detection
    # is incomplete or a hybrid GPU system is reported incorrectly; each vendor-specific
    # Run-* helper still performs its own hardware safety check before applying a change.
    $mine= if($Vendor -eq "AMD"){"AMD GPU"}else{"NVIDIA GPU"}
    $other= if($Vendor -eq "AMD"){"NVIDIA GPU"}else{"AMD GPU"}

    # Toggle Logic: If clicking the already active preset, turn it OFF.
    if($Global:ActiveGpuPreset -eq $Vendor){
        foreach($t in $Global:TweakInfo){
            if($t.Group -eq $mine){ $Global:TweakToggles[$t.Key]=$false }
        }
        $Global:ActiveGpuPreset = $null
        Add-Log "GPU preset: Deselected" "#FFFFFF"
    } else {
        $Global:DetectedGpuVendor=$Vendor
        foreach($t in $Global:TweakInfo){
            if($t.Group -eq $mine){ $Global:TweakToggles[$t.Key]=$true }
            elseif($t.Group -eq $other){ $Global:TweakToggles[$t.Key]=$false }
        }
        $Global:ActiveGpuPreset = $Vendor
        Add-Log "GPU preset: $Vendor tweaks enabled" "#FFFFFF"
    }

    Update-PresetGlowConsistency
    # Always open the selected vendor list so AMD/NVIDIA values are immediately selectable.
    # This is intentionally independent of the previous tab/category and fixes the case where
    # the preset changed state but left the user looking at an empty or unrelated view.
    $Global:ActiveCategory=$mine
    Show-CategoryDetail $mine
    Save-TweakState
}
$GpuPresetAmd.Add_Click({ Play-UiBeep; Set-GpuPreset -Vendor "AMD" })
$GpuPresetNvidia.Add_Click({ Play-UiBeep; Set-GpuPreset -Vendor "NVIDIA" })
# Independent FiveM dashboard presets. LOW INPUT LAG owns input/render/session keys;
# FLOW NET owns transport/adapter/DNS/packet-flow keys. The lists are intentionally
# explicit and disjoint so clicking one never changes the other. FULL SYSTEM below
# enumerates every key present in TweakInfo, rather than relying on a hand-maintained list.
$Global:LowInputLagPresetKeys=@('KbQueue','USB_PowerSuspendOff','NET_USBSelSuspend','NET_AdaptersOptimizer','NET_LanMtu','NET_WifiMtu','FIVEM_PriorityBoost','FIVEM_HighPerformanceGPU','GM_FiveMPerfOptions','FiveMBooster','GM_GameMode','GM_FSOptim','GM_SmoothMotion','GM_NoGameDVR','GM_GameBarOff','FIVEM_SessionServices')
$Global:FlowNetPresetKeys=@('GM_NoStickyKeys','INPUT_KeyboardRepeat','NetThrottle','TcpGlobal','NET_NoNagle','NET_PowerSaving','NET_FastLan','NET_LowLatencyLan','NET_FastWifi','NET_LowLatencyWifi','NET_RSC','NET_ECN','NET_FastOpen','NET_FlowControlOff','NET_FlowControlStable','NET_TcpTimedWait','NET_TcpTimedWait_WiFi','NET_PortRange','NET_PortRange_WiFi','NET_QoSReserve','NET_QoSReserve_WiFi','NET_NcsiNoActiveProbe','NET_DnsCacheAggressive','NET_DeliveryOptOff','NET_DnsFast','NET_DnsFast_WiFi','NET_LltdDisable','NET_NetbiosDisable','NET_FiveMQos','NET_FiveMFirewall','NET_Ipv6Transition')
$Global:LowInputLagPresetEnabled=$false; $Global:FlowNetPresetEnabled=$false; $Global:FullSystemPresetEnabled=$false
function Get-AvailablePresetKeys {
    param([string[]]$Keys)
    # LAN and Wi-Fi are manual choices. Dashboard presets never silently select
    # either network group; use the dedicated LAN/WIFI buttons instead.
    return @($Keys | Where-Object {
        $key=[string]$_
        if(-not $Global:TweakInfoByKey.ContainsKey($key)){ return $false }
        $group=[string]$Global:TweakInfoByKey[$key].Group
        $group -notin @('LAN NETWORK','WI-FI NETWORK')
    } | Select-Object -Unique)
}
function Update-DashboardSpecialPresetButtons {
    foreach($entry in @(@($DashboardLowInputButton,[bool]$Global:LowInputLagPresetEnabled,'LOW INPUT LAG'),@($DashboardFlowNetButton,[bool]$Global:FlowNetPresetEnabled,'FLOW NET'),@($DashboardFullSystemButton,[bool]$Global:FullSystemPresetEnabled,'FULL SYSTEM'))){
        $button=$entry[0]; if(-not $button){continue}; $on=[bool]$entry[1]; $label=[string]$entry[2]
        $button.Content=('{0}  /  {1}' -f $label,($(if($on){'ON'}else{'OFF'})))
    $button.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString($(if($on){'#12324A'}else{'#101820'}))
    $button.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString($(if($on){'#4CB7FF'}else{'#36566B'}))
    }
    Update-DashboardStatusPanel
}
function Update-DashboardNetworkButtons {
    if($DashboardLanButton){
        $lanOn=([string]$Global:ActiveNetPreset -eq 'LAN NETWORK')
        $DashboardLanButton.Content=('LAN  /  {0}' -f $(if($lanOn){'ON'}else{'OFF'}))
        $DashboardLanButton.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString($(if($lanOn){'#12324A'}else{'#101820'}))
        $DashboardLanButton.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString($(if($lanOn){'#4CB7FF'}else{'#36566B'}))
    }
    if($DashboardWifiButton){
        $wifiOn=([string]$Global:ActiveNetPreset -eq 'WI-FI NETWORK')
        $DashboardWifiButton.Content=('WIFI  /  {0}' -f $(if($wifiOn){'ON'}else{'OFF'}))
        $DashboardWifiButton.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString($(if($wifiOn){'#12324A'}else{'#101820'}))
        $DashboardWifiButton.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString($(if($wifiOn){'#4CB7FF'}else{'#36566B'}))
    }
}
function Set-DashboardSpecialPreset {
    param([ValidateSet('LOW INPUT LAG','FLOW NET','FULL SYSTEM')][string]$Preset)
    $isLow=($Preset -eq 'LOW INPUT LAG'); $isFlow=($Preset -eq 'FLOW NET')
    # Network selection is independent from the three main presets. Preserve a
    # LAN/WIFI choice made before this click; the user may choose either order.
    $keys=if(-not $isLow -and -not $isFlow){ @(Get-AvailablePresetKeys @($Global:TweakInfo | ForEach-Object {[string]$_.Key})) } else { @(Get-AvailablePresetKeys $(if($isLow){$Global:LowInputLagPresetKeys}else{$Global:FlowNetPresetKeys})) }
    $enabled=if($isLow){-not [bool]$Global:LowInputLagPresetEnabled}elseif($isFlow){-not [bool]$Global:FlowNetPresetEnabled}else{-not [bool]$Global:FullSystemPresetEnabled}
    foreach($key in $keys){ $Global:TweakToggles[$key]=[bool]$enabled }
    if($isLow){$Global:LowInputLagPresetEnabled=$enabled}elseif($isFlow){$Global:FlowNetPresetEnabled=$enabled}else{$Global:FullSystemPresetEnabled=$enabled}
    Update-DashboardSpecialPresetButtons; Update-EnabledBadge
    # Navigate to the exact selector view after a dashboard preset click. This keeps
    # LOW INPUT LAG's keyboard values visible in TWEAKS instead of leaving the user
    # on the previously selected category.
    if($isLow){
        Set-MainMenuActive 'TOOLS'; $Global:ActiveToolsView='__LOW_INPUT_LAG__'; Set-ToolsSubTabActive $BtnTabInput; Show-CategoryDetail '__LOW_INPUT_LAG__'
    } elseif(-not $isFlow){
        Set-MainMenuActive 'TOOLS'; $Global:ActiveToolsView='__ALL__'; Set-ToolsSubTabActive $BtnTabAll; Show-CategoryDetail '__ALL__'
    } elseif($Global:ActiveCategory){ Show-CategoryDetail $Global:ActiveCategory }
    Save-TweakState
    Add-Log ('{0} preset {1}: {2} explicit tweak values selected; other preset unchanged.' -f $Preset,$(if($enabled){'ON'}else{'OFF'}),$keys.Count) '#FFFFFF'
    Set-CurrentTask ('{0} {1}. Press START LESS PROJECT to apply.' -f $Preset,($(if($enabled){'ON'}else{'OFF'})))
    Show-TweakToast -Label $Preset -Enabled $enabled -OverrideText ('{0}  /  {1}' -f $Preset,$(if($enabled){'ON'}else{'OFF'})) -DurationMs 2200
}
