# These are the three Recommended network cards that must always follow ONE CLICK LESS.
# Keep the explicit list in addition to metadata-driven discovery so a renamed badge,
# stale cache, or future safety-profile change cannot silently drop them.
$Global:OneClickRequiredNetworkKeys = @("LanOptimize","NET_NoNagle","NET_PowerSaving")
function Get-OneClickLessKeys {
    # Balanced realtime preset. Do not derive this list from every card marked
    # RECOMMENDED: future metadata changes must not silently enable risky knobs.
    # Boot/clock changes, forced core parking, memory purges and driver experiments
    # stay manual so the profile remains predictable over long sessions.
    $balancedKeys=@(
        "GM_FiveMPerfOptions","FiveMBooster","GM_GameMode","GM_NoGameDVR","GM_GameBarOff",
        "GM_FSOptim","KbQueue","GM_NoStickyKeys","PWR_Throttling","UX_MenuInstant",
        "TcpGlobal","NetThrottle","NET_NoNagle","NET_PowerSaving","LanOptimize",
        "NET_FiveMQos","NET_FiveMFirewall","NET_DnsCacheAggressive","NET_DeliveryOptOff",
        "NET_NcsiNoActiveProbe"
    )
    return @(
        foreach($key in $balancedKeys){
            if($Global:TweakInfoByKey.ContainsKey([string]$key)){ [string]$key }
        }
    ) | Select-Object -Unique
}
function Set-OneClickLessButtonState {
    param([bool]$Active)
    if(-not $BtnPresetAllExceptGpuLan){ return }
    $Global:OneClickLessSelected = $Active
    try {
        if($Active){
            $BtnPresetAllExceptGpuLan.Content = "ONE CLICK LESS  /  ON"
            $BtnPresetAllExceptGpuLan.ToolTip = "ONE CLICK LESS เปิดอยู่ — balanced realtime preset พร้อม hysteresis และเพดาน AboveNormal; NIC/GPU/boot ขั้นสูงยังเลือกเอง"
        } else {
            $BtnPresetAllExceptGpuLan.Content = "ONE CLICK LESS  /  OFF"
            $BtnPresetAllExceptGpuLan.ToolTip = "ONE CLICK LESS ปิดอยู่ — กดเพื่อเลือก balanced realtime preset; ค่าขั้นสูงยังเลือกเอง"
        }
    } catch {}
    Set-SelectAllGlow -Active $Active
}
function Set-PresetAllExceptGpuLan {
    param([bool]$Enabled = $true)
    # ONE CLICK LESS selects only the bounded balanced realtime preset. Advanced
    # adapter, GPU, boot, memory-purge and service changes remain manual.
    $keys=@(Get-OneClickLessKeys)
    if($Enabled){
        # Migrate older state files safely: the previous preset could have left
        # Advanced/legacy selections enabled. They are now manual-only and must
        # not silently re-enter a balanced realtime run.
        $legacyBlocked=@(
            $Global:ExtendedTweakKeys +
            @($Global:RecommendedFiveMBalancedKeys | Where-Object { $keys -notcontains $_ }) +
            @("GM_FiveMCoreAffinity","GM_StandbyClean","GamingMemory","PWR_UltimatePlan","SYS_NoCoreParking","BcdTimer","ADV_HPET","GM_HAGS","GM_MMCSS","SYS_Win32Priority","CLEAN_KillBackgroundProcs")
        ) | Select-Object -Unique
        foreach($blockedKey in @($legacyBlocked)){
            if($Global:TweakToggles.ContainsKey([string]$blockedKey)){$Global:TweakToggles[[string]$blockedKey]=$false}
        }
    }
    # Defensive second pass: these required Recommended cards are never allowed
    # to be omitted even if metadata/cache is incomplete on an older session.
    foreach($requiredKey in @($Global:OneClickRequiredNetworkKeys)){
        if($Global:TweakToggles.ContainsKey($requiredKey) -and $keys -notcontains $requiredKey){ $keys += $requiredKey }
    }
    $keys=@($keys | Select-Object -Unique)
    foreach($key in $keys){ $Global:TweakToggles[$key]=[bool]$Enabled }
    Set-OneClickLessButtonState -Active $Enabled
    if($Enabled){
        Add-Log ("ONE CLICK LESS ON: {0} balanced realtime tweaks selected. Bounded FiveM priority and hysteresis are armed; advanced NIC/GPU/boot changes remain manual." -f $keys.Count) "#FFFFFF"
        Set-CurrentTask "ONE CLICK LESS ON — balanced realtime profile selected. Press START LESS PROJECT to apply."
        Show-TweakToast -Label "ONE CLICK LESS" -Enabled $true -OverrideText "ONE CLICK LESS  /  ON" -DurationMs 2200
    } else {
        Add-Log ("ONE CLICK LESS OFF: {0} balanced realtime selections cleared. Manual advanced profiles were left unchanged." -f $keys.Count) "#D8D8D8"
        Set-CurrentTask "ONE CLICK LESS OFF — no balanced realtime values from this preset are selected."
        Show-TweakToast -Label "ONE CLICK LESS" -Enabled $false -OverrideText "ONE CLICK LESS  /  OFF" -DurationMs 2200
    }
    Update-PresetGlowConsistency
    if($Global:ActiveCategory){ Show-CategoryDetail $Global:ActiveCategory }
    Save-TweakState
}
function Invoke-OneClickSoftPowerplan {
    if(-not (Test-IsAdministrator)){
        if(Restart-LessProjectAsAdministrator -ApplyAfterStart -PendingPowerPlanName 'SOFTPOWERPLAN'){
            try { $window.Close() } catch {}
        } else {
            [System.Windows.MessageBox]::Show("ONE CLICK LESS ต้องใช้สิทธิ์ Administrator แต่ไม่สามารถขอสิทธิ์ได้ กรุณาคลิกขวาไฟล์แล้วเลือก Run as administrator","ONE CLICK LESS",[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Warning) | Out-Null
        }
        return
    }
    try{
        try {
            $prev=Get-LessActivePowerPlan
            if($prev -and $prev.Guid -and -not $Global:OrigMisc.ContainsKey('ONECLICK_PREV_POWERPLAN')){
                $Global:OrigMisc['ONECLICK_PREV_POWERPLAN']=@{Type='ActivePowerPlan';Guid=[string]$prev.Guid;Name=[string]$prev.Name}
                Save-TweakState
            }
        } catch {}
        $r=Activate-SoftPowerplan
        if(-not $r -or -not $r.Guid){ throw "SOFTPOWERPLAN activation could not be verified." }
        $Global:SoftPowerplanLocked=$true
        $Global:PowerPlanSelectedLabel="SOFTPOWERPLAN"
        $Global:PowerPlanExpectedGuid=[string]$r.Guid
        $Global:PowerPlanStatusUiLock=$true
        Add-Log ("SOFTPOWERPLAN activated and locked: {0}" -f $r.Guid) "#FFFFFF"
        Show-TweakToast -Label "POWERPLAN" -Enabled $true -OverrideText "SOFTPOWERPLAN  /  LOCKED" -DurationMs 2800
        Set-CurrentTask "ONE CLICK LESS ready. SOFTPOWERPLAN is active and locked."
    } catch {
        $Global:SoftPowerplanLocked=$false
        Add-Log ("SOFTPOWERPLAN activation failed: {0}" -f $_.Exception.Message) "#D8D8D8"
        Show-TweakToast -Label "POWERPLAN" -Enabled $false -OverrideText "SOFTPOWERPLAN  /  FAILED" -DurationMs 3200
    }
}
$BtnPresetAllExceptGpuLan.Add_Click({
    Play-OneClickToggleSound -Type "Click"
    $enableOneClick = (-not [bool]$Global:OneClickLessSelected)
    Set-PresetAllExceptGpuLan -Enabled $enableOneClick
    Play-OneClickToggleSound -Type $(if($enableOneClick){"On"}else{"Off"})
    if($enableOneClick){
        Invoke-OneClickSoftPowerplan
    } else {
        $Global:SoftPowerplanLocked = $false
        $Global:PowerPlanStatusUiLock = $false
        try { Stop-RealtimeBoostController -Restore $true } catch {}
        try {
            $prev=$Global:OrigMisc['ONECLICK_PREV_POWERPLAN']
            if($prev -and $prev.Guid -and (Test-IsAdministrator)){
                [void](Invoke-LessPowerCfg -Arguments @('/setactive', [string]$prev.Guid))
                Add-Log ("ONE CLICK LESS OFF: restored previous power plan {0}" -f $prev.Guid) "#D8D8D8"
            }
        } catch {}
        Add-Log "ONE CLICK LESS OFF: SOFTPOWERPLAN lock released; realtime priority controller stopped." "#D8D8D8"
        Set-CurrentTask "ONE CLICK LESS OFF — SOFTPOWERPLAN is unlocked."
    }
})
