# Main navigation: TOOLS owns the five utility sub-tabs. FIVEM and RESHADE
# are standalone modules and never activate or inherit a TOOLS sub-tab.
$Global:ActiveMainMenu = "TOOLS"
$Global:ActiveToolsView = "__TOOLS_ALL__"
function Set-ToolsSubTabActive {
    param($Active)
    $activeBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#3A3A3A")
    $idleBrush=[System.Windows.Media.Brushes]::Transparent
    $activeText=[System.Windows.Media.Brushes]::White
    $idleText=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#8C8C8C")
    foreach($tab in @($BtnTabAll,$BtnTabLan,$BtnTabWifi,$BtnTabInput,$BtnTabSystem)){
        if($tab){
            $tab.Background=if($tab -eq $Active){$activeBrush}else{$idleBrush}
            $tab.Foreground=if($tab -eq $Active){$activeText}else{$idleText}
        }
    }
}
function Set-NavButtonVisualState {
    param($Button,[bool]$IsActive)
    if(-not $Button){ return }
    try {
        $activeBg=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#12324A')
        $idleBg=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#141A22')
        $activeBorder=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#4CB7FF')
        $idleBorder=[System.Windows.Media.BrushConverter]::new().ConvertFromString('#445A7080')
        $Button.Background=if($IsActive){$activeBg}else{$idleBg}
        $Button.BorderBrush=if($IsActive){$activeBorder}else{$idleBorder}
        $Button.Foreground=if($IsActive){[System.Windows.Media.Brushes]::White}else{[System.Windows.Media.BrushConverter]::new().ConvertFromString('#B5B5B5')}
        $content=$Button.Content
        if($content -is [System.Windows.Controls.StackPanel] -and $content.Children.Count -ge 2){
            $icon=$content.Children[0]; $label=$content.Children[1]
            if($icon -is [System.Windows.Controls.TextBlock]){ $icon.Foreground=if($IsActive){[System.Windows.Media.BrushConverter]::new().ConvertFromString('#4CB7FF')}else{[System.Windows.Media.BrushConverter]::new().ConvertFromString('#8FA8BC')} }
            if($label -is [System.Windows.Controls.TextBlock]){ $label.Foreground=if($IsActive){[System.Windows.Media.Brushes]::White}else{[System.Windows.Media.BrushConverter]::new().ConvertFromString('#B5B5B5')} }
        }
    } catch {}
}
function Set-MainMenuActive {
    param([ValidateSet("DASHBOARD","TOOLS","FIVEM","RESHADE","POWERPLAN","WIN32","NETTWEAKS","SETTINGS")][string]$Menu)
    $Global:ActiveMainMenu=$Menu
    if($SystemInfoPanel){
        # Removed from every function/view; retain the object only for legacy bindings.
        $SystemInfoPanel.Visibility=[System.Windows.Visibility]::Collapsed
        $SystemInfoPanel.Width=0
        $SystemInfoPanel.MinWidth=0
        $SystemInfoPanel.MaxWidth=0
    }
    $activeBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#12324A")
    $idleBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#141A22")
    $activeBorder=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#4CB7FF")
    $idleBorder=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#445A7080")
    $activeText=[System.Windows.Media.Brushes]::White
    $idleText=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#B5B5B5")
    foreach($entry in @(
        @{Button=$BtnTabDashboard; Menu="DASHBOARD"},
        @{Button=$BtnTabTools; Menu="TOOLS"},
        @{Button=$BtnTabFiveM; Menu="FIVEM"},
        @{Button=$BtnTabReshade; Menu="RESHADE"},
        @{Button=$BtnTabSettings; Menu="POWERPLAN"},
        @{Button=$BtnTabWin32; Menu="WIN32"},
        @{Button=$BtnTabNetTweaks; Menu="NETTWEAKS"},
        @{Button=$BtnTabAppSettings; Menu="SETTINGS"}
    )){
        if($entry.Button){
            Set-NavButtonVisualState -Button $entry.Button -IsActive:($entry.Menu -eq $Menu)
        }
    }
    if($ToolsSubNav){
        $ToolsSubNav.Visibility=if($Menu -eq "TOOLS"){[System.Windows.Visibility]::Visible}else{[System.Windows.Visibility]::Collapsed}
    }
    if($Menu -ne "TOOLS"){ Set-ToolsSubTabActive $null }
}
function Start-PremiumViewTransition {
    param([scriptblock]$RenderAction)
    if(-not $RenderAction){ return }
    try {
        if($CategoryOverlay){
            $CategoryOverlay.BeginAnimation([System.Windows.UIElement]::OpacityProperty,$null)
            $CategoryOverlay.Opacity=1
            if($CategoryOverlay.RenderTransform -is [System.Windows.Media.TranslateTransform]){
                $CategoryOverlay.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty,$null)
                $CategoryOverlay.RenderTransform.Y=0
            }
        }
        & $RenderAction
        if(-not $Global:GlowTreeCleared){ Disable-LessProjectGlow }
    } catch { try { & $RenderAction } catch {} }
}
function Show-ToolsView {
    param([string]$ViewName,$ActiveTab)
    if($DashboardPanel){$DashboardPanel.Visibility=[System.Windows.Visibility]::Collapsed}
    if($SettingsPanel){$SettingsPanel.Visibility=[System.Windows.Visibility]::Collapsed}
    if($GalaxyTimer){$GalaxyTimer.Stop()}; if($Global:PerformanceTimer){$Global:PerformanceTimer.Stop()}
    # Apply is intentionally available from the Dashboard card only.
    if($BtnRun){ $BtnRun.Visibility=[System.Windows.Visibility]::Collapsed }
    Set-MainMenuActive "TOOLS"
    Set-ToolsSubTabActive $ActiveTab
    $Global:ActiveToolsView=$ViewName
    if($CategoryOverlay){ $CategoryOverlay.Visibility=[System.Windows.Visibility]::Visible; $CategoryOverlay.Opacity=1 }
    Start-PremiumViewTransition { Show-CategoryDetail $ViewName }
}
