function Run-FiveMPerfOptions{
    Set-CurrentTask "FiveM processes -> CpuPriorityClass 2 (Normal baseline)"
    $applied=0
    foreach($exeName in @(Get-FiveMExecutableNames)){
        $p="HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$exeName\PerfOptions"
        Save-Orig ("GM_FiveMPerfOptions::$exeName") $p "CpuPriorityClass"
        Set-RegValue $p "CpuPriorityClass" 2|Out-Null
        $applied++
    }
    Add-Log ("FiveM CpuPriorityClass set to 2 (Normal baseline) via IFEO for {0} executable name(s); dynamic boost is load-aware" -f $applied) "#FFFFFF"
    $Global:AppliedKeys["GM_FiveMPerfOptions"]=$true
}
function Run-FiveMCoreAffinity{
    Set-CurrentTask "FiveM Core Affinity -> Auto-Optimized"
    try{
        $logical=[Environment]::ProcessorCount
        if($logical -le 2){
            Add-Log "Only $logical logical cores detected - skipping affinity change (not enough cores to spare)" "#FFFFFF"
            $Global:AppliedKeys["GM_FiveMCoreAffinity"]=$true
            return
        }
        # Leave core 0 for system/DPC work; use every remaining logical processor.
        [uint64]$mask=0
        for($i=1;$i -lt $logical -and $i -lt 64;$i++){ $mask=$mask -bor ([uint64]1 -shl $i) }
        $procs=@(Get-FiveMGameProcesses)
        if($procs.Count -gt 0){
            foreach($proc in $procs){
                try{ $proc.ProcessorAffinity=[IntPtr]$mask; Add-Log "$($proc.ProcessName) affinity set to cores 1-$($logical-1) (mask 0x$($mask.ToString('X')))" "#FFFFFF" }catch{ Add-Log "Could not set affinity for $($proc.ProcessName): $_" "#D8D8D8" }
            }
        } else {
            Add-Log "FiveM game process not running yet - will auto-apply as soon as it starts (watching for 10 min)" "#FFFFFF"
            $affinityJob = Start-Job -ScriptBlock {
                param($mask)
                $deadline=(Get-Date).AddMinutes(10)
                while((Get-Date) -lt $deadline){
                    $proc=Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -like '*GTAProcess*' -or $_.ProcessName -like 'FiveM_*' } | Select-Object -First 1
                    if($proc){ try{ $proc.ProcessorAffinity=[IntPtr]$mask }catch{}; break }
                    Start-Sleep -Seconds 5
                }
            } -ArgumentList $mask
            if(-not $Global:BackgroundJobs){ $Global:BackgroundJobs=[System.Collections.ArrayList]::new() }
            [void]$Global:BackgroundJobs.Add($affinityJob)
        }
        $Global:AppliedKeys["GM_FiveMCoreAffinity"]=$true
    } catch { Add-Log "FiveM core affinity error: $_" "#D8D8D8" }
}
function Run-KillerFix{
    Set-CurrentTask "Killer NIC Traffic Analysis -> Disabled"
    try{
        # Only ever touch user-mode "smart traffic" services (Win32OwnProcess/Win32ShareProcess),
        # never a Kernel/FileSystem driver - that keeps the actual NIC driver completely untouched
        # so the adapter itself can never be broken by this tweak.
        $killerSvcs=Get-CimInstance Win32_Service -Filter "Name LIKE '%Killer%'" -EA SilentlyContinue | Where-Object { $_.ServiceType -notmatch "Kernel|FileSystem" }
        if($killerSvcs){
            foreach($svc in $killerSvcs){
                Save-OrigService "NET_KillerFix_$($svc.Name)" $svc.Name
                Stop-Service -Name $svc.Name -Force -EA SilentlyContinue
                Set-Service -Name $svc.Name -StartupType Disabled -EA SilentlyContinue
                Add-Log "Killer service disabled: $($svc.DisplayName)" "#FFFFFF"
            }
        } else {
            Add-Log "No Killer NIC detected - skipped" "#A0A0A0"
        }
        $Global:AppliedKeys["NET_KillerFix"]=$true
    } catch { Add-Log "Killer NIC check failed: $_" "#D8D8D8" }
}
function Run-FiveMQos{
    Set-CurrentTask "FiveM Traffic -> QoS Priority Tag"
    try{
        # Windows only applies DSCP tagging on domain networks by default - this flips that on
        # for home/private networks too. It only permits tagging, it never blocks or throttles.
        $p="HKLM:\SOFTWARE\Policies\Microsoft\Windows\QoS"
        Save-Orig "NET_FiveMQos_NLA" $p "DoNotUseNLA"
        Set-RegValue $p "DoNotUseNLA" 1|Out-Null

        $created=@()
        foreach($procName in @(Get-FiveMExecutableNames)){
            $polName="LessProject FiveM Priority - $procName"
            try{
                Get-NetQosPolicy -Name $polName -EA SilentlyContinue | Remove-NetQosPolicy -Confirm:$false -EA SilentlyContinue
                New-NetQosPolicy -Name $polName -AppPathNameMatchCondition $procName -DSCPAction 46 -NetworkProfile All -EA Stop | Out-Null
                $created+=$polName
                Add-Log "QoS priority tag applied: $procName" "#FFFFFF"
            } catch { Add-Log "QoS policy for $procName skipped: $_" "#FFFFFF" }
        }
        if($created.Count -gt 0){ $Global:OrigMisc["NET_FiveMQos_Policies"]=@{Type="NetQosPolicy";Names=@($created)} }
        $Global:AppliedKeys["NET_FiveMQos"]=$true
    } catch { Add-Log "FiveM QoS setup failed: $_" "#D8D8D8" }
}
function Run-FiveMFirewall{
    Set-CurrentTask "FiveM -> Explicit Firewall Allow Rule"
    try{
        $paths=@(Get-FiveMExecutablePaths)
        if($paths.Count -eq 0){
            Add-Log "FiveM executable not found - firewall rule skipped" "#FFFFFF"
            $Global:AppliedKeys["NET_FiveMFirewall"]=$true
            return
        }
        $created=@()
        $seenPaths=@{}
        foreach($path in $paths){
            if(-not $path -or $seenPaths.ContainsKey($path)){ continue }
            $seenPaths[$path]=$true
            $procLeaf=[IO.Path]::GetFileNameWithoutExtension($path)
            $ruleName="LessProject - FiveM Allow ($procLeaf)"
            if(-not (Get-NetFirewallRule -DisplayName $ruleName -EA SilentlyContinue)){
                try{
                    New-NetFirewallRule -DisplayName $ruleName -Direction Inbound -Action Allow -Program $path -Profile Any -EA Stop | Out-Null
                    New-NetFirewallRule -DisplayName "$ruleName (Out)" -Direction Outbound -Action Allow -Program $path -Profile Any -EA Stop | Out-Null
                    $created+=$ruleName; $created+="$ruleName (Out)"
                    Add-Log "Firewall allow rule added: $procLeaf" "#FFFFFF"
                } catch { Add-Log "Firewall rule for $procLeaf skipped: $_" "#FFFFFF" }
            }
        }
        if($created.Count -gt 0){ $Global:OrigMisc["NET_FiveMFirewall_Rules"]=@{Type="FirewallRule";Names=@($created)} }
        $Global:AppliedKeys["NET_FiveMFirewall"]=$true
    } catch { Add-Log "FiveM firewall rule failed: $_" "#D8D8D8" }
}
function Run-DriverHealth{Set-CurrentTask "Driver Health Check";try{$bad=Get-CimInstance Win32_PnPEntity -EA SilentlyContinue|Where-Object{$_.ConfigManagerErrorCode -ne 0};if($bad){foreach($d in $bad){Add-Log "Problem: $($d.Name)" "#D8D8D8"}}else{Add-Log "All drivers OK" "#FFFFFF"};$Global:AppliedKeys["DriverHealth"]=$true}catch{Add-Log "Driver check skipped" "#FFFFFF"}}
function Get-AdapterNumericMaximum {
    param([object]$Property)
    $numbers=@()
    foreach($v in @($Property.DisplayValueTable)){
        $s=[string]$v
        if($s -match "(?<![0-9])(\d+)(?![0-9])"){
            try{ $numbers += [int64]$matches[1] }catch{}
        }
    }
    if($numbers.Count -gt 0){ return [string](($numbers | Measure-Object -Maximum).Maximum) }
    return $null
}
function Run-NicBuffers{
    Set-CurrentTask "NIC Receive/Transmit Buffers -> Maximum"
    try{
        $adapters=@(Get-NetAdapter -Physical -EA SilentlyContinue | Where-Object {$_.Status -eq "Up"})
        $changed=0
        foreach($adapter in $adapters){
            $props=@(Get-NetAdapterAdvancedProperty -Name $adapter.Name -EA SilentlyContinue | Where-Object {$_.DisplayName -match "Receive Buffers|Transmit Buffers|Receive Buffer|Transmit Buffer"})
            foreach($prop in $props){
                $maxValue=Get-AdapterNumericMaximum $prop
                $values=@()
                if($maxValue){ $values+=$maxValue }
                $values+="Maximum"; $values+="Max"
                if(Set-ExtendedAdapterProperty "NET_NicBuffers" $adapter $prop $values){ $changed++ }
            }
        }
        Add-Log "NIC buffer maximum requested on $changed adapter setting(s) (unsupported values skipped)" "#FFFFFF"
        $Global:AppliedKeys["NET_NicBuffers"]=$true
    } catch { Add-Log "NIC buffer profile skipped: $($_.Exception.Message)" "#D8D8D8" }
}
function Run-NetworkSpeedTest{
    Set-CurrentTask "Network Speed Test -> Ping / Download / Upload"
    try{
        $pingMs=$null
        try{
            $reply=Test-Connection -ComputerName "1.1.1.1" -Count 3 -ErrorAction Stop | Measure-Object -Property ResponseTime -Average
            if($reply.Average){$pingMs=[math]::Round([double]$reply.Average,1)}
        }catch{}
        $downloadMbps=$null
        try{
            $uri="https://speed.cloudflare.com/__down?bytes=10000000"
            $sw=[Diagnostics.Stopwatch]::StartNew()
            $response=Invoke-WebRequest -Uri $uri -UseBasicParsing -TimeoutSec 30 -ErrorAction Stop
            $sw.Stop()
            $bytes=if($response.RawContentLength -gt 0){[double]$response.RawContentLength}else{[double]([Text.Encoding]::UTF8.GetByteCount([string]$response.Content))}
            if($sw.Elapsed.TotalSeconds -gt 0){$downloadMbps=[math]::Round(($bytes*8/1MB)/$sw.Elapsed.TotalSeconds,2)}
        }catch{}
        $uploadMbps=$null
        try{
            $payload=New-Object byte[] (2MB)
            (New-Object System.Random).NextBytes($payload)
            $sw=[Diagnostics.Stopwatch]::StartNew()
            Invoke-WebRequest -Uri "https://speed.cloudflare.com/__up" -Method Post -Body $payload -ContentType "application/octet-stream" -TimeoutSec 30 -UseBasicParsing -ErrorAction Stop | Out-Null
            $sw.Stop()
            if($sw.Elapsed.TotalSeconds -gt 0){$uploadMbps=[math]::Round(($payload.Length*8/1MB)/$sw.Elapsed.TotalSeconds,2)}
        }catch{}
        $pingText=if($null -ne $pingMs){"{0} ms" -f $pingMs}else{"N/A"}
        $downText=if($null -ne $downloadMbps){"{0} Mbps" -f $downloadMbps}else{"N/A"}
        $upText=if($null -ne $uploadMbps){"{0} Mbps" -f $uploadMbps}else{"N/A"}
        Add-Log ("SPEED TEST RESULT: Ping={0}; Download={1}; Upload={2}" -f $pingText,$downText,$upText) "#FFFFFF"
        $Global:AppliedKeys["NET_SpeedTest"]=$true
    } catch { Add-Log "Speed Test failed: $($_.Exception.Message)" "#D8D8D8" }
}
function Run-ReleaseRenewIp{
    Set-CurrentTask "Release / Renew IP Address"
    try{
        $release=@(ipconfig /release 2>&1);$releaseCode=[int]$LASTEXITCODE
        foreach($line in $release){if(-not [string]::IsNullOrWhiteSpace([string]$line)){Add-Log ("[Release IP] " + [string]$line) "#A0A0A0"}}
        $renew=@(ipconfig /renew 2>&1);$renewCode=[int]$LASTEXITCODE
        foreach($line in $renew){if(-not [string]::IsNullOrWhiteSpace([string]$line)){Add-Log ("[Renew IP] " + [string]$line) "#A0A0A0"}}
        if($releaseCode -eq 0 -and $renewCode -eq 0){Add-Log "IP address released and renewed successfully" "#FFFFFF";return $true}
        Add-Log ("IP release/renew completed with errors (release={0}, renew={1})" -f $releaseCode,$renewCode) "#D8D8D8";return $false
    }catch{Add-Log ("IP release/renew failed: " + $_.Exception.Message) "#D8D8D8";return $false}
}
