function Run-NetworkProfile{
    param([ValidateSet("FAST","LOW LATENCY")][string]$Mode,[ValidateSet("LAN","WI-FI")][string]$Target)
    Set-CurrentTask ("{0} Network Profile -> {1}" -f $Mode,$Target)
    try{
        $adapters=@(Get-NetAdapter -Physical -EA SilentlyContinue | Where-Object {
            $_.Status -eq "Up" -and $(if($Target -eq "LAN"){$_.InterfaceDescription -notmatch "Wi-Fi|Wireless"}else{$_.InterfaceDescription -match "Wi-Fi|Wireless"})
        })
        $changed=0; $checked=0
        foreach($adapter in $adapters){
            $checked++
            try{ Disable-NetAdapterPowerManagement -Name $adapter.Name -EA SilentlyContinue }catch{}
            try{ Enable-NetAdapterRss -Name $adapter.Name -EA SilentlyContinue }catch{}
            $props=@(Get-NetAdapterAdvancedProperty -Name $adapter.Name -EA SilentlyContinue)
            foreach($prop in $props){
                $values=$null
                if($Mode -eq "LOW LATENCY" -and $prop.DisplayName -match 'Interrupt Moderation'){$values=@('Disabled','Off')}
                elseif($prop.DisplayName -match 'Energy[- ]Efficient Ethernet|Green Ethernet|Power Saving|Power Management'){$values=@('Disabled','Off')}
                elseif($prop.DisplayName -match 'TCP Checksum Offload|UDP Checksum Offload|IPv4 Checksum Offload|Checksum Offload'){$values=@('Rx & Tx Enabled','Enabled','On')}
                elseif($prop.DisplayName -match 'Receive Side Scaling|RSS'){$values=@('Enabled','On')}
                if($values -and (Set-ExtendedAdapterProperty ("NET_{0}_{1}" -f $Mode,$Target) $adapter $prop $values)){$changed++}
            }
        }
        Add-Log ("{0} {1} profile applied: {2} active adapter(s), {3} setting(s) changed; unsupported values skipped" -f $Mode,$Target,$checked,$changed) '#FFFFFF'
    } catch { Add-Log ("{0} {1} profile failed: {2}" -f $Mode,$Target,$_.Exception.Message) '#D8D8D8' }
}
function Run-FastLan{ Run-NetworkProfile -Mode "FAST" -Target "LAN" }
function Run-LowLatencyLan{ Run-NetworkProfile -Mode "LOW LATENCY" -Target "LAN" }
function Run-FastWifi{ Run-NetworkProfile -Mode "FAST" -Target "WI-FI" }
function Run-LowLatencyWifi{ Run-NetworkProfile -Mode "LOW LATENCY" -Target "WI-FI" }
function Run-NetworkAdaptersOptimizer{
    Set-CurrentTask "Network Adapters Optimizer -> RSS / Offload / Low Latency"
    try{
        $adapters=@(Get-NetAdapter -Physical -EA SilentlyContinue | Where-Object {$_.Status -eq "Up"})
        $changed=0; $checked=0
        foreach($adapter in $adapters){
            $checked++
            try{ Disable-NetAdapterPowerManagement -Name $adapter.Name -EA SilentlyContinue }catch{}
            try{ Enable-NetAdapterRss -Name $adapter.Name -EA SilentlyContinue }catch{}
            $props=@(Get-NetAdapterAdvancedProperty -Name $adapter.Name -EA SilentlyContinue)
            foreach($prop in $props){
                $values=$null
                if($prop.DisplayName -match 'Interrupt Moderation|Energy[- ]Efficient Ethernet|Green Ethernet|Power Saving|Power Management'){
                    $values=@('Disabled','Off')
                } elseif($prop.DisplayName -match 'TCP Checksum Offload|UDP Checksum Offload|IPv4 Checksum Offload|Checksum Offload'){
                    $values=@('Rx & Tx Enabled','Enabled','On')
                } elseif($prop.DisplayName -match 'Receive Side Scaling|RSS'){
                    $values=@('Enabled','On')
                }
                if($values -and (Set-ExtendedAdapterProperty 'NET_AdaptersOptimizer' $adapter $prop $values)){$changed++}
            }
        }
        Add-Log ("Network Adapters Optimizer applied: {0} active adapter(s), {1} setting(s) changed; unsupported values skipped" -f $checked,$changed) '#FFFFFF'
        $Global:AppliedKeys['NET_AdaptersOptimizer']=$true
    } catch { Add-Log "Network Adapters Optimizer skipped: $($_.Exception.Message)" '#D8D8D8' }
}
function Run-LanOptimize{
    Set-CurrentTask "LAN Performance Profile -> RSS + Offload"
    try{
        $ecnMode=if($Global:TweakToggles["NET_ECN"]){"disabled"}else{"enabled"}
        $baseOutput=& netsh int tcp set global autotuninglevel=normal rss=enabled ecncapability=$ecnMode fastopen=enabled fastopenfallback=enabled congestionprovider=ctcp 2>&1
        if($LASTEXITCODE -ne 0){ throw "netsh returned exit code $LASTEXITCODE" }
        & netsh int tcp set global rsc=enabled 2>&1 | Out-Null
        $adapters=@(Get-NetAdapter -Physical -EA SilentlyContinue | Where-Object {$_.Status -eq "Up" -and $_.InterfaceDescription -notmatch "Wi-Fi|Wireless"})
        $rssCount=0; $offloadCount=0
        foreach($adapter in $adapters){
            try{ Enable-NetAdapterRss -Name $adapter.Name -EA Stop; $rssCount++ }catch{}
            $props=@(Get-NetAdapterAdvancedProperty -Name $adapter.Name -EA SilentlyContinue | Where-Object {$_.DisplayName -match "TCP Checksum Offload|UDP Checksum Offload|IPv4 Checksum Offload|Checksum Offload"})
            foreach($prop in $props){
                if(Set-ExtendedAdapterProperty "LanOptimize" $adapter $prop @("Rx & Tx Enabled","Enabled","On")){ $offloadCount++ }
            }
        }
        Add-Log "LAN profile applied: TCP/RSS enabled, RSS on $rssCount adapter(s), checksum offload on $offloadCount setting(s)" "#FFFFFF"
        $Global:AppliedKeys["LanOptimize"]=$true
    } catch { Add-Log "LAN optimize failed: $_" "#D8D8D8" }
}
