function Run-WifiSpeedDuplex{Run-NetworkSpeedDuplex "WI-FI"}
function Run-DnsFastLan{
    Set-CurrentTask "DNS -> Auto Best (LAN)"
    try{
        $la=Get-NetAdapter -EA SilentlyContinue | Where-Object {$_.Status -eq "Up" -and $_.InterfaceDescription -notmatch "Wi-Fi|Wireless"}
        $pair=Get-BestDnsPair
        $count=0
        foreach($a in $la){
            $old=@(Get-DnsClientServerAddress -InterfaceIndex $a.IfIndex -AddressFamily IPv4 -EA SilentlyContinue | Select-Object -ExpandProperty ServerAddresses)
            $Global:OrigMisc["DNS::LAN::$($a.IfIndex)"]=@{Type="DnsServerAddresses";InterfaceIndex=[int]$a.IfIndex;AddressFamily=2;ServerAddresses=@($old);Reset=($old.Count -eq 0)}
            try{ Set-DnsClientServerAddress -InterfaceIndex $a.IfIndex -AddressFamily IPv4 -ServerAddresses @($pair.Primary,$pair.Secondary) -EA Stop; $count++ }catch{}
        }
        $probeText=if($pair.Milliseconds -ge 0){" ($($pair.Milliseconds) ms probe)"}else{""}
        if($count -gt 0){ Add-Log ("LAN DNS auto-selected $($pair.Name): $($pair.Primary) / $($pair.Secondary)$probeText on $count adapter(s)") "#FFFFFF" } else { Add-Log "No wired adapter detected - skipped" "#A0A0A0" }
        $Global:AppliedKeys["NET_DnsFast"]=$true
    } catch { Add-Log "DNS tweak (LAN) skipped" "#FFFFFF" }
}
