            Add-Log "FiveM cache cleared" "#FFFFFF"
        } else { Add-Log "FiveM cache folder not found - skipped" "#A0A0A0" }
        $Global:AppliedKeys["CLEAN_ClearFiveMCache"]=$true
    } catch { Add-Log "FiveM cache clear skipped (files in use)" "#FFFFFF" }
}
function Run-RemoveBloat{
    Set-CurrentTask "Remove Unnecessary Pre-Installed Apps"
    $bloatList=$Global:BloatList
    $removed=0; $skipped=0; $removedNames=@()
    # One enumeration of all installed packages instead of calling Get-AppxPackage once per
    # name in $bloatList (~30 separate full-repository queries) - much faster, same result.
    $allPkgs = @(Get-AppxPackage -EA SilentlyContinue)
    foreach($name in $bloatList){
        try{
            $pkgs=$allPkgs | Where-Object { $_.Name -eq $name }
            if($pkgs){
                $pkgs | Remove-AppxPackage -EA SilentlyContinue
                $removed++; $removedNames+=$name
            } else { $skipped++ }
        } catch { $skipped++ }
    }
    if($removedNames.Count -gt 0){ $Global:OrigMisc["CLEAN_RemoveBloat"]=$removedNames }
    Add-Log "Pre-installed app cleanup: $removed app(s) removed, $skipped not found/skipped" "#FFFFFF"
    $Global:AppliedKeys["CLEAN_RemoveBloat"]=$true
}
function Run-KillBackgroundProcesses{
    Set-CurrentTask "Non-Essential Processes and Services -> Closed"
    # Curated process list: no shell, driver, security, FiveM, or messenger executables.
    $procList=@($Global:KillProcList | Where-Object { -not (Test-ProtectedMessengerText $_) } | Select-Object -Unique)
    $closed=0; $notRunning=0; $protectedSkipped=0
    foreach($name in $procList){
        try{
            $procs=@(Get-Process -Name $name -EA Ignore)
            if(-not $procs -or $procs.Count -eq 0){ $notRunning++; continue }
            foreach($proc in $procs){
                if(Test-ProtectedMessengerProcess $proc){ $protectedSkipped++; continue }
                Stop-Process -Id $proc.Id -Force -EA SilentlyContinue
                $closed++
            }
        } catch { }
    }

    # Services are handled separately from processes. Save the original startup mode
    # and running state so Restore Defaults can put each service back.
    $serviceList=@($Global:KillServiceList | Where-Object { -not (Test-ProtectedMessengerText $_) } | Select-Object -Unique)
    $servicesChanged=0; $servicesNotFound=0; $serviceFailures=0
    foreach($name in $serviceList){
        try{
            if(Test-ProtectedMessengerText $name){ $protectedSkipped++; continue }
            $svc=Get-Service -Name $name -EA Stop
            if($svc){
                if((Test-ProtectedMessengerText ([string]$svc.Name)) -or (Test-ProtectedMessengerText ([string]$svc.DisplayName))){ $protectedSkipped++; continue }
                Save-OrigService "CLEAN_KillBackgroundSvc::$name" $name
                if($svc.Status -eq "Running") { Stop-Service -Name $name -Force -EA Stop }
                Set-Service -Name $name -StartupType Disabled -EA Stop
                $servicesChanged++
            }
        } catch {
            if($_.Exception.Message -match "Cannot find|not found|does not exist|No service") { $servicesNotFound++ } else { $serviceFailures++ }
        }
    }
    Add-Log "Background cleanup: $closed process(es) closed, $notRunning process(es) not running" "#FFFFFF"
    Add-Log "Service cleanup: $servicesChanged service(s) stopped/disabled, $servicesNotFound not installed, $serviceFailures failed (admin or protected)" "#FFFFFF"
    if($protectedSkipped -gt 0){ Add-Log "Protected messenger apps (LINE and similar) were left running: $protectedSkipped skip(s)" "#FFFFFF" }
    $Global:AppliedKeys["CLEAN_KillBackgroundProcs"]=$true
}
function Run-DisableLauncherStartup{
    Set-CurrentTask "Game Launchers & Chat Apps -> Startup Disabled"
    # Matches by substring against the value NAME (usually the app's own registered name) so it catches
    # "Steam", "Discord", "EpicGamesLauncher", "Battle.net", "Origin", "Ubisoft Connect", "RiotClientServices", "GOG Galaxy", "Spotify".
    $targets=$Global:StartupDisableTargets
    $runPaths=@(
        "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run",
        "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run",
        "HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run"
    )
    $backup=@(); $removed=0
    foreach($rp in $runPaths){
        try{
            if(-not (Test-Path $rp)){ continue }
            $props=Get-ItemProperty -Path $rp -EA SilentlyContinue
            if(-not $props){ continue }
            foreach($name in $props.PSObject.Properties.Name){
                if($name -in @("PSPath","PSParentPath","PSChildName","PSDrive","PSProvider")){ continue }
                if(Test-ProtectedMessengerText $name){ continue }
                try { if($props.$name -and (Test-ProtectedMessengerText ([string]$props.$name))){ continue } } catch {}
                foreach($t in $targets){
                    if(Test-ProtectedMessengerText $t){ continue }
                    if($name -match [regex]::Escape($t)){
                        $val=$props.$name
                        $backup += @{Path=$rp;Name=$name;Value=$val}
                        try{
                            Remove-ItemProperty -Path $rp -Name $name -EA Stop
                            $removed++
                            Add-Log "Startup entry disabled: $name" "#FFFFFF"
                        } catch { Add-Log "Could not remove startup entry $name (may need admin on HKLM): $_" "#FFFFFF" }
                        break
                    }
                }
            }
        } catch {}
    }
    if($backup.Count -gt 0){ $Global:OrigMisc["CLEAN_DisableLauncherStartup"]=@{Type="StartupEntries";Entries=@($backup)} }
    if($removed -gt 0){ Add-Log "Startup cleanup: $removed launcher/chat app(s) will no longer auto-start" "#FFFFFF" }
    else { Add-Log "No matching startup entries found (nothing to disable)" "#A0A0A0" }
    $Global:AppliedKeys["CLEAN_DisableLauncherStartup"]=$true
}
function Run-DnsFastWifi{
