function Run-NoNagle{
    param($ToggleKey)
    Set-CurrentTask "Nagle's Algorithm -> Disabled"
    try{
        Invoke-DedupedGlobalTweak "NET_NoNagle" $ToggleKey {
            $ifRoot="HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces"
            # Only touch GUIDs belonging to physical adapters that are currently Up.
            # This avoids changing stale VPN/virtual interface profiles and reduces the
            # chance of altering a tunnel or an inactive connection unintentionally.
            $upGuids=@(Get-NetAdapter -Physical -EA SilentlyContinue | Where-Object {$_.Status -eq "Up" -and $_.InterfaceGuid} | ForEach-Object {[string]$_.InterfaceGuid})
            $ifaces=@(Get-ChildItem -Path $ifRoot -EA SilentlyContinue | Where-Object {$upGuids -contains [string]$_.PSChildName})
            $count=0
            foreach($i in $ifaces){
                Save-Orig "NET_NoNagle_$($i.PSChildName)_Ack" $i.PSPath "TcpAckFrequency"
                Save-Orig "NET_NoNagle_$($i.PSChildName)_Delay" $i.PSPath "TCPNoDelay"
                Set-RegValue $i.PSPath "TcpAckFrequency" 1|Out-Null
                Set-RegValue $i.PSPath "TCPNoDelay" 1|Out-Null
                $count++
            }
            Add-Log "Nagle's algorithm disabled on $count adapter(s)" "#FFFFFF"
        }
    } catch { Add-Log "Nagle disable failed" "#D8D8D8" }
}
function Run-UltimatePlan{
    Set-CurrentTask "Ultimate Performance Power Plan"
    try{
        $srcGuid="e9a42b02-d5df-448d-aa00-03f14749eb61"
        $guid=$null
        # Reuse the scheme this app created on a previous run (if it's still present) instead of
        # matching the literal English label "Ultimate Performance" - that text is localized on
        # non-English Windows installs, which made the old check silently fail and duplicate a
        # brand-new power scheme every single time this tweak ran.
        if($Global:OrigMisc.ContainsKey("PWR_UltimatePlanGuid")){
            $savedGuid=$Global:OrigMisc["PWR_UltimatePlanGuid"]
            if((powercfg /list) -match [regex]::Escape($savedGuid)){ $guid=$savedGuid }
        }
        if(-not $guid){
            $dup=powercfg /duplicatescheme $srcGuid 2>&1
            $guid=[regex]::Match($dup,"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}").Value
            if($guid){ $Global:OrigMisc["PWR_UltimatePlanGuid"]=$guid }
        }
        if($guid){
            $null=powercfg /setactive $guid 2>&1; $activateCode=$LASTEXITCODE
            $activeText=(powercfg /getactivescheme 2>&1 | Out-String)
            if($activateCode -ne 0 -or $activeText -notmatch [regex]::Escape($guid)){ throw "Power plan activation was rejected (exit=$activateCode)" }
            Add-Log "Ultimate Performance plan active and verified for this Windows installation" "#FFFFFF"
            $Global:AppliedKeys["PWR_UltimatePlan"]=$true
        } else { Add-Log "Ultimate Performance plan unavailable; kept the current supported plan" "#A0A0A0" }
    } catch { Add-Log "Ultimate Performance plan skipped: $($_.Exception.Message)" "#A0A0A0" }
}
function Run-NoCoreParking{
    Set-CurrentTask "CPU Core Parking -> Disabled"
    try{
        $null=powercfg /setacvalueindex scheme_current sub_processor 0cc5b647-c1df-4637-891a-dec35c318583 100 2>&1; $acCode=$LASTEXITCODE
        $null=powercfg /setdcvalueindex scheme_current sub_processor 0cc5b647-c1df-4637-891a-dec35c318583 100 2>&1; $dcCode=$LASTEXITCODE
        $null=powercfg /setactive scheme_current 2>&1; $activeCode=$LASTEXITCODE
        if($acCode -ne 0 -or $dcCode -ne 0 -or $activeCode -ne 0){ throw "Core parking setting unsupported or rejected (AC=$acCode DC=$dcCode ACTIVE=$activeCode)" }
        Add-Log "Core parking disabled (all supported processor cores active)" "#FFFFFF"
        $Global:AppliedKeys["SYS_NoCoreParking"]=$true
    } catch { Add-Log "Core parking skipped on this processor/power-plan: $($_.Exception.Message)" "#A0A0A0" }
}
