function Run-TimerRes{
    Set-CurrentTask "System Timer Resolution -> 0.5ms"
    try{
        if(-not ("Win32TimerResNS.Win32TimerRes" -as [type])){
            Add-Type -Namespace Win32TimerResNS -Name Win32TimerRes -MemberDefinition @"
