function Invoke-Win32PriorityProfile {
    param([string]$Profile)
    try {
        if(-not (Test-IsAdministrator)){
            if(Restart-LessProjectAsAdministrator -PendingWin32Profile $Profile){
                try { $window.Close() } catch {}
            } else {
                [System.Windows.MessageBox]::Show('Win32 Priority ต้องใช้สิทธิ์ Administrator และไม่สามารถขอสิทธิ์ได้ กรุณาคลิกขวาไฟล์แล้วเลือก Run as administrator','WIN32 PROFILE',[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Warning) | Out-Null
            }
            return $false
        }
        $map=@{
            'WINDOWS DEFAULT (0x26)'=0x26
            'GAMING RECOMMENDED (0x2E)'=0x2E
            'GAMING RECOMMENDED ALT A (0x2E)'=0x2E
            'GAMING RECOMMENDED ALT B (0x2E)'=0x2E
            'SHORT FIXED / HIGH BOOST (0x2A)'=0x2A
            'SHORT FIXED / MEDIUM BOOST (0x29)'=0x29
            'SHORT FIXED / NO BOOST (0x28)'=0x28
            'SHORT VARIABLE / HIGH BOOST (0x26)'=0x26
            'SHORT VARIABLE / MEDIUM BOOST (0x25)'=0x25
            'SHORT VARIABLE / NO BOOST (0x24)'=0x24
            'LONG FIXED / HIGH BOOST (0x1A)'=0x1A
            'LONG FIXED / MEDIUM BOOST (0x19)'=0x19
            'LONG FIXED / NO BOOST (0x18)'=0x18
            'LONG VARIABLE / HIGH BOOST (0x16)'=0x16
            'LONG VARIABLE / MEDIUM BOOST (0x15)'=0x15
            'LONG VARIABLE / NO BOOST (0x14)'=0x14
            'CUSTOM LOW INPUT LAG (0xFA332A)'=0xFA332A
            'CUSTOM HEX (0xE82A)'=0xE82A
            'CUSTOM HEX (0xFB882828)'=0xFB882828
            'CUSTOM HEX (0xFA2A2A)'=0xFA2A2A
            'CUSTOM HEX (0xFA002A)'=0xFA002A
            'CUSTOM HEX (0x0FFF987)'=0x0FFF987
            'CUSTOM HEX (0x0FB00000)'=0x0FB00000
            'CUSTOM HEX (0x02)'=0x02
        }
        if(-not $map.ContainsKey($Profile)){ throw "Unsupported Win32 profile: $Profile" }
        $win32Value=[int64]$map[$Profile]
        if($win32Value -gt 0x3F -or $win32Value -lt 0){
            Add-Log ("Win32 profile {0} uses value 0x{1:X} which Windows ignores; applying GAMING RECOMMENDED 0x2E instead." -f $Profile,$win32Value) "#D8D8D8"
            $win32Value=0x2E
        }
        $path='HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl'
        Save-Orig 'SYS_Win32Priority' $path 'Win32PrioritySeparation'
        Set-RegValue $path 'Win32PrioritySeparation' ([int]$win32Value) | Out-Null
        $verify=Get-RegValue $path 'Win32PrioritySeparation'
        if($null -eq $verify -or [int]$verify -ne [int]$win32Value){ throw "Win32PrioritySeparation verification failed for $Profile" }
        $Global:SelectedWin32Profile=$Profile
        $Global:TweakToggles['SYS_Win32Priority']=$true
        Save-TweakState
        if($Global:Win32ProfileStatus){ $Global:Win32ProfileStatus.Text="$Profile / APPLIED" }
        if($Global:Win32LiveStatus){ $Global:Win32LiveStatus.Text=('CURRENT 0x{0:X} / {0} / APPLIED' -f ([int]$map[$Profile])) }
        Add-Log "Win32 Priority Profile applied: $Profile ($([int]$map[$Profile]) decimal)" '#FFFFFF'
        Set-CurrentTask "Win32 profile applied: $Profile"
        Show-TweakToast -Label 'WIN32 PROFILE' -Enabled $true -OverrideText "$Profile / APPLIED" -DurationMs 2400
        return $true
    } catch {
        if($Global:Win32ProfileStatus){ $Global:Win32ProfileStatus.Text='APPLY FAILED / CHECK LIVE LOG' }
        Add-Log "[FAILED] Win32 Priority Profile: $($_.Exception.Message)" '#D8D8D8'
        Show-TweakToast -Label 'WIN32 PROFILE' -Enabled $false -OverrideText 'APPLY FAILED' -DurationMs 2800
        return $false
    }
}

function Run-Win32Priority{
    $profile=[string]$Global:SelectedWin32Profile
    if([string]::IsNullOrWhiteSpace($profile)){ $profile='GAMING RECOMMENDED (0x2E)' }
    Set-CurrentTask ("Win32PrioritySeparation -> {0}" -f $profile)
    try {
        $map=@{
            'WINDOWS DEFAULT (0x26)'=0x26; 'GAMING RECOMMENDED (0x2E)'=0x2E; 'GAMING RECOMMENDED ALT A (0x2E)'=0x2E; 'GAMING RECOMMENDED ALT B (0x2E)'=0x2E
            'SHORT FIXED / HIGH BOOST (0x2A)'=0x2A; 'SHORT FIXED / MEDIUM BOOST (0x29)'=0x29; 'SHORT FIXED / NO BOOST (0x28)'=0x28
            'SHORT VARIABLE / HIGH BOOST (0x26)'=0x26; 'SHORT VARIABLE / MEDIUM BOOST (0x25)'=0x25; 'SHORT VARIABLE / NO BOOST (0x24)'=0x24
            'LONG FIXED / HIGH BOOST (0x1A)'=0x1A; 'LONG FIXED / MEDIUM BOOST (0x19)'=0x19; 'LONG FIXED / NO BOOST (0x18)'=0x18
            'LONG VARIABLE / HIGH BOOST (0x16)'=0x16; 'LONG VARIABLE / MEDIUM BOOST (0x15)'=0x15; 'LONG VARIABLE / NO BOOST (0x14)'=0x14
            'CUSTOM LOW INPUT LAG (0xFA332A)'=0xFA332A; 'CUSTOM HEX (0xE82A)'=0xE82A; 'CUSTOM HEX (0xFB882828)'=0xFB882828; 'CUSTOM HEX (0xFA2A2A)'=0xFA2A2A; 'CUSTOM HEX (0xFA002A)'=0xFA002A; 'CUSTOM HEX (0x0FFF987)'=0x0FFF987; 'CUSTOM HEX (0x0FB00000)'=0x0FB00000; 'CUSTOM HEX (0x02)'=0x02
        }
        if(-not $map.ContainsKey($profile)){ $profile='GAMING RECOMMENDED (0x2E)' }
        $value=[int]$map[$profile]
        $p="HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl"
        Save-Orig "SYS_Win32Priority" $p "Win32PrioritySeparation"
        Set-RegValue $p "Win32PrioritySeparation" $value|Out-Null
        $verify=Get-RegValue $p "Win32PrioritySeparation"
        if($null -eq $verify -or [int]$verify -ne $value){ throw "Win32PrioritySeparation verification failed for $profile" }
        $Global:SelectedWin32Profile=$profile
        Add-Log ("Win32PrioritySeparation set to {0} / {1} decimal and verified" -f $profile,$value) "#FFFFFF"
        $Global:AppliedKeys["SYS_Win32Priority"]=$true
    } catch { Add-Log "Win32 profile skipped or rejected by Windows: $($_.Exception.Message)" "#A0A0A0" }
}
