}
function Run-NoBackgroundApps{
    Set-CurrentTask "UWP Background Apps -> Blocked (gpedit)"
    $p="HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppPrivacy"
    Save-Orig "SYS_NoBackgroundApps" $p "LetAppsRunInBackground"
    Set-RegValue $p "LetAppsRunInBackground" 2|Out-Null
    $allowName="LetAppsRunInBackground_ForceAllowTheseApps"
    $families=@(Get-ProtectedMessengerPackageFamilies)
    if($families.Count -gt 0){
        Save-Orig "SYS_NoBackgroundApps_ForceAllow" $p $allowName
        try { New-ItemProperty -LiteralPath $p -Name $allowName -PropertyType MultiString -Value $families -Force -EA SilentlyContinue | Out-Null } catch {}
        Add-Log ("UWP background apps force-denied; messengers allowed: " + ($families -join ", ")) "#FFFFFF"
    } else {
        Add-Log "UWP background apps force-denied; no Store messenger packages found to allow" "#FFFFFF"
    }
    Protect-MessengerBackgroundAccess
    $Global:AppliedKeys["SYS_NoBackgroundApps"]=$true
}
