$Global:RecoverySelected = "restore"
$Global:RecoveryJob = $null
$Global:RecoveryPoller = $null
$Global:RestorePointCreated = $false
function Set-RecoverySelection {
    param([string]$Key)
    if([string]::IsNullOrWhiteSpace($Key)){ return }
    $Global:RecoverySelected=$Key
    $RecoveryRun.IsEnabled=$true
    $RecoveryRun.Content = switch($Key){
        "restore" { "RESTORE SAVED SETTINGS" }
        "network" { "RUN NETWORK REPAIR" }
        "windows" { "RUN WINDOWS FILE REPAIR" }
        "services" { "RESTORE SERVICES & TASKS" }
        "power" { "RESTORE POWER / BCD" }
        "diagnostics" { "EXPORT DIAGNOSTICS" }
        default { "RUN SELECTED" }
    }
}
function Show-RecoveryCenter {
    if(-not $RecoveryOverlay){ return }
    $hasSnapshot = (($Global:Orig.Count + $Global:OrigServices.Count + $Global:OrigMisc.Count) -gt 0)
    $RecoverySnapshotText.Text = if($hasSnapshot){ "READY" } else { "EMPTY" }
    $RecoverySnapshotText.Foreground = if($hasSnapshot){ [System.Windows.Media.BrushConverter]::new().ConvertFromString("#D0D0D0") } else { [System.Windows.Media.BrushConverter]::new().ConvertFromString("#B8B8B8") }
    if($Global:RestorePointCreated){ $RecoveryRestorePointText.Text="READY"; $RecoveryRestorePointText.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#D0D0D0") }
    else { $RecoveryRestorePointText.Text="SKIPPED"; $RecoveryRestorePointText.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#B8B8B8") }
    $RecoveryOverlay.Visibility="Visible"
    Set-RecoverySelection "restore"
    Set-CurrentTask "Recovery Center ready. Select a repair tool."
}
function Close-RecoveryCenter {
    if($RecoveryOverlay){ $RecoveryOverlay.Visibility="Collapsed" }
}
function Start-RecoveryJobAsync {
    param([string]$Title,[scriptblock]$Script,[object[]]$ArgumentList=@(),[int]$TimeoutSeconds=900)
    if($Global:RecoveryJob -and $Global:RecoveryJob.State -eq 'Running'){ Add-Log "A recovery task is already running." "#FFFFFF"; return }
    $RecoveryRun.IsEnabled=$false; $RecoveryClose.IsEnabled=$false; $RecoveryCloseX.IsEnabled=$false
    Set-StatusRunning; Set-CurrentTask "Running recovery: $Title..."; Add-Log "[RUNNING] Recovery: $Title" "#FFFFFF"
    if($ArgumentList -and $ArgumentList.Count -gt 0){ $Global:RecoveryJob=Start-Job -ArgumentList $ArgumentList -ScriptBlock $Script }
    else { $Global:RecoveryJob=Start-Job -ScriptBlock $Script }
    $Global:RecoveryStartedUtc=[DateTime]::UtcNow
    $Global:RecoveryPoller=New-Object System.Windows.Threading.DispatcherTimer
    $Global:RecoveryPoller.Interval=[TimeSpan]::FromMilliseconds(350)
    $Global:RecoveryPoller.Add_Tick({
        if(-not $Global:RecoveryJob){ return }
        $age=([DateTime]::UtcNow-$Global:RecoveryStartedUtc).TotalSeconds
        if($Global:RecoveryJob.State -eq 'Running' -and $age -lt $Global:RecoveryTimeoutSeconds){ return }
        $Global:RecoveryPoller.Stop()
        $timedOut=($Global:RecoveryJob.State -eq 'Running')
        if($timedOut){ Stop-Job $Global:RecoveryJob -EA SilentlyContinue; Add-Log "[TIMEOUT] Recovery: $Title exceeded $($Global:RecoveryTimeoutSeconds)s." "#D8D8D8"; Set-CurrentTask "Recovery timed out. Check Live Log."; Set-StatusIssues }
        else {
            $result=@(Receive-Job $Global:RecoveryJob -Wait -AutoRemoveJob -EA SilentlyContinue)
            foreach($line in $result){ if($null -ne $line -and -not [string]::IsNullOrWhiteSpace([string]$line)){ Add-Log ([string]$line) "#888888" } }
            $failed=($Global:RecoveryJob.ChildJobs[0].JobStateInfo.State -eq 'Failed')
            if($failed){ Add-Log "[FAILED] Recovery: $Title" "#D8D8D8"; Set-CurrentTask "Recovery failed. Check Live Log."; Set-StatusIssues }
            else { Add-Log "[APPLIED] Recovery: $Title" "#FFFFFF"; Set-CurrentTask "Recovery complete. Restart Windows if requested."; Set-StatusDone }
        }
        Remove-Job $Global:RecoveryJob -Force -EA SilentlyContinue; $Global:RecoveryJob=$null
        $RecoveryRun.IsEnabled=$true; $RecoveryClose.IsEnabled=$true; $RecoveryCloseX.IsEnabled=$true
    }.GetNewClosure())
    $Global:RecoveryTimeoutSeconds=$TimeoutSeconds
    $Global:RecoveryPoller.Start()
}
function Export-RecoveryDiagnosticsAsync {
    $snapshot=@($Global:LogLines | ForEach-Object { [string]$_ })
    $diagScript={
        param($stateDir,$logLines,$os,$cpu,$gpu,$adapter)
        try {
            $reportDir=Join-Path $stateDir "Reports"; New-Item -ItemType Directory -Path $reportDir -Force | Out-Null
            $file=Join-Path $reportDir ("LessProject-Diagnostics-{0}.txt" -f (Get-Date -Format "yyyyMMdd-HHmmss"))
            $lines=@("LESS PROJECT DIAGNOSTICS","Generated: $(Get-Date -Format o)","OS: $os","CPU: $cpu","GPU: $gpu","Adapter: $adapter","","LIVE LOG") + @($logLines)
            $lines | Set-Content -LiteralPath $file -Encoding UTF8
            "Diagnostics report saved: $file"
        } catch { "Diagnostics export failed: $($_.Exception.Message)" }
    }
    Start-RecoveryJobAsync "Export diagnostics" $diagScript @($Global:StateDir,(,$snapshot),$Global:SysInfo.OS,$Global:SysInfo.CPU,$Global:SysInfo.GPU,$Global:SysInfo.Adapter) 60
}
function Invoke-RecoverySelection {
    switch([string]$Global:RecoverySelected){
        "restore" { Close-RecoveryCenter; Start-RestoreDefaultsAsync -Scope 'all'; return }
        "services" { Close-RecoveryCenter; Add-Log "Restoring tracked services..." "#FFFFFF"; Start-RestoreDefaultsAsync -Scope 'services'; return }
        "power" { Close-RecoveryCenter; Add-Log "Restoring tracked power and boot values..." "#FFFFFF"; Start-RestoreDefaultsAsync -Scope 'power'; return }
        "network" {
            $networkScript={
                $ErrorActionPreference="Continue"
                "Resetting Winsock..."; & netsh.exe winsock reset 2>&1 | ForEach-Object { [string]$_ }
                "Resetting TCP/IP..."; & netsh.exe int ip reset 2>&1 | ForEach-Object { [string]$_ }
                "Flushing DNS cache..."; & ipconfig.exe /flushdns 2>&1 | ForEach-Object { [string]$_ }
                "Network repair finished. A restart may be required."
            }
            Start-RecoveryJobAsync "Network repair" $networkScript @() 180; return
        }
        "windows" {
            $windowsScript={
                $ErrorActionPreference="Continue"
                "Checking Windows component store (DISM)..."; & DISM.exe /Online /Cleanup-Image /RestoreHealth 2>&1 | ForEach-Object { [string]$_ }
                "Checking protected system files (SFC)..."; & sfc.exe /scannow 2>&1 | ForEach-Object { [string]$_ }
                "Windows file repair finished. Review the output above."
            }
            Start-RecoveryJobAsync "Windows file repair" $windowsScript @() 1800; return
        }
        "diagnostics" { Export-RecoveryDiagnosticsAsync; return }
    }
}
foreach($recoveryButton in @($RecoveryRestore,$RecoveryNetwork,$RecoveryWindows,$RecoveryServices,$RecoveryPower,$RecoveryDiagnostics)){
    if($recoveryButton){ $recoveryButton.Add_Click({ param($sender,$args); Set-RecoverySelection ([string]$sender.Tag) }.GetNewClosure()) }
}
$RecoveryCloseX.Add_Click({ Close-RecoveryCenter })
$RecoveryClose.Add_Click({ Close-RecoveryCenter })
$RecoveryRun.Add_Click({ Invoke-RecoverySelection })

function Start-CreateRestorePointAsync {
    if($Global:RestorePointJob -and $Global:RestorePointJob.State -eq 'Running'){ return }
    $BtnCreateRestore.IsEnabled=$false; Set-CurrentTask "Creating a Windows restore point..."
    Add-Log "Creating System Restore Point in the background..." "#C2C2C2"
    $Global:RestorePointJob=Start-Job -ScriptBlock {
        try {
            Enable-ComputerRestore -Drive "$env:SystemDrive\" -EA SilentlyContinue
            Checkpoint-Computer -Description "LESS PROJECT - manual restore point" -RestorePointType "MODIFY_SETTINGS" -EA Stop
            'Restore point created successfully.'
        } catch { "Restore point failed: $_" }
    }
    $Global:RestorePointPoller=New-Object System.Windows.Threading.DispatcherTimer
    $Global:RestorePointPoller.Interval=[TimeSpan]::FromMilliseconds(300)
    $Global:RestorePointPoller.Add_Tick({
        if($Global:RestorePointJob.State -eq 'Running'){ return }
        $Global:RestorePointPoller.Stop(); $result=Receive-Job $Global:RestorePointJob -Wait -AutoRemoveJob -EA SilentlyContinue
        $restoreText=($result -join ' '); Add-Log $restoreText "#FFFFFF"; if($restoreText -notmatch 'failed|error'){ $Global:RestorePointCreated=$true; Update-DashboardStatusPanel }; Set-CurrentTask "Restore point task finished."; $BtnCreateRestore.IsEnabled=$true
    }.GetNewClosure())
    $Global:RestorePointPoller.Start()
}
function Start-RestoreDefaultsAsync {
    param([ValidateSet('all','services','power')][string]$Scope='all')
    if($Global:RestoreDefaultsJob -and $Global:RestoreDefaultsJob.State -eq 'Running'){ return }
    if($Global:Orig.Count -eq 0 -and $Global:OrigServices.Count -eq 0 -and $Global:OrigMisc.Count -eq 0){ Add-Log "No saved settings are available to restore." "#C5C5C5"; return }
    $answer=[System.Windows.MessageBox]::Show("Restore the saved registry and service settings from the first profile snapshot?`n`nApp removals and cache cleanup cannot be undone.","LESS PROJECT - Restore Defaults",[System.Windows.MessageBoxButton]::YesNo,[System.Windows.MessageBoxImage]::Warning)
    if($answer -ne [System.Windows.MessageBoxResult]::Yes){ return }
    try { Stop-RealtimeBoostController -Restore $true } catch {}
    $Global:TweakToggles["FiveMBooster"]=$false
    $BtnRestore.IsEnabled=$false; Set-CurrentTask "Restoring saved defaults in the background..."
    $savedRegistry=if($Scope -eq 'all'){@($Global:Orig.Values)}else{@()}
    $savedServices=if($Scope -in @('all','services')){@($Global:OrigServices.Values)}else{@()}
    $savedMisc=if($Scope -in @('all','power')){@($Global:OrigMisc.Values)}else{@()}
    $Global:RestoreDefaultsJob=Start-Job -ArgumentList @(,$savedRegistry),(,$savedServices),(,$savedMisc) -ScriptBlock {
        param($registry,$services,$misc)
        $restored=0; $failed=0
        foreach($item in $registry){
            try { if($null -eq $item.Value){ Remove-ItemProperty -LiteralPath $item.Path -Name $item.Name -Force -EA SilentlyContinue } else { Set-ItemProperty -LiteralPath $item.Path -Name $item.Name -Value $item.Value -Force -EA Stop }; $restored++ } catch { $failed++ }
        }
        foreach($svc in $services){
            try { if($svc.StartType){ $type=switch($svc.StartType){'Auto'{'Automatic'};'Manual'{'Manual'};'Disabled'{'Disabled'};default{'Manual'}}; Set-Service -Name $svc.ServiceName -StartupType $type -EA SilentlyContinue }; if($svc.Status -eq 'Running'){Start-Service -Name $svc.ServiceName -EA SilentlyContinue}; $restored++ } catch { $failed++ }
        }
        foreach($item in $misc){
            # Newer state entries carry a Type marker.  Flatten legacy array entries as
            # well so Restore Defaults can recover startup values written by older builds.
            $entries = @($item)
            foreach($entry in $entries){
                try {
                    if($entry.Type -eq 'PowerCfg'){
                        if($null -ne $entry.AC){ & powercfg /setacvalueindex SCHEME_CURRENT $entry.SubGroup $entry.Setting ([int]$entry.AC) 2>$null | Out-Null }
                        if($null -ne $entry.DC){ & powercfg /setdcvalueindex SCHEME_CURRENT $entry.SubGroup $entry.Setting ([int]$entry.DC) 2>$null | Out-Null }
                        & powercfg /setactive SCHEME_CURRENT 2>$null | Out-Null
                        $restored++
                    } elseif($entry.Type -eq 'ActivePowerPlan'){
                        if($entry.Guid){ & powercfg /setactive ([string]$entry.Guid) 2>$null | Out-Null; $restored++ }
                    } elseif($entry.Type -eq 'BCD'){
                        if([bool]$entry.Exists -and $entry.Value){ & bcdedit /set $entry.Identifier $entry.Name $entry.Value 2>$null | Out-Null }
                        else { & bcdedit /deletevalue $entry.Identifier $entry.Name 2>$null | Out-Null }
                        $restored++
                    } elseif($entry.Type -eq 'AdapterProperty'){
                        Set-NetAdapterAdvancedProperty -Name $entry.AdapterName -DisplayName $entry.DisplayName -DisplayValue $entry.DisplayValue -EA Stop | Out-Null; $restored++
                    } elseif($entry.Type -eq 'IPInterfaceMtu'){
                        Set-NetIPInterface -InterfaceIndex $entry.InterfaceIndex -AddressFamily $entry.AddressFamily -NlMtuBytes ([int]$entry.NlMtuBytes) -EA Stop | Out-Null; $restored++
                    } elseif($entry.Type -eq 'ProcessPriorityBoost'){
                        $proc=Get-Process -Id ([int]$entry.ProcessId) -EA Stop
                        $proc.PriorityBoostEnabled=[bool]$entry.Enabled
                        $restored++
                    } elseif($entry.Type -eq 'DnsServerAddresses'){
                        if([bool]$entry.Reset){ Set-DnsClientServerAddress -InterfaceIndex $entry.InterfaceIndex -AddressFamily $entry.AddressFamily -ResetServerAddresses -EA Stop }
                        else { Set-DnsClientServerAddress -InterfaceIndex $entry.InterfaceIndex -AddressFamily $entry.AddressFamily -ServerAddresses @($entry.ServerAddresses) -EA Stop }
                        $restored++
                    } elseif($entry.Type -eq 'AdapterBinding'){
                        if([bool]$entry.Enabled){ Enable-NetAdapterBinding -Name $entry.AdapterName -ComponentID $entry.ComponentID -EA Stop | Out-Null }
                        else { Disable-NetAdapterBinding -Name $entry.AdapterName -ComponentID $entry.ComponentID -EA Stop | Out-Null }
                        $restored++
                    } elseif($entry.Type -eq 'PageFileMode'){
                        $cs=Get-CimInstance -ClassName Win32_ComputerSystem -EA Stop
                        Set-CimInstance -InputObject $cs -Property @{AutomaticManagedPagefile=[bool]$entry.AutomaticManagedPagefile} -EA Stop | Out-Null
                        $restored++
                    } elseif($entry.Type -eq 'ScheduledTask'){
                        if([bool]$entry.Enabled){ Enable-ScheduledTask -TaskPath $entry.TaskPath -TaskName $entry.TaskName -EA Stop | Out-Null } else { Disable-ScheduledTask -TaskPath $entry.TaskPath -TaskName $entry.TaskName -EA Stop | Out-Null }; $restored++
                    } elseif($entry.Type -eq 'NetQosPolicy'){
                        foreach($name in @($entry.Names)){ Remove-NetQosPolicy -Name $name -Confirm:$false -EA Stop | Out-Null; $restored++ }
                    } elseif($entry.Type -eq 'FirewallRule'){
                        foreach($name in @($entry.Names)){ Remove-NetFirewallRule -DisplayName $name -Confirm:$false -EA Stop | Out-Null; $restored++ }
                    } elseif($entry.Type -eq 'DefenderExclusion'){
                        foreach($path in @($entry.Paths)){ Remove-MpPreference -ExclusionPath $path -EA Stop; $restored++ }
                    } elseif($entry.Type -eq 'StartupEntries'){
                        foreach($startup in @($entry.Entries)){
                            if($null -eq $startup.Value){ Remove-ItemProperty -LiteralPath $startup.Path -Name $startup.Name -Force -EA SilentlyContinue }
                            else {
                                $current=Get-ItemProperty -LiteralPath $startup.Path -Name $startup.Name -EA SilentlyContinue
                                if($null -eq $current -or $null -eq $current.PSObject.Properties[$startup.Name]){ New-ItemProperty -LiteralPath $startup.Path -Name $startup.Name -Value $startup.Value -PropertyType String -Force -EA Stop | Out-Null }
                                else { Set-ItemProperty -LiteralPath $startup.Path -Name $startup.Name -Value $startup.Value -Force -EA Stop }
                            }
                            $restored++
                        }
                    } elseif($entry.Path -and $entry.Name){
                        # Legacy startup-entry format from pre-typed state files.
                        if($null -eq $entry.Value){ Remove-ItemProperty -LiteralPath $entry.Path -Name $entry.Name -Force -EA SilentlyContinue }
                        else { New-ItemProperty -LiteralPath $entry.Path -Name $entry.Name -Value $entry.Value -PropertyType String -Force -EA Stop | Out-Null }
                        $restored++
                    }
                } catch { $failed++ }
            }
        }
        "Restored $restored saved settings; skipped/failed $failed."
    }
    $Global:RestoreDefaultsPoller=New-Object System.Windows.Threading.DispatcherTimer
    $Global:RestoreDefaultsPoller.Interval=[TimeSpan]::FromMilliseconds(300)
    $Global:RestoreDefaultsPoller.Add_Tick({
        if($Global:RestoreDefaultsJob.State -eq 'Running'){ return }
        $Global:RestoreDefaultsPoller.Stop(); $result=Receive-Job $Global:RestoreDefaultsJob -Wait -AutoRemoveJob -EA SilentlyContinue
        Add-Log ($result -join ' ') "#FFFFFF"; Set-CurrentTask "Restore complete. Restart Windows if a restored setting requires it."; $BtnRestore.IsEnabled=$true
    }.GetNewClosure())
    $Global:RestoreDefaultsPoller.Start()
}
$BtnCreateRestore.Add_Click({ Start-CreateRestorePointAsync })
$BtnRestore.Add_Click({ Show-RecoveryCenter })

function Save-OrigAdapterProperty {
    param([string]$Key,[string]$AdapterName,[string]$DisplayName,[string]$DisplayValue)
    $id = "Adapter::$Key::$AdapterName::$DisplayName"
    if($Global:OrigMisc.ContainsKey($id)){ return }
    $Global:OrigMisc[$id] = @{ Type="AdapterProperty"; AdapterName=$AdapterName; DisplayName=$DisplayName; DisplayValue=$DisplayValue }
}
function Set-ExtendedAdapterProperty {
    param([string]$Key,[object]$Adapter,[object]$Property,[string[]]$Values)
    foreach($value in $Values){
        try {
            Save-OrigAdapterProperty $Key $Adapter.Name $Property.DisplayName $Property.DisplayValue
            Set-NetAdapterAdvancedProperty -Name $Adapter.Name -DisplayName $Property.DisplayName -DisplayValue $value -EA Stop | Out-Null
            return $true
        } catch { }
    }
    return $false
}
function Get-BcdCurrentValue {
    param([string]$Name)
    try {
        $lines=@(bcdedit /enum "{current}" 2>$null)
        foreach($line in $lines){
            if([string]$line -match "^\s*$([regex]::Escape($Name))\s+(.+?)\s*$"){ return [string]$matches[1] }
        }
    } catch {}
    return $null
}
function Save-OrigBcd {
    param([string]$Key,[string]$Name)
    $id="BCD::$Name"
    if(-not $Global:OrigMisc.ContainsKey($id)){
        $value=Get-BcdCurrentValue $Name
        $Global:OrigMisc[$id]=@{Type="BCD";Identifier="{current}";Name=$Name;Exists=($null -ne $value);Value=$value;Key=$Key}
    }
}
function Save-OrigPowerCfg {
    param([string]$Key,[string]$SubGroup,[string]$Setting)
    $id="PowerCfg::$SubGroup::$Setting"
    if($Global:OrigMisc.ContainsKey($id)){ return }
    $ac=$null; $dc=$null
    try {
        $lines=@(powercfg /query SCHEME_CURRENT $SubGroup $Setting 2>$null)
        foreach($line in $lines){
            if([string]$line -match "Current AC Power Setting Index:\s+0x([0-9A-Fa-f]+)"){ $ac=[Convert]::ToInt32($matches[1],16) }
            if([string]$line -match "Current DC Power Setting Index:\s+0x([0-9A-Fa-f]+)"){ $dc=[Convert]::ToInt32($matches[1],16) }
        }
    } catch {}
    $Global:OrigMisc[$id]=@{Type="PowerCfg";Key=$Key;SubGroup=$SubGroup;Setting=$Setting;AC=$ac;DC=$dc}
}
function Run-ExtendedGamingTweak {
    param([string]$ToggleKey)
    try {
        switch($ToggleKey){
            "BCD_UsePlatformClockOff" {
                Set-CurrentTask "BCDEdit -> Platform Clock Off"
                Save-OrigBcd $ToggleKey "useplatformclock"
                $null=bcdedit /set "{current}" useplatformclock false 2>&1
                if($LASTEXITCODE -ne 0){ throw "bcdedit failed for useplatformclock (exit $LASTEXITCODE)" }
                Add-Log "BCDEdit useplatformclock=false applied (reboot required; Advanced)" "#FFFFFF"
            }
            "BCD_DisableDynamicTick" {
                Set-CurrentTask "BCDEdit -> Dynamic Tick Off"
                Save-OrigBcd $ToggleKey "disabledynamictick"
                $null=bcdedit /set "{current}" disabledynamictick yes 2>&1
                if($LASTEXITCODE -ne 0){ throw "bcdedit failed for disabledynamictick (exit $LASTEXITCODE)" }
                Add-Log "BCDEdit disabledynamictick=yes applied (reboot required; Advanced)" "#FFFFFF"
            }
            "BCD_TscSyncPolicy" {
                Set-CurrentTask "BCDEdit -> TSC Sync Enhanced"
                Save-OrigBcd $ToggleKey "tscsyncpolicy"
                $null=bcdedit /set "{current}" tscsyncpolicy Enhanced 2>&1
                if($LASTEXITCODE -ne 0){ throw "bcdedit failed for tscsyncpolicy (exit $LASTEXITCODE)" }
                Add-Log "BCDEdit tscsyncpolicy=Enhanced applied (reboot required; Advanced)" "#FFFFFF"
            }
            "SYS_MMCSSSystemResponsiveness" {
                Set-CurrentTask "MMCSS System Responsiveness -> 0"
                $p="HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile"
                Save-Orig "SYS_MMCSSSystemResponsiveness" $p "SystemResponsiveness"
                Set-RegValue $p "SystemResponsiveness" 0 | Out-Null
                Add-Log "MMCSS SystemResponsiveness set to 0 (Advanced; restorable)" "#FFFFFF"
            }
            "NET_RSC" {
                Set-CurrentTask "RSC Packet Coalescing -> Disabled"
                netsh int tcp set global rsc=disabled 2>&1 | Out-Null
                Add-Log "RSC disabled to reduce packet batching latency (reboot/network reset may be required)" "#FFFFFF"
            }
            "NET_ECN" {
                Set-CurrentTask "ECN -> Disabled"
                netsh int tcp set global ecncapability=disabled 2>&1 | Out-Null
                Add-Log "ECN disabled for router compatibility" "#FFFFFF"
            }
            "NET_FastOpen" {
                Set-CurrentTask "TCP Fast Open -> Enabled"
                netsh int tcp set global fastopen=enabled fastopenfallback=enabled 2>&1 | Out-Null
                Add-Log "TCP Fast Open and fallback enabled" "#FFFFFF"
            }
            "NET_TaskOffload" {
                Set-CurrentTask "TCP Task Offload / LSO -> Disabled"
                $adapters=@(Get-NetAdapter -Physical -EA SilentlyContinue | Where-Object {$_.Status -eq "Up"})
                $changed=0
                foreach($adapter in $adapters){
                    $props=@(Get-NetAdapterAdvancedProperty -Name $adapter.Name -EA SilentlyContinue | Where-Object {$_.DisplayName -match "Large Send Offload.*(IPv4|IPv6)|LSO"})
                    foreach($prop in $props){ if(Set-ExtendedAdapterProperty $ToggleKey $adapter $prop @("Disabled","Off")){ $changed++ } }
                }
                Add-Log "Large Send Offload disabled on $changed NIC setting(s)" "#FFFFFF"
            }
            "NET_TCPParameters" {
                Set-CurrentTask "TCP Parameters -> Low-Latency Profile"
                $p="HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters"
                Save-Orig "NET_TCPParameters_Timestamps" $p "Tcp1323Opts"
                Save-Orig "NET_TCPParameters_PMTU" $p "EnablePMTUDiscovery"
                Set-RegValue $p "Tcp1323Opts" 1 | Out-Null
                Set-RegValue $p "EnablePMTUDiscovery" 1 | Out-Null
                Add-Log "TCP timestamps and path-MTU discovery enabled" "#FFFFFF"
            }
            "NET_FlowControlStable" {
                Set-CurrentTask "LAN Flow Control -> Driver Default/Enabled"
                $adapters=@(Get-NetAdapter -Physical -EA SilentlyContinue | Where-Object {$_.Status -eq "Up" -and $_.InterfaceDescription -notmatch "Wi-Fi|Wireless"})
                $changed=0
                foreach($adapter in $adapters){
                    $props=@(Get-NetAdapterAdvancedProperty -Name $adapter.Name -EA SilentlyContinue | Where-Object {$_.DisplayName -match "Flow Control"})
                    foreach($prop in $props){
                        if(Set-ExtendedAdapterProperty $ToggleKey $adapter $prop @("Rx & Tx Enabled","Enabled","Auto")){ $changed++ }
                    }
                }
                Add-Log "LAN flow-control stability profile requested on $changed setting(s) (unsupported values skipped)" "#FFFFFF"
            }
            "FIVEM_SessionServices" {
                Set-CurrentTask "FiveM Session -> Pause Optional Services"
                $services=@("WSearch","DiagTrack","WerSvc","DoSvc")
                $changed=0
                foreach($name in $services){
                    try{
                        $svc=Get-Service -Name $name -EA Stop
                        if($svc.Status -eq "Running"){
                            Save-OrigService "FIVEM_SessionServices::$name" $name
                            Stop-Service -Name $name -Force -EA Stop
                            $changed++
                        } else { Add-Log "$name already stopped - skipped" "#A0A0A0" }
                    } catch { Add-Log "$name unavailable or protected - skipped" "#A0A0A0" }
                }
                Add-Log "FiveM session profile paused $changed optional service(s); startup types were not changed" "#FFFFFF"
            }
            "NIC_EnergyEfficientEthernet" {
                Set-CurrentTask "NIC Energy Efficient Ethernet -> Off"
                $adapters=@(Get-NetAdapter -Physical -EA SilentlyContinue | Where-Object {$_.Status -eq "Up"})
                $changed=0
                foreach($adapter in $adapters){
                    $props=@(Get-NetAdapterAdvancedProperty -Name $adapter.Name -EA SilentlyContinue | Where-Object {$_.DisplayName -match "Energy Efficient Ethernet|Green Ethernet|Power Saving Mode"})
                    foreach($prop in $props){ if(Set-ExtendedAdapterProperty $ToggleKey $adapter $prop @("Disabled","Off")){ $changed++ } }
                }
                Add-Log "Energy-saving NIC options disabled on $changed setting(s)" "#FFFFFF"
            }
            "AUDIO_MMCSS" {
                Set-CurrentTask "Audio MMCSS -> High Priority"
                $p="HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Audio"
                Save-Orig "AUDIO_MMCSS_Category" $p "Scheduling Category"; Save-Orig "AUDIO_MMCSS_Priority" $p "Priority"; Save-Orig "AUDIO_MMCSS_SFIO" $p "SFIO Priority"
                Set-RegValue $p "Scheduling Category" "High" "String" | Out-Null
                Set-RegValue $p "Priority" 6 | Out-Null
                Set-RegValue $p "SFIO Priority" "High" "String" | Out-Null
                Add-Log "Windows Audio MMCSS profile set to High" "#FFFFFF"
            }
            "SSD_ReTrim" {
                Set-CurrentTask "SSD ReTrim -> Run Once"
                $volumes=@(Get-Volume -EA SilentlyContinue | Where-Object {$_.DriveType -eq "Fixed" -and $_.DriveLetter})
                $trimmed=0
                foreach($volume in $volumes){ try { Optimize-Volume -DriveLetter $volume.DriveLetter -ReTrim -EA Stop | Out-Null; $trimmed++ } catch { } }
                Add-Log "ReTrim sent to $trimmed fixed volume(s)" "#FFFFFF"
            }
            "SSD_NtfsLastAccess" {
                Set-CurrentTask "NTFS Last Access Updates -> Off"
                $p="HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem"
                Save-Orig "SSD_NtfsLastAccess" $p "NtfsDisableLastAccessUpdate"
                Set-RegValue $p "NtfsDisableLastAccessUpdate" 1 | Out-Null
                Add-Log "NTFS last-access metadata updates disabled" "#FFFFFF"
            }
            "SVC_XboxBackground" {
                Set-CurrentTask "Xbox Background Services -> Disabled"
                $services=@("XblAuthManager","XblGameSave","XboxNetApiSvc","XboxGipSvc")
                $changed=0
                foreach($name in $services){ try { Save-OrigService "SVC_XboxBackground::$name" $name; Stop-Service $name -Force -EA SilentlyContinue; Set-Service $name -StartupType Disabled -EA Stop; $changed++ } catch { } }
                Add-Log "Xbox background services disabled: $changed" "#FFFFFF"
            }
            "TASK_Telemetry" {
                Set-CurrentTask "Telemetry Scheduled Tasks -> Disabled"
                $tasks=@("\Microsoft\Windows\Application Experience\Microsoft Compatibility Appraiser","\Microsoft\Windows\Application Experience\ProgramDataUpdater","\Microsoft\Windows\Customer Experience Improvement Program\Consolidator","\Microsoft\Windows\Customer Experience Improvement Program\UsbCeip")
                $changed=0
                foreach($taskName in $tasks){
                    try {
                        $task=Get-ScheduledTask -TaskPath (Split-Path $taskName -Parent) -TaskName (Split-Path $taskName -Leaf) -EA Stop
                        $id="Task::$taskName"
                        if(-not $Global:OrigMisc.ContainsKey($id)){ $Global:OrigMisc[$id]=@{Type="ScheduledTask";TaskPath=$task.TaskPath;TaskName=$task.TaskName;Enabled=[bool]$task.Settings.Enabled} }
                        Disable-ScheduledTask -InputObject $task -EA Stop | Out-Null; $changed++
                    } catch { }
                }
                Add-Log "Telemetry scheduled tasks disabled: $changed" "#FFFFFF"
            }
            "DEF_FiveMExclusions" {
                Run-GameExclusion
                Add-Log "Defender remains enabled; only game folder exclusions were added" "#FFFFFF"
            }
            "PRIVACY_AdvertisingId" {
                Set-CurrentTask "Advertising ID -> Disabled"
                $p="HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\AdvertisingInfo"
                Save-Orig "PRIVACY_AdvertisingId" $p "Enabled"; Set-RegValue $p "Enabled" 0 | Out-Null
                Add-Log "Windows Advertising ID disabled" "#FFFFFF"
            }
            "PRIVACY_ActivityHistory" {
                Set-CurrentTask "Activity History -> Disabled"
                $p="HKCU:\SOFTWARE\Policies\Microsoft\Windows\System"
                Save-Orig "PRIVACY_ActivityHistory_Publish" $p "PublishUserActivities"; Save-Orig "PRIVACY_ActivityHistory_Upload" $p "UploadUserActivities"
                Set-RegValue $p "PublishUserActivities" 0 | Out-Null; Set-RegValue $p "UploadUserActivities" 0 | Out-Null
                Add-Log "Windows activity history publishing disabled" "#FFFFFF"
            }
            "STARTUP_BackgroundApps" {
                Set-CurrentTask "Background App Startup -> Blocked"
                $p="HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications"
                Save-Orig "STARTUP_BackgroundApps" $p "GlobalUserDisabled"; Set-RegValue $p "GlobalUserDisabled" 1 | Out-Null
                Protect-MessengerBackgroundAccess
                Add-Log "Store app background startup blocked for current user; LINE and similar messengers were kept allowed" "#FFFFFF"
            }
            "USB_PowerSuspendOff" {
                Set-CurrentTask "USB Selective Suspend -> Off"
                powercfg /setacvalueindex SCHEME_CURRENT SUB_USB USBSELECTIVE 0 2>&1 | Out-Null
                powercfg /setactive SCHEME_CURRENT 2>&1 | Out-Null
                Add-Log "USB selective suspend disabled on AC power" "#FFFFFF"
            }
            "INPUT_KeyboardRepeat" {
                Set-CurrentTask "Keyboard Repeat -> Fast"
                $p="HKCU:\Control Panel\Keyboard"
                Save-Orig "INPUT_KeyboardRepeat_Delay" $p "KeyboardDelay"; Save-Orig "INPUT_KeyboardRepeat_Speed" $p "KeyboardSpeed"
                Set-RegValue $p "KeyboardDelay" "0" "String" | Out-Null; Set-RegValue $p "KeyboardSpeed" "31" "String" | Out-Null
                Add-Log "Keyboard repeat set to fastest Windows values" "#FFFFFF"
            }
            "FIVEM_HighPerformanceGPU" {
                Set-CurrentTask "FiveM GPU Preference -> High Performance"
                $gpuPrefPath="HKCU:\SOFTWARE\Microsoft\DirectX\UserGpuPreferences"
                $exePaths=@()
                foreach($proc in @(Get-FiveMRelatedProcesses)){
                    try{ if($proc.Path){ $exePaths += [string]$proc.Path } }catch{}
                    try{ if($proc.MainModule -and $proc.MainModule.FileName){ $exePaths += [string]$proc.MainModule.FileName } }catch{}
                }
                foreach($exe in @(Get-FiveMExecutablePaths)){ $exePaths += $exe }
                $exePaths += @(
                    "$env:LOCALAPPDATA\FiveM\FiveM.app\FiveM.exe",
                    "$env:LOCALAPPDATA\FiveM\FiveM.app\FiveM_GTAProcess.exe"
                )
                $exePaths=@($exePaths | Where-Object {$_ -and (Test-Path -LiteralPath $_)} | Sort-Object -Unique)
                $changed=0
                foreach($exe in $exePaths){
                    Save-Orig "FIVEM_HighPerformanceGPU::$exe" $gpuPrefPath $exe
                    if(Set-RegValue $gpuPrefPath $exe "GpuPreference=2;" "String") { $changed++ }
                }
                if($changed -gt 0){ Add-Log "Windows high-performance GPU preference set for $changed FiveM executable(s)" "#FFFFFF" }
                else { Add-Log "FiveM executable not found - GPU preference skipped" "#A0A0A0" }
            }
            "FIVEM_PriorityBoost" {
                Set-CurrentTask "FiveM Process -> Priority Boost On"
                $procs=@(Get-FiveMRelatedProcesses)
                $changed=0
                foreach($proc in $procs){
                    try{
                        $id="ProcessPriorityBoost::$($proc.Id)"
                        if(-not $Global:OrigMisc.ContainsKey($id)){ $Global:OrigMisc[$id]=@{Type="ProcessPriorityBoost";ProcessId=[int]$proc.Id;Enabled=[bool]$proc.PriorityBoostEnabled} }
                        $proc.PriorityBoostEnabled=$true
                        $changed++
                    } catch { }
                }
                if($changed -gt 0){ Add-Log "FiveM priority boost enabled on $changed running process(es)" "#FFFFFF" }
                else { Add-Log "FiveM is not running - priority boost will be skipped" "#A0A0A0" }
            }
            "CP_VisualEffects" {
                Set-CurrentTask "Control Panel Visual Effects -> Performance"
                $p="HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects"
                Save-Orig "CP_VisualEffects" $p "VisualFXSetting"; Set-RegValue $p "VisualFXSetting" 2 | Out-Null
                Add-Log "Windows visual effects switched to performance profile" "#FFFFFF"
            }
            "BLOAT_ProvisionedApps" {
                Set-CurrentTask "Provisioned Bloatware -> Remove"
                $targets=@("Microsoft.BingWeather","Microsoft.BingNews","Microsoft.GetHelp","Microsoft.Getstarted","Microsoft.MicrosoftOfficeHub","Microsoft.MicrosoftSolitaireCollection","Microsoft.People","Microsoft.WindowsFeedbackHub","Microsoft.XboxApp","Microsoft.Xbox.TCUI","Microsoft.XboxGamingOverlay","Microsoft.ZuneMusic","Microsoft.ZuneVideo")
                $removed=0
                foreach($pkg in @(Get-AppxProvisionedPackage -Online -EA SilentlyContinue | Where-Object {$targets -contains $_.DisplayName})){ try { Remove-AppxProvisionedPackage -Online -PackageName $pkg.PackageName -EA Stop | Out-Null; $removed++ } catch { } }
                Add-Log "Provisioned bloat packages removed: $removed (new profiles only)" "#FFFFFF"
            }
            "GPE_GamePolicy" {
                Set-CurrentTask "Group Policy -> Game Capture Off"
                Run-NoGameDVR
                Add-Log "Game capture policy applied (gpedit equivalent)" "#FFFFFF"
            }
        }
        $Global:AppliedKeys[$ToggleKey]=$true
        Save-TweakState
    } catch { Add-Log "$ToggleKey skipped: $($_.Exception.Message)" "#FFFFFF" }
}

function Get-TweakWorkerScript {
    param([string[]]$FunctionNames)
    $builder = New-Object System.Text.StringBuilder
    [void]$builder.AppendLine('$ErrorActionPreference = "Stop"')
    [void]$builder.AppendLine('if($Orig){ $Global:Orig = $Orig }')
    [void]$builder.AppendLine('if($AppliedKeys){ $Global:AppliedKeys = $AppliedKeys }')
    [void]$builder.AppendLine('if($OrigServices){ $Global:OrigServices = $OrigServices }')
    [void]$builder.AppendLine('if($OrigMisc){ $Global:OrigMisc = $OrigMisc }')
    [void]$builder.AppendLine('if($TweakToggles){ $Global:TweakToggles = $TweakToggles }')
    [void]$builder.AppendLine('if($KillProcList){ $Global:KillProcList = $KillProcList }')
    [void]$builder.AppendLine('if($KillServiceList){ $Global:KillServiceList = $KillServiceList }')
    [void]$builder.AppendLine('if($StartupDisableTargets){ $Global:StartupDisableTargets = $StartupDisableTargets }')
    [void]$builder.AppendLine('if($ProtectedMessengerNames){ $Global:ProtectedMessengerNames = $ProtectedMessengerNames }')
    [void]$builder.AppendLine('if($StateDir){ $Global:StateDir = $StateDir }')
    [void]$builder.AppendLine('if($StateFile){ $Global:StateFile = $StateFile }')
    foreach($name in @($FunctionNames | Sort-Object -Unique)){
        $fn = Get-Command $name -CommandType Function -ErrorAction SilentlyContinue
        if(-not $fn){ continue }
        [void]$builder.AppendLine("function $name {")
        [void]$builder.AppendLine($fn.Definition)
        [void]$builder.AppendLine("}")
    }
    [void]$builder.AppendLine(@'
function Add-Log {
    param([string]$msg,[string]$color="#A0A0A0")
    if($null -ne $WorkerEventQueue){
        $isFailure=([string]$color).ToUpperInvariant() -eq "#D8D8D8"
        [void]$WorkerEventQueue.Enqueue([pscustomobject]@{ LessProjectEvent="Log"; Message=$msg; Color=$color; Failure=$isFailure })
    }
}
function Set-CurrentTask {
    param([string]$msg)
    if($null -ne $WorkerEventQueue){
        [void]$WorkerEventQueue.Enqueue([pscustomobject]@{ LessProjectEvent="Task"; Message=$msg; Color="#888888" })
    }
}
function Emit-WorkerResult {
    param([string]$Status,[string]$Message,[bool]$Changed=$false)
    if($null -ne $WorkerEventQueue){
        $eventColor = if($Status -eq "Failed"){"#D8D8D8"}else{"#A0A0A0"}
        [void]$WorkerEventQueue.Enqueue([pscustomobject]@{ LessProjectEvent="Result"; Key=$WorkerToggleKey; Status=$Status; Message=$Message; Changed=$Changed; Color=$eventColor })
    }
}
try {
    $cmd=Get-Command $WorkerRunFunction -CommandType Function -ErrorAction Stop
    & $cmd.ScriptBlock $WorkerToggleKey
    if($AppliedKeys.ContainsKey($WorkerToggleKey) -and [bool]$AppliedKeys[$WorkerToggleKey]){
        Emit-WorkerResult "Applied" "$WorkerToggleKey completed and was verified by the handler." $true
    } else {
        Emit-WorkerResult "Skipped" "$WorkerToggleKey completed without an applied marker; no supported change was confirmed." $false
    }
} catch {
    $msg=$_.Exception.Message
    $looksUnsupported=($msg -match "not found|not supported|cannot find|does not exist|unsupported")
    if($looksUnsupported){ Emit-WorkerResult "Unsupported" $msg $false } else { Emit-WorkerResult "Failed" $msg $false }
    if($null -ne $WorkerEventQueue){
        [void]$WorkerEventQueue.Enqueue([pscustomobject]@{ LessProjectEvent="Error"; Message=$msg; Color="#D8D8D8"; Failure=$true })
    }
}
'@
)
    return $builder.ToString()
}
function Start-TweakWorker {
    param([string]$FunctionName,[string]$ToggleKey,[string]$WorkerScript)
    $runspace = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
    $runspace.ApartmentState = "MTA"
    $runspace.ThreadOptions = "ReuseThread"
    $runspace.Open()
    # Pass the mutable state tables by reference so the background runspace can save
    # registry/service originals and AppliedKeys without touching WPF controls.
    foreach($name in @("Orig","AppliedKeys","OrigServices","OrigMisc","TweakToggles","BloatList","KillProcList","KillServiceList","StartupDisableTargets","ProtectedMessengerNames","ExtendedTweakKeys","GpuVendors","DetectedGpuVendor","StateDir","StateFile","BackgroundJobs")){
        try {
            $value = Get-Variable -Name $name -Scope Global -ValueOnly -ErrorAction Stop
            $runspace.SessionStateProxy.SetVariable($name,$value)
        } catch {}
    }
    $runspace.SessionStateProxy.SetVariable("WorkerRunFunction",$FunctionName)
    $runspace.SessionStateProxy.SetVariable("WorkerToggleKey",$ToggleKey)
    $worker = [PowerShell]::Create()
    $worker.Runspace = $runspace
    [void]$worker.AddScript($WorkerScript)
    $eventQueue=New-Object 'System.Collections.Concurrent.ConcurrentQueue[object]'
    $runspace.SessionStateProxy.SetVariable("WorkerEventQueue",$eventQueue)
    $async = $worker.BeginInvoke()
    return @{ PowerShell=$worker; Runspace=$runspace; Async=$async; Key=$ToggleKey; EventQueue=$eventQueue; HadError=$false; ResultStatus=$null; ResultMessage=$null; ResultChanged=$false; StartedUtc=[DateTime]::UtcNow }
}
function Stop-TweakWorker {
    if(-not $Global:TweakWorker){ return }
    $worker = $Global:TweakWorker
    try { if($worker.PowerShell -and $worker.PowerShell.InvocationStateInfo.State -eq "Running"){ $worker.PowerShell.Stop() } } catch {}
    try { if($worker.PowerShell){ $worker.PowerShell.Dispose() } } catch {}
    try { if($worker.Runspace){ $worker.Runspace.Close(); $worker.Runspace.Dispose() } } catch {}
    $Global:TweakWorker = $null
}
function Receive-TweakWorkerEvents {
    param($Worker)
    if(-not $Worker -or -not $Worker.EventQueue){ return $false }
    $hasError=$false
    $eventObj=$null
    while($Worker.EventQueue.TryDequeue([ref]$eventObj)){
        if($eventObj -and $eventObj.PSObject.Properties["LessProjectEvent"]){
            $eventType=[string]$eventObj.LessProjectEvent
            if($eventType -eq "Log"){
                Add-Log ([string]$eventObj.Message) ([string]$eventObj.Color)
                if($eventObj.PSObject.Properties["Failure"] -and [bool]$eventObj.Failure){ $Worker["HadError"]=$true }
            } elseif($eventType -eq "Task"){
                Set-CurrentTask ([string]$eventObj.Message)
            } elseif($eventType -eq "Result"){
                $status=[string]$eventObj.Status
                $Worker["ResultStatus"]=$status
                $Worker["ResultMessage"]=[string]$eventObj.Message
                $Worker["ResultChanged"]=[bool]$eventObj.Changed
                if($status -eq "Failed"){ $hasError=$true; $Worker["HadError"]=$true }
                $color=if($status -eq "Failed"){"#D8D8D8"}elseif($status -eq "Applied"){"#4CB7FF"}else{"#A0A0A0"}
                Add-Log ("[$status] {0}: {1}" -f $Worker.Key,$eventObj.Message) $color
            } elseif($eventType -eq "Error"){
                $hasError=$true; $Worker["HadError"]=$true
                Add-Log ([string]$eventObj.Message) ([string]$eventObj.Color)
            }
        }
        $eventObj=$null
    }
    return ($hasError -or [bool]$Worker["HadError"])
}

function Get-LessNetworkCapability {
    try {
        if(-not (Get-Command Get-NetAdapter -ErrorAction SilentlyContinue)){ return [pscustomobject]@{Known=$false; Lan=0; Wifi=0} }
        $adapters=@(Get-NetAdapter -Physical -ErrorAction Stop | Where-Object { $_.Status -eq 'Up' })
        $lan=@($adapters | Where-Object { $_.InterfaceDescription -notmatch 'Wi-Fi|Wireless|802.11' }).Count
        $wifi=@($adapters | Where-Object { $_.InterfaceDescription -match 'Wi-Fi|Wireless|802.11' }).Count
        return [pscustomobject]@{Known=$true; Lan=[int]$lan; Wifi=[int]$wifi}
    } catch { return [pscustomobject]@{Known=$false; Lan=0; Wifi=0} }
}
function Get-LessNetworkKeysWithoutCapability {
    param([string[]]$Keys,[object]$Capability)
    if(-not $Capability -or -not [bool]$Capability.Known){ return @() }
    $lanKeys=@('LanOptimize','NET_FastLan','NET_LowLatencyLan','NET_LanMtu','NET_LanSpeedDuplex','NET_LanJumboFrame','NET_LanInterruptModeration','NET_DnsFast','NET_Ipv6Disable')
    $wifiKeys=@('WifiOptimize','NET_FastWifi','NET_LowLatencyWifi','NET_WifiMtu','NET_WifiSpeedDuplex','NET_WifiPowerSaveMode','NET_WifiRoamingAggressiveness','NET_DnsFast_WiFi','NET_Ipv6Disable_WiFi')
    $skip=@()
    if([int]$Capability.Lan -eq 0){ $skip += @($Keys | Where-Object { $lanKeys -contains $_ }) }
    if([int]$Capability.Wifi -eq 0){ $skip += @($Keys | Where-Object { $wifiKeys -contains $_ }) }
    return @($skip | Select-Object -Unique)
}
function Invoke-ApplyPressFx{
    try {
        if(-not $BtnRun){ return }
        [void]$BtnRun.ApplyTemplate()
        if($BtnRun.RenderTransform -is [System.Windows.Media.ScaleTransform]){
            $pressX=New-Object System.Windows.Media.Animation.DoubleAnimation
            $pressX.From=1.0; $pressX.To=0.965; $pressX.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(95)); $pressX.AutoReverse=$true
            $pressX.EasingFunction=New-Object System.Windows.Media.Animation.CubicEase
            $pressY=$pressX.Clone()
            $BtnRun.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$pressX)
            $BtnRun.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$pressY)
        }
        $applyBorder=$BtnRun.Template.FindName("ApplyBorder",$BtnRun)
        if($applyBorder){
            $flash=New-Object System.Windows.Media.Animation.ColorAnimation
            $flash.From=[System.Windows.Media.Color]::FromRgb(0xE9,0xE9,0xE9); $flash.To=[System.Windows.Media.Color]::FromRgb(0xD0,0xD0,0xD0); $flash.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(150)); $flash.AutoReverse=$true
            $flash.EasingFunction=New-Object System.Windows.Media.Animation.CubicEase
            $applyBrush=$applyBorder.Background
            if($applyBrush -is [System.Windows.Media.SolidColorBrush]){ $applyBrush.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty,$flash) }
            # Keep the press feedback crisp; animated DropShadowEffect can bleed
            # beyond the rounded Apply button and make the whole UI look blurry.
            $applyBorder.Effect=$null
        }
    } catch {}
}
$BtnRun.Add_Click({
    if($Global:TweakRunBusy){ Add-Log "A LESS PROJECT run is already in progress." "#D8D8D8"; return }
    if($Global:TweakRunTimer){ try{$Global:TweakRunTimer.Stop()}catch{} }
    $Global:TweakRunTimer=$null
    $Global:TweakRunQueue=$null
    # Persist the latest card selections before taking the immutable Apply snapshot.
    # This guarantees that the values shown in the cards are the values sent to Run-*.
    Save-TweakState
    $preflightKeys=@($Global:TweakToggles.Keys | Where-Object { [bool]$Global:TweakToggles[$_] } | ForEach-Object { [string]$_ })
    $preflightTotal=($preflightKeys|Measure-Object).Count
    if($preflightTotal -eq 0){ Add-Log "No tweaks selected." "#D8D8D8"; return }
    if(-not (Confirm-LessProjectApplyPreflight)){ return }
    # User Mode: save the selected profile first, then ask for elevation only for
    # the protected Apply phase. The elevated helper reads the same state file.
    if(-not (Test-IsAdministrator)){
        Add-Log "Protected Apply requires Administrator. Opening elevated helper..." "#D8D8D8"
        if(Restart-LessProjectAsAdministrator -ApplyAfterStart){
            try { $window.Close() } catch {}
        } else {
            [System.Windows.MessageBox]::Show("การ Apply ค่าระบบต้องใช้สิทธิ์ Administrator`n`nกรุณากด Yes ในหน้าต่าง UAC หรือคลิกขวาไฟล์แล้วเลือก Run as administrator","LESS PROJECT / APPLY PERMISSION",[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Warning)|Out-Null
        }
        return
    }
    $Global:TweakRunBusy=$true
    $runModes=@()
    if($Global:LowInputLagPresetEnabled){$runModes+='LOW INPUT LAG'}
    if($Global:FlowNetPresetEnabled){$runModes+='FLOW NET'}
    if($Global:FullSystemPresetEnabled){$runModes+='FULL SYSTEM'}
    if($Global:ActiveNetPreset -eq 'LAN NETWORK'){$runModes+='LAN'}
    if($Global:ActiveNetPreset -eq 'WI-FI NETWORK'){$runModes+='WIFI'}
    $Global:TweakRunProfileLabel=if($runModes.Count -gt 0){$runModes -join ' + '}else{'CUSTOM TWEAK SELECTION'}
    $activeKeys=@($Global:TweakToggles.Keys | Where-Object { [bool]$Global:TweakToggles[$_] } | ForEach-Object { [string]$_ })
    $total=($activeKeys|Measure-Object).Count
    if($total -eq 0){$Global:TweakRunBusy=$false;Add-Log "No tweaks selected." "#D8D8D8";return}
    # Network adapter properties are hardware/driver-specific. Remove only the
    # LAN/Wi-Fi-specific keys that cannot apply on this machine; generic TCP
    # settings remain in the queue.
    $networkCapability=Get-LessNetworkCapability
    $networkSkipKeys=@(Get-LessNetworkKeysWithoutCapability -Keys $activeKeys -Capability $networkCapability)
    foreach($networkSkipKey in $networkSkipKeys){
        Add-Log ("[SKIPPED] {0}: no matching active LAN/Wi-Fi adapter was detected on this machine." -f $networkSkipKey) "#A0A0A0"
    }
    if($networkSkipKeys.Count -gt 0){
        $activeKeys=@($activeKeys | Where-Object { $networkSkipKeys -notcontains $_ })
        $total=($activeKeys|Measure-Object).Count
        if($total -eq 0){ $Global:TweakRunBusy=$false; Add-Log "No compatible network tweaks remain for this machine." "#A0A0A0"; return }
    }
    Invoke-ApplyPressFx

    # FIX: AppliedKeys used to be loaded from state.json at startup and never reset before a
    # new Run. Invoke-DedupedGlobalTweak (and the GPU TdrDelay dedup block) checks AppliedKeys
    # and SKIPS the actual registry write if a key was ever marked applied in a *previous*
    # session - even if Windows/an update reverted the setting since. That made NetThrottle,
    # TcpGlobal and GPU TdrDelay permanently "stick" at whatever they were the very first time
    # you ran the tool, no matter how many times you ran it again. Reset per-run so every click
    # of Run actually re-applies the selected tweaks.
    $Global:AppliedKeys = @{}
    # Keep the first factory snapshot. Save-Orig / Save-OrigService already skip keys
    # that were captured on a previous run, so a second Apply can still restore Windows defaults.

    # --- Safety check #1: warn about the selected tweaks that change system behavior in ways the user should know about ---
    $riskyMap = [ordered]@{
        "SYS_PauseUpdates"        = "Windows Update will be paused"
        "CLEAN_NoTelemetry"       = "Telemetry / diagnostic data collection will be disabled"
        "CLEAN_NoWER"             = "Windows Error Reporting will be disabled"
        "CLEAN_NoPrintSpooler"    = "Print Spooler service will be disabled (printing will stop working)"
        "SYS_NoBackgroundApps"    = "Background Store apps will be restricted; LINE and similar messengers stay allowed"
        "CLEAN_RemoveBloat"       = "Pre-installed 'bloatware' apps will be removed"
        "CLEAN_KillBackgroundProcs" = "Optional third-party background apps will be force-closed; LINE / WhatsApp / Telegram are never closed; selected non-essential services will be stopped (core hardware services are excluded)"
        "CLEAN_DisableLauncherStartup" = "Steam/Discord/Epic/Battle.net/Origin/Ubisoft/Riot/GOG/Spotify will no longer auto-start with Windows; LINE and similar messengers are not removed from startup"
        "SYS_ConsumerFeaturesOff" = "Windows 'suggested content' / consumer features will be disabled"
        "SYS_WidgetsOff"         = "Windows Widgets will be disabled"
        "SYS_OneDriveSyncOff"    = "OneDrive sync will be turned off"
        "NET_RemoteAssistanceOff"= "Remote Assistance will be disabled"
        "NET_NoAutoRootCertUpdate" = "Automatic root certificate updates will be disabled"
        "NduDisable"             = "Network Data Usage (Ndu) driver will be disabled"
        "NduDisable_WiFi"        = "Network Data Usage (Ndu) driver will be disabled"
        "NET_Ipv6Disable"        = "IPv6 will be unbound on the wired adapter"
        "NET_Ipv6Disable_WiFi"   = "IPv6 will be unbound on the Wi-Fi adapter"
        "NET_ECN"                = "ECN negotiation will be disabled"
        "NET_TaskOffload"        = "NIC Large Send Offload will be disabled (higher CPU use is possible)"
        "NET_NicBuffers"         = "Physical NIC receive/transmit buffers will be set to each driver's maximum (uses more RAM)"
        "NET_FlowControlStable"  = "Wired NIC flow control will be enabled when the driver supports it (pause frames may add latency under congestion)"
        "FIVEM_PriorityBoost"    = "FiveM process priority boost will be enabled while FiveM is running"
        "FIVEM_HighPerformanceGPU" = "Windows high-performance GPU preference will be set for detected FiveM executables"
        "FIVEM_SessionServices" = "Optional background services will be stopped temporarily; startup types will not be changed"
        "SSD_NtfsLastAccess"     = "NTFS last-access timestamps will be disabled"
        "SVC_XboxBackground"     = "Xbox background services will be disabled"
        "TASK_Telemetry"         = "Selected telemetry scheduled tasks will be disabled"
        "USB_PowerSuspendOff"    = "USB selective suspend will be disabled on AC power"
        "BLOAT_ProvisionedApps"  = "Provisioned consumer apps will be removed for new profiles"
        "NET_RSC"                = "RSC packet coalescing will be disabled; CPU use may rise"
        "NET_FastOpen"           = "TCP Fast Open will be enabled where supported"
        "NET_TCPParameters"      = "TCP timestamp and PMTU registry values will be changed"
        "AUDIO_MMCSS"            = "Windows Audio MMCSS priority will be raised"
        "SSD_ReTrim"             = "TRIM will run once on supported fixed volumes"
        "CP_VisualEffects"       = "Windows visual effects will switch to the Performance profile"
        "BCD_UsePlatformClockOff"= "BCDEdit useplatformclock=false will be applied; reboot required"
        "BCD_DisableDynamicTick" = "BCDEdit disabledynamictick=yes will be applied; reboot required"
        "BCD_TscSyncPolicy"      = "BCDEdit tscsyncpolicy=Enhanced will be applied; reboot required"
        "SYS_MMCSSSystemResponsiveness" = "MMCSS SystemResponsiveness will be set to 0; background responsiveness may change"
    }
    $activeRisky=@()
    foreach($k in $riskyMap.Keys){ if($Global:TweakToggles[$k] -and ($activeRisky -notcontains $riskyMap[$k])){ $activeRisky += $riskyMap[$k] } }
    if($activeRisky.Count -gt 0){
        Add-Log ("Risk review items selected: {0}. Applying without popup; details remain in Live Log." -f $activeRisky.Count) "#A0A0A0"
    }

    # --- Safety check #1b: for the three tweaks that remove/kill/disable actual apps, show the
    # SPECIFIC list of what's actually installed/running on THIS machine (not a generic description)
    # and let the user opt each one out individually without cancelling the whole run. ---
    $skipKeys=@()
    if($Global:TweakToggles["CLEAN_RemoveBloat"]){
        $__installedPkgs = @(Get-AppxPackage -EA SilentlyContinue | Select-Object -ExpandProperty Name)
        $foundBloat=@($Global:BloatList | Where-Object { $__installedPkgs -contains $_ })
        if($foundBloat.Count -gt 0){
            Add-Log ("Bloatware removal selected for {0} installed package(s); applying without popup." -f $foundBloat.Count) "#A0A0A0"
        }
    }
    if($Global:TweakToggles["CLEAN_KillBackgroundProcs"]){
        Add-Log "Background cleanup selected; applying without confirmation." "#A0A0A0"
    }
    if($Global:TweakToggles["CLEAN_DisableLauncherStartup"]){
        Add-Log "Launcher startup cleanup selected; applying without confirmation." "#A0A0A0"
    }
    if($skipKeys.Count -gt 0){
        $activeKeys=@($activeKeys | Where-Object { $skipKeys -notcontains $_ })
        $total=($activeKeys|Measure-Object).Count
        if($total -eq 0){ $Global:TweakRunBusy=$false; Add-Log "No tweaks left to run after declining the app changes above." "#D8D8D8"; return }
    }

    Set-StatusRunning; Add-Log "--- LESS PROJECT STARTED ---" "#FFFFFF"
    Set-CurrentTask "Preparing $total selected tweaks..."
    Add-Log "[QUEUE] Preparing $total selected ON tweaks for Apply. OFF tweaks are not queued. Each key will report Applied/Skipped/Unsupported/Failed." "#FFFFFF"
    $Global:IsCancelled=$false; $Global:TweakRunBusy=$true; $script:_done=0
    if($activeKeys -contains "FiveMBooster"){
        Start-RealtimeBoostController
        Add-Log "Realtime Boost controller attached to the live UI timer." "#FFFFFF"
    }
    Update-Progress 0 $total
    $runMap=@{
        "NetThrottle"="Run-NetThrottle";"BcdTimer"="Run-BcdTimer";"TcpGlobal"="Run-TcpGlobal"
        "KbQueue"="Run-KbQueue";"NduDisable"="Run-NduDisable";"GamingMemory"="Run-GamingMemory"
        "FiveMBooster"="Run-FiveMBooster";"GM_FiveMPerfOptions"="Run-FiveMPerfOptions";"GM_FiveMCoreAffinity"="Run-FiveMCoreAffinity";"NET_KillerFix"="Run-KillerFix";"NET_FiveMQos"="Run-FiveMQos";"NET_FiveMFirewall"="Run-FiveMFirewall";"DriverHealth"="Run-DriverHealth"
        "LanOptimize"="Run-LanOptimize";"WifiOptimize"="Run-WifiOptimize"
        "PWR_Throttling"="Run-PwrThrottling";"GM_FSOptim"="Run-FSOptim"
        "UX_MenuInstant"="Run-MenuInstant";"UX_Notifications"="Run-Notifications"
        "ADV_HPET"="Run-HPET";"GM_SmoothMotion"="Run-MPODisable";"CLEAN_SmoothOptim"="Run-SmoothOptim"
        "NET_NoNagle"="Run-NoNagle";"PWR_UltimatePlan"="Run-UltimatePlan";"SYS_NoCoreParking"="Run-NoCoreParking";"GM_HAGS"="Run-HAGS"
        "NET_PowerSaving"="Run-NetPowerSaving";"NET_AdaptersOptimizer"="Run-NetworkAdaptersOptimizer";"NET_FlushDns"="Run-FlushDns";"NET_ResetWinsock"="Run-ResetWinsock";"NET_SpeedTest"="Run-NetworkSpeedTest";"NET_FastLan"="Run-FastLan";"NET_LowLatencyLan"="Run-LowLatencyLan";"NET_LanMtu"="Run-LanMtu";"NET_LanSpeedDuplex"="Run-LanSpeedDuplex";"NET_FastWifi"="Run-FastWifi";"NET_LowLatencyWifi"="Run-LowLatencyWifi";"NET_WifiMtu"="Run-WifiMtu";"NET_WifiSpeedDuplex"="Run-WifiSpeedDuplex";"NET_USBSelSuspend"="Run-UsbSelSuspend"
        "SYS_TimerRes"="Run-TimerRes";"SYS_PauseUpdates"="Run-PauseUpdates"
        "GM_GameMode"="Run-GameMode";"GM_NoGameDVR"="Run-NoGameDVR";"GM_GameBarOff"="Run-GameBarOff";"GM_StandbyClean"="Run-StandbyClean"
        "CLEAN_NoSearchIndex"="Run-NoSearchIndex";"CLEAN_NoTelemetry"="Run-NoTelemetry";"CLEAN_NoStorageSense"="Run-NoStorageSense"
        "SYS_Win32Priority"="Run-Win32Priority";"GM_MMCSS"="Run-MMCSS"
        "NET_TcpTimedWait"="Run-TcpTimedWait";"NET_PortRange"="Run-PortRange";"NET_QoSReserve"="Run-QoSReserve"
        "GM_NoStickyKeys"="Run-NoStickyKeys"
        "SYS_NoBackgroundApps"="Run-NoBackgroundApps";"CLEAN_NoWER"="Run-NoWER";"CLEAN_NoPrintSpooler"="Run-NoPrintSpooler"
        "GPU_TdrDelay_Nvidia"="Run-GpuTdrDelay";"GPU_TdrDelay_Amd"="Run-GpuTdrDelay";"GPU_NvidiaPowerMode"="Run-NvidiaPowerMode";"GPU_NvidiaTelemetryOff"="Run-NvidiaTelemetryOff"
        "GPU_NvidiaMSIMode"="Run-NvidiaMSIMode";"GPU_NvidiaOverlayOff"="Run-NvidiaOverlayOff"
        "GPU_AmdUlps"="Run-AmdUlps";"GPU_AmdEventsUtil"="Run-AmdEventsUtil"
        "GPU_AmdMSIMode"="Run-AmdMSIMode";"GPU_AmdCrashDefenderOff"="Run-AmdCrashDefenderOff"
        "NetThrottle_WiFi"="Run-NetThrottle";"TcpGlobal_WiFi"="Run-TcpGlobal";"NduDisable_WiFi"="Run-NduDisable"
        "NET_NoNagle_WiFi"="Run-NoNagle";"NET_PowerSaving_WiFi"="Run-NetPowerSaving"
        "NET_TcpTimedWait_WiFi"="Run-TcpTimedWait";"NET_PortRange_WiFi"="Run-PortRange";"NET_QoSReserve_WiFi"="Run-QoSReserve"
        "NET_LanJumboFrame"="Run-LanJumboFrame";"NET_LanInterruptModeration"="Run-LanInterruptModeration"
        "NET_WifiPowerSaveMode"="Run-WifiPowerSaveMode";"NET_WifiRoamingAggressiveness"="Run-WifiRoamingAggressiveness"
        "NET_DnsFast"="Run-DnsFastLan";"NET_DnsFast_WiFi"="Run-DnsFastWifi"
        "NET_DeliveryOptOff"="Run-DeliveryOptOff";"NET_DnsCacheAggressive"="Run-DnsCacheAggressive"
        "SYS_BottleneckCheck"="Run-BottleneckCheck";"GPU_ClearShaderCache"="Run-ClearShaderCache"
        "CLEAN_ClearTempJunk"="Run-ClearTempJunk";"CLEAN_ClearFiveMCache"="Run-ClearFiveMCache"
        "CLEAN_RemoveBloat"="Run-RemoveBloat";"CLEAN_KillBackgroundProcs"="Run-KillBackgroundProcesses";"CLEAN_DisableLauncherStartup"="Run-DisableLauncherStartup"
        "NET_Ipv6Disable"="Run-Ipv6DisableLan";"NET_Ipv6Disable_WiFi"="Run-Ipv6DisableWifi"
        "NET_RssEnable"="Run-RssEnable";"NET_FlowControlOff"="Run-FlowControlOff"
        "DEF_GameExclusion"="Run-GameExclusion";"SYS_PageFileAuto"="Run-PageFileAuto"
        "NET_Ipv6Transition"="Run-Ipv6TransitionDisable";"NET_DnsClientPolicy"="Run-DnsClientPolicy"
        "NET_LltdDisable"="Run-LltdDisable";"NET_BitsNoLimit"="Run-BitsNoLimit";"NET_NetbiosDisable"="Run-NetbiosDisable"
        "NET_NcsiNoActiveProbe"="Run-NcsiNoActiveProbe";"NET_NoAutoRootCertUpdate"="Run-NoAutoRootCertUpdate"
        "SYS_NoBkgndGPRefresh"="Run-NoBkgndGPRefresh";"SYS_NoSmartScreenCheck"="Run-NoSmartScreenCheck"
        "NET_RemoteAssistanceOff"="Run-RemoteAssistanceOff"
        "NET_NicBuffers"="Run-NicBuffers"
        "SYS_OneDriveSyncOff"="Run-OneDriveSyncOff";"SYS_WidgetsOff"="Run-WidgetsOff";"SYS_ConsumerFeaturesOff"="Run-ConsumerFeaturesOff"
    }
    foreach($extendedKey in $Global:ExtendedTweakKeys){ $runMap[$extendedKey]="Run-ExtendedGamingTweak" }
    # NET_NicBuffers has a dedicated adapter-property implementation; keep it from being overwritten by the generic Advanced handler.
    $runMap["NET_NicBuffers"]="Run-NicBuffers"
    # Include every boot/session-wide setting that cannot take full effect until
    # Windows restarts. This is especially important for FULL SYSTEM, which also
    # enables the opt-in BCD/MMCSS/visual-effects controls.
    $restartRequiredKeys=@("BcdTimer","ADV_HPET","GM_HAGS","PWR_UltimatePlan","SYS_NoCoreParking","BCD_UsePlatformClockOff","BCD_DisableDynamicTick","BCD_TscSyncPolicy","SYS_MMCSSSystemResponsiveness","CP_VisualEffects","USB_PowerSuspendOff")
    $restartRequired=[bool](@($activeKeys | Where-Object { $restartRequiredKeys -contains $_ }).Count -gt 0)
    # Run each tweak in a dedicated MTA runspace.  The old DispatcherTimer called the
    # entire tweak function on the WPF thread, so WMI, AppX, service and adapter calls
    # made the window look frozen until that function returned.  A regular Queue is
    # populated explicitly so a single selected tweak cannot hit the Queue(int) overload.
    # Include the two helper tweaks called from Run-ExtendedGamingTweak. A
    # runspace only receives functions listed here; omitting transitive helpers
    # made DEF_FiveMExclusions and GPE_GamePolicy fail as "command not found".
    $workerFunctionNames=@("Get-FiveMRelatedProcesses","Get-FiveMGameProcesses","Get-FiveMExecutableNames","Get-FiveMExecutablePaths","Find-FiveMAppRoot","Get-RealtimeFiveMProcesses","Run-NetworkProfile","Run-NetworkMtu","Run-NetworkSpeedDuplex","Save-TweakState","ConvertTo-HashtableDeep","Set-RegValue","Get-RegValue","Save-Orig","Invoke-DedupedGlobalTweak","Save-OrigService","Restore-OrigService","Get-BcdCurrentValue","Save-OrigBcd","Save-OrigPowerCfg","Save-OrigAdapterProperty","Get-AdapterNumericMaximum","Set-ExtendedAdapterProperty","Get-GpuVendors","Get-GpuClassSubKeys","Get-GpuInstancePaths","Run-GameExclusion","Run-NoGameDVR","Test-ProtectedMessengerText","Test-ProtectedMessengerProcess","Get-ProtectedMessengerPackageFamilies","Protect-MessengerBackgroundAccess") + @($runMap.Values)
    $workerScriptText=Get-TweakWorkerScript $workerFunctionNames
    $timer=New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval=[TimeSpan]::FromMilliseconds(120)
    $keyQueue=New-Object System.Collections.Queue
    foreach($queuedKey in @($activeKeys)){ [void]$keyQueue.Enqueue([string]$queuedKey) }
    $Global:TweakRunTotal=$total
    $Global:TweakRunDone=0
    $Global:TweakRunSucceeded=0
    $Global:TweakRunFailed=0
    $Global:TweakRunSkipped=0
    $Global:TweakRunUnsupported=0
    $Global:TweakResults=@{}
    $Global:TweakRunMap=$runMap
    $Global:TweakWorkerScriptText=$workerScriptText
    $Global:TweakRestartRequired=$restartRequired
    $Global:TweakDisplayNames=@{}
    foreach($tweakMeta in $Global:TweakInfo){ $Global:TweakDisplayNames[[string]$tweakMeta.Key]=[string]$tweakMeta.Title }
    $Global:TweakWorker=$null
    # A single Windows command can occasionally wait forever (WMI, AppX, a driver
    # property or a service control call). Keep the UI responsive and move on to the
    # next selected tweak instead of leaving the run permanently at "RUNNING".
    $Global:TweakWorkerTimeoutSeconds=180
    Add-Log "[QUEUE] Background execution enabled (per-tweak timeout: $($Global:TweakWorkerTimeoutSeconds)s)." "#FFFFFF"
    # Keep the timer and queue rooted after the click handler returns.  Without a
    # global reference the DispatcherTimer could be collected before its first Tick,
    # leaving the UI stuck at "LESS PROJECT STARTED" with 0% progress.
    $Global:TweakRunTimer=$timer
    $Global:TweakRunQueue=$keyQueue
    $timer.Add_Tick({
        try {
            $timer=$Global:TweakRunTimer
            $keyQueue=$Global:TweakRunQueue
            if(-not $timer -or -not $keyQueue){ return }
            if($Global:IsCancelled){
                $timer.Stop(); $Global:TweakRunTimer=$null; $Global:TweakRunQueue=$null; $Global:TweakRunBusy=$false; Stop-TweakWorker; Save-TweakState
                Add-Log "--- LESS PROJECT CANCELLED ---" "#FFFFFF"; Set-CurrentTask "Cancelled. No more tweaks will run."; Set-StatusDone
                return
            }
            if($Global:TweakWorker){
                $finished=$Global:TweakWorker
                $workerAge=if($finished.StartedUtc){([DateTime]::UtcNow-[DateTime]$finished.StartedUtc).TotalSeconds}else{0}
                $finishedName=if($Global:TweakDisplayNames[$finished.Key]){$Global:TweakDisplayNames[$finished.Key]}else{$finished.Key}
                if(-not $finished.Async.IsCompleted -and $workerAge -ge $Global:TweakWorkerTimeoutSeconds){
                    # Stop and dispose the timed-out worker, then let this same tick
                    # continue with the next queue item.
                    Add-Log "[TIMEOUT] $finishedName exceeded $($Global:TweakWorkerTimeoutSeconds)s; skipped to keep Apply responsive." "#D8D8D8"
                    Set-CurrentTask "Timed out: $finishedName. Continuing..."
                    Stop-TweakWorker
                    $Global:TweakRunFailed++
                    $Global:TweakRunDone++
                    Update-Progress $Global:TweakRunDone $Global:TweakRunTotal
                } else {
                    $hadError=Receive-TweakWorkerEvents $finished
                    if(-not $finished.Async.IsCompleted){ return }
                    try { [void]$finished.PowerShell.EndInvoke($finished.Async) } catch { $hadError=$true; Add-Log "[FAIL] $($finished.Key): $($_.Exception.Message)" "#D8D8D8" }
                    if((Receive-TweakWorkerEvents $finished)){ $hadError=$true }
                    if($finished.PowerShell.Streams.Error.Count -gt 0){
                        $hadError=$true
                        foreach($streamError in $finished.PowerShell.Streams.Error){ Add-Log ([string]$streamError) "#FFFFFF" }
                    }
                    $elapsed=if($finished.StartedUtc){[math]::Round(([DateTime]::UtcNow-[DateTime]$finished.StartedUtc).TotalSeconds,1)}else{0}
                    $status=[string]$finished.ResultStatus
                    if([string]::IsNullOrWhiteSpace($status)){ $status=if($hadError){"Failed"}else{"Applied"} }
                    $Global:TweakResults[$finished.Key]=[ordered]@{Key=$finished.Key;Status=$status;Message=[string]$finished.ResultMessage;Changed=[bool]$finished.ResultChanged;ElapsedSeconds=$elapsed;Utc=([DateTime]::UtcNow.ToString("o"))}
                    Stop-TweakWorker
                    switch($status){
                        "Failed" { $Global:TweakRunFailed++; Add-Log "[FAILED] $finishedName (${elapsed}s)" "#D8D8D8" }
                        "Unsupported" { $Global:TweakRunUnsupported++; Add-Log "[UNSUPPORTED] $finishedName (${elapsed}s)" "#A0A0A0" }
                        "Skipped" { $Global:TweakRunSkipped++; Add-Log "[SKIPPED] $finishedName (${elapsed}s)" "#A0A0A0" }
                        default { $Global:TweakRunSucceeded++; Add-Log "[APPLIED] $finishedName (${elapsed}s)" "#FFFFFF" }
                    }
                    $Global:TweakRunDone++; Update-Progress $Global:TweakRunDone $Global:TweakRunTotal
                }
            }
            if($keyQueue.Count -eq 0){
                $timer.Stop(); $Global:TweakRunTimer=$null; $Global:TweakRunQueue=$null; Save-TweakState
                $Global:TweakRunSummary="PROFILE: $($Global:TweakRunProfileLabel)`nAPPLIED: $($Global:TweakRunSucceeded)   SKIPPED: $($Global:TweakRunSkipped)   UNSUPPORTED: $($Global:TweakRunUnsupported)   FAILED: $($Global:TweakRunFailed)"
                Add-Log "[RESULT] $($Global:TweakRunSummary -replace "`n",'; ')." $(if($Global:TweakRunFailed -gt 0){"#D8D8D8"}else{"#FFFFFF"})
                if($Global:TweakRunFailed -gt 0){
                    Add-Log "--- LESS PROJECT COMPLETE WITH ISSUES ---" "#D8D8D8"
                    Set-CurrentTask "Finished with issues. Check the failed entries in Live Log."
                    Set-StatusIssues
                    Show-LessProjectCompletionNotification "รัน LESS PROJECT เสร็จแล้ว แต่มีบางรายการไม่สำเร็จ`n`n$($Global:TweakRunSummary)`n`nตรวจสอบรายละเอียดเพิ่มเติมใน Live Log" $true
                } elseif($Global:TweakRestartRequired){
                    Add-Log "--- LESS PROJECT COMPLETE ---" "#FFFFFF"
                    Add-Log "At least one selected advanced tweak requires a restart to fully take effect." "#FFFFFF"
                    Set-CurrentTask "Complete. Restart required for selected advanced options."
                    Set-StatusDone
                    Show-LessProjectCompletionNotification "รัน LESS PROJECT เสร็จแล้ว`n`nRESTART REQUIRED: ต้องรีสตาร์ต Windows เพื่อให้ค่าบางรายการมีผลครบถ้วน`n`n$($Global:TweakRunSummary)" $false
                } else {
                    Add-Log "--- LESS PROJECT COMPLETE ---" "#FFFFFF"
                    Add-Log "Optimize profile applied. Start or return to FiveM; no restart is required for this profile." "#FFFFFF"
                    Set-CurrentTask "Complete. Ready for FiveM."
                    Set-StatusDone
                    Show-LessProjectCompletionNotification "รัน LESS PROJECT เสร็จเรียบร้อยแล้ว`nตรวจสอบผลการทำงานแล้ว`n`n$($Global:TweakRunSummary)`n`nโปรไฟล์ได้รับการปรับใช้แล้ว" $false
                }
                Update-Progress $Global:TweakRunTotal $Global:TweakRunTotal; return
            }
            $k=[string]$keyQueue.Dequeue(); $fnName=$Global:TweakRunMap[$k]
            $displayName=if($Global:TweakDisplayNames[$k]){$Global:TweakDisplayNames[$k]}else{$k}
            if($fnName){
                $nextNumber=$Global:TweakRunDone+1
                Set-CurrentTask "Running $displayName ($nextNumber/$($Global:TweakRunTotal))..."
                Add-Log "[RUNNING $nextNumber/$($Global:TweakRunTotal)] $displayName" "#FFFFFF"
                try { $Global:TweakWorker=Start-TweakWorker -FunctionName $fnName -ToggleKey $k -WorkerScript $Global:TweakWorkerScriptText }
                catch { Add-Log "[FAILED] $displayName`: $($_.Exception.Message)" "#D8D8D8"; $Global:TweakRunFailed++; $Global:TweakRunDone++; Update-Progress $Global:TweakRunDone $Global:TweakRunTotal }
            } else {
                Set-CurrentTask $displayName; Add-Log "[APPLIED] $displayName" "#FFFFFF"; $Global:TweakRunSucceeded++; $Global:TweakRunDone++; Update-Progress $Global:TweakRunDone $Global:TweakRunTotal
            }
        } catch {
            Add-Log "Tweak queue error: $($_.Exception.Message)" "#D8D8D8"; Stop-TweakWorker; $timer.Stop(); $Global:TweakRunTimer=$null; $Global:TweakRunQueue=$null; $Global:TweakRunBusy=$false; Set-StatusIssues; Show-TweakToast -Label 'LESS PROJECT' -Enabled $false -OverrideText 'LESS PROJECT  /  QUEUE ERROR`nตรวจสอบ Live Log' -DurationMs 4200
        }
    })
    $timer.Start()
})

Add-Log "> LESS PROJECT console initialised." "#FFFFFF"
Add-Log "> Safe client-side profile selected. Server/ISP ping is not changed by local tweaks." "#A0A0A0"

$window.Add_KeyDown({
    param($s,$e)
    if($e.Key -eq [System.Windows.Input.Key]::Escape){
        if($CategoryOverlay.Visibility -eq "Visible"){ Close-CategoryDetail; $e.Handled=$true }
    }
})

$window.Add_Closing({
    try { Stop-EmbeddedGifBackground -ScopeName "Main" } catch {}
    try { if($Global:SystemInfoTimer){ $Global:SystemInfoTimer.Stop() } } catch {}
    try { if($Global:DashboardMetricsJob){ Stop-Job -Job $Global:DashboardMetricsJob -ErrorAction SilentlyContinue; Remove-Job -Job $Global:DashboardMetricsJob -Force -ErrorAction SilentlyContinue; $Global:DashboardMetricsJob=$null } } catch {}
    try { if($Global:PowerPlanStatusTimer){ $Global:PowerPlanStatusTimer.Stop() } } catch {}
    try { if($Global:PowerPlanActivationPoller){ $Global:PowerPlanActivationPoller.Stop() } } catch {}
    try { if($Global:PowerPlanActivationJob){ Stop-Job $Global:PowerPlanActivationJob -ErrorAction SilentlyContinue; Remove-Job $Global:PowerPlanActivationJob -Force -ErrorAction SilentlyContinue } } catch {}
    $Global:PowerPlanActionBusy=$false
    try { if($Global:SystemInfoJob){ Stop-Job $Global:SystemInfoJob -ErrorAction SilentlyContinue; Remove-Job $Global:SystemInfoJob -Force -ErrorAction SilentlyContinue } } catch {}
    try { if($Global:TweakRunTimer){ $Global:TweakRunTimer.Stop() } } catch {}
    try { Stop-RealtimeBoostController -Restore $true } catch {}
    $Global:TweakRunTimer=$null
    $Global:TweakRunQueue=$null
    try { if($Global:TweakWorker){ Stop-TweakWorker } } catch {}
    if($Global:BackgroundJobs){
        foreach($j in $Global:BackgroundJobs){
            try{ Stop-Job -Job $j -EA SilentlyContinue; Remove-Job -Job $j -Force -EA SilentlyContinue }catch{}
        }
    }
})

$window.Add_ContentRendered({
    try {
        if($RootGrid -and $RootClipGeom){
            Update-MainWindowChrome
        }
    } catch {}
    # Keep the exact Dashboard visible after WPF completes its first layout pass.
    # The old System Info and category overlay must not be restored over it.
    try {
        if($Global:ActiveMainMenu -eq "DASHBOARD") {
            if($SystemInfoPanel){ $SystemInfoPanel.Visibility=[System.Windows.Visibility]::Collapsed }
            if($DashboardPanel){ $DashboardPanel.Visibility=[System.Windows.Visibility]::Visible }
            if($CategoryOverlay){ $CategoryOverlay.Visibility=[System.Windows.Visibility]::Collapsed }
            if($BtnRun){ $BtnRun.Visibility=[System.Windows.Visibility]::Collapsed }
        } else {
            if($SystemInfoPanel){ $SystemInfoPanel.Visibility=[System.Windows.Visibility]::Collapsed; $SystemInfoPanel.Width=0; $SystemInfoPanel.MinWidth=0; $SystemInfoPanel.MaxWidth=0 }
            Show-CategoryDetail "__TOOLS_ALL__"
        }
    } catch {}
    try { Apply-PremiumMonochromeTheme } catch {}
    try { Disable-LessProjectGlow } catch {}
    try { Update-SystemInfoUi } catch {}
    try { Update-ActiveTweakCounts } catch {}
    try { Update-PresetGlowConsistency } catch {}
    try { Initialize-OneClickToggleSounds } catch {}
    try { Update-DashboardStatusPanel } catch {}
    try { if($CurrentTask){ $CurrentTask.Text = "UI READY." }; if($FooterNoticeText){ $FooterNoticeText.Text = ""; $FooterNoticeText.Visibility=[System.Windows.Visibility]::Collapsed } } catch {}
    if($Global:ApplyAfterStart -and (Test-IsAdministrator)){
        $Global:ApplyAfterStart=$false
        try {
            $applyTimer=New-Object System.Windows.Threading.DispatcherTimer
            $applyTimer.Interval=[TimeSpan]::FromMilliseconds(650)
            $applyTimer.Add_Tick({
                param($sender,$eventArgs)
                $sender.Stop()
                try { $BtnRun.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Button]::ClickEvent))) } catch {}
            })
            $applyTimer.Start()
        } catch {}
    }
    if((Test-IsAdministrator) -and ($Global:PendingWin32Profile -or $Global:PendingPowerPlanName)){
        $pendingWin32=[string]$Global:PendingWin32Profile
        $pendingPower=[string]$Global:PendingPowerPlanName
        $Global:PendingWin32Profile=$null; $Global:PendingPowerPlanName=$null
        try {
            $pendingTimer=New-Object System.Windows.Threading.DispatcherTimer
            $pendingTimer.Interval=[TimeSpan]::FromMilliseconds(800)
            $pendingTimer.Add_Tick({
                param($sender,$eventArgs)
                $sender.Stop()
                try {
                    if(-not [string]::IsNullOrWhiteSpace($pendingWin32)){
                        [void](Invoke-Win32PriorityProfile $pendingWin32)
                    } elseif(-not [string]::IsNullOrWhiteSpace($pendingPower)){
                        if($pendingPower -eq 'SOFTPOWERPLAN'){
                            Invoke-OneClickSoftPowerplan
                        } else {
                            $pendingFile=Get-LessUncPowerplanFile -PlanName $pendingPower
                            if([string]::IsNullOrWhiteSpace($pendingFile)){ throw "Power Plan file not found for $pendingPower" }
                            $pendingResult=Import-AndActivate-LessPowerplan -PowerplanFile $pendingFile -DisplayLabel $pendingPower
                            if($pendingResult -and $pendingResult.Guid){ Add-Log ("Pending Power Plan applied and verified: {0} / {1}" -f $pendingPower,$pendingResult.Guid) '#FFFFFF' }
                        }
                    }
                } catch { Add-Log ("Pending privileged action failed: {0}" -f $_.Exception.Message) '#D8D8D8' }
            }.GetNewClosure())
            $pendingTimer.Start()
        } catch { Add-Log ("Could not start pending privileged action: {0}" -f $_.Exception.Message) '#D8D8D8' }
    }
})
# The initial list is rendered once from ContentRendered after layout is ready.
$window.ShowDialog() | Out-Null
